    # Compute expected window from inputs
    expected_window: Optional[Dict[str, Any]] = None
    hours: List[Dict[str, Any]] = []
    window_hours = None
    checked_hours_count = None
    if isinstance(thresholds_json, dict) and forecast_json is not None:
        hours = extract_hours(forecast_json)
        checked_hours_count = len(hours)
        try:
            # Sliding window selection
            wins = sliding_windows(hours, thresholds_json)
            if wins:
                expected_window = wins[0]
                # Round avg_temp_F to one decimal for comparison to CSV formatted value
                expected_window["avg_temp_F_rounded"] = round(expected_window["avg_temp_F"] + 1e-9, 1)
            window_hours = int(thresholds_json.get("window_hours")) if "window_hours" in thresholds_json else None
        except Exception:
            expected_window = None

    # Validate CSV
    if os.path.isfile(csv_path):
        checks["csv_exists"] = True
        try:
            with open(csv_path, "r", encoding="utf-8") as f:
                raw_lines = f.read().splitlines()
            # Filter out purely empty lines
            lines = [ln for ln in raw_lines if ln.strip() != ""]
            if len(lines) == 2:
                checks["csv_two_lines"] = True
            header_expected = "start_time,end_time,avg_temp_F,max_wind_mph,max_gust_mph,dry_post_hours_ok"
            if lines:
                if lines[0].strip() == header_expected:
                    checks["csv_header_ok"] = True
            # If we have expected window computed and there is a data line, validate contents
            if len(lines) >= 2 and expected_window is not None:
                data_fields = parse_csv_line(lines[1])
                if len(data_fields) == 6:
                    csv_start, csv_end, csv_avg_s, csv_max_wind_s, csv_max_gust_s, csv_dry = data_fields
                    # Start/end times
                    if csv_start == expected_window.get("start_time", ""):
                        checks["csv_start_time_ok"] = True
                    if csv_end == expected_window.get("end_time", ""):
                        checks["csv_end_time_ok"] = True
                    # Numeric comparisons
                    try:
                        csv_avg = float(csv_avg_s)
                        exp_avg = expected_window["avg_temp_F_rounded"]
                        if float_close(csv_avg, exp_avg, tol=0.11):
                            checks["csv_avg_temp_ok"] = True
                    except Exception:
                        pass
                    try:
                        csv_max_wind = float(csv_max_wind_s)
                        if float_close(csv_max_wind, float(expected_window["max_wind_mph"]), tol=0.01):
                            checks["csv_max_wind_ok"] = True
                    except Exception:
                        pass
                    try:
                        csv_max_gust = float(csv_max_gust_s)
                        if float_close(csv_max_gust, float(expected_window["max_gust_mph"]), tol=0.01):
                            checks["csv_max_gust_ok"] = True
                    except Exception:
                        pass
                    # Dry flag (should be "yes" if the window was chosen)
                    dry_flag_ok = csv_dry.strip().lower() == ("yes" if expected_window.get("dry_post_hours_ok", False) else "no")
                    if dry_flag_ok:
                        checks["csv_dry_flag_ok"] = True
        except Exception:
            # Leave CSV-related checks as-is (False)
            pass

    # Validate summary.json
    summary_data = None
    if os.path.isfile(summary_path):
        checks["summary_exists"] = True
        try:
            summary_data = read_json(summary_path)
            if isinstance(summary_data, dict):
                checks["summary_valid_json"] = True
                # field_id
                if summary_data.get("field_id") == 14:
                    checks["summary_field_id_ok"] = True
                # thresholds_used match input exactly (deep equality by canonical JSON)
                if isinstance(thresholds_json, dict) and "thresholds_used" in summary_data:
                    try:
                        t_in = json.dumps(thresholds_json, sort_keys=True)
                        t_out = json.dumps(summary_data["thresholds_used"], sort_keys=True)
                        if t_in == t_out:
                            checks["summary_thresholds_match"] = True
                    except Exception:
                        pass
                # selected_window checks
                sel = summary_data.get("selected_window")
                if isinstance(sel, dict) and expected_window is not None:
                    times_ok = (sel.get("start_time") == expected_window.get("start_time")) and (sel.get("end_time") == expected_window.get("end_time"))
                    if times_ok:
                        checks["summary_selected_times_ok"] = True
                    # hour_count
                    try:
                        if window_hours is not None and int(sel.get("hour_count")) == int(window_hours):
                            checks["summary_hour_count_ok"] = True
                    except Exception:
                        pass
                    # avg temp
                    try:
                        if float_close(float(sel.get("avg_temp_F")), float(expected_window["avg_temp_F_rounded"]), tol=0.11):
                            checks["summary_avg_temp_ok"] = True
                    except Exception:
                        pass
                    # max wind/gust
                    try:
                        if float_close(float(sel.get("max_wind_mph")), float(expected_window["max_wind_mph"]), tol=0.01):
                            checks["summary_max_wind_ok"] = True
                    except Exception:
                        pass
                    try:
                        if float_close(float(sel.get("max_gust_mph")), float(expected_window["max_gust_mph"]), tol=0.01):
                            checks["summary_max_gust_ok"] = True
                    except Exception:
                        pass
                # checked_hours equals total hours in input
                if checked_hours_count is not None:
                    try:
                        if int(summary_data.get("checked_hours")) == int(checked_hours_count):
                            checks["summary_checked_hours_ok"] = True
                    except Exception:
                        pass
        except Exception:
            # summary_valid_json remains False if parsing failed
            pass

    # Cross-consistency between CSV and JSON (if both parsed and have expected)
    if checks["csv_exists"] and checks["summary_valid_json"] and summary_data and expected_window is not None:
        try:
            with open(csv_path, "r", encoding="utf-8") as f:
                lines = [ln for ln in f.read().splitlines() if ln.strip() != ""]
            if len(lines) >= 2:
                data_fields = parse_csv_line(lines[1])
                if len(data_fields) == 6:
                    csv_start, csv_end, csv_avg_s, csv_max_wind_s, csv_max_gust_s, csv_dry = data_fields
                    sel = summary_data.get("selected_window", {})
                    consistent = True
                    consistent &= (sel.get("start_time") == csv_start)
                    consistent &= (sel.get("end_time") == csv_end)
                    try:
                        consistent &= float_close(float(sel.get("avg_temp_F")), float(csv_avg_s), tol=0.11)
                    except Exception:
                        consistent = False
                    try:
                        consistent &= float_close(float(sel.get("max_wind_mph")), float(csv_max_wind_s), tol=0.01)
                    except Exception:
                        consistent = False
                    try:
                        consistent &= float_close(float(sel.get("max_gust_mph")), float(csv_max_gust_s), tol=0.01)
                    except Exception:
                        consistent = False
                    if consistent:
                        checks["csv_json_consistent"] = True
        except Exception:
            pass

    # Compute reward
    # Baseline: if required artifacts missing, reward must be exactly 0.0
    required_present = checks["csv_exists"] and checks["summary_exists"]
    if not required_present:
        reward = 0.0
    else:
        # Reward is fraction of passed checks (excluding existence to encourage correctness, or include them all equally)
        total_checks = len(checks)
        passed_checks = sum(1 for v in checks.values() if v)
        reward = passed_checks / total_checks if total_checks > 0 else 0.0
        # Clamp between 0 and 1
        reward = max(0.0, min(1.0, reward))

    result = {"reward": reward}
    result.update(checks)
    print(json.dumps(result))

if __name__ == "__main__":
    main()

import json
import csv
import sys
import subprocess
from pathlib import Path
from datetime import datetime, timedelta


WEEKDAY_NAMES = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]


def _read_text_safe(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _load_json_safe(path: Path):
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _load_csv_safe(path: Path):
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            rows = list(reader)
            return rows
    except Exception:
        return None


def _parse_simple_yaml(path: Path):
    # Very simple YAML parser for key: "value" pairs on single lines
    text = _read_text_safe(path)
    if text is None:
        return None
    data = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if ":" not in line:
            continue
        key, val = line.split(":", 1)
        key = key.strip()
        val = val.strip()
        # Remove surrounding quotes if present
        if (val.startswith('"') and val.endswith('"')) or (val.startswith("'") and val.endswith("'")):
            val = val[1:-1]
        data[key] = val
    return data


def _parse_iso_z(dt_str: str):
    # Parses YYYY-MM-DDTHH:MM:SSZ into naive datetime in UTC
    try:
        s = dt_str.strip()
        if not s.endswith("Z"):
            return None
        s2 = s[:-1]
        # Allow seconds optional; but spec includes seconds
        # Try with seconds first
        try:
            return datetime.fromisoformat(s2)
        except ValueError:
            # Try adding seconds if missing
            try:
                return datetime.fromisoformat(s2 + ":00")
            except Exception:
                return None
    except Exception:
        return None


def _isoformat_z(dt: datetime) -> str:
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")


def _weekday_name(dt: datetime) -> str:
    return WEEKDAY_NAMES[dt.weekday()]


def _compute_slot_analysis(members: list, calls: list):
    # returns dict keyed by (weekday_idx, weekday_name, hour) -> dict with calls_count and avg_attendance
    member_emails = {m.get("email") for m in members if isinstance(m, dict) and m.get("email")}
    groups = {}
    for row in calls:
        start = row.get("start_utc")
        attendees_field = row.get("attendees_emails", "")
        dt = _parse_iso_z(start) if isinstance(start, str) else None
        if dt is None:
            return None  # malformed data; fail the whole check
        # filter attendees by members.json
        attendees_raw = [a.strip() for a in attendees_field.split(";")] if isinstance(attendees_field, str) else []
        attendees = [a for a in attendees_raw if a in member_emails]
        weekday_idx = dt.weekday()
        weekday = WEEKDAY_NAMES[weekday_idx]
        hour = dt.hour
        key = (weekday_idx, weekday, hour)
        if key not in groups:
            groups[key] = []
        groups[key].append(len(attendees))
    result = {}
    for key, counts in groups.items():
        calls_count = len(counts)
        avg_attendance = sum(counts) / calls_count if calls_count > 0 else 0.0
        result[key] = {"calls_count": calls_count, "avg_attendance": avg_attendance}
    return result


def _pick_best_slot(slot_analysis: dict):
    # slot_analysis keys: (weekday_idx, weekday_name, hour) -> {calls_count, avg_attendance}
    if not slot_analysis:
        return None
    # Sort by -avg_attendance, -calls_count, weekday_idx ascending, hour ascending
    items = []
    for key, stats in slot_analysis.items():
        weekday_idx, weekday_name, hour = key
        calls_count = stats["calls_count"]
        avg_attendance = stats["avg_attendance"]
        items.append((-(avg_attendance), -(calls_count), weekday_idx, hour, key))
    items.sort()
    best_key = items[0][4]
    return best_key  # (weekday_idx, weekday_name, hour)


def _next_occurrence_after(reference_dt: datetime, target_weekday_idx: int, target_hour: int) -> datetime:
    # Compute next datetime strictly after reference_dt with weekday=target and hour=target_hour, minute=0, second=0
    # Calculate days ahead to the target weekday
    ref_weekday = reference_dt.weekday()
    days_ahead = (target_weekday_idx - ref_weekday) % 7
    candidate_date = (reference_dt.date() + timedelta(days=days_ahead))
    candidate_dt = datetime(candidate_date.year, candidate_date.month, candidate_date.day, target_hour, 0, 0)
    if candidate_dt <= reference_dt:
        candidate_dt = candidate_dt + timedelta(days=7)
    return candidate_dt


def _format_utc_offset_signed(offset_hours: float) -> str:
    # Convert offset hours to +HH:MM or -HH:MM
    total_minutes = int(round(offset_hours * 60))
    sign = "+" if total_minutes >= 0 else "-"
    abs_minutes = abs(total_minutes)
    hh = abs_minutes // 60
    mm = abs_minutes % 60
    return f"{sign}{hh:02d}:{mm:02d}"


def _apply_template(template: str, replacements: dict) -> str:
    # Simple placeholder replacement
    out = template
    for k, v in replacements.items():
        out = out.replace("{" + k + "}", v)
    return out


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "script_runs": 0.0,
        "slot_analysis_header_correct": 0.0,
        "slot_analysis_rows_correct": 0.0,
        "avg_attendance_decimal_precision": 0.0,
        "next_call_utc_correct": 0.0,
        "invites_files_present": 0.0,
        "invites_content_correct": 0.0,
    }

    # Attempt to run the user's script
    cmd = [
        sys.executable,
        "plan_next_call.py",
        "--members", "input/members.json",
        "--calls", "input/past_calls.csv",
        "--config", "input/config.yaml",
        "--template", "input/invite_template.txt",
        "--outdir", "output",
    ]
    try:
        proc = subprocess.run(
            cmd,
            cwd=str(workspace),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=30
        )
        if proc.returncode == 0:
            scores["script_runs"] = 1.0
    except Exception:
        # If execution fails, leave script_runs at 0.0
        pass

    # Load inputs for expected computations
    members_path = workspace / "input" / "members.json"
    calls_path = workspace / "input" / "past_calls.csv"
    config_path = workspace / "input" / "config.yaml"
    template_path = workspace / "input" / "invite_template.txt"

    members = _load_json_safe(members_path)
    calls = _load_csv_safe(calls_path)
    config = _parse_simple_yaml(config_path)
    template_text = _read_text_safe(template_path)

    expected_slot_analysis = None
    expected_best_slot = None
    expected_next_iso = None
    expected_next_dt = None

    if members is not None and calls is not None and config is not None and template_text is not None:
        expected_slot_analysis = _compute_slot_analysis(members, calls)
        if expected_slot_analysis is not None and expected_slot_analysis:
            expected_best_slot = _pick_best_slot(expected_slot_analysis)
            # Compute next occurrence strictly after reference timestamp
            ref_str = config.get("reference_date_utc")
            ref_dt = _parse_iso_z(ref_str) if isinstance(ref_str, str) else None
            if ref_dt is not None and expected_best_slot is not None:
                weekday_idx, weekday_name, hour = expected_best_slot
                next_dt = _next_occurrence_after(ref_dt, weekday_idx, hour)
                expected_next_dt = next_dt
                expected_next_iso = _isoformat_z(next_dt)

    # Validate slot_analysis.csv
    slot_analysis_path = workspace / "output" / "slot_analysis.csv"
    if slot_analysis_path.exists() and expected_slot_analysis is not None:
        try:
            with slot_analysis_path.open("r", encoding="utf-8", newline="") as f:
                reader = csv.reader(f)
                rows = list(reader)
            if rows:
                header = rows[0]
                if header == ["weekday", "hour_utc", "calls_count", "avg_attendance"]:
                    scores["slot_analysis_header_correct"] = 1.0
                # Parse rows into mapping
                actual_map = {}
                avg_field_strings = []
                for r in rows[1:]:
                    if len(r) != 4:
                        actual_map = None
                        break
                    weekday, hour_s, calls_count_s, avg_att_s = r
                    try:
                        hour = int(hour_s)
                        calls_count = int(calls_count_s)
                        avg_val = float(avg_att_s)
                        avg_field_strings.append(avg_att_s)
                    except Exception:
                        actual_map = None
                        break
                    if weekday not in WEEKDAY_NAMES:
                        actual_map = None
                        break
                    key = (WEEKDAY_NAMES.index(weekday), weekday, hour)
                    actual_map[key] = (calls_count, avg_val, avg_att_s)
                if actual_map is not None:
                    # Build expected map for comparison
                    expected_map = {}
                    for key, stats in expected_slot_analysis.items():
                        expected_map[key] = (stats["calls_count"], float(stats["avg_attendance"]))
                    # Compare keys
                    if set(actual_map.keys()) == set(expected_map.keys()):
                        # Compare numeric values for each key
                        ok = True
                        for key in expected_map:
                            exp_calls, exp_avg = expected_map[key]
                            act_calls, act_avg, act_avg_str = actual_map[key]
                            if act_calls != exp_calls:
                                ok = False
                                break
                            # Compare float exactly; since we built exp_avg from same arithmetic, it should match parse
                            # Allow a tiny tolerance to avoid float quirks
                            if abs(act_avg - exp_avg) > 1e-9:
                                ok = False
                                break
                        if ok:
                            scores["slot_analysis_rows_correct"] = 1.0
                    # Check decimal precision: ensure every avg_attendance string has a decimal point
                    if actual_map is not None:
                        has_decimal_all = True
                        for key in actual_map:
                            avg_str = actual_map[key][2]
                            if "." not in avg_str:
                                has_decimal_all = False
                                break
                        scores["avg_attendance_decimal_precision"] = 1.0 if has_decimal_all else 0.0
        except Exception:
            pass

    # Validate next_call_utc.txt
    next_call_path = workspace / "output" / "next_call_utc.txt"
    if expected_next_iso is not None and next_call_path.exists():
        content = _read_text_safe(next_call_path)
        if content is not None:
            line = content.strip()
            if line == expected_next_iso:
                scores["next_call_utc_correct"] = 1.0

    # Validate invites files presence and content
    invites_dir = workspace / "output" / "invites"
    expected_invite_filenames = set()
    if members is not None:
        for m in members:
            if isinstance(m, dict) and m.get("email"):
                expected_invite_filenames.add(f"{m['email']}.txt")

    if invites_dir.exists() and invites_dir.is_dir() and expected_invite_filenames:
        actual_files = {p.name for p in invites_dir.glob("*.txt")}
        if actual_files == expected_invite_filenames:
            scores["invites_files_present"] = 1.0

    # Validate invites content
    if expected_next_dt is not None and template_text is not None and invites_dir.exists() and expected_invite_filenames:
        correct_count = 0
        total = len(expected_invite_filenames)
        for m in members:
            name = m.get("name")
            email = m.get("email")
            offset = m.get("utc_offset_hours")
            if not isinstance(name, str) or not isinstance(email, str):
                continue
            try:
                offset_hours = float(offset)
            except Exception:
                continue
            total_minutes = int(round(offset_hours * 60))
            local_dt = expected_next_dt + timedelta(minutes=total_minutes)
            local_str = local_dt.strftime("%Y-%m-%d %H:%M")
            offset_signed = _format_utc_offset_signed(offset_hours)
            meeting_title = config.get("meeting_title", "")
            video_link = config.get("video_link", "")
            replacements = {
                "name": name,
                "meeting_title": meeting_title,
                "video_link": video_link,
                "local_datetime": local_str,
                "utc_offset_signed": offset_signed,
            }
            expected_invite = _apply_template(template_text, replacements)
            invite_path = invites_dir / f"{email}.txt"
            actual_invite = _read_text_safe(invite_path)
            if actual_invite is None:
                continue
            # Normalize newlines for comparison
            exp_norm = expected_invite.replace("\r\n", "\n").replace("\r", "\n")
            act_norm = actual_invite.replace("\r\n", "\n").replace("\r", "\n")
            if exp_norm == act_norm:
                correct_count += 1
        if total > 0:
            scores["invites_content_correct"] = float(correct_count) / float(total)

    return scores


def main() -> None:
    import json as _json
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(_json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

import json
import csv
import re
from pathlib import Path
from html.parser import HTMLParser
from typing import List, Dict, Optional, Tuple


def read_text_safe(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


class SEOHTMLParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.title: Optional[str] = None
        self._in_title = False
        self._title_chunks: List[str] = []

        self.description: Optional[str] = None

        self.h1: Optional[str] = None
        self._in_h1 = False
        self._h1_chunks: List[str] = []

        self.img_missing_alt_count: int = 0

    def handle_starttag(self, tag: str, attrs: List[Tuple[str, Optional[str]]]):
        tag_l = tag.lower()
        attrs_dict = {k.lower(): (v if v is not None else "") for k, v in attrs}
        if tag_l == "title":
            # record content of the first title only
            if self.title is None:
                self._in_title = True
                self._title_chunks = []
        elif tag_l == "meta":
            if self.description is None:
                name = attrs_dict.get("name", "")
                if isinstance(name, str) and name.lower() == "description":
                    self.description = attrs_dict.get("content", "")
                    if self.description is None:
                        self.description = ""
        elif tag_l == "h1":
            if self.h1 is None:
                self._in_h1 = True
                self._h1_chunks = []
        elif tag_l == "img":
            # count missing alt attribute
            if "alt" not in attrs_dict:
                self.img_missing_alt_count += 1

    def handle_endtag(self, tag: str):
        tag_l = tag.lower()
        if tag_l == "title":
            if self._in_title and self.title is None:
                self.title = "".join(self._title_chunks).strip()
            self._in_title = False
        elif tag_l == "h1":
            if self._in_h1 and self.h1 is None:
                self.h1 = "".join(self._h1_chunks).strip()
            self._in_h1 = False

    def handle_data(self, data: str):
        if self._in_title:
            self._title_chunks.append(data)
        if self._in_h1:
            self._h1_chunks.append(data)


def parse_html_info(html_text: str) -> Dict[str, Optional[str]]:
    parser = SEOHTMLParser()
    parser.feed(html_text)
    title = parser.title.strip() if parser.title is not None else None
    description = parser.description.strip() if parser.description is not None else None
    h1 = parser.h1.strip() if parser.h1 is not None else None
    return {
        "title": title,
        "description": description,
        "h1": h1,
        "img_missing_alt_count": parser.img_missing_alt_count,
    }


def find_html_files(input_root: Path) -> List[Path]:
    if not input_root.exists():
        return []
    return sorted([p for p in input_root.rglob("*.html") if p.is_file()])


def normalize_for_dup(s: str) -> str:
    # normalize for duplicate comparison: trim and casefold only (no internal collapse)
    return s.strip().casefold()


def normalize_space_casefold(s: str) -> str:
    return " ".join(s.split()).strip().casefold()


def length_or_none(s: Optional[str]) -> Optional[int]:
    if s is None:
        return None
    return len(s.strip())


def compute_issues(pages: Dict[str, Dict]) -> Dict[str, Dict[str, bool]]:
    # Determine duplicates
    title_map: Dict[str, List[str]] = {}
    desc_map: Dict[str, List[str]] = {}

    for path, info in pages.items():
        if info["title"] is not None:
            key = normalize_for_dup(info["title"])
            title_map.setdefault(key, []).append(path)
        if info["description"] is not None:
            keyd = normalize_for_dup(info["description"])
            desc_map.setdefault(keyd, []).append(path)

    dup_title_paths = set()
    for paths in title_map.values():
        if len(paths) > 1:
            dup_title_paths.update(paths)

    dup_desc_paths = set()
    for paths in desc_map.values():
        if len(paths) > 1:
            dup_desc_paths.update(paths)

    issues: Dict[str, Dict[str, bool]] = {}
    for path, info in pages.items():
        tlen = length_or_none(info["title"])
        dlen = length_or_none(info["description"])
        page_issues = {
            "missing_title": info["title"] is None,
            "title_length_short": (tlen is not None and tlen < 30),
            "title_length_long": (tlen is not None and tlen > 65),
            "duplicate_title": path in dup_title_paths,
            "missing_description": info["description"] is None,
            "description_length_short": (dlen is not None and dlen < 110),
            "description_length_long": (dlen is not None and dlen > 160),
            "duplicate_description": path in dup_desc_paths,
        }
        issues[path] = page_issues
    return issues


def expected_overview(pages: Dict[str, Dict], issues: Dict[str, Dict[str, bool]]) -> Dict[str, int]:
    total_pages_scanned = len(pages)
    pages_with_missing_title = sum(1 for p, i in issues.items() if i["missing_title"])
    pages_with_missing_description = sum(1 for p, i in issues.items() if i["missing_description"])
    pages_with_duplicate_titles = sum(1 for p, i in issues.items() if i["duplicate_title"])
    pages_with_duplicate_descriptions = sum(1 for p, i in issues.items() if i["duplicate_description"])
    pages_with_out_of_range_titles = sum(
        1 for p, i in issues.items() if not i["missing_title"] and (i["title_length_short"] or i["title_length_long"])
    )
    pages_with_out_of_range_descriptions = sum(
        1 for p, i in issues.items() if not i["missing_description"] and (i["description_length_short"] or i["description_length_long"])
    )
    total_images_missing_alt = sum(pages[p]["img_missing_alt_count"] for p in pages)
    return {
        "total_pages_scanned": total_pages_scanned,
        "pages_with_missing_title": pages_with_missing_title,
        "pages_with_missing_description": pages_with_missing_description,
        "pages_with_duplicate_titles": pages_with_duplicate_titles,
        "pages_with_duplicate_descriptions": pages_with_duplicate_descriptions,
        "pages_with_out_of_range_titles": pages_with_out_of_range_titles,
        "pages_with_out_of_range_descriptions": pages_with_out_of_range_descriptions,
        "total_images_missing_alt": total_images_missing_alt,
    }


def parse_overview_totals_from_md(md_text: str) -> Dict[str, Optional[int]]:
    keys = [
        "total_pages_scanned",
        "pages_with_missing_title",
        "pages_with_missing_description",
        "pages_with_duplicate_titles",
        "pages_with_duplicate_descriptions",
        "pages_with_out_of_range_titles",
        "pages_with_out_of_range_descriptions",
        "total_images_missing_alt",
    ]
    results: Dict[str, Optional[int]] = {k: None for k in keys}
    for k in keys:
        # match key: number (allow spaces)
        m = re.search(rf"{re.escape(k)}\s*:\s*(\d+)", md_text, flags=re.IGNORECASE)
        if m:
            try:
                results[k] = int(m.group(1))
            except Exception:
                results[k] = None
    return results


def load_csv_rows(path: Path) -> Optional[List[Dict[str, str]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            rows = [dict({k: (v if v is not None else "") for k, v in row.items()}) for row in reader]
            return rows
    except Exception:
        return None


def get_duplicate_groups(pages: Dict[str, Dict]) -> Tuple[Dict[str, List[str]], Dict[str, List[str]]]:
    # Returns mappings normalized_title_text -> list of paths, and normalized_description_text -> paths
    title_map: Dict[str, List[str]] = {}
    desc_map: Dict[str, List[str]] = {}
    for path, info in pages.items():
        if info["title"] is not None:
            key = normalize_for_dup(info["title"])
            title_map.setdefault(key, []).append(path)
        if info["description"] is not None:
            keyd = normalize_for_dup(info["description"])
            desc_map.setdefault(keyd, []).append(path)
    dup_titles = {k: v for k, v in title_map.items() if len(v) > 1}
    dup_descs = {k: v for k, v in desc_map.items() if len(v) > 1}
    return dup_titles, dup_descs


def find_line_for_page(md_lines: List[str], page_path: str) -> Optional[str]:
    for line in md_lines:
        if page_path in line:
            return line
    return None


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "outputs_present": 0.0,
        "audit_overview_totals_correct": 0.0,
        "audit_per_page_summary_contains_pages_and_issues": 0.0,
        "audit_duplicates_section_present_and_correct": 0.0,
        "recommendations_csv_structure_valid": 0.0,
        "recommendations_rows_cover_expected_pages": 0.0,
        "recommendations_current_fields_match_extracted": 0.0,
        "recommendations_title_constraints": 0.0,
        "recommendations_description_constraints": 0.0,
        "recommendations_rationale_mentions_issues": 0.0,
    }

    input_root = workspace / "input" / "site"
    output_md = workspace / "output" / "seo_audit.md"
    output_csv = workspace / "output" / "meta_recommendations.csv"

    # Gather pages
    html_files = find_html_files(input_root)
    pages: Dict[str, Dict] = {}
    for p in html_files:
        text = read_text_safe(p)
        if text is None:
            continue
        info = parse_html_info(text)
        rel = p.relative_to(input_root).as_posix()
        pages[rel] = {
            "title": info["title"],
            "description": info["description"],
            "h1": info["h1"] if info["h1"] is not None else "",
            "img_missing_alt_count": info["img_missing_alt_count"],
            "raw_title": info["title"],
            "raw_description": info["description"],
        }

    issues = compute_issues(pages)
    overview_expected = expected_overview(pages, issues)

    # outputs_present
    if output_md.exists() and output_csv.exists():
        scores["outputs_present"] = 1.0

    # seo_audit.md checks
    md_text = read_text_safe(output_md) if output_md.exists() else None
    if md_text is not None and len(md_text.strip()) > 0:
        # totals
        found_totals = parse_overview_totals_from_md(md_text)
        if all(found_totals.get(k) == v for k, v in overview_expected.items()):
            scores["audit_overview_totals_correct"] = 1.0

        md_lines = md_text.splitlines()

        # per-page summary: each page line should include file path and issue tags
        per_page_ok = True
        for rel_path, info in pages.items():
            line = find_line_for_page(md_lines, rel_path)
            if line is None:
                per_page_ok = False
                break
            # tokens to expect
            tokens = []
            # title issues
            if issues[rel_path]["missing_title"]:
                tokens.append("missing_title")
            else:
                if issues[rel_path]["title_length_short"]:
                    tokens.append("title_length_short")
                if issues[rel_path]["title_length_long"]:
                    tokens.append("title_length_long")
            if issues[rel_path]["duplicate_title"]:
                tokens.append("duplicate_title")
            # description issues
            if issues[rel_path]["missing_description"]:
                tokens.append("missing_description")
            else:
                if issues[rel_path]["description_length_short"]:
                    tokens.append("description_length_short")
                if issues[rel_path]["description_length_long"]:
                    tokens.append("description_length_long")
            if issues[rel_path]["duplicate_description"]:
                tokens.append("duplicate_description")
            # image count
            tokens.append(f"image_missing_alt_count={pages[rel_path]['img_missing_alt_count']}")

            # Verify tokens presence
            for t in tokens:
                if t not in line:
                    per_page_ok = False
                    break
            if not per_page_ok:
                break
        if per_page_ok and len(pages) > 0:
            scores["audit_per_page_summary_contains_pages_and_issues"] = 1.0
        elif per_page_ok and len(pages) == 0:
            # If no pages, consider per-page summary trivially satisfied
            scores["audit_per_page_summary_contains_pages_and_issues"] = 1.0

        # duplicates groups
        dup_titles, dup_descs = get_duplicate_groups(pages)
        dup_ok = True
        # Check each duplicate group is referenced by duplicated string and file paths
        def group_text_present(dup_map: Dict[str, List[str]], kind: str) -> bool:
            # For each group, ensure the duplicated string appears and all file paths appear in the md text.
            for norm_text, paths in dup_map.items():
                representative = None
                first_path = paths[0] if paths else None
                if first_path:
                    field = "title" if kind == "title" else "description"
                    representative = pages[first_path][field]
                if not representative:
                    representative = norm_text  # fallback
                if representative and representative not in md_text:
                    return False
                for rp in paths:
                    if rp not in md_text:
                        return False
            return True

        if not group_text_present(dup_titles, "title"):
            dup_ok = False
        if not group_text_present(dup_descs, "description"):
            dup_ok = False

        if dup_ok:
            scores["audit_duplicates_section_present_and_correct"] = 1.0

    # meta_recommendations.csv checks
    rows = load_csv_rows(output_csv) if output_csv.exists() else None
    expected_header = ["file_path", "current_title", "current_description", "recommended_title", "recommended_description", "rationale"]
    header_ok = False
    if rows is not None:
        # Re-open to get header order reliably
        try:
            with output_csv.open("r", encoding="utf-8", newline="") as f:
                reader = csv.reader(f)
                header = next(reader, [])
        except Exception:
            header = []
        if header == expected_header:
            header_ok = True
            scores["recommendations_csv_structure_valid"] = 1.0

    if rows is not None and header_ok:
        # Determine expected pages requiring recommendations: any title/description issue
        expected_issue_pages = set()
        for rel_path, iss in issues.items():
            td_issues = [
                iss["missing_title"], iss["title_length_short"], iss["title_length_long"], iss["duplicate_title"],
                iss["missing_description"], iss["description_length_short"], iss["description_length_long"], iss["duplicate_description"]
            ]
            if any(td_issues):
                expected_issue_pages.add(rel_path)

        # Map rows by file_path endswith rel_path
        row_map: Dict[str, Dict[str, str]] = {}
        unmatched_rows = []
        for r in rows:
            row_fp = (r.get("file_path") or "").strip()
            matched = None
            for rel in expected_issue_pages:
                if row_fp.endswith(rel):
                    matched = rel
                    break
            if matched is None:
                unmatched_rows.append(row_fp)
            else:
                if matched in row_map:
                    unmatched_rows.append(row_fp)
                else:
                    row_map[matched] = r

        if set(row_map.keys()) == expected_issue_pages and not unmatched_rows:
            scores["recommendations_rows_cover_expected_pages"] = 1.0

        # current fields match extracted
        curr_ok = True
        for rel, r in row_map.items():
            exp_title = pages[rel]["title"] if pages[rel]["title"] is not None else ""
            exp_desc = pages[rel]["description"] if pages[rel]["description"] is not None else ""
            cur_title = (r.get("current_title") or "").strip()
            cur_desc = (r.get("current_description") or "").strip()
            if cur_title != exp_title or cur_desc != exp_desc:
                curr_ok = False
                break
        if curr_ok and len(row_map) == len(expected_issue_pages):
            scores["recommendations_current_fields_match_extracted"] = 1.0

        # recommended title constraints and uniqueness
        title_constraints_ok = True
        rec_titles_seen = set()
        for rel, r in row_map.items():
            rec_title = (r.get("recommended_title") or "").strip()
            if not (30 <= len(rec_title) <= 65):
                title_constraints_ok = False
                break
            # include H1 text
            h1_text = pages[rel]["h1"] or ""
            if h1_text:
                if normalize_space_casefold(h1_text) not in normalize_space_casefold(rec_title):
                    title_constraints_ok = False
                    break
            else:
                # If no H1, we can't verify inclusion; consider it failing
                title_constraints_ok = False
                break
            # include brand "Valleys Explorer"
            if "valleys explorer" not in rec_title.casefold():
                title_constraints_ok = False
                break
            # uniqueness
            if rec_title in rec_titles_seen:
                title_constraints_ok = False
                break
            rec_titles_seen.add(rec_title)
        if title_constraints_ok and len(row_map) == len(expected_issue_pages):
            scores["recommendations_title_constraints"] = 1.0

        # recommended description constraints and uniqueness
        desc_constraints_ok = True
        rec_descs_seen = set()
        for rel, r in row_map.items():
            rec_desc = (r.get("recommended_description") or "").strip()
            if not (110 <= len(rec_desc) <= 160):
                desc_constraints_ok = False
                break
            if "torfaen" not in rec_desc.casefold():
                desc_constraints_ok = False
                break
            if rec_desc in rec_descs_seen:
                desc_constraints_ok = False
                break
            rec_descs_seen.add(rec_desc)
        if desc_constraints_ok and len(row_map) == len(expected_issue_pages):
            scores["recommendations_description_constraints"] = 1.0

        # rationale mentions issues prompting recommendation
        rationale_ok = True
        for rel, r in row_map.items():
            rationale = (r.get("rationale") or "").strip()
            # Determine title/description issues for this page
            rel_issues = issues[rel]
            expected_tokens = []
            if rel_issues["missing_title"]:
                expected_tokens.append("missing_title")
            else:
                if rel_issues["title_length_short"]:
                    expected_tokens.append("title_length_short")
                if rel_issues["title_length_long"]:
                    expected_tokens.append("title_length_long")
            if rel_issues["duplicate_title"]:
                expected_tokens.append("duplicate_title")
            if rel_issues["missing_description"]:
                expected_tokens.append("missing_description")
            else:
                if rel_issues["description_length_short"]:
                    expected_tokens.append("description_length_short")
                if rel_issues["description_length_long"]:
                    expected_tokens.append("description_length_long")
            if rel_issues["duplicate_description"]:
                expected_tokens.append("duplicate_description")
            # Require that all expected_tokens appear in rationale
            for tok in expected_tokens:
                if tok not in rationale:
                    rationale_ok = False
                    break
            if not rationale_ok:
                break
        if rationale_ok and len(row_map) == len(expected_issue_pages):
            scores["recommendations_rationale_mentions_issues"] = 1.0

    return scores


def main() -> None:
    import sys
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

