import json
import csv
import re
import math
import sys
from pathlib import Path
from typing import Dict, List, Optional, Tuple


def _safe_read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _safe_read_json(path: Path) -> Optional[dict]:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None


def _safe_read_jsonl(path: Path) -> Optional[List[dict]]:
    rows = []
    try:
        with path.open("r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                rows.append(json.loads(line))
        return rows
    except Exception:
        return None


def _safe_read_csv_dicts(path: Path) -> Optional[List[dict]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            return list(reader)
    except Exception:
        return None


def _float_or_none(s: Optional[str]) -> Optional[float]:
    if s is None:
        return None
    s = s.strip()
    if s == "":
        return None
    try:
        return float(s)
    except Exception:
        return None


def _close(a: float, b: float, tol: float = 1e-6) -> bool:
    return abs(a - b) <= tol


def _parse_markdown_journals(journal_dir: Path) -> Tuple[Dict[str, dict], int]:
    """
    Returns (data_by_date, count_days)
    data_by_date: date -> { 'headache': float, 'dizziness': float, 'fatigue': float, 'diary_screen_time_hours': float }
    """
    data: Dict[str, dict] = {}
    count_days = 0
    if not journal_dir.exists():
        return data, 0
    for md_file in sorted(journal_dir.glob("*.md")):
        text = _safe_read_text(md_file)
        if text is None:
            continue
        date = md_file.stem
        headache = None
        dizziness = None
        fatigue = None
        screen_time = None

        head_m = re.search(r'Headache:\s*([0-9]+(?:\.[0-9]+)?)/10', text, flags=re.IGNORECASE)
        if head_m:
            try:
                headache = float(head_m.group(1))
            except Exception:
                headache = None
        dizzy_m = re.search(r'Dizziness:\s*([0-9]+(?:\.[0-9]+)?)/10', text, flags=re.IGNORECASE)
        if dizzy_m:
            try:
                dizziness = float(dizzy_m.group(1))
            except Exception:
                dizziness = None
        fatigue_m = re.search(r'Fatigue:\s*([0-9]+(?:\.[0-9]+)?)/10', text, flags=re.IGNORECASE)
        if fatigue_m:
            try:
                fatigue = float(fatigue_m.group(1))
            except Exception:
                fatigue = None
        screen_m = re.search(r'Screen time:\s*([0-9]+(?:\.[0-9]+)?)\s*h', text, flags=re.IGNORECASE)
        if screen_m:
            try:
                screen_time = float(screen_m.group(1))
            except Exception:
                screen_time = None

        if date:
            fields = {}
            if headache is not None:
                fields["headache"] = headache
            if dizziness is not None:
                fields["dizziness"] = dizziness
            if fatigue is not None:
                fields["fatigue"] = fatigue
            if screen_time is not None:
                fields["diary_screen_time_hours"] = screen_time
            data.setdefault(date, {}).update(fields)
            count_days += 1
    return data, count_days


def _parse_wearable_csv(csv_path: Path) -> Tuple[Dict[str, dict], int]:
    data: Dict[str, dict] = {}
    rows = _safe_read_csv_dicts(csv_path)
    if rows is None:
        return data, 0
    for r in rows:
        date = r.get("date")
        if not date:
            continue
        sleep = _float_or_none(r.get("sleep_hours"))
        steps_val = r.get("steps")
        steps = None
        try:
            if steps_val is not None and steps_val != "":
                steps = float(steps_val)
        except Exception:
            steps = None
        fields = {}
        if sleep is not None:
            fields["sleep_hours"] = sleep
        if steps is not None:
            fields["steps"] = steps
        data.setdefault(date, {}).update(fields)
    return data, len(rows)


def _parse_checkins_jsonl(jsonl_path: Path) -> Tuple[Dict[str, dict], int]:
    data: Dict[str, dict] = {}
    rows = _safe_read_jsonl(jsonl_path)
    if rows is None:
        return data, 0
    for r in rows:
        date = r.get("date")
        if not date:
            continue
        pcs_overall = r.get("pcs_overall")
        st = r.get("screen_time_hours")
        fields = {}
        try:
            if pcs_overall is not None:
                fields["pcs_overall"] = float(pcs_overall)
        except Exception:
            pass
        try:
            if st is not None:
                fields["checkin_screen_time_hours"] = float(st)
        except Exception:
            pass
        data.setdefault(date, {}).update(fields)
    return data, len(rows)


def _pearson_corr(xs: List[float], ys: List[float]) -> Optional[float]:
    if len(xs) != len(ys):
        return None
    n = len(xs)
    if n < 2:
        return None
    mean_x = sum(xs) / n
    mean_y = sum(ys) / n
    num = sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys))
    den_x = math.sqrt(sum((x - mean_x) ** 2 for x in xs))
    den_y = math.sqrt(sum((y - mean_y) ** 2 for y in ys))
    if den_x == 0 or den_y == 0:
        return None
    return num / (den_x * den_y)


def _moving_average(series_dates: List[str], series_values: List[Optional[float]], window: int) -> List[Tuple[str, float]]:
    result = []
    for i in range(len(series_values)):
        if i + 1 < window:
            continue
        window_vals = series_values[i - window + 1 : i + 1]
        if any(v is None for v in window_vals):
            continue
        avg = sum(window_vals) / window  # type: ignore
        result.append((series_dates[i], avg))
    return result


def _rolling_mean(series: List[Optional[float]], end_index: int, window: int) -> Optional[float]:
    start = end_index - window + 1
    if start < 0:
        return None
    vals = series[start : end_index + 1]
    if len(vals) != window:
        return None
    if any(v is None for v in vals):
        return None
    return sum(vals) / window  # type: ignore


def _compute_expected_from_inputs(workspace: Path):
    md_data, md_count = _parse_markdown_journals(workspace / "input" / "symptom_journal")
    wearable_data, wearable_count = _parse_wearable_csv(workspace / "input" / "wearable" / "metrics.csv")
    checkins_data, checkins_count = _parse_checkins_jsonl(workspace / "input" / "checkins.jsonl")

    union_dates = sorted(set(md_data.keys()) | set(wearable_data.keys()) | set(checkins_data.keys()))
    combined_expected = {}
    for d in union_dates:
        row = {
            "date": d,
            "headache": None,
            "dizziness": None,
            "fatigue": None,
            "pcs_overall": None,
            "diary_screen_time_hours": None,
            "checkin_screen_time_hours": None,
            "sleep_hours": None,
            "steps": None,
        }
        if d in md_data:
            if "headache" in md_data[d]:
                row["headache"] = md_data[d]["headache"]
            if "dizziness" in md_data[d]:
                row["dizziness"] = md_data[d]["dizziness"]
            if "fatigue" in md_data[d]:
                row["fatigue"] = md_data[d]["fatigue"]
            if "diary_screen_time_hours" in md_data[d]:
                row["diary_screen_time_hours"] = md_data[d]["diary_screen_time_hours"]
        if d in checkins_data:
            if "pcs_overall" in checkins_data[d]:
                row["pcs_overall"] = checkins_data[d]["pcs_overall"]
            if "checkin_screen_time_hours" in checkins_data[d]:
                row["checkin_screen_time_hours"] = checkins_data[d]["checkin_screen_time_hours"]
        if d in wearable_data:
            if "sleep_hours" in wearable_data[d]:
                row["sleep_hours"] = wearable_data[d]["sleep_hours"]
            if "steps" in wearable_data[d]:
                row["steps"] = wearable_data[d]["steps"]
        combined_expected[d] = row

    headache_series = [combined_expected[d]["headache"] for d in union_dates]
    dizziness_series = [combined_expected[d]["dizziness"] for d in union_dates]
    fatigue_series = [combined_expected[d]["fatigue"] for d in union_dates]

    ma_headache = _moving_average(union_dates, headache_series, 7)
    ma_dizziness = _moving_average(union_dates, dizziness_series, 7)
    ma_fatigue = _moving_average(union_dates, fatigue_series, 7)

    xs = []
    ys = []
    for d in union_dates:
        h = combined_expected[d]["headache"]
        st = combined_expected[d]["diary_screen_time_hours"]
        if h is not None and st is not None:
            xs.append(st)
            ys.append(h)
    corr_st_headache = _pearson_corr(xs, ys)

    xs2 = []
    ys2 = []
    for d in union_dates:
        h = combined_expected[d]["headache"]
        sl = combined_expected[d]["sleep_hours"]
        if h is not None and sl is not None:
            xs2.append(sl)
            ys2.append(h)
    corr_sleep_headache = _pearson_corr(xs2, ys2)

    change_points = []
    for i in range(len(headache_series)):
        cur_mean = _rolling_mean(headache_series, i, 3)
        prev_mean = _rolling_mean(headache_series, i - 3, 3) if cur_mean is not None else None
        if cur_mean is None or prev_mean is None:
            continue
        if cur_mean - prev_mean >= 1.5:
            change_points.append(union_dates[i])

    inconsistencies = []
    for d in union_dates:
        diary_st = combined_expected[d]["diary_screen_time_hours"]
        checkin_st = combined_expected[d]["checkin_screen_time_hours"]
        if diary_st is not None and checkin_st is not None:
            diff = abs(diary_st - checkin_st)
            if diff > 0.5:
                inconsistencies.append({"date": d, "diary_vs_checkin_screen_time_diff": diff})

    expected = {
        "union_dates": union_dates,
        "combined_expected": combined_expected,
        "moving_averages": {
            "headache_7d": ma_headache,
            "dizziness_7d": ma_dizziness,
            "fatigue_7d": ma_fatigue,
        },
        "correlations": {
            "screen_time_vs_headache": corr_st_headache,
            "sleep_vs_headache": corr_sleep_headache,
        },
        "change_points": change_points,
        "inconsistencies": inconsistencies,
        "coverage_counts": {
            "markdown_days": md_count,
            "wearable_days": wearable_count,
            "checkin_days": checkins_count,
        },
    }
    return expected


def _read_combined_csv(path: Path) -> Optional[List[dict]]:
    rows = _safe_read_csv_dicts(path)
    return rows


def _parse_float_cell(cell: str) -> Optional[float]:
    if cell is None:
        return None
    s = str(cell).strip()
    if s == "":
        return None
    try:
        return float(s)
    except Exception:
        return None


def _validate_header(row: dict, expected_fields: List[str]) -> bool:
    return list(row.keys()) == expected_fields


def _load_trend_summary(path: Path) -> Optional[dict]:
    return _safe_read_json(path)


def _find_cli_script_under_tools(workspace: Path) -> bool:
    tools_dir = workspace / "tools"
    if not tools_dir.exists():
        return False
    for p in tools_dir.glob("*.py"):
        if p.is_file():
            return True
    return False


def _read_run_command(workspace: Path) -> Optional[str]:
    path = workspace / "output" / "reports" / "run_command.txt"
    try:
        return path.read_text(encoding="utf-8").strip()
    except Exception:
        return None


def _extract_section(text: str, section_title: str, next_titles: List[str]) -> str:
    idx = text.lower().find(section_title.lower())
    if idx == -1:
        return ""
    after = text[idx + len(section_title):]
    next_idx = len(after)
    for t in next_titles:
        j = after.lower().find(t.lower())
        if j != -1 and j < next_idx:
            next_idx = j
    return after[:next_idx]


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "cli_script_under_tools_present": 0.0,
        "run_command_logged": 0.0,
        "combined_csv_present": 0.0,
        "combined_csv_header_correct": 0.0,
        "combined_csv_dates_complete": 0.0,
        "combined_csv_values_correct": 0.0,
        "trend_summary_present": 0.0,
        "moving_averages_correct": 0.0,
        "correlations_correct": 0.0,
        "change_points_correct": 0.0,
        "inconsistencies_correct": 0.0,
        "summary_md_sections_present": 0.0,
        "summary_md_correlations_match": 0.0,
        "summary_md_change_points_match": 0.0,
    }

    expected = _compute_expected_from_inputs(workspace)
    union_dates = expected.get("union_dates", [])
    combined_expected = expected.get("combined_expected", {})

    if _find_cli_script_under_tools(workspace):
        scores["cli_script_under_tools_present"] = 1.0

    run_cmd = _read_run_command(workspace)
    if run_cmd and "tools/" in run_cmd and ".py" in run_cmd:
        scores["run_command_logged"] = 1.0

    combined_path = workspace / "output" / "combined" / "daily_metrics.csv"
    combined_rows = None
    if combined_path.exists():
        scores["combined_csv_present"] = 1.0
        combined_rows = _read_combined_csv(combined_path)
    else:
        combined_rows = None

    expected_fields = [
        "date",
        "headache",
        "dizziness",
        "fatigue",
        "pcs_overall",
        "diary_screen_time_hours",
        "checkin_screen_time_hours",
        "sleep_hours",
        "steps",
    ]

    if combined_rows is not None and len(combined_rows) > 0:
        if _validate_header(combined_rows[0], expected_fields):
            scores["combined_csv_header_correct"] = 1.0

        try:
            produced_dates = [r.get("date", "") for r in combined_rows]
            if set(produced_dates) == set(union_dates):
                scores["combined_csv_dates_complete"] = 1.0
        except Exception:
            pass

        try:
            produced_map = {r.get("date", ""): r for r in combined_rows}
            all_ok = True
            for d in union_dates:
                if d not in produced_map:
                    all_ok = False
                    break
                r = produced_map[d]
                exp = combined_expected.get(d, {})
                for f in expected_fields[1:]:
                    expected_val = exp.get(f)
                    cell = r.get(f, "")
                    got_val = _parse_float_cell(cell)
                    if expected_val is None:
                        if cell is None or str(cell).strip() == "":
                            continue
                        else:
                            all_ok = False
                            break
                    else:
                        if got_val is None:
                            all_ok = False
                            break
                        if not _close(float(expected_val), float(got_val), tol=1e-6):
                            all_ok = False
                            break
                if not all_ok:
                    break
            if all_ok:
                scores["combined_csv_values_correct"] = 1.0
        except Exception:
            pass

    trend_summary_path = workspace / "output" / "reports" / "trend_summary.json"
    ts = None
    if trend_summary_path.exists():
        ts = _load_trend_summary(trend_summary_path)
        if isinstance(ts, dict):
            scores["trend_summary_present"] = 1.0

    if isinstance(ts, dict):
        try:
            ma = ts.get("moving_averages", {})
            exp_ma = expected["moving_averages"]

            def _check_ma(key: str, exp_list: List[Tuple[str, float]]) -> bool:
                obs_list = ma.get(key, [])
                if not isinstance(obs_list, list):
                    return False
                if len(obs_list) != len(exp_list):
                    return False
                obs_map = {}
                for item in obs_list:
                    if not isinstance(item, dict):
                        return False
                    dd = item.get("date")
                    val = item.get("value")
                    if dd is None or val is None:
                        return False
                    obs_map[dd] = float(val)
                for d, v in exp_list:
                    if d not in obs_map:
                        return False
                    if not _close(obs_map[d], v, tol=1e-6):
                        return False
                return True

            ma_ok = (
                _check_ma("headache_7d", exp_ma["headache_7d"]) and
                _check_ma("dizziness_7d", exp_ma["dizziness_7d"]) and
                _check_ma("fatigue_7d", exp_ma["fatigue_7d"])
            )
            if ma_ok:
                scores["moving_averages_correct"] = 1.0
        except Exception:
            pass

        try:
            corr = ts.get("correlations", {})
            exp_corr = expected["correlations"]
            st_h = corr.get("screen_time_vs_headache")
            sl_h = corr.get("sleep_vs_headache")
            corr_ok = (
                st_h is not None and sl_h is not None and
                exp_corr["screen_time_vs_headache"] is not None and
                exp_corr["sleep_vs_headache"] is not None and
                _close(float(st_h), float(exp_corr["screen_time_vs_headache"]), tol=1e-6) and
                _close(float(sl_h), float(exp_corr["sleep_vs_headache"]), tol=1e-6)
            )
            if corr_ok:
                scores["correlations_correct"] = 1.0
        except Exception:
            pass

        try:
            obs_cp = ts.get("change_points", [])
            if isinstance(obs_cp, list):
                obs_cp_set = set([str(x) for x in obs_cp])
                exp_cp_set = set(expected["change_points"])
                if obs_cp_set == exp_cp_set:
                    scores["change_points_correct"] = 1.0
        except Exception:
            pass

        try:
            obs_inc = ts.get("inconsistencies", [])
            if isinstance(obs_inc, list):
                obs_map = {}
                for item in obs_inc:
                    if not isinstance(item, dict):
                        continue
                    dd = item.get("date")
                    diff = item.get("diary_vs_checkin_screen_time_diff")
                    if dd is not None and diff is not None:
                        obs_map[dd] = float(diff)
                exp_list = expected["inconsistencies"]
                exp_map = {e["date"]: e["diary_vs_checkin_screen_time_diff"] for e in exp_list}
                if set(obs_map.keys()) == set(exp_map.keys()):
                    diffs_ok = True
                    for d, v in exp_map.items():
                        if not _close(obs_map[d], v, tol=1e-6):
                            diffs_ok = False
                            break
                    if diffs_ok:
                        scores["inconsistencies_correct"] = 1.0
        except Exception:
            pass

    summary_path = workspace / "output" / "reports" / "summary.md"
    summary_text = _safe_read_text(summary_path) if summary_path.exists() else None
    if summary_text:
        has_sections = (
            "Data coverage" in summary_text and
            "Correlations" in summary_text and
            "Detected change points" in summary_text
        )
        if has_sections:
            scores["summary_md_sections_present"] = 1.0

        try:
            corr_section = _extract_section(summary_text, "Correlations", ["Data coverage", "Detected change points"])
            found_nums = []
            for m in re.finditer(r'[-+]?\d*\.\d+|\d+', corr_section):
                try:
                    found_nums.append(float(m.group(0)))
                except Exception:
                    pass
            exp_st_h = expected["correlations"]["screen_time_vs_headache"]
            exp_sl_h = expected["correlations"]["sleep_vs_headache"]
            corr_match = False
            if exp_st_h is not None and exp_sl_h is not None:
                have_st = any(_close(x, exp_st_h, tol=1e-3) for x in found_nums)
                have_sl = any(_close(x, exp_sl_h, tol=1e-3) for x in found_nums)
                if have_st and have_sl:
                    corr_match = True
            if corr_match:
                scores["summary_md_correlations_match"] = 1.0
        except Exception:
            pass

        try:
            cp_section = _extract_section(summary_text, "Detected change points", ["Data coverage", "Correlations"])
            exp_cps = set(expected["change_points"])
            present_dates = set(re.findall(r'\b\d{4}-\d{2}-\d{2}\b', cp_section))
            if exp_cps.issubset(present_dates):
                scores["summary_md_change_points_match"] = 1.0
        except Exception:
            pass

    return scores


def main() -> None:
    workspace = "."
    if len(sys.argv) >= 2 and sys.argv[1]:
        workspace = sys.argv[1]
    result = grade([], workspace)
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

import json
import csv
import sys
import re
from math import ceil, isfinite
from pathlib import Path
from typing import Optional, Dict, Any, List


def _read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _load_json(path: Path) -> Optional[Dict[str, Any]]:
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _safe_float(val: Any) -> Optional[float]:
    try:
        x = float(val)
        if isfinite(x):
            return x
        return None
    except Exception:
        return None


def _parse_scalar_value(raw: str) -> Any:
    s = raw.strip()
    if s.startswith('"') and s.endswith('"') and len(s) >= 2:
        return s[1:-1]
    if s.lower() == "true":
        return True
    if s.lower() == "false":
        return False
    try:
        if "." in s:
            return float(s)
        return int(s)
    except Exception:
        return s.strip('"')


def _parse_schedule_yaml_text(text: str) -> Optional[Dict[str, Any]]:
    try:
        lines = text.splitlines()
        schedule: Dict[str, Any] = {}
        tasks: List[Dict[str, Any]] = []
        pass_thresholds: Dict[str, Any] = {}

        for line in lines:
            stripped = line.strip()
            if not stripped or stripped.startswith("#"):
                continue
            if re.match(r'^[A-Za-z_]+:', stripped):
                key, rest = stripped.split(":", 1)
                val = rest.strip()
                if key in ("time_zone", "target_release", "hardware_revision", "simulate"):
                    schedule[key] = _parse_scalar_value(val)

        task_start_idx = None
        for idx, line in enumerate(lines):
            if line.strip().startswith("tasks:"):
                task_start_idx = idx + 1
                break
        if task_start_idx is not None:
            i = task_start_idx
            current_task: Optional[Dict[str, Any]] = None
            while i < len(lines):
                line = lines[i]
                stripped = line.strip()
                if not stripped or stripped.startswith("#"):
                    i += 1
                    continue
                if stripped.startswith("pass_thresholds:"):
                    if current_task:
                        tasks.append(current_task)
                        current_task = None
                    break
                m = re.match(r'^\s*-\s+name:\s*(.*)$', line)
                if m:
                    if current_task:
                        tasks.append(current_task)
                    name_raw = m.group(1).strip()
                    name_val = _parse_scalar_value(name_raw)
                    current_task = {"name": name_val}
                    j = i + 1
                    while j < len(lines):
                        l2 = lines[j]
                        s2 = l2.strip()
                        if not s2 or s2.startswith("#"):
                            j += 1
                            continue
                        if re.match(r'^\s*-\s+name:', l2) or s2.startswith("pass_thresholds:") or not l2.startswith("  "):
                            break
                        if "run_at:" in s2:
                            _, rrest = s2.split(":", 1)
                            current_task["run_at"] = _parse_scalar_value(rrest)
                        elif "input_csv:" in s2:
                            _, crest = s2.split(":", 1)
                            current_task["input_csv"] = _parse_scalar_value(crest)
                        j += 1
                    i = j
                    continue
                else:
                    i += 1
                    continue
            if current_task:
                tasks.append(current_task)
        if tasks:
            schedule["tasks"] = tasks

        pass_idx = None
        for idx, line in enumerate(lines):
            if line.strip().startswith("pass_thresholds:"):
                pass_idx = idx + 1
                break
        if pass_idx is not None:
            i = pass_idx
            while i < len(lines):
                line = lines[i]
                if not line.strip() or line.strip().startswith("#"):
                    i += 1
                    continue
                if not line.startswith(" "):
                    break
                s = line.strip()
                if ":" in s:
                    k, rest = s.split(":", 1)
                    pass_thresholds[k.strip()] = _parse_scalar_value(rest)
                i += 1
            schedule["pass_thresholds"] = pass_thresholds

        return schedule
    except Exception:
        return None


def _compute_metrics_from_csv(csv_path: Path) -> Optional[Dict[str, Any]]:
    try:
        with csv_path.open("r", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            latencies: List[float] = []
            throughputs: List[float] = []
            powers: List[float] = []
            for row in reader:
                lat = _safe_float(row.get("latency_ms"))
                thr = _safe_float(row.get("throughput_ops"))
                pwr = _safe_float(row.get("power_mw"))
                if lat is None or thr is None or pwr is None:
                    return None
                latencies.append(lat)
                throughputs.append(thr)
                powers.append(pwr)
        n = len(latencies)
        if n == 0:
            return None
        throughput_mean = sum(throughputs) / n
        power_mean = sum(powers) / n
        lat_sorted = sorted(latencies)
        k = ceil(0.95 * n)
        idx = max(1, k) - 1
        latency_p95 = lat_sorted[idx]
        return {
            "throughput_mean_ops": throughput_mean,
            "latency_p95_ms": latency_p95,
            "power_mean_mw": power_mean,
            "samples": n,
        }
    except Exception:
        return None


def _float_eq(a: float, b: float, tol: float = 1e-6) -> bool:
    return a is not None and b is not None and abs(a - b) <= tol


def _number_strings(x: float) -> List[str]:
    reps = set()
    for nd in (0, 1, 2, 3):
        fmt = f"{{:.{nd}f}}"
        reps.add(fmt.format(x))
    try:
        if abs(x - int(round(x))) < 1e-9:
            reps.add(str(int(round(x))))
    except Exception:
        pass
    reps.add(str(x))
    return list(reps)


def _text_contains_any(text: str, candidates: List[str]) -> bool:
    for c in candidates:
        if c in text:
            return True
    return False


def _count_bullet_action_items(text: str) -> int:
    count = 0
    for line in text.splitlines():
        stripped = line.strip()
        if stripped.startswith("-") or stripped.startswith("*"):
            has_metric = any(tok in stripped.lower() for tok in ["throughput", "latency", "power"])
            has_path = ("out/summary/compare.json" in stripped) or ("out/runs/" in stripped)
            if has_metric and has_path:
                count += 1
    return count


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores: Dict[str, float] = {
        "schedule_updated_target_release": 0.0,
        "schedule_updated_hardware_revision": 0.0,
        "schedule_task_renamed_candidate_rc2": 0.0,
        "schedule_thresholds_updated_values": 0.0,
        "schedule_simulate_true_after_update": 0.0,
        "tools_run_benchmarks_py_exists": 0.0,
        "per_run_metrics_files_present": 0.0,
        "per_run_metrics_content_valid_baseline": 0.0,
        "per_run_metrics_content_valid_candidate": 0.0,
        "summary_compare_exists_and_structure": 0.0,
        "summary_compare_stats_and_deltas_correct": 0.0,
        "summary_compare_thresholds_and_gates_correct": 0.0,
        "meeting_notes_context_includes_release_and_revision": 0.0,
        "meeting_notes_lists_data_sources": 0.0,
        "meeting_notes_results_match_summary": 0.0,
        "meeting_notes_action_items_refer_paths_and_metrics": 0.0,
    }

    schedule_path = workspace / "input" / "schedule.yaml"
    current_csv = workspace / "input" / "current_firmware.csv"
    candidate_csv = workspace / "input" / "candidate_firmware.csv"
    run_script = workspace / "tools" / "run_benchmarks.py"
    summary_path = workspace / "out" / "summary" / "compare.json"
    notes_path = workspace / "docs" / "meeting_notes" / "next_firmware_sync.md"

    schedule_text = _read_text(schedule_path)
    schedule = None
    if schedule_text is not None:
        schedule = _parse_schedule_yaml_text(schedule_text)

    metrics_current = _compute_metrics_from_csv(current_csv) if current_csv.exists() else None
    metrics_candidate = _compute_metrics_from_csv(candidate_csv) if candidate_csv.exists() else None

    if schedule is not None:
        updated_release = schedule.get("target_release") == "v1.2.0-rc2"
        updated_hw = schedule.get("hardware_revision") == "revD"
        tasks = schedule.get("tasks") or []
        renamed = False
        if isinstance(tasks, list) and len(tasks) >= 2:
            names = [t.get("name") for t in tasks]
            renamed = "candidate_rc2" in names
        pt = schedule.get("pass_thresholds") or {}
        try:
            thr_ok = (
                float(pt.get("throughput_mean_ops")) == 1000.0
                and float(pt.get("latency_p95_ms")) == 10.0
                and float(pt.get("power_mean_mw")) == 480.0
            )
        except Exception:
            thr_ok = False

        if updated_release:
            scores["schedule_updated_target_release"] = 1.0
        if updated_hw:
            scores["schedule_updated_hardware_revision"] = 1.0
        if renamed:
            scores["schedule_task_renamed_candidate_rc2"] = 1.0
        if thr_ok:
            scores["schedule_thresholds_updated_values"] = 1.0

        # Only award simulate true if the other required updates are present to avoid credit for pre-existing state
        if updated_release and updated_hw and renamed and thr_ok and schedule.get("simulate") is True:
            scores["schedule_simulate_true_after_update"] = 1.0

    if run_script.exists() and run_script.is_file():
        scores["tools_run_benchmarks_py_exists"] = 1.0

    metrics_files_present = False
    baseline_metrics_ok = False
    candidate_metrics_ok = False
    if schedule is not None and isinstance(schedule.get("tasks"), list) and len(schedule["tasks"]) >= 2:
        baseline_task = None
        candidate_task = None
        for t in schedule["tasks"]:
            if t.get("name") == "current_baseline":
                baseline_task = t
            if t.get("name") == "candidate_rc2":
                candidate_task = t
        if baseline_task and candidate_task:
            baseline_run_at = baseline_task.get("run_at")
            candidate_run_at = candidate_task.get("run_at")
            if isinstance(baseline_run_at, str) and isinstance(candidate_run_at, str):
                expected_baseline_dir = workspace / "out" / "runs" / f"{baseline_task['name']}_{baseline_run_at}"
                expected_candidate_dir = workspace / "out" / "runs" / f"{candidate_task['name']}_{candidate_run_at}"
                baseline_metrics_path = expected_baseline_dir / "metrics.json"
                candidate_metrics_path = expected_candidate_dir / "metrics.json"
                if baseline_metrics_path.exists() and candidate_metrics_path.exists():
                    metrics_files_present = True

                if baseline_metrics_path.exists():
                    mj = _load_json(baseline_metrics_path)
                    if isinstance(mj, dict):
                        stats = mj.get("stats") or {}
                        try:
                            conds = [
                                mj.get("task_name") == "current_baseline",
                                mj.get("firmware_version") == schedule.get("target_release"),
                                mj.get("hardware_revision") == schedule.get("hardware_revision"),
                                mj.get("run_at") == baseline_run_at,
                                mj.get("input_csv") == baseline_task.get("input_csv"),
                                isinstance(stats.get("samples"), int),
                            ]
                            if metrics_current is not None:
                                conds.extend([
                                    _float_eq(float(stats.get("throughput_mean_ops")), metrics_current["throughput_mean_ops"]),
                                    _float_eq(float(stats.get("latency_p95_ms")), metrics_current["latency_p95_ms"]),
                                    _float_eq(float(stats.get("power_mean_mw")), metrics_current["power_mean_mw"]),
                                    int(stats.get("samples")) == metrics_current["samples"],
                                ])
                            baseline_metrics_ok = all(conds)
                        except Exception:
                            baseline_metrics_ok = False

                if candidate_metrics_path.exists():
                    mj = _load_json(candidate_metrics_path)
                    if isinstance(mj, dict):
                        stats = mj.get("stats") or {}
                        try:
                            conds = [
                                mj.get("task_name") == "candidate_rc2",
                                mj.get("firmware_version") == schedule.get("target_release"),
                                mj.get("hardware_revision") == schedule.get("hardware_revision"),
                                mj.get("run_at") == candidate_run_at,
                                mj.get("input_csv") == candidate_task.get("input_csv"),
                                isinstance(stats.get("samples"), int),
                            ]
                            if metrics_candidate is not None:
                                conds.extend([
                                    _float_eq(float(stats.get("throughput_mean_ops")), metrics_candidate["throughput_mean_ops"]),
                                    _float_eq(float(stats.get("latency_p95_ms")), metrics_candidate["latency_p95_ms"]),
                                    _float_eq(float(stats.get("power_mean_mw")), metrics_candidate["power_mean_mw"]),
                                    int(stats.get("samples")) == metrics_candidate["samples"],
                                ])
                            candidate_metrics_ok = all(conds)
                        except Exception:
                            candidate_metrics_ok = False

    if metrics_files_present:
        scores["per_run_metrics_files_present"] = 1.0
    if baseline_metrics_ok:
        scores["per_run_metrics_content_valid_baseline"] = 1.0
    if candidate_metrics_ok:
        scores["per_run_metrics_content_valid_candidate"] = 1.0

    compare = _load_json(summary_path) if summary_path.exists() else None
    summary_structure_ok = False
    summary_stats_ok = False
    summary_thresholds_gates_ok = False

    if isinstance(compare, dict) and schedule is not None:
        try:
            required_top = [
                compare.get("release") == "v1.2.0-rc2",
                compare.get("hardware_revision") == "revD",
                compare.get("time_zone") == schedule.get("time_zone"),
                compare.get("baseline_task") == "current_baseline",
                compare.get("candidate_task") == "candidate_rc2",
                isinstance(compare.get("baseline_stats"), dict),
                isinstance(compare.get("candidate_stats"), dict),
                isinstance(compare.get("deltas"), dict),
                isinstance(compare.get("thresholds"), dict),
                isinstance(compare.get("gates"), dict),
            ]
            summary_structure_ok = all(required_top)
        except Exception:
            summary_structure_ok = False

        if summary_structure_ok and metrics_current is not None and metrics_candidate is not None:
            try:
                bs = compare["baseline_stats"]
                cs = compare["candidate_stats"]
                deltas = compare["deltas"]
                conds_stats = [
                    _float_eq(float(bs.get("throughput_mean_ops")), metrics_current["throughput_mean_ops"]),
                    _float_eq(float(bs.get("latency_p95_ms")), metrics_current["latency_p95_ms"]),
                    _float_eq(float(bs.get("power_mean_mw")), metrics_current["power_mean_mw"]),
                    _float_eq(float(cs.get("throughput_mean_ops")), metrics_candidate["throughput_mean_ops"]),
                    _float_eq(float(cs.get("latency_p95_ms")), metrics_candidate["latency_p95_ms"]),
                    _float_eq(float(cs.get("power_mean_mw")), metrics_candidate["power_mean_mw"]),
                ]
                conds_deltas = [
                    _float_eq(float(deltas.get("throughput_mean_ops")), metrics_candidate["throughput_mean_ops"] - metrics_current["throughput_mean_ops"]),
                    _float_eq(float(deltas.get("latency_p95_ms")), metrics_candidate["latency_p95_ms"] - metrics_current["latency_p95_ms"]),
                    _float_eq(float(deltas.get("power_mean_mw")), metrics_candidate["power_mean_mw"] - metrics_current["power_mean_mw"]),
                ]
                summary_stats_ok = all(conds_stats + conds_deltas)
            except Exception:
                summary_stats_ok = False

        if summary_structure_ok:
            try:
                thr = compare["thresholds"]
                thr_ok = (
                    float(thr.get("throughput_mean_ops_min")) == 1000.0
                    and float(thr.get("latency_p95_ms_max")) == 10.0
                    and float(thr.get("power_mean_mw_max")) == 480.0
                )
                gates = compare["gates"]
                cs = compare.get("candidate_stats") or {}
                c_thr = _safe_float(cs.get("throughput_mean_ops"))
                c_lat = _safe_float(cs.get("latency_p95_ms"))
                c_pwr = _safe_float(cs.get("power_mean_mw"))
                g_thr = "PASS" if (c_thr is not None and c_thr >= 1000.0) else "FAIL"
                g_lat = "PASS" if (c_lat is not None and c_lat <= 10.0) else "FAIL"
                g_pwr = "PASS" if (c_pwr is not None and c_pwr <= 480.0) else "FAIL"
                gates_ok = (
                    isinstance(gates, dict)
                    and gates.get("throughput_mean_ops") == g_thr
                    and gates.get("latency_p95_ms") == g_lat
                    and gates.get("power_mean_mw") == g_pwr
                )
                summary_thresholds_gates_ok = thr_ok and gates_ok
            except Exception:
                summary_thresholds_gates_ok = False

    if summary_structure_ok:
        scores["summary_compare_exists_and_structure"] = 1.0
    if summary_stats_ok:
        scores["summary_compare_stats_and_deltas_correct"] = 1.0
    if summary_thresholds_gates_ok:
        scores["summary_compare_thresholds_and_gates_correct"] = 1.0

    notes_text = _read_text(notes_path) if notes_path.exists() else None
    if notes_text:
        has_release = "v1.2.0-rc2" in notes_text
        has_hw = "revD" in notes_text
        if has_release and has_hw:
            scores["meeting_notes_context_includes_release_and_revision"] = 1.0

        has_current_csv = "input/current_firmware.csv" in notes_text
        has_candidate_csv = "input/candidate_firmware.csv" in notes_text
        if has_current_csv and has_candidate_csv:
            scores["meeting_notes_lists_data_sources"] = 1.0

        results_ok = False
        if isinstance(compare, dict) and metrics_current and metrics_candidate:
            try:
                has_metric_tokens = all(tok in notes_text for tok in ["throughput_mean_ops", "latency_p95_ms", "power_mean_mw"])
                tb = metrics_current["throughput_mean_ops"]
                tc = metrics_candidate["throughput_mean_ops"]
                lb = metrics_current["latency_p95_ms"]
                lc = metrics_candidate["latency_p95_ms"]
                pb = metrics_current["power_mean_mw"]
                pc = metrics_candidate["power_mean_mw"]
                dt = tc - tb
                dl = lc - lb
                dp = pc - pb

                def num_in_text(x: float) -> bool:
                    return _text_contains_any(notes_text, _number_strings(x))

                baseline_nums_ok = num_in_text(tb) and num_in_text(lb) and num_in_text(pb)
                candidate_nums_ok = num_in_text(tc) and num_in_text(lc) and num_in_text(pc)
                deltas_ok = num_in_text(dt) and num_in_text(dl) and num_in_text(dp)

                gate_vals = list((compare.get("gates") or {}).values())
                pass_needed = sum(1 for g in gate_vals if g == "PASS")
                fail_needed = sum(1 for g in gate_vals if g == "FAIL")
                pass_count = notes_text.count("PASS")
                fail_count = notes_text.count("FAIL")

                gates_words_ok = (pass_count >= pass_needed) and (fail_count >= fail_needed)

                results_ok = has_metric_tokens and baseline_nums_ok and candidate_nums_ok and deltas_ok and gates_words_ok
            except Exception:
                results_ok = False
        if results_ok:
            scores["meeting_notes_results_match_summary"] = 1.0

        bullets = _count_bullet_action_items(notes_text)
        if bullets >= 3:
            scores["meeting_notes_action_items_refer_paths_and_metrics"] = 1.0

    return scores


