import json
import sys
import csv
import re
from pathlib import Path
from typing import List, Dict, Tuple, Optional


def _safe_read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _safe_read_csv(path: Path) -> Tuple[Optional[List[str]], Optional[List[Dict[str, str]]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.reader(f)
            rows = list(reader)
        if not rows:
            return None, None
        header = rows[0]
        data = []
        for r in rows[1:]:
            if len(r) != len(header):
                return None, None
            data.append({header[i]: r[i] for i in range(len(header))})
        return header, data
    except Exception:
        return None, None


def _parse_numeric_row(row: Dict[str, str]) -> Optional[Dict[str, object]]:
    try:
        parsed = dict(row)
        parsed["impressions"] = int(row["impressions"])
        parsed["ctr"] = float(row["ctr"])
        parsed["avg_position"] = float(row["avg_position"])
        return parsed
    except Exception:
        return None


def _compute_expected_filtered_sorted(rows: List[Dict[str, object]]) -> List[Dict[str, object]]:
    expected = []
    for r in rows:
        try:
            city = str(r["city"])
            impressions = int(r["impressions"])
            ctr = float(r["ctr"])
            avg_position = float(r["avg_position"])
        except Exception:
            continue
        if city == "Kansas City" and impressions >= 100 and ctr < 0.10 and 3.0 <= avg_position <= 15.0:
            opportunity_score = impressions * (0.10 - ctr)
            rr = dict(r)
            rr["opportunity_score"] = float(opportunity_score)
            expected.append(rr)
    expected.sort(key=lambda x: (-x["opportunity_score"], x.get("file_name", "")))
    return expected


def _safe_parse_yaml_site(path: Path) -> Optional[Dict[str, object]]:
    text = _safe_read_text(path)
    if text is None:
        return None
    brand = None
    city = None
    target_terms: List[str] = []
    in_list = False
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if re.match(r"^[A-Za-z0-9_\-]+:\s*$", stripped):
            key = stripped[:-1].strip()
            if key == "target_terms":
                in_list = True
                continue
            else:
                in_list = False
        if in_list:
            m = re.match(r"^-\s*(.+)$", stripped)
            if m:
                target_terms.append(m.group(1).strip())
            continue
        m = re.match(r"^([A-Za-z0-9_\-]+):\s*(.+)$", stripped)
        if m:
            k = m.group(1).strip()
            v = m.group(2).strip().strip('"').strip("'")
            if k == "brand":
                brand = v
            elif k == "city":
                city = v
            elif k == "target_terms":
                pass
    if brand is None or city is None:
        return None
    return {"brand": brand, "city": city, "target_terms": target_terms}


def _extract_title(text: str) -> Optional[str]:
    m = re.search(r"<title>(.*?)</title>", text, flags=re.IGNORECASE | re.DOTALL)
    if not m:
        return None
    return m.group(1).strip()


def _find_meta_description_tags(text: str) -> List[str]:
    return re.findall(r"<meta\b[^>]*\bname=[\"']description[\"'][^>]*>", text, flags=re.IGNORECASE)


def _extract_meta_description_content(text: str) -> Optional[str]:
    m = re.search(r"<meta\b[^>]*\bname=[\"']description[\"'][^>]*>", text, flags=re.IGNORECASE)
    if not m:
        return None
    tag = m.group(0)
    m2 = re.search(r"content\s*=\s*([\"'])(.*?)\1", tag, flags=re.IGNORECASE | re.DOTALL)
    if not m2:
        return None
    return m2.group(2)


def _normalize_html_excluding_title_and_meta(text: str) -> Optional[str]:
    try:
        text2 = re.sub(r"(<title>)(.*?)(</title>)", r"\1TITLE\3", text, flags=re.IGNORECASE | re.DOTALL, count=1)
        def _replace_meta(match: re.Match) -> str:
            tag = match.group(0)
            m2 = re.search(r"(content\s*=\s*)([\"'])(.*?)(\2)", tag, flags=re.IGNORECASE | re.DOTALL)
            if not m2:
                return tag
            start, end = m2.start(3), m2.end(3)
            new_tag = tag[:start] + "DESC" + tag[end:]
            return new_tag
        text3 = re.sub(r"<meta\b[^>]*\bname=[\"']description[\"'][^>]*>", _replace_meta, text2, flags=re.IGNORECASE, count=1)
        return text3
    except Exception:
        return None


def _parse_ranked_output(path: Path) -> Tuple[Optional[List[str]], Optional[List[Dict[str, object]]]]:
    header, raw_rows = _safe_read_csv(path)
    if header is None or raw_rows is None:
        return None, None
    parsed_rows: List[Dict[str, object]] = []
    for r in raw_rows:
        p = _parse_numeric_row(r)
        if p is None:
            return header, None
        try:
            p["opportunity_score"] = float(r["opportunity_score"])
        except Exception:
            return header, None
        parsed_rows.append(p)
    return header, parsed_rows


def _floats_close(a: float, b: float, tol: float = 1e-6) -> bool:
    return abs(a - b) <= tol


def _format_score_variants(val: float) -> List[str]:
    variants = set()
    try:
        variants.add(f"{val}")
        variants.add(f"{val:.1f}")
        variants.add(f"{val:.2f}")
        variants.add(f"{val:.0f}")
    except Exception:
        pass
    return list(variants)


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "ranked_csv_exists_and_columns": 0.0,
        "ranked_csv_filter_and_sort_correct": 0.0,
        "optimized_pages_top5_only": 0.0,
        "optimized_titles_valid": 0.0,
        "optimized_meta_valid": 0.0,
        "optimized_preserve_structure": 0.0,
        "owner_update_summary_sentences": 0.0,
        "owner_update_page_bullets": 0.0,
        "owner_update_next_steps": 0.0,
    }

    input_csv_path = workspace / "input" / "pages.csv"
    input_pages_dir = workspace / "input" / "pages"
    site_yaml_path = workspace / "input" / "site.yaml"
    output_ranked_path = workspace / "output" / "ranked_pages.csv"
    output_optimized_dir = workspace / "output" / "optimized_pages"
    owner_update_path = workspace / "output" / "owner_update.md"

    expected_header = ["file_name", "url_path", "city", "impressions", "ctr", "avg_position", "primary_keyword", "opportunity_score"]
    out_header, _ = _safe_read_csv(output_ranked_path)
    if out_header is not None and out_header == expected_header:
        scores["ranked_csv_exists_and_columns"] = 1.0

    in_header, in_rows_raw = _safe_read_csv(input_csv_path)
    expected_sorted: List[Dict[str, object]] = []
    input_rows_parsed: List[Dict[str, object]] = []
    if in_header is not None and in_rows_raw is not None:
        ok = True
        for r in in_rows_raw:
            p = _parse_numeric_row(r)
            if p is None:
                ok = False
                break
            input_rows_parsed.append(p)
        if ok:
            expected_sorted = _compute_expected_filtered_sorted(input_rows_parsed)

    out_header2, out_rows_parsed = _parse_ranked_output(output_ranked_path)
    if expected_sorted and out_header2 == expected_header and out_rows_parsed is not None:
        if len(out_rows_parsed) == len(expected_sorted):
            # Validate set equality by file_name and field correctness
            expected_by_file = {str(e["file_name"]): e for e in expected_sorted}
            values_ok = True
            for o in out_rows_parsed:
                fname = str(o.get("file_name", ""))
                if fname not in expected_by_file:
                    values_ok = False
                    break
                e = expected_by_file[fname]
                for f in ["file_name", "url_path", "city", "primary_keyword"]:
                    if str(o.get(f, "")) != str(e.get(f, "")):
                        values_ok = False
                        break
                if not values_ok:
                    break
                try:
                    if int(o.get("impressions", -1)) != int(e.get("impressions", -2)):
                        values_ok = False
                        break
                    if not _floats_close(float(o.get("ctr", 0.0)), float(e.get("ctr", 1.0))):
                        values_ok = False
                        break
                    if not _floats_close(float(o.get("avg_position", 0.0)), float(e.get("avg_position", 1.0))):
                        values_ok = False
                        break
                    recomputed = int(e["impressions"]) * (0.10 - float(e["ctr"]))
                    if not _floats_close(float(o.get("opportunity_score", -9999.0)), recomputed):
                        values_ok = False
                        break
                except Exception:
                    values_ok = False
                    break
            # Validate non-increasing order by opportunity_score
            non_increasing = True
            prev = None
            for o in out_rows_parsed:
                try:
                    cur = float(o["opportunity_score"])
                except Exception:
                    non_increasing = False
                    break
                if prev is not None and cur > prev + 1e-9:
                    non_increasing = False
                    break
                prev = cur
            if values_ok and non_increasing:
                scores["ranked_csv_filter_and_sort_correct"] = 1.0

    top5_files: List[str] = []
    if expected_sorted:
        top5_files = [str(r["file_name"]) for r in expected_sorted[:5]]

    if top5_files:
        if output_optimized_dir.exists() and output_optimized_dir.is_dir():
            produced_files = sorted([p.name for p in output_optimized_dir.glob("*.html")])
            if sorted(produced_files) == sorted(top5_files):
                scores["optimized_pages_top5_only"] = 1.0

    site_info = _safe_parse_yaml_site(site_yaml_path)

    originals: Dict[str, Dict[str, object]] = {}
    if input_pages_dir.exists():
        for p in input_pages_dir.glob("*.html"):
            content = _safe_read_text(p)
            if content is None:
                continue
            title = _extract_title(content)
            meta = _extract_meta_description_content(content)
            originals[p.name] = {"text": content, "title": title, "meta": meta}

    titles_valid = True
    if site_info is not None and top5_files and output_optimized_dir.exists():
        brand = site_info.get("brand", "")
        for r in expected_sorted[:5]:
            fname = str(r["file_name"])
            primary_kw = str(r.get("primary_keyword", ""))
            out_path = output_optimized_dir / fname
            in_original = originals.get(fname)
            out_text = _safe_read_text(out_path)
            if in_original is None or out_text is None:
                titles_valid = False
                break
            orig_title = in_original.get("title")
            new_title = _extract_title(out_text)
            if new_title is None:
                titles_valid = False
                break
            if len(new_title) > 60:
                titles_valid = False
                break
            if primary_kw not in new_title:
                titles_valid = False
                break
            if brand not in new_title:
                titles_valid = False
                break
            if orig_title is None or new_title == orig_title:
                titles_valid = False
                break
    else:
        titles_valid = False
    if titles_valid:
        scores["optimized_titles_valid"] = 1.0

    meta_valid = True
    if site_info is not None and top5_files and output_optimized_dir.exists():
        city_required = "Kansas City"
        target_terms = [str(t) for t in site_info.get("target_terms", [])]
        allowed_ctas = ["Order now", "Book today", "Call us", "Learn more"]
        for r in expected_sorted[:5]:
            fname = str(r["file_name"])
            out_path = output_optimized_dir / fname
            out_text = _safe_read_text(out_path)
            if out_text is None:
                meta_valid = False
                break
            tags = _find_meta_description_tags(out_text)
            if len(tags) != 1:
                meta_valid = False
                break
            meta_desc = _extract_meta_description_content(out_text)
            if meta_desc is None:
                meta_valid = False
                break
            desc = meta_desc.strip()
            if not (120 <= len(desc) <= 160):
                meta_valid = False
                break
            if city_required not in desc:
                meta_valid = False
                break
            has_term = any(t.lower() in desc.lower() for t in target_terms)
            if not has_term:
                meta_valid = False
                break
            if not any(desc.endswith(cta) for cta in allowed_ctas):
                meta_valid = False
                break
    else:
        meta_valid = False
    if meta_valid:
        scores["optimized_meta_valid"] = 1.0

    preserve_ok = True
    if top5_files and output_optimized_dir.exists():
        for fname in top5_files:
            in_info = originals.get(fname)
            out_text = _safe_read_text(output_optimized_dir / fname)
            if in_info is None or out_text is None:
                preserve_ok = False
                break
            in_text = in_info.get("text")
            if not isinstance(in_text, str):
                preserve_ok = False
                break
            norm_in = _normalize_html_excluding_title_and_meta(in_text)
            norm_out = _normalize_html_excluding_title_and_meta(out_text)
            if norm_in is None or norm_out is None:
                preserve_ok = False
                break
            if norm_in != norm_out:
                preserve_ok = False
                break
    else:
        preserve_ok = False
    if preserve_ok:
        scores["optimized_preserve_structure"] = 1.0

    update_text = _safe_read_text(owner_update_path)
    if update_text is not None:
        lines = update_text.splitlines()
        para_lines = []
        for ln in lines:
            if ln.strip() == "":
                break
            para_lines.append(ln)
        paragraph = " ".join(para_lines).strip()
        if paragraph:
            cleaned = re.sub(r"[\-\*\•]\s+", " ", paragraph)
            parts = re.split(r"[.!?]+", cleaned)
            sentence_count = len([p for p in parts if p.strip() != ""])
            if 4 <= sentence_count <= 6:
                scores["owner_update_summary_sentences"] = 1.0

        bullets_ok = True
        if top5_files:
            opportunity_map: Dict[str, float] = {}
            orig_title_len: Dict[str, int] = {}
            new_title_len: Dict[str, int] = {}
            orig_meta_len: Dict[str, int] = {}
            new_meta_len: Dict[str, int] = {}
            for r in expected_sorted[:5]:
                fname = str(r["file_name"])
                opportunity_map[fname] = float(r["impressions"]) * (0.10 - float(r["ctr"]))
                in_info = originals.get(fname, {})
                o_title = in_info.get("title") if in_info else None
                o_meta = in_info.get("meta") if in_info else None
                if not isinstance(o_title, str) or not isinstance(o_meta, str):
                    bullets_ok = False
                    break
                orig_title_len[fname] = len(o_title)
                orig_meta_len[fname] = len(o_meta)
                out_text_f = _safe_read_text(output_optimized_dir / fname)
                if out_text_f is None:
                    bullets_ok = False
                    break
                n_title = _extract_title(out_text_f)
                n_meta = _extract_meta_description_content(out_text_f)
                if n_title is None or n_meta is None:
                    bullets_ok = False
                    break
                new_title_len[fname] = len(n_title)
                new_meta_len[fname] = len(n_meta)
            bullet_lines = [ln for ln in lines if ln.lstrip().startswith("- ") or ln.lstrip().startswith("* ")]
            for fname in top5_files:
                found = False
                for bl in bullet_lines:
                    if fname in bl:
                        variants = _format_score_variants(opportunity_map[fname])
                        has_score = any(v in bl for v in variants)
                        ot = str(orig_title_len.get(fname, -1))
                        nt = str(new_title_len.get(fname, -1))
                        om = str(orig_meta_len.get(fname, -1))
                        nm = str(new_meta_len.get(fname, -1))
                        has_lens = (ot in bl and nt in bl and om in bl and nm in bl)
                        if has_score and has_lens:
                            found = True
                            break
                if not found:
                    bullets_ok = False
                    break
        else:
            bullets_ok = False
        if bullets_ok:
            scores["owner_update_page_bullets"] = 1.0

        next_steps_ok = False
        idx = -1
        for i, ln in enumerate(lines):
            if re.search(r"\bNext steps\b", ln, flags=re.IGNORECASE):
                idx = i
                break
        if idx >= 0:
            cnt = 0
            for j in range(idx + 1, len(lines)):
                ln = lines[j]
                if ln.strip() == "":
                    if cnt > 0:
                        break
                    else:
                        continue
                if ln.lstrip().startswith("- ") or ln.lstrip().startswith("* "):
                    cnt += 1
                else:
                    if cnt > 0:
                        break
                    else:
                        continue
            if cnt == 3:
                next_steps_ok = True
        if next_steps_ok:
            scores["owner_update_next_steps"] = 1.0

    return scores


def main() -> None:
    workspace_path = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace_path)
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

import csv
import json
import math
import sys
from pathlib import Path
from typing import List, Dict, Optional, Tuple


def _read_csv(path: Path) -> Tuple[Optional[List[str]], Optional[List[Dict[str, str]]]]:
    try:
        with path.open("r", newline="", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            if reader.fieldnames is None:
                return None, None
            rows = [dict(row) for row in reader]
            return reader.fieldnames, rows
    except Exception:
        return None, None


def _to_float(val: str) -> Optional[float]:
    try:
        return float(val)
    except Exception:
        return None


def _to_int(val: str) -> Optional[int]:
    try:
        return int(val)
    except Exception:
        try:
            return int(float(val))
        except Exception:
            return None


def _format_num(x: float) -> str:
    # Always format to two decimals
    return f"{x:.2f}"


def _median(values: List[float]) -> float:
    n = len(values)
    if n == 0:
        return 0.0
    s = sorted(values)
    mid = n // 2
    if n % 2 == 1:
        return float(s[mid])
    else:
        return float((s[mid - 1] + s[mid]) / 2.0)


def _compute_practice_summary(workspace: Path) -> Optional[List[Dict[str, str]]]:
    # Read input
    in_path = workspace / "input" / "practice_log.csv"
    header, rows = _read_csv(in_path)
    if header is None or rows is None:
        return None

    # Validate necessary columns
    required_cols = {"exercise", "minutes", "bpm", "errors", "take_type", "valid"}
    if not required_cols.issubset(set(header)):
        return None

    # Filter rows: valid == 1 and take_type == "practice"
    filtered = []
    for r in rows:
        v = _to_int(r.get("valid", ""))
        if v != 1:
            continue
        if r.get("take_type", "") != "practice":
            continue
        minutes = _to_float(r.get("minutes", ""))
        bpm = _to_float(r.get("bpm", ""))
        errors = _to_int(r.get("errors", ""))
        exercise = r.get("exercise", "")
        if minutes is None or bpm is None or errors is None or exercise == "":
            continue
        filtered.append({
            "exercise": exercise,
            "minutes": minutes,
            "bpm": bpm,
            "errors": errors,
        })

    # Group by exercise
    groups: Dict[str, Dict[str, float]] = {}
    bpm_lists: Dict[str, List[float]] = {}
    counts: Dict[str, int] = {}
    for row in filtered:
        ex = row["exercise"]
        groups.setdefault(ex, {"total_minutes": 0.0, "total_errors": 0.0, "sum_bpm": 0.0})
        bpm_lists.setdefault(ex, [])
        counts.setdefault(ex, 0)
        groups[ex]["total_minutes"] += float(row["minutes"])
        groups[ex]["total_errors"] += float(row["errors"])
        groups[ex]["sum_bpm"] += float(row["bpm"])
        bpm_lists[ex].append(float(row["bpm"]))
        counts[ex] += 1

    # Build summary rows
    results: List[Dict[str, str]] = []
    for ex, agg in groups.items():
        takes = counts.get(ex, 0)
        if takes <= 0:
            continue
        total_minutes = agg["total_minutes"]
        sum_bpm = agg["sum_bpm"]
        bpms = bpm_lists.get(ex, [])
        avg_bpm = sum_bpm / takes if takes > 0 else 0.0
        median_bpm = _median(bpms)
        max_bpm = max(bpms) if bpms else 0.0
        total_errors = agg["total_errors"]
        avg_errors_per_min = (total_errors / total_minutes) if total_minutes > 0 else 0.0

        results.append({
            "exercise": ex,
            "total_minutes": _format_num(total_minutes),
            "takes": _format_num(float(takes)),
            "avg_bpm": _format_num(avg_bpm),
            "median_bpm": _format_num(median_bpm),
            "max_bpm": _format_num(max_bpm),
            "total_errors": _format_num(total_errors),
            "avg_errors_per_min": _format_num(avg_errors_per_min),
        })

    # Sort by avg_errors_per_min desc, then exercise asc
    def sort_key(d: Dict[str, str]):
        return (-float(d["avg_errors_per_min"]), d["exercise"])

    results.sort(key=sort_key)
    return results


def _compute_song_timing_summary(workspace: Path) -> Optional[List[Dict[str, str]]]:
    cat_path = workspace / "input" / "songs_catalog.csv"
    meas_path = workspace / "input" / "song_bpm_measurements.csv"
    cat_header, cat_rows = _read_csv(cat_path)
    meas_header, meas_rows = _read_csv(meas_path)
    if cat_header is None or cat_rows is None or meas_header is None or meas_rows is None:
        return None

    # Validate columns
    if not {"song", "target_bpm"}.issubset(set(cat_header)):
        return None
    if not {"song", "take_id", "bar", "bpm", "valid"}.issubset(set(meas_header)):
        return None

    # Build catalog map
    catalog: Dict[str, float] = {}
    for r in cat_rows:
        song = r.get("song", "")
        target_bpm = _to_float(r.get("target_bpm", ""))
        if song == "" or target_bpm is None:
            continue
        catalog[song] = target_bpm

    # Filter measurements: valid == 1 and song in catalog
    by_song_bpms: Dict[str, List[float]] = {}
    by_song_takes: Dict[str, set] = {}
    for r in meas_rows:
        v = _to_int(r.get("valid", ""))
        if v != 1:
            continue
        song = r.get("song", "")
        if song not in catalog:
            continue
        bpm = _to_float(r.get("bpm", ""))
        take_id = r.get("take_id", "")
        if bpm is None or take_id == "":
            continue
        by_song_bpms.setdefault(song, []).append(float(bpm))
        by_song_takes.setdefault(song, set()).add(take_id)

    # Build summary
    results: List[Dict[str, str]] = []
    for song, bpms in by_song_bpms.items():
        N = len(bpms)
        if N <= 0:
            continue
        mean_bpm = sum(bpms) / N
        # population standard deviation
        variance = sum((x - mean_bpm) ** 2 for x in bpms) / N
        std_bpm = math.sqrt(variance)
        target_bpm = catalog[song]
        mean_abs_dev = sum(abs(x - target_bpm) for x in bpms) / N
        timing_risk = std_bpm + mean_abs_dev
        bars_count = N
        takes_count = len(by_song_takes.get(song, set()))
        results.append({
            "song": song,
            "target_bpm": _format_num(target_bpm),
            "mean_bpm": _format_num(mean_bpm),
            "std_bpm": _format_num(std_bpm),
            "mean_abs_deviation": _format_num(mean_abs_dev),
            "timing_risk_score": _format_num(timing_risk),
            "bars_count": _format_num(float(bars_count)),
            "takes_count": _format_num(float(takes_count)),
        })

    # Sort by timing_risk_score desc; tie by song asc
    def sort_key(d: Dict[str, str]):
        return (-float(d["timing_risk_score"]), d["song"])

    results.sort(key=sort_key)
    return results


def _compute_focus_shortlists(
    practice_summary: Optional[List[Dict[str, str]]],
    song_timing_summary: Optional[List[Dict[str, str]]],
) -> Tuple[Optional[List[Dict[str, str]]], Optional[List[Dict[str, str]]]]:
    top_exercises = None
    if practice_summary is not None:
        # Already sorted by avg_errors_per_min desc then exercise asc
        top_exercises = []
        for row in practice_summary[:3]:
            top_exercises.append({
                "exercise": row["exercise"],
                "avg_errors_per_min": row["avg_errors_per_min"],
                "total_minutes": row["total_minutes"],
            })

    top_songs = None
    if song_timing_summary is not None:
        # Already sorted by timing_risk_score desc then song asc
        top_songs = []
        for row in song_timing_summary[:3]:
            top_songs.append({
                "song": row["song"],
                "timing_risk_score": row["timing_risk_score"],
                "std_bpm": row["std_bpm"],
                "mean_abs_deviation": row["mean_abs_deviation"],
            })

    return top_exercises, top_songs


def _read_output_csv(path: Path) -> Tuple[Optional[List[str]], Optional[List[List[str]]]]:
    # Returns (header, rows as list of list of strings in header order)
    header, rows = _read_csv(path)
    if header is None or rows is None:
        return None, None
    ordered_rows: List[List[str]] = []
    for r in rows:
        ordered_rows.append([r.get(col, "") for col in header])
    return header, ordered_rows


def _rows_from_dicts(dict_rows: List[Dict[str, str]], columns: List[str]) -> List[List[str]]:
    out = []
    for d in dict_rows:
        out.append([d.get(c, "") for c in columns])
    return out


def _compare_rows(expected: List[List[str]], actual: List[List[str]]) -> bool:
    if len(expected) != len(actual):
        return False
    for e_row, a_row in zip(expected, actual):
        if len(e_row) != len(a_row):
            return False
        for ev, av in zip(e_row, a_row):
            if ev != av:
                return False
    return True


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "practice_summary_structure": 0.0,
        "practice_summary_content": 0.0,
        "song_timing_summary_structure": 0.0,
        "song_timing_summary_content": 0.0,
        "top_exercises_structure": 0.0,
        "top_exercises_content": 0.0,
        "top_songs_structure": 0.0,
        "top_songs_content": 0.0,
        "analyze_script_present": 0.0,
        "analyze_script_cli_flags": 0.0,
    }

    # Expected columns
    practice_cols = [
        "exercise", "total_minutes", "takes", "avg_bpm", "median_bpm", "max_bpm", "total_errors", "avg_errors_per_min"
    ]
    song_cols = [
        "song", "target_bpm", "mean_bpm", "std_bpm", "mean_abs_deviation", "timing_risk_score", "bars_count", "takes_count"
    ]
    top_ex_cols = ["exercise", "avg_errors_per_min", "total_minutes"]
    top_song_cols = ["song", "timing_risk_score", "std_bpm", "mean_abs_deviation"]

    # Compute expected from inputs
    expected_practice = _compute_practice_summary(workspace)
    expected_song = _compute_song_timing_summary(workspace)
    expected_top_ex, expected_top_song = _compute_focus_shortlists(expected_practice, expected_song)

    # Paths to outputs
    practice_out = workspace / "output" / "practice_summary.csv"
    song_out = workspace / "output" / "song_timing_summary.csv"
    top_ex_out = workspace / "output" / "top_exercises_by_errors.csv"
    top_song_out = workspace / "output" / "top_songs_by_timing_risk.csv"

    # Check practice_summary.csv
    p_header, p_rows = _read_output_csv(practice_out)
    if p_header is not None and p_rows is not None and p_header == practice_cols:
        scores["practice_summary_structure"] = 1.0
        if expected_practice is not None:
            expected_rows = _rows_from_dicts(expected_practice, practice_cols)
            if _compare_rows(expected_rows, p_rows):
                scores["practice_summary_content"] = 1.0

    # Check song_timing_summary.csv
    s_header, s_rows = _read_output_csv(song_out)
    if s_header is not None and s_rows is not None and s_header == song_cols:
        scores["song_timing_summary_structure"] = 1.0
        if expected_song is not None:
            expected_rows = _rows_from_dicts(expected_song, song_cols)
            if _compare_rows(expected_rows, s_rows):
                scores["song_timing_summary_content"] = 1.0

    # Check top_exercises_by_errors.csv
    te_header, te_rows = _read_output_csv(top_ex_out)
    if te_header is not None and te_rows is not None and te_header == top_ex_cols:
        scores["top_exercises_structure"] = 1.0
        if expected_top_ex is not None:
            expected_rows = _rows_from_dicts(expected_top_ex, top_ex_cols)
            if _compare_rows(expected_rows, te_rows):
                scores["top_exercises_content"] = 1.0

    # Check top_songs_by_timing_risk.csv
    ts_header, ts_rows = _read_output_csv(top_song_out)
    if ts_header is not None and ts_rows is not None and ts_header == top_song_cols:
        scores["top_songs_structure"] = 1.0
        if expected_top_song is not None:
            expected_rows = _rows_from_dicts(expected_top_song, top_song_cols)
            if _compare_rows(expected_rows, ts_rows):
                scores["top_songs_content"] = 1.0

    # Check analyze_practice.py existence and CLI flags
    script_path = workspace / "analyze_practice.py"
    if script_path.exists() and script_path.is_file():
        scores["analyze_script_present"] = 1.0
        try:
            content = script_path.read_text(encoding="utf-8", errors="ignore")
            required_flags = ["--practice", "--catalog", "--measurements", "--outdir"]
            if all(flag in content for flag in required_flags):
                scores["analyze_script_cli_flags"] = 1.0
        except Exception:
            pass

    return scores


def main() -> None:
    workspace = "."
    if len(sys.argv) >= 2 and sys.argv[1]:
        workspace = sys.argv[1]
    result = grade([], workspace)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

