import json
import os
import sys
import csv
from decimal import Decimal, ROUND_HALF_UP

def get_workspace_root():
    return sys.argv[1] if len(sys.argv) > 1 else "/root/.openclaw/workspace"

def d2(x):
    """Quantize Decimal to exactly 2 decimals with half up rounding."""
    if not isinstance(x, Decimal):
        x = Decimal(str(x))
    return x.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

def parse_decimal_maybe(value):
    """Parse numeric or numeric string to Decimal; return None if invalid."""
    if value is None:
        return None
    try:
        return Decimal(str(value))
    except Exception:
        return None

def parse_rate_to_decimal(rate):
    """Parse rate which may be a string like '4.5%' or numeric; returns Decimal or None."""
    if rate is None:
        return None
    if isinstance(rate, str):
        s = rate.strip()
        if s.endswith("%"):
            s = s[:-1].strip()
        if not s:
            return None
        try:
            return Decimal(s)
        except Exception:
            return None
    try:
        return Decimal(str(rate))
    except Exception:
        return None

def format_rate_str(rate_dec):
    """Format Decimal percentage with exactly two decimals and a percent sign."""
    return f"{d2(rate_dec):.2f}%"

def is_valid_affiliate_url(url):
    return isinstance(url, str) and url.lower().startswith("http")

def read_input_catalog(input_path):
    try:
        with open(input_path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        return []
    if isinstance(data, dict):
        if isinstance(data.get("queries"), list):
            return data["queries"]
        elif isinstance(data.get("data"), list):
            return data["data"]
        else:
            # Single query dict?
            if "keywords" in data and isinstance(data.get("results"), list):
                return [data]
            return []
    if isinstance(data, list):
        return data
    return []

def normalize_product(prod):
    # Title
    title = prod.get("title", "")
    # Price
    price_raw = prod.get("price")
    price_dec = parse_decimal_maybe(price_raw)
    if price_dec is None or price_dec <= 0:
        return None
    # Affiliate URL
    affiliate_url = prod.get("affiliateUrl")
    if not is_valid_affiliate_url(affiliate_url):
        return None
    # Shop
    shop = prod.get("shop") or {}
    shop_name = shop.get("name")
    shop_domain = shop.get("domain")
    if not (isinstance(shop_name, str) and shop_name.strip()) or not (isinstance(shop_domain, str) and shop_domain.strip()):
        return None

    # Cashback
    cb = prod.get("cashback") or {}
    rate_dec = parse_rate_to_decimal(cb.get("rate"))
    amount_dec = parse_decimal_maybe(cb.get("amount"))
    # Compute missing fields
    if amount_dec is None and rate_dec is not None:
        # amount = price * rate / 100
        amount_dec = d2(price_dec * rate_dec / Decimal("100"))
    elif rate_dec is None and amount_dec is not None:
        # rate = amount / price * 100
        rate_dec = d2((amount_dec / price_dec) * Decimal("100"))
    elif amount_dec is None and rate_dec is None:
        amount_dec = Decimal("0")
        rate_dec = Decimal("0")

    amount_dec = d2(amount_dec)
    rate_str = format_rate_str(rate_dec)

    effective_price = d2(price_dec - amount_dec)

    return {
        "title": str(title),
        "shop_name": str(shop_name),
        "shop_domain": str(shop_domain),
        "price_dec": price_dec,  # original price as Decimal
        "price_str": f"{d2(price_dec):.2f}",
        "cashback_amount_dec": amount_dec,
        "cashback_amount_str": f"{amount_dec:.2f}",
        "cashback_rate_str": rate_str,
        "effective_price_dec": effective_price,
        "effective_price_str": f"{effective_price:.2f}",
        "affiliate_url": affiliate_url,
    }

def compute_expected(catalog_queries):
    expected_rows = []  # list of dicts for CSV rows
    summary_queries = []  # list of per-query summaries
    all_valid_products = []  # list of tuples (query_str, normalized_prod)

    for q in catalog_queries:
        query_str = q.get("keywords")
        if query_str is None:
            query_str = q.get("query")
        if query_str is None:
            query_str = ""
        results = q.get("results")
        if not isinstance(results, list):
            results = []

        normalized = []
        for prod in results:
            norm = normalize_product(prod)
            if norm is not None:
                normalized.append(norm)
                all_valid_products.append((query_str, norm))

        # Sort for top deals: effective_price asc, cashback_amount desc, shop_name alphabetical
        sorted_norm = sorted(
            normalized,
            key=lambda p: (
                p["effective_price_dec"],
                Decimal("-1") * p["cashback_amount_dec"],  # higher cashback first
                p["shop_name"].lower(),
            ),
        )

        # Select top 3
        top_n = sorted_norm[:3]

        # Emit CSV rows
        rank = 1
        for p in top_n:
            expected_rows.append({
                "query": query_str,
                "rank": str(rank),
                "title": p["title"],
                "shop_name": p["shop_name"],
                "shop_domain": p["shop_domain"],
                "price": p["price_str"],
                "cashback_rate": p["cashback_rate_str"],
                "cashback_amount": p["cashback_amount_str"],
                "effective_price": p["effective_price_str"],
                "affiliate_url": p["affiliate_url"],
            })
            rank += 1

        # Summary per-query
        count = len(normalized)
        if count > 0:
            avg_price = d2(sum(p["price_dec"] for p in normalized) / Decimal(count))
            avg_eff = d2(sum(p["effective_price_dec"] for p in normalized) / Decimal(count))
        else:
            avg_price = d2(Decimal("0"))
            avg_eff = d2(Decimal("0"))

        # best_shop_by_count among top selection
        best_shop = ""
        if top_n:
            counts = {}
            for p in top_n:
                counts[p["shop_name"]] = counts.get(p["shop_name"], 0) + 1
            # max count, tie-breaker alphabetical
            max_count = max(counts.values())
            candidates = [name for name, c in counts.items() if c == max_count]
            best_shop = sorted(candidates, key=lambda s: s.lower())[0]

        summary_queries.append({
            "query": query_str,
            "total_results_considered": count,
            "average_price": float(avg_price),
            "average_effective_price": float(avg_eff),
            "best_shop_by_count": best_shop,
        })

    # Global lowest effective deal
    global_best = None
    if all_valid_products:
        # Sorting with same tie-breakers
        global_best = sorted(
            all_valid_products,
            key=lambda qp: (
                qp[1]["effective_price_dec"],
                Decimal("-1") * qp[1]["cashback_amount_dec"],
                qp[1]["shop_name"].lower(),
            ),
        )[0]
        gb_query, gb_prod = global_best
        global_best_obj = {
            "query": gb_query,
            "title": gb_prod["title"],
            "shop_name": gb_prod["shop_name"],
            "effective_price": float(gb_prod["effective_price_dec"]),
            "effective_price_str": gb_prod["effective_price_str"],  # for string formatting check
        }
    else:
        global_best_obj = {
            "query": "",
            "title": "",
            "shop_name": "",
            "effective_price": float(d2(Decimal("0"))),
            "effective_price_str": f"{d2(Decimal('0')):.2f}",
        }

    return expected_rows, summary_queries, global_best_obj

def validate_csv(csv_path, expected_rows):
    checks = {
        "csv_exists": False,
        "csv_header_ok": False,
        "csv_content_ok": False,
    }
    expected_header = "query,rank,title,shop_name,shop_domain,price,cashback_rate,cashback_amount,effective_price,affiliate_url"
    if not os.path.isfile(csv_path):
        return checks, []
    checks["csv_exists"] = True

    # Read raw first line for header comparison
    try:
        with open(csv_path, "r", encoding="utf-8", newline="") as f:
            first_line = f.readline().rstrip("\n").rstrip("\r")
            checks["csv_header_ok"] = (first_line == expected_header)
    except Exception:
        return checks, []

    actual_rows = []
    try:
        with open(csv_path, "r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            # Ensure header names exactly match expected when DictReader parsed
            if reader.fieldnames != expected_header.split(","):
                # If header mismatch, content cannot be ok
                return checks, []
            for row in reader:
                # Keep all fields as-is (strings)
                actual_rows.append({
                    "query": row.get("query", ""),
                    "rank": row.get("rank", ""),
                    "title": row.get("title", ""),
                    "shop_name": row.get("shop_name", ""),
                    "shop_domain": row.get("shop_domain", ""),
                    "price": row.get("price", ""),
                    "cashback_rate": row.get("cashback_rate", ""),
                    "cashback_amount": row.get("cashback_amount", ""),
                    "effective_price": row.get("effective_price", ""),
                    "affiliate_url": row.get("affiliate_url", ""),
                })
    except Exception:
        return checks, []

    # Compare exact sequence and values
    checks["csv_content_ok"] = (actual_rows == expected_rows)

    return checks, actual_rows

def validate_summary_json(json_path, expected_summary_queries, expected_global_best):
    checks = {
        "summary_exists": False,
        "summary_queries_correct": False,
        "global_best_correct": False,
        "cross_file_consistency": False,  # will be set later when CSV rows available
    }
    if not os.path.isfile(json_path):
        return checks, None
    checks["summary_exists"] = True

    try:
        with open(json_path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        return checks, None

    # Validate structure and content for queries
    queries = data.get("queries")
    if isinstance(queries, list) and len(queries) == len(expected_summary_queries):
        # Map by query string for comparison
        actual_by_query = {}
        ok = True
        for item in queries:
            if not isinstance(item, dict):
                ok = False
                break
            q = item.get("query", "")
            actual_by_query[q] = item
        # Now compare each expected
        for exp in expected_summary_queries:
            aq = actual_by_query.get(exp["query"])
            if aq is None:
                ok = False
                break
            # total_results_considered
            if aq.get("total_results_considered") != exp["total_results_considered"]:
                ok = False
                break
            # average_price and average_effective_price: numeric and equal to rounded expected
            ap = aq.get("average_price")
            aep = aq.get("average_effective_price")
            try:
                ap_num = float(ap)
                aep_num = float(aep)
            except Exception:
                ok = False
                break
            if ap_num != exp["average_price"] or aep_num != exp["average_effective_price"]:
                ok = False
                break
            # best_shop_by_count exact string match
            if aq.get("best_shop_by_count") != exp["best_shop_by_count"]:
                ok = False
                break
        checks["summary_queries_correct"] = ok
    else:
        checks["summary_queries_correct"] = False

    # Validate global lowest effective deal
    gb = data.get("global_lowest_effective_deal")
    if isinstance(gb, dict):
        gb_ok = True
        if gb.get("query") != expected_global_best["query"]:
            gb_ok = False
        if gb.get("title") != expected_global_best["title"]:
            gb_ok = False
        if gb.get("shop_name") != expected_global_best["shop_name"]:
            gb_ok = False
        # effective_price can be number or string; must equal expected value rounded to 2 decimals
        eff = gb.get("effective_price")
        eff_ok = False
        # Try number compare
        try:
            eff_num = float(eff)
            if eff_num == expected_global_best["effective_price"]:
                eff_ok = True
        except Exception:
            eff_ok = False
        # If not numeric match, try string exact two-decimal match
        if not eff_ok and isinstance(eff, str):
            if eff == expected_global_best["effective_price_str"]:
                eff_ok = True
        gb_ok = gb_ok and eff_ok
        checks["global_best_correct"] = gb_ok
    else:
        checks["global_best_correct"] = False

    return checks, gb if isinstance(gb, dict) else None

def compute_reward(checks):
    # Weighted sum; sum to 1.0
    weights = {
        "csv_exists": 0.10,
        "csv_header_ok": 0.15,
        "csv_content_ok": 0.45,
        "summary_exists": 0.10,
        "summary_queries_correct": 0.15,
        "global_best_correct": 0.05,
        # cross_file_consistency is not weighted; informative only
    }
    reward = 0.0
    for k, w in weights.items():
        if checks.get(k, False):
            reward += w
    # Ensure within [0,1]
    if reward < 0.0:
        reward = 0.0
    if reward > 1.0:
        reward = 1.0
    return reward

def main():
    workspace_root = get_workspace_root()
    input_dir = os.path.join(workspace_root, "input")
    output_dir = os.path.join(workspace_root, "output")
    reward_dir = os.path.join(workspace_root, "reward")

    catalog_path = os.path.join(input_dir, "catalog.json")
    csv_path = os.path.join(output_dir, "deals", "top_deals.csv")
    summary_path = os.path.join(output_dir, "deals", "summary.json")

    checks = {
        "csv_exists": False,
        "csv_header_ok": False,
        "csv_content_ok": False,
        "summary_exists": False,
        "summary_queries_correct": False,
        "global_best_correct": False,
        "cross_file_consistency": False,
    }

    # Read input catalog (reference only)
    catalog_queries = read_input_catalog(catalog_path)
    expected_rows, expected_summary_queries, expected_global_best = compute_expected(catalog_queries)

    # Validate CSV
    csv_checks, actual_rows = validate_csv(csv_path, expected_rows)
    checks.update(csv_checks)

    # Validate summary JSON
    summary_checks, actual_gb = validate_summary_json(summary_path, expected_summary_queries, expected_global_best)
    checks.update(summary_checks)

    # Cross-file consistency: if both csv_content_ok and summary global best correct, ensure the top-1 row for that query matches the summary global best
    if checks["csv_content_ok"] and checks["global_best_correct"] and actual_gb is not None:
        # Find the top-1 row for the query in expected_rows (since actual_rows == expected_rows when csv_content_ok is True)
        target_query = actual_gb.get("query", "")
        target_title = actual_gb.get("title", "")
        target_shop = actual_gb.get("shop_name", "")
        # effective_price value comparison; get formatted string from CSV
        target_eff_value = None
        try:
            target_eff_value = float(actual_gb.get("effective_price"))
        except Exception:
            target_eff_value = None
        target_eff_str = None
        if target_eff_value is None and isinstance(actual_gb.get("effective_price"), str):
            target_eff_str = actual_gb.get("effective_price")
        else:
            # Build two-dec string from numeric
            if target_eff_value is not None:
                target_eff_str = f"{d2(Decimal(str(target_eff_value))):.2f}"

        # Locate rank 1 for query
        top1_row = None
        for row in actual_rows:
            if row.get("query") == target_query and row.get("rank") == "1":
                top1_row = row
                break
        if top1_row:
            eff_match = (top1_row.get("effective_price") == target_eff_str)
            if top1_row.get("title") == target_title and top1_row.get("shop_name") == target_shop and eff_match:
                checks["cross_file_consistency"] = True

    reward = compute_reward(checks)

    # No-op baseline: if outputs missing entirely, ensure reward is 0.0
    outputs_present = checks["csv_exists"] or checks["summary_exists"]
    if not outputs_present:
        reward = 0.0

    result = {"reward": reward}
    result.update(checks)
    print(json.dumps(result))

if __name__ == "__main__":
    main()

import sys
import json
import csv
import math
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple


def _read_text_safe(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _load_json_safe(path: Path) -> Optional[Any]:
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _load_csv_rows(path: Path) -> Optional[List[Dict[str, str]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            if reader.fieldnames is None or len(reader.fieldnames) == 0:
                return None
            rows = [dict(r) for r in reader]
        return rows
    except Exception:
        return None


def _parse_csv_file(path: Path) -> Tuple[Optional[List[str]], Optional[List[List[str]]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.reader(f)
            rows = list(reader)
        if not rows:
            return None, None
        header = rows[0]
        body = rows[1:]
        return header, body
    except Exception:
        return None, None


def _parse_yaml_config(path: Path) -> Optional[Dict[str, Any]]:
    text = _read_text_safe(path)
    if text is None:
        return None
    data: Dict[str, Any] = {}
    stack: List[Tuple[int, Dict[str, Any]]] = [(0, data)]
    for raw in text.splitlines():
        line = raw.split("#", 1)[0].rstrip()
        if not line.strip():
            continue
        indent = len(line) - len(line.lstrip(" "))
        while stack and indent < stack[-1][0]:
            stack.pop()
        current = stack[-1][1]
        if ":" in line.strip():
            if line.strip().endswith(":"):
                key = line.strip()[:-1].strip()
                current[key] = {}
                stack.append((indent + 2, current[key]))
            else:
                key, val = line.split(":", 1)
                key = key.strip()
                val = val.strip()
                if (val.startswith('"') and val.endswith('"')) or (val.startswith("'") and val.endswith("'")):
                    val_clean: Any = val[1:-1]
                else:
                    try:
                        if "." in val:
                            val_clean = float(val)
                        else:
                            val_clean = int(val)
                    except Exception:
                        val_clean = val
                current[key] = val_clean
    return data


def _median(values: List[float]) -> float:
    n = len(values)
    if n == 0:
        return float("nan")
    s = sorted(values)
    mid = n // 2
    if n % 2 == 1:
        return s[mid]
    return (s[mid - 1] + s[mid]) / 2.0


def _pearson_corr(x: List[float], y: List[float]) -> float:
    n = len(x)
    if n != len(y) or n < 2:
        return float("nan")
    mean_x = sum(x) / n
    mean_y = sum(y) / n
    sxy = sum((xi - mean_x) * (yi - mean_y) for xi, yi in zip(x, y))
    sx2 = sum((xi - mean_x) ** 2 for xi in x)
    sy2 = sum((yi - mean_y) ** 2 for yi in y)
    denom = math.sqrt(sx2) * math.sqrt(sy2)
    if denom == 0:
        return float("nan")
    return sxy / denom


def _format4(x: float) -> str:
    return f"{x:.4f}"


def _compute_expected_metrics(ml_rows: List[Dict[str, str]], fc_rows: List[Dict[str, str]]) -> Optional[Dict[str, Any]]:
    try:
        spreads: List[float] = []
        depths: List[float] = []
        for r in ml_rows:
            spreads.append(float(r["bid_ask_spread"]))
            depths.append(float(r["depth"]))
        total_rows = len(ml_rows)
        if total_rows == 0:
            return None
        mean_spread = sum(spreads) / total_rows
        median_spread = _median(spreads)
        mean_depth = sum(depths) / total_rows

        coverage_by_date: Dict[str, float] = {}
        for r in fc_rows:
            coverage_by_date[r["date"]] = float(r["coverage_ratio"])
        jx: List[float] = []
        jy: List[float] = []
        for r in ml_rows:
            d = r["date"]
            if d in coverage_by_date:
                jx.append(float(r["bid_ask_spread"]))
                jy.append(coverage_by_date[d])
        corr = _pearson_corr(jx, jy)

        per_market: Dict[str, Dict[str, List[float]]] = {}
        for r in ml_rows:
            m = r["market"]
            per_market.setdefault(m, {"s": [], "d": []})
            per_market[m]["s"].append(float(r["bid_ask_spread"]))
            per_market[m]["d"].append(float(r["depth"]))
        aggs: List[Tuple[str, float, float, int]] = []
        for m, vals in per_market.items():
            n = len(vals["s"])
            avg_s = sum(vals["s"]) / n if n else float("nan")
            avg_d = sum(vals["d"]) / n if n else float("nan")
            aggs.append((m, avg_s, avg_d, n))
        aggs.sort(key=lambda t: (-t[1], t[0]))
        return {
            "total_rows": total_rows,
            "mean_spread": mean_spread,
            "median_spread": median_spread,
            "mean_depth": mean_depth,
            "spread_coverage_corr": corr,
            "market_aggs": aggs,
        }
    except Exception:
        return None


def _find_section(text: str, heading: str, all_headings: List[str]) -> Optional[str]:
    lines = text.splitlines()
    idx = None
    for i, ln in enumerate(lines):
        if ln.strip() == heading:
            idx = i
            break
    if idx is None:
        return None
    next_idx = None
    for j in range(idx + 1, len(lines)):
        if lines[j].strip() in all_headings:
            next_idx = j
            break
    if next_idx is None:
        section_lines = lines[idx + 1 :]
    else:
        section_lines = lines[idx + 1 : next_idx]
    return "\n".join(section_lines).strip("\n")


def _bullet_lines(section_text: str) -> List[str]:
    return [ln.strip() for ln in section_text.splitlines() if ln.strip().startswith("- ")]


def _path_mentions(line: str, workspace: Path, target: Path) -> bool:
    try_opts = [
        str(target),  # absolute or given
        str(target.resolve()) if target.exists() else str(target),
        str(target.as_posix()),
        str(target.relative_to(workspace)) if str(target).startswith(str(workspace)) else str(target.name),
        str(target.name),
    ]
    return any(opt in line for opt in try_opts if opt)


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores: Dict[str, float] = {
        "manifest_exists_and_structure": 0.0,
        "manifest_row_counts_and_sizes": 0.0,
        "summary_stats_exists_and_header": 0.0,
        "summary_stats_values_correct": 0.0,
        "market_aggregates_exists_and_header": 0.0,
        "market_aggregates_values_and_sorting": 0.0,
        "meeting_notes_headings_present": 0.0,
        "meeting_notes_environment_section_content": 0.0,
        "meeting_notes_key_metrics_section_content": 0.0,
        "meeting_notes_action_items_correct": 0.0,
    }

    # Parse config to locate output directories
    config_path = workspace / "input" / "config.yaml"
    config = _parse_yaml_config(config_path) if config_path.exists() else None
    metrics_dir = workspace / "output" / "metrics"
    logs_dir = workspace / "output" / "logs"
    reports_dir = workspace / "output" / "reports"
    if isinstance(config, dict) and isinstance(config.get("outputs"), dict):
        try:
            metrics_dir = workspace / str(config["outputs"].get("metrics_dir", "output/metrics"))
            logs_dir = workspace / str(config["outputs"].get("logs_dir", "output/logs"))
            reports_dir = workspace / str(config["outputs"].get("reports_dir", "output/reports"))
        except Exception:
            pass

    # Load inputs for expected computations
    ml_path = workspace / "input" / "market_liquidity.csv"
    fc_path = workspace / "input" / "fiscal_coverage.csv"
    ml_rows = _load_csv_rows(ml_path) if ml_path.exists() else None
    fc_rows = _load_csv_rows(fc_path) if fc_path.exists() else None
    expected = _compute_expected_metrics(ml_rows, fc_rows) if (ml_rows is not None and fc_rows is not None) else None

    # 1) Manifest checks
    manifest_path = logs_dir / "input_manifest.json"
    manifest = _load_json_safe(manifest_path) if manifest_path.exists() else None
    if isinstance(manifest, list):
        required_files = {"market_liquidity.csv", "fiscal_coverage.csv"}
        structure_ok = True
        if len(manifest) != 2:
            structure_ok = False
        present = set()
        for entry in manifest:
            if not isinstance(entry, dict):
                structure_ok = False
                break
            if not all(k in entry for k in ("file_path", "size_bytes", "row_count")):
                structure_ok = False
                break
            fp_str = str(entry.get("file_path"))
            name = Path(fp_str).name
            if name in required_files:
                present.add(name)
        if structure_ok and present == required_files:
            scores["manifest_exists_and_structure"] = 1.0

        if scores["manifest_exists_and_structure"] == 1.0:
            by_name: Dict[str, Dict[str, Any]] = {}
            for entry in manifest:
                name = Path(str(entry.get("file_path"))).name
                by_name[name] = entry
            ok = True
            # market_liquidity.csv
            if ml_path.exists():
                exp_rows = len(ml_rows) if ml_rows is not None else None
                exp_size = ml_path.stat().st_size
                e = by_name.get("market_liquidity.csv")
                if not isinstance(e, dict):
                    ok = False
                else:
                    if not isinstance(e.get("row_count"), int) or (exp_rows is not None and e.get("row_count") != exp_rows):
                        ok = False
                    if not isinstance(e.get("size_bytes"), int) or e.get("size_bytes") != exp_size:
                        ok = False
                    # file_path should reference input path
                    fp = str(e.get("file_path"))
                    if not (fp.endswith("input/market_liquidity.csv") or Path(fp).name == "market_liquidity.csv"):
                        ok = False
            else:
                ok = False
            # fiscal_coverage.csv
            if fc_path.exists():
                exp_rows = len(fc_rows) if fc_rows is not None else None
                exp_size = fc_path.stat().st_size
                e = by_name.get("fiscal_coverage.csv")
                if not isinstance(e, dict):
                    ok = False
                else:
                    if not isinstance(e.get("row_count"), int) or (exp_rows is not None and e.get("row_count") != exp_rows):
                        ok = False
                    if not isinstance(e.get("size_bytes"), int) or e.get("size_bytes") != exp_size:
                        ok = False
                    fp = str(e.get("file_path"))
                    if not (fp.endswith("input/fiscal_coverage.csv") or Path(fp).name == "fiscal_coverage.csv"):
                        ok = False
            else:
                ok = False

            if ok:
                scores["manifest_row_counts_and_sizes"] = 1.0

    # 2) Summary stats checks
    summary_path = metrics_dir / "summary_stats.csv"
    s_header, s_body = _parse_csv_file(summary_path) if summary_path.exists() else (None, None)
    if s_header is not None and s_body is not None:
        expected_header = ["total_rows", "mean_spread", "median_spread", "mean_depth", "spread_coverage_corr"]
        if s_header == expected_header and len(s_body) == 1:
            scores["summary_stats_exists_and_header"] = 1.0
        if scores["summary_stats_exists_and_header"] == 1.0 and expected is not None:
            row = s_body[0]
            try:
                total_rows_ok = row[0] == str(int(expected["total_rows"]))
                mean_spread_ok = row[1] == _format4(expected["mean_spread"])
                median_spread_ok = row[2] == _format4(expected["median_spread"])
                mean_depth_ok = row[3] == _format4(expected["mean_depth"])
                corr_ok = row[4] == _format4(expected["spread_coverage_corr"])
                if total_rows_ok and mean_spread_ok and median_spread_ok and mean_depth_ok and corr_ok:
                    scores["summary_stats_values_correct"] = 1.0
            except Exception:
                pass

    # 3) Market aggregates checks
    aggs_path = metrics_dir / "market_aggregates.csv"
    a_header, a_body = _parse_csv_file(aggs_path) if aggs_path.exists() else (None, None)
    if a_header is not None and a_body is not None:
        expected_a_header = ["market", "avg_spread", "avg_depth", "n_days"]
        if a_header == expected_a_header and len(a_body) > 0:
            scores["market_aggregates_exists_and_header"] = 1.0
        if scores["market_aggregates_exists_and_header"] == 1.0 and expected is not None:
            exp_aggs = expected["market_aggs"]
            exp_rows = [[m, _format4(avg_s), _format4(avg_d), str(n)] for (m, avg_s, avg_d, n) in exp_aggs]
            ok = True
            if len(a_body) != len(exp_rows):
                ok = False
            else:
                for got, exp in zip(a_body, exp_rows):
                    if got != exp:
                        ok = False
                        break
            if ok:
                scores["market_aggregates_values_and_sorting"] = 1.0

    # 4) Meeting notes checks
    notes_path = reports_dir / "meeting_notes.md"
    notes_text = _read_text_safe(notes_path) if notes_path.exists() else None
    headings = ["Environment:", "Key Metrics:", "Action Items:"]
    if notes_text is not None:
        if all(h in notes_text for h in headings):
            scores["meeting_notes_headings_present"] = 1.0

        # Environment section: Python version mention and bullet list of created output directories
        env_sec = _find_section(notes_text, "Environment:", headings)
        if env_sec is not None:
            env_ok = False
            # Python version mention heuristic
            if "Python" in env_sec and any(ch.isdigit() for ch in env_sec):
                env_ok = True
            # Bullet list includes created output directories
            blines = _bullet_lines(env_sec)
            dirs_ok = True
            for tdir in [metrics_dir, logs_dir, reports_dir]:
                found = False
                for ln in blines:
                    if _path_mentions(ln, workspace, tdir):
                        found = True
                        break
                if not found:
                    dirs_ok = False
                    break
            if env_ok and dirs_ok:
                scores["meeting_notes_environment_section_content"] = 1.0

        # Key Metrics section: include numeric values and list top 3 markets by avg_spread with values, in order
        km_sec = _find_section(notes_text, "Key Metrics:", headings)
        if km_sec is not None and expected is not None and scores["summary_stats_values_correct"] == 1.0:
            km_ok = True
            required_vals = [
                str(int(expected["total_rows"])),
                _format4(expected["mean_spread"]),
                _format4(expected["median_spread"]),
                _format4(expected["mean_depth"]),
                _format4(expected["spread_coverage_corr"]),
            ]
            for v in required_vals:
                if v not in km_sec:
                    km_ok = False
                    break
            if km_ok:
                top3 = [(m, _format4(avg_s)) for (m, avg_s, avg_d, n) in expected["market_aggs"][:3]]
                indices: List[int] = []
                for m, val in top3:
                    pos_m = km_sec.find(m)
                    pos_v = km_sec.find(val)
                    if pos_m == -1 or pos_v == -1:
                        km_ok = False
                        break
                    indices.append(min(pos_m, pos_v))
                if km_ok and not (len(indices) == 3 and indices[0] < indices[1] < indices[2]):
                    km_ok = False
            if km_ok:
                scores["meeting_notes_key_metrics_section_content"] = 1.0

        # Action Items section
        ai_sec = _find_section(notes_text, "Action Items:", headings)
        if ai_sec is not None and expected is not None:
            avg_spreads = [avg_s for (_, avg_s, _, _) in expected["market_aggs"]]
            med = _median(avg_spreads)
            targets = [(m, avg_s) for (m, avg_s, _, _) in expected["market_aggs"] if avg_s > med]
            blines = _bullet_lines(ai_sec)
            final_expected = "- Confirm date alignment in fiscal coverage vs. liquidity data."
            ai_ok = True
            # Ensure "Investigate" bullets for each target
            inv_lines = [ln for ln in blines if ln.startswith("- Investigate")]
            if len(inv_lines) != len(targets):
                ai_ok = False
            else:
                for m, avg_s in targets:
                    val = _format4(avg_s)
                    found = False
                    for ln in inv_lines:
                        if ln.startswith("- Investigate") and (m in ln) and (val in ln):
                            found = True
                            break
                    if not found:
                        ai_ok = False
                        break
            # Final bullet exact and last
            if not blines or blines[-1] != final_expected:
                ai_ok = False
            if ai_ok:
                scores["meeting_notes_action_items_correct"] = 1.0

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

