import csv
import json
import re
import sys
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple


def _safe_read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _safe_load_json(path: Path) -> Optional[Any]:
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _safe_load_csv_dicts(path: Path) -> Tuple[Optional[List[str]], Optional[List[Dict[str, str]]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            header = reader.fieldnames
            if header is None:
                return None, None
            rows = [dict(row) for row in reader]
            return header, rows
    except Exception:
        return None, None


def _parse_manifest(manifest_data: Any) -> Optional[Dict[str, Dict[str, Any]]]:
    try:
        experiments = manifest_data.get("experiments", [])
        result: Dict[str, Dict[str, Any]] = {}
        for item in experiments:
            sid = item.get("sample_id")
            desc = item.get("description")
            exp = item.get("expected_replicates")
            if not isinstance(sid, str) or not isinstance(desc, str) or not isinstance(exp, int):
                return None
            result[sid] = {
                "description": desc,
                "expected_replicates": exp,
            }
        return result
    except Exception:
        return None


def _parse_results(rows: List[Dict[str, str]]) -> Optional[List[Dict[str, Any]]]:
    parsed: List[Dict[str, Any]] = []
    for row in rows:
        try:
            sid = row.get("sample_id")
            rid = row.get("replicate_id")
            v = row.get("viability_pct")
            if sid is None or rid is None or v is None:
                return None
            v_float = float(v)
            parsed.append({
                "sample_id": sid,
                "replicate_id": rid,
                "viability_pct": v_float,
            })
        except Exception:
            return None
    return parsed


def _parse_lab_notes_exclusions(text: str) -> List[Dict[str, str]]:
    exclusions: List[Dict[str, str]] = []
    # Pattern: - Exclude: sample_id=..., replicate_id=..., reason=...
    pattern = re.compile(
        r'^\s*-\s*Exclude:\s*sample_id=(?P<sid>[^,]+),\s*replicate_id=(?P<rid>[^,]+),\s*reason=(?P<reason>.+?)\s*$'
    )
    for line in text.splitlines():
        m = pattern.match(line)
        if m:
            sid = m.group("sid").strip()
            rid = m.group("rid").strip()
            reason = m.group("reason").strip()
            exclusions.append({
                "sample_id": sid,
                "replicate_id": rid,
                "reason": reason,
            })
    return exclusions


def _compute_expected(manifest: Dict[str, Dict[str, Any]],
                      results: List[Dict[str, Any]],
                      exclusions: List[Dict[str, str]]
                      ) -> Tuple[Dict[str, Dict[str, Any]], List[Dict[str, str]]]:
    # Map sample -> list of result rows
    results_by_sample: Dict[str, List[Dict[str, Any]]] = {}
    for r in results:
        results_by_sample.setdefault(r["sample_id"], []).append(r)

    # Build set of exclusions to apply
    exclude_pairs = {(e["sample_id"], e["replicate_id"]) for e in exclusions}
    # Determine which exclusions actually match a results row
    all_pairs_in_results = {(r["sample_id"], r["replicate_id"]) for r in results}
    applied_exclusions = [
        {"sample_id": e["sample_id"], "replicate_id": e["replicate_id"], "reason": e["reason"]}
        for e in exclusions
        if (e["sample_id"], e["replicate_id"]) in all_pairs_in_results
    ]

    summary: Dict[str, Dict[str, Any]] = {}
    for sid, info in manifest.items():
        expected = info["expected_replicates"]
        description = info["description"]
        sample_rows = results_by_sample.get(sid, [])
        present_count = len(sample_rows)
        excluded_rows = [r for r in sample_rows if (r["sample_id"], r["replicate_id"]) in exclude_pairs]
        included_rows = [r for r in sample_rows if (r["sample_id"], r["replicate_id"]) not in exclude_pairs]
        excluded_count = len(excluded_rows)
        included_count = len(included_rows)
        missing_count = expected - present_count
        if missing_count < 0:
            missing_count = 0
        if included_count > 0:
            mean_val = sum(r["viability_pct"] for r in included_rows) / included_count
            mean_str = f"{round(mean_val + 1e-12, 2):.2f}"
        else:
            mean_str = ""
        summary[sid] = {
            "sample_id": sid,
            "description": description,
            "expected_replicates": expected,
            "included_replicates": included_count,
            "excluded_replicates": excluded_count,
            "missing_replicates": missing_count,
            "mean_viability_pct": mean_str,
        }

    return summary, applied_exclusions


def _read_viability_summary(path: Path) -> Tuple[bool, Optional[List[str]], Optional[List[Dict[str, str]]]]:
    header, rows = _safe_load_csv_dicts(path)
    if header is None or rows is None:
        return False, None, None
    return True, header, rows


def _parse_int(value: str) -> Optional[int]:
    try:
        if value is None:
            return None
        return int(str(value).strip())
    except Exception:
        return None


def _parse_float(value: str) -> Optional[float]:
    try:
        if value is None or str(value).strip() == "":
            return None
        return float(str(value).strip())
    except Exception:
        return None


def _find_section_indices(lines: List[str], header_label: str) -> Optional[Tuple[int, int]]:
    # Find a line that, after stripping leading '#', spaces, equals the header_label exactly
    header_idx = None
    for i, line in enumerate(lines):
        stripped = line.strip()
        stripped = stripped.lstrip('#').strip()
        if stripped == header_label:
            header_idx = i
            break
    if header_idx is None:
        return None
    # Find next header or end
    end_idx = len(lines)
    for j in range(header_idx + 1, len(lines)):
        s2 = lines[j].strip().lstrip('#').strip()
        if s2 in {
            "Completed",
            "Missing replicates",
            "Anomalies (<50% mean viability)"
        }:
            end_idx = j
            break
    return header_idx, end_idx


def _extract_bullets_in_section(text: str, header_label: str) -> List[str]:
    lines = text.splitlines()
    idxs = _find_section_indices(lines, header_label)
    if idxs is None:
        return []
    start, end = idxs
    bullets: List[str] = []
    for line in lines[start + 1:end]:
        s = line.strip()
        if s.startswith("- ") or s.startswith("* "):
            bullets.append(s)
    return bullets


def _line_contains_all_counts(line: str, counts: List[int]) -> bool:
    ints = [int(x) for x in re.findall(r'\b\d+\b', line)]
    needed = list(counts)
    # simple multiset containment check
    for c in counts:
        if c in ints:
            needed.remove(c)
            ints.remove(c)
    return len(needed) == 0


def _extract_sample_ids_from_bullets(bullets: List[str], valid_sample_ids: List[str]) -> List[str]:
    found: List[str] = []
    for b in bullets:
        for sid in valid_sample_ids:
            if sid in b:
                found.append(sid)
                break
    return found


def _bullet_has_ratio(bullet: str, included: int, expected: int) -> bool:
    # Look for x/y pattern that matches included/expected (allow spaces)
    for m in re.finditer(r'(\d+)\s*/\s*(\d+)', bullet):
        x = int(m.group(1))
        y = int(m.group(2))
        if x == included and y == expected:
            return True
    return False


def _bullet_has_mean_approx(bullet: str, mean_val: Optional[float]) -> bool:
    if mean_val is None:
        return True  # not required if not available
    candidates = re.findall(r'(\d+\.\d+)', bullet)
    for c in candidates:
        try:
            v = float(c)
            if abs(v - mean_val) <= 0.01:
                return True
        except Exception:
            continue
    return False


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)

    # Prepare expected data from inputs
    input_manifest_path = workspace / "input" / "experiment_manifest.json"
    input_results_path = workspace / "input" / "assay_results.csv"
    input_notes_path = workspace / "input" / "lab_notes.md"

    manifest_data = _safe_load_json(input_manifest_path)
    results_header, results_rows = _safe_load_csv_dicts(input_results_path)
    notes_text = _safe_read_text(input_notes_path)

    manifest = _parse_manifest(manifest_data) if manifest_data is not None else None
    results = _parse_results(results_rows) if results_rows is not None else None
    exclusions = _parse_lab_notes_exclusions(notes_text) if notes_text is not None else None

    expected_summary: Optional[Dict[str, Dict[str, Any]]] = None
    applied_exclusions: Optional[List[Dict[str, str]]] = None
    if manifest is not None and results is not None and exclusions is not None:
        expected_summary, applied_exclusions = _compute_expected(manifest, results, exclusions)

    # Output paths
    out_dir = workspace / "output"
    summary_csv_path = out_dir / "viability_summary.csv"
    exclusions_json_path = out_dir / "exclusions_applied.json"
    weekly_update_path = out_dir / "weekly_update.md"

    scores: Dict[str, float] = {
        "viability_summary_file_structure": 0.0,
        "viability_summary_sample_coverage": 0.0,
        "viability_summary_field_values": 0.0,
        "exclusions_applied_json_content": 0.0,
        "weekly_update_summary_line": 0.0,
        "weekly_update_sections_lists": 0.0,
        "weekly_update_bullet_details": 0.0,
        "weekly_update_data_sources": 0.0,
    }

    # Check viability_summary.csv structure
    ok_summary, header, summary_rows = _read_viability_summary(summary_csv_path)
    required_header = [
        "sample_id",
        "description",
        "expected_replicates",
        "included_replicates",
        "excluded_replicates",
        "missing_replicates",
        "mean_viability_pct",
    ]
    if ok_summary and header == required_header:
        scores["viability_summary_file_structure"] = 1.0

    # Check sample coverage and field values if we have expected and file parsed
    if ok_summary and expected_summary is not None and summary_rows is not None:
        sample_ids_from_manifest = list(expected_summary.keys())
        # Build rows by sample_id
        rows_by_sid: Dict[str, Dict[str, str]] = {}
        valid = True
        for row in summary_rows:
            sid = row.get("sample_id")
            if sid in rows_by_sid:
                valid = False  # duplicate sample row
                break
            rows_by_sid[sid] = row
        if valid and set(rows_by_sid.keys()) == set(sample_ids_from_manifest):
            scores["viability_summary_sample_coverage"] = 1.0

        # Validate field values
        all_match = True
        for sid, expected in expected_summary.items():
            row = rows_by_sid.get(sid)
            if row is None:
                all_match = False
                break
            # description
            if row.get("description") != expected["description"]:
                all_match = False
                break
            # expected_replicates
            exp_int = _parse_int(row.get("expected_replicates", ""))
            if exp_int is None or exp_int != expected["expected_replicates"]:
                all_match = False
                break
            # included_replicates
            inc_int = _parse_int(row.get("included_replicates", ""))
            if inc_int is None or inc_int != expected["included_replicates"]:
                all_match = False
                break
            # excluded_replicates
            exc_int = _parse_int(row.get("excluded_replicates", ""))
            if exc_int is None or exc_int != expected["excluded_replicates"]:
                all_match = False
                break
            # missing_replicates
            miss_int = _parse_int(row.get("missing_replicates", ""))
            if miss_int is None or miss_int != expected["missing_replicates"]:
                all_match = False
                break
            # mean_viability_pct
            mean_str = row.get("mean_viability_pct", "")
            if expected["included_replicates"] == 0:
                if mean_str != "":
                    all_match = False
                    break
            else:
                mean_val = _parse_float(mean_str)
                exp_mean_val = _parse_float(expected["mean_viability_pct"])
                if mean_val is None or exp_mean_val is None:
                    all_match = False
                    break
                if round(mean_val, 2) != round(exp_mean_val, 2):
                    all_match = False
                    break
        if all_match:
            scores["viability_summary_field_values"] = 1.0

    # Check exclusions_applied.json content
    applied_ok = False
    exclusions_data = _safe_load_json(exclusions_json_path)
    if isinstance(exclusions_data, list) and applied_exclusions is not None:
        # Build sets of tuples for comparison; ignore order
        def norm_list(lst: List[Dict[str, str]]) -> Optional[List[Tuple[str, str, str]]]:
            out: List[Tuple[str, str, str]] = []
            for item in lst:
                try:
                    s = str(item["sample_id"])
                    r = str(item["replicate_id"])
                    reason = str(item["reason"])
                except Exception:
                    return None
                out.append((s, r, reason))
            return out

        expected_tuples = norm_list(applied_exclusions)
        actual_tuples = norm_list(exclusions_data)
        if expected_tuples is not None and actual_tuples is not None:
            if set(actual_tuples) == set(expected_tuples) and len(actual_tuples) == len(expected_tuples):
                applied_ok = True
    if applied_ok:
        scores["exclusions_applied_json_content"] = 1.0

    # Weekly update checks
    weekly_text = _safe_read_text(weekly_update_path)
    if weekly_text is not None and expected_summary is not None:
        # Summary line with counts
        total_samples = len(expected_summary)
        complete_count = sum(1 for v in expected_summary.values()
                             if v["included_replicates"] == v["expected_replicates"])
        missing_count = sum(1 for v in expected_summary.values()
                            if v["missing_replicates"] > 0)
        anomalies_count = 0
        for v in expected_summary.values():
            if v["included_replicates"] > 0:
                mv = float(v["mean_viability_pct"])
                if mv < 50.0:
                    anomalies_count += 1

        # Find any line containing all required counts
        found_summary_line = False
        for line in weekly_text.splitlines():
            if line.strip() == "":
                continue
            if _line_contains_all_counts(line, [total_samples, complete_count, missing_count, anomalies_count]):
                found_summary_line = True
                break
        if found_summary_line:
            scores["weekly_update_summary_line"] = 1.0

        # Sections: Completed, Missing replicates, Anomalies
        valid_sample_ids = list(expected_summary.keys())
        # Determine expected sets
        completed_expected = {sid for sid, v in expected_summary.items()
                              if v["included_replicates"] == v["expected_replicates"]}
        missing_expected = {sid for sid, v in expected_summary.items()
                            if v["missing_replicates"] > 0}
        anomalies_expected = {sid for sid, v in expected_summary.items()
                              if (v["included_replicates"] > 0 and float(v["mean_viability_pct"]) < 50.0)}

        bullets_completed = _extract_bullets_in_section(weekly_text, "Completed")
        bullets_missing = _extract_bullets_in_section(weekly_text, "Missing replicates")
        bullets_anomalies = _extract_bullets_in_section(weekly_text, "Anomalies (<50% mean viability)")

        have_sections = (len(bullets_completed) >= 0 and len(bullets_missing) >= 0 and len(bullets_anomalies) >= 0)
        coverage_ok = False
        if have_sections:
            completed_found = set(_extract_sample_ids_from_bullets(bullets_completed, valid_sample_ids))
            missing_found = set(_extract_sample_ids_from_bullets(bullets_missing, valid_sample_ids))
            anomalies_found = set(_extract_sample_ids_from_bullets(bullets_anomalies, valid_sample_ids))
            if completed_found == completed_expected and missing_found == missing_expected and anomalies_found == anomalies_expected:
                coverage_ok = True
        if coverage_ok:
            scores["weekly_update_sections_lists"] = 1.0

        # Bullet details: ratio and mean
        details_ok = True
        # Completed
        for b in bullets_completed:
            sid = None
            for candidate in valid_sample_ids:
                if candidate in b:
                    sid = candidate
                    break
            if sid is None:
                continue
            v = expected_summary[sid]
            if not _bullet_has_ratio(b, v["included_replicates"], v["expected_replicates"]):
                details_ok = False
                break
            mean_val = float(v["mean_viability_pct"]) if v["included_replicates"] > 0 else None
            if not _bullet_has_mean_approx(b, mean_val):
                details_ok = False
                break
        # Missing replicates
        if details_ok:
            for b in bullets_missing:
                sid = None
                for candidate in valid_sample_ids:
                    if candidate in b:
                        sid = candidate
                        break
                if sid is None:
                    continue
                v = expected_summary[sid]
                if not _bullet_has_ratio(b, v["included_replicates"], v["expected_replicates"]):
                    details_ok = False
                    break
                mean_val = float(v["mean_viability_pct"]) if v["included_replicates"] > 0 else None
                if not _bullet_has_mean_approx(b, mean_val):
                    details_ok = False
                    break
        # Anomalies
        if details_ok:
            for b in bullets_anomalies:
                sid = None
                for candidate in valid_sample_ids:
                    if candidate in b:
                        sid = candidate
                        break
                if sid is None:
                    continue
                v = expected_summary[sid]
                if not _bullet_has_ratio(b, v["included_replicates"], v["expected_replicates"]):
                    details_ok = False
                    break
                mean_val = float(v["mean_viability_pct"]) if v["included_replicates"] > 0 else None
                if not _bullet_has_mean_approx(b, mean_val):
                    details_ok = False
                    break
        if details_ok and have_sections:
            scores["weekly_update_bullet_details"] = 1.0

        # Data sources line
        data_sources_ok = False
        if all(p in weekly_text for p in [
            "input/experiment_manifest.json",
            "input/assay_results.csv",
            "input/lab_notes.md",
        ]):
            for line in weekly_text.splitlines():
                if line.strip().lower().startswith("data sources"):
                    data_sources_ok = True
                    break
        if data_sources_ok:
            scores["weekly_update_data_sources"] = 1.0

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

import csv
import json
import re
import sys
import ast
from pathlib import Path
from typing import Dict, List, Tuple, Optional, Any


def _read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _load_csv_dicts(path: Path) -> Tuple[Optional[List[str]], Optional[List[Dict[str, str]]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            try:
                sample = f.read(4096)
                f.seek(0)
            except Exception:
                sample = ""
                f.seek(0)
            dialect = csv.excel
            try:
                if sample:
                    dialect = csv.Sniffer().sniff(sample)
            except Exception:
                pass
            reader = csv.DictReader(f, dialect=dialect)
            rows = [dict({k: (v if v is not None else "") for k, v in row.items()}) for row in reader]
            headers = reader.fieldnames or []
            return headers, rows
    except Exception:
        return None, None


def _parse_simple_yaml(yaml_text: str) -> Dict[str, Any]:
    data: Dict[str, Any] = {}
    for raw_line in yaml_text.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        if line.startswith("#"):
            continue
        parts_comment = line.split(" #", 1)
        line = parts_comment[0].strip()
        if ":" not in line:
            continue
        key, val = line.split(":", 1)
        key = key.strip()
        val = val.strip()
        if val == "":
            data[key] = ""
            continue
        if val.startswith("[") and val.endswith("]"):
            try:
                parsed = ast.literal_eval(val)
                if isinstance(parsed, list):
                    parsed_list = []
                    for item in parsed:
                        if isinstance(item, str):
                            parsed_list.append(item)
                        else:
                            parsed_list.append(str(item))
                    data[key] = parsed_list
                else:
                    data[key] = []
            except Exception:
                data[key] = []
            continue
        low = val.lower()
        if low == "true":
            data[key] = True
            continue
        if low == "false":
            data[key] = False
            continue
        if (val.startswith('"') and val.endswith('"')) or (val.startswith("'") and val.endswith("'")):
            data[key] = val[1:-1]
        else:
            data[key] = val
    return data


def _normalize_hex_to_int(value: str) -> Optional[int]:
    if value is None:
        return None
    s = value.strip()
    if not s:
        return None
    s_clean = s.lower().replace("0x", "").replace(",", "").replace(" ", "")
    if re.fullmatch(r"[0-9a-f]+", s_clean):
        try:
            return int(s_clean, 16)
        except Exception:
            return None
    m2 = re.search(r"0x[0-9a-fA-F]+", s)
    if m2:
        try:
            return int(m2.group(0), 16)
        except Exception:
            return None
    return None


def _find_header_key(fieldnames: List[str], target: str) -> Optional[str]:
    target_lower = target.strip().lower()
    for name in fieldnames:
        if name is None:
            continue
        if name.strip().lower() == target_lower:
            return name
    return None


def _get_case_insensitive_value(row: Dict[str, str], fieldnames: List[str], target: str) -> Optional[str]:
    key = _find_header_key(fieldnames, target)
    if key is None:
        lowered = {k.strip().lower(): k for k in row.keys() if k is not None}
        if target.strip().lower() in lowered:
            key = lowered[target.strip().lower()]
    if key is None:
        return None
    return row.get(key, "")


def _is_recommended_flag(val: Optional[str]) -> bool:
    if val is None:
        return False
    s = str(val).strip().lower()
    return s in {"y", "yes"}


def _normalized_name(desc: Optional[str]) -> str:
    if not desc:
        return ""
    s = desc.lower()
    s_ascii = "".join(ch if ord(ch) < 128 else " " for ch in s)
    s_hy = re.sub(r"[^a-z0-9]+", "-", s_ascii)
    s_hy = re.sub(r"-{2,}", "-", s_hy).strip("-")
    return s_hy


def _parse_iana_registry(path: Path) -> Tuple[bool, Dict[int, Dict[str, str]]]:
    headers, rows = _load_csv_dicts(path)
    if headers is None or rows is None:
        return False, {}
    has_value = any((h or "").strip().lower() == "value" for h in headers)
    has_desc = any((h or "").strip().lower() == "description" for h in headers)
    has_rec = any((h or "").strip().lower() == "recommended" for h in headers)
    if not (has_value and has_desc and has_rec):
        return False, {}
    mapping: Dict[int, Dict[str, str]] = {}
    for row in rows:
        value_str = _get_case_insensitive_value(row, headers, "Value")
        desc = _get_case_insensitive_value(row, headers, "Description") or ""
        rec = _get_case_insensitive_value(row, headers, "Recommended") or ""
        val_int = _normalize_hex_to_int(value_str or "")
        if val_int is None:
            continue
        if val_int not in mapping:
            mapping[val_int] = {"Description": desc, "Recommended": rec}
    return True, mapping


def _load_input_suites(path: Path) -> Tuple[Optional[List[Dict[str, str]]], Optional[List[str]]]:
    headers, rows = _load_csv_dicts(path)
    if headers is None or rows is None:
        return None, None
    header_map = {h.strip().lower(): h for h in headers if h is not None}
    if not all(col in header_map for col in ["hex_value", "note"]):
        return None, None
    ordered_rows = []
    ordered_hexes = []
    for r in rows:
        hex_val = r.get(header_map["hex_value"], "")
        note = r.get(header_map["note"], "")
        ordered_rows.append({"hex_value": hex_val, "note": note})
        ordered_hexes.append(hex_val)
    return ordered_rows, ordered_hexes


def _load_yaml_config(path: Path) -> Optional[Dict[str, Any]]:
    text = _read_text(path)
    if text is None:
        return None
    try:
        return _parse_simple_yaml(text)
    except Exception:
        return None


def _compute_expected_enriched(input_rows: List[Dict[str, str]], iana_map: Dict[int, Dict[str, str]]) -> List[Dict[str, str]]:
    enriched = []
    for r in input_rows:
        hex_value = r.get("hex_value", "")
        note = r.get("note", "")
        val_int = _normalize_hex_to_int(hex_value)
        desc = ""
        rec = ""
        if val_int is not None and val_int in iana_map:
            desc = iana_map[val_int].get("Description", "") or ""
            rec = iana_map[val_int].get("Recommended", "") or ""
        norm_name = _normalized_name(desc)
        enriched.append({
            "hex_value": hex_value,
            "iana_description": desc,
            "iana_recommended": rec,
            "note": note,
            "normalized_name": norm_name,
        })
    return enriched


def _parse_csv_to_rows_by_header(path: Path) -> Tuple[Optional[List[str]], Optional[List[Dict[str, str]]]]:
    return _load_csv_dicts(path)


def _rows_index_by_hex(rows: List[Dict[str, str]]) -> Dict[str, Dict[str, str]]:
    idx: Dict[str, Dict[str, str]] = {}
    for r in rows:
        hv = r.get("hex_value", "")
        idx[hv.strip().lower()] = r
    return idx


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores: Dict[str, float] = {
        "registry_csv_valid": 0.0,
        "enriched_csv_columns_order": 0.0,
        "enriched_rows_match_join": 0.0,
        "normalized_name_correct": 0.0,
        "config_sibling_name_set": 0.0,
        "config_output_fields_exact": 0.0,
        "config_include_recommended_only_retained": 0.0,
        "config_highlight_keywords_unchanged": 0.0,
        "recommended_csv_columns_match_config": 0.0,
        "recommended_filtering_correct": 0.0,
        "email_greeting_includes_name": 0.0,
        "email_sentence_count_valid": 0.0,
        "email_references_output_paths": 0.0,
        "email_bullet_list_covers_recommended": 0.0,
    }

    registry_path = workspace / "downloads" / "iana_tls_cipher_suites.csv"
    input_path = workspace / "input" / "tls_suites.csv"
    enriched_path = workspace / "out" / "tls_suites_enriched.csv"
    recommended_path = workspace / "out" / "tls_suites_recommended.csv"
    email_path = workspace / "out" / "email_to_sibling.txt"
    config_path = workspace / "config" / "filters.yaml"

    # Load registry
    registry_ok, iana_map = _parse_iana_registry(registry_path)
    if registry_ok:
        scores["registry_csv_valid"] = 1.0

    # Load input
    input_rows, input_hexes = _load_input_suites(input_path)

    # Compute expected enriched
    expected_enriched: List[Dict[str, str]] = []
    if input_rows is not None and registry_ok:
        expected_enriched = _compute_expected_enriched(input_rows, iana_map)

    # Verify enriched CSV
    enriched_headers, enriched_rows = _parse_csv_to_rows_by_header(enriched_path)
    required_enriched_columns = ["hex_value", "iana_description", "iana_recommended", "note", "normalized_name"]
    if enriched_headers is not None and enriched_rows is not None:
        if enriched_headers == required_enriched_columns:
            scores["enriched_csv_columns_order"] = 1.0

        if expected_enriched:
            actual_idx = _rows_index_by_hex(enriched_rows)
            expected_hex_set = {e["hex_value"].strip().lower() for e in expected_enriched}
            actual_hex_set = {r.get("hex_value", "").strip().lower() for r in enriched_rows}
            join_match = (expected_hex_set == actual_hex_set)
            fields_match = True
            norm_match = True
            if join_match:
                for exp in expected_enriched:
                    key = exp["hex_value"].strip().lower()
                    act = actual_idx.get(key)
                    if act is None:
                        fields_match = False
                        norm_match = False
                        break
                    if (act.get("iana_description", "") != exp["iana_description"] or
                        act.get("iana_recommended", "") != exp["iana_recommended"] or
                        act.get("note", "") != exp["note"]):
                        fields_match = False
                    if (act.get("normalized_name", "") != exp["normalized_name"]):
                        norm_match = False
            else:
                fields_match = False
                norm_match = False

            if fields_match and join_match:
                scores["enriched_rows_match_join"] = 1.0
            if norm_match and join_match:
                scores["normalized_name_correct"] = 1.0

    # Load and validate config
    cfg = _load_yaml_config(config_path)
    sibling_ok = False
    fields_ok = False
    if cfg is not None:
        if str(cfg.get("sibling_name", "")).strip() == "Riley":
            scores["config_sibling_name_set"] = 1.0
            sibling_ok = True

        output_fields = cfg.get("output_fields", None)
        if isinstance(output_fields, list) and output_fields == ["hex_value", "iana_description", "iana_recommended", "note"]:
            scores["config_output_fields_exact"] = 1.0
            fields_ok = True

        if sibling_ok and fields_ok:
            if cfg.get("include_recommended_only", None) is True:
                scores["config_include_recommended_only_retained"] = 1.0
            hk = cfg.get("highlight_keywords", None)
            if isinstance(hk, list) and hk == ["AES", "CHACHA20", "GCM"]:
                scores["config_highlight_keywords_unchanged"] = 1.0

    # Verify recommended CSV structure matches config and filtering correctness
    rec_headers, rec_rows = _parse_csv_to_rows_by_header(recommended_path)
    if cfg is not None and isinstance(cfg.get("output_fields", None), list) and rec_headers is not None:
        if rec_headers == cfg["output_fields"]:
            scores["recommended_csv_columns_match_config"] = 1.0

    if expected_enriched:
        expected_recommended = [e for e in expected_enriched if _is_recommended_flag(e.get("iana_recommended", ""))]
        cols_for_recommended = None
        if cfg is not None and isinstance(cfg.get("output_fields", None), list) and cfg["output_fields"]:
            cols_for_recommended = cfg["output_fields"]
        else:
            cols_for_recommended = ["hex_value", "iana_description", "iana_recommended", "note"]

        expected_set = set()
        for e in expected_recommended:
            tup = tuple(e.get(c, "") for c in cols_for_recommended)
            expected_set.add(tup)

        if rec_rows is not None and rec_headers is not None and rec_headers == cols_for_recommended:
            actual_set = set()
            for r in rec_rows:
                tup = tuple(r.get(c, "") for c in cols_for_recommended)
                actual_set.add(tup)
            if expected_set == actual_set:
                scores["recommended_filtering_correct"] = 1.0

    # Email checks
    email_text = _read_text(email_path)
    if email_text is not None and cfg is not None:
        sibling_name = str(cfg.get("sibling_name", "")).strip()
        lines = [ln.rstrip("\n\r") for ln in email_text.splitlines()]
        first_nonempty_idx = None
        for i, ln in enumerate(lines):
            if ln.strip():
                first_nonempty_idx = i
                break
        greeting_ok = False
        if first_nonempty_idx is not None:
            first_line = lines[first_nonempty_idx]
            if sibling_name and sibling_name in first_line:
                greeting_ok = True
        if greeting_ok:
            scores["email_greeting_includes_name"] = 1.0

        non_bullet_text_parts = []
        for ln in lines:
            if re.match(r"^\s*[-*\u2022]\s+", ln):
                continue
            non_bullet_text_parts.append(ln)
        non_bullet_text = " ".join(non_bullet_text_parts)
        sentence_candidates = re.split(r"[.!?]+", non_bullet_text)
        sentences = [s.strip() for s in sentence_candidates if s.strip()]
        if 3 <= len(sentences) <= 6:
            scores["email_sentence_count_valid"] = 1.0

        refs_ok = ("out/tls_suites_enriched.csv" in email_text) and ("out/tls_suites_recommended.csv" in email_text)
        if refs_ok:
            scores["email_references_output_paths"] = 1.0

        bullet_lines = [ln for ln in lines if re.match(r"^\s*[-*\u2022]\s+", ln)]
        bullet_ok = False
        if expected_enriched:
            rec_items = [e for e in expected_enriched if _is_recommended_flag(e.get("iana_recommended", ""))]
            if not rec_items:
                bullet_ok = True
            else:
                def line_hex_ints(ln: str) -> List[int]:
                    ints = []
                    for m in re.finditer(r"0x[0-9a-fA-F]+", ln):
                        try:
                            ints.append(int(m.group(0), 16))
                        except Exception:
                            pass
                    return ints

                covered = 0
                for e in rec_items:
                    hex_str = e.get("hex_value", "")
                    val_int = _normalize_hex_to_int(hex_str)
                    name1 = e.get("normalized_name", "")
                    name2 = e.get("iana_description", "")
                    found = False
                    for bl in bullet_lines:
                        ints_in_line = line_hex_ints(bl)
                        if val_int is not None and val_int in ints_in_line:
                            if (name1 and name1.lower() in bl.lower()) or (name2 and name2.lower() in bl.lower()):
                                found = True
                                break
                    if found:
                        covered += 1
                bullet_ok = (covered == len(rec_items))
        if bullet_ok:
            scores["email_bullet_list_covers_recommended"] = 1.0

    return scores


def main() -> None:
    workspace = "."
    if len(sys.argv) > 1:
        workspace = sys.argv[1]
    result = grade([], workspace)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

import csv
import json
import re
import sys
from html.parser import HTMLParser
from pathlib import Path
from typing import List, Dict, Optional, Tuple


BASELINE_BUSINESS_PLAN = """# Sustainable Seafood Market – Business Plan

## Executive Summary
Our market will focus on responsibly sourced seafood with transparent labeling and strong supplier partnerships.

## Sourcing & Sustainability Strategy

<!-- AUTO-UPDATE:SOURCING_START -->
This section is automatically updated by the weekly sourcing workflow.
It will include a summary of low-stock species, recommended sustainable suppliers, and key compliance notes.
<!-- AUTO-UPDATE:SOURCING_END -->

## Operations Plan
We will maintain rigorous cold chain management and staff training to meet food safety and labeling standards.
"""


class RegulationsParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.in_tbody = False
        self.in_tr = False
        self.in_td = False
        self.current_cell: List[str] = []
        self.current_row: List[str] = []
        self.rows: List[List[str]] = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "tbody":
            self.in_tbody = True
        elif tag.lower() == "tr" and self.in_tbody:
            self.in_tr = True
            self.current_row = []
        elif tag.lower() == "td" and self.in_tr:
            self.in_td = True
            self.current_cell = []

    def handle_endtag(self, tag):
        if tag.lower() == "tbody":
            self.in_tbody = False
        elif tag.lower() == "tr" and self.in_tr:
            self.in_tr = False
            if self.current_row:
                self.rows.append(self.current_row)
            self.current_row = []
        elif tag.lower() == "td" and self.in_td:
            self.in_td = False
            cell_text = "".join(self.current_cell).strip()
            self.current_row.append(_normalize_ws(cell_text))
            self.current_cell = []

    def handle_data(self, data):
        if self.in_td:
            self.current_cell.append(data)


def _normalize_ws(s: str) -> str:
    return " ".join(s.split())


def _read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _read_csv_dicts(path: Path) -> Optional[List[Dict[str, str]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            rows = [dict(row) for row in reader]
        return rows
    except Exception:
        return None


def _parse_retail_requirements(path: Path) -> Optional[List[str]]:
    text = _read_text(path)
    if text is None:
        return None
    try:
        parser = RegulationsParser()
        parser.feed(text)
        reqs: List[str] = []
        for row in parser.rows:
            if len(row) >= 2 and row[0].strip() == "Retail":
                reqs.append(row[1].strip())
        return reqs
    except Exception:
        return None


def _to_float(value: str) -> Optional[float]:
    try:
        return float(value)
    except Exception:
        return None


def _compute_low_stock(inventory_rows: List[Dict[str, str]]) -> Optional[List[Dict[str, float]]]:
    low: List[Dict[str, float]] = []
    try:
        for row in inventory_rows:
            species = row.get("species", "").strip()
            c = _to_float(row.get("current_stock_kg", "").strip())
            r = _to_float(row.get("reorder_point_kg", "").strip())
            if species == "" or c is None or r is None:
                return None
            if c < r:
                low.append({
                    "species": species,
                    "current_stock_kg": c,
                    "reorder_point_kg": r,
                })
        return low
    except Exception:
        return None


def _select_suppliers(supplier_rows: List[Dict[str, str]], low_species: List[str]) -> Optional[Dict[str, Dict[str, Optional[float]]]]:
    try:
        selected: Dict[str, Dict[str, Optional[float]]] = {}
        for sp in low_species:
            candidates = []
            for row in supplier_rows:
                if row.get("species", "").strip() != sp:
                    continue
                cert = row.get("certification", "").strip()
                if cert not in {"MSC", "ASC"}:
                    continue
                score = _to_float(row.get("sustainability_score", "").strip())
                price = _to_float(row.get("price_per_kg", "").strip())
                sname = row.get("supplier_name", "").strip()
                if sname == "" or score is None or price is None:
                    return None
                if score >= 80:
                    candidates.append({
                        "supplier_name": sname,
                        "price_per_kg": price,
                        "sustainability_score": score,
                        "certification": cert,
                    })
            if candidates:
                candidates.sort(key=lambda d: (d["price_per_kg"], -d["sustainability_score"], d["supplier_name"]))
                best = candidates[0]
                selected[sp] = best
            else:
                selected[sp] = {
                    "supplier_name": "No eligible supplier",
                    "price_per_kg": None,
                    "sustainability_score": None,
                    "certification": "",
                }
        return selected
    except Exception:
        return None


def _find_headings_order(text: str, expected: List[str]) -> bool:
    lines = [ln.strip() for ln in text.splitlines()]
    indices = []
    for h in expected:
        try:
            idx = lines.index(h)
        except ValueError:
            return False
        indices.append(idx)
    return all(indices[i] < indices[i + 1] for i in range(len(indices) - 1))


def _extract_section(text: str, heading: str, all_headings: List[str]) -> Optional[str]:
    lines = text.splitlines()
    stripped = [ln.strip() for ln in lines]
    try:
        start_idx = stripped.index(heading)
    except ValueError:
        return None
    end_idx = len(lines)
    for i in range(start_idx + 1, len(lines)):
        if stripped[i] in all_headings:
            end_idx = i
            break
    content = "\n".join(lines[start_idx + 1:end_idx]).strip("\n")
    return content


def _parse_markdown_table(section_text: str, header_line_exact: str) -> Optional[List[Dict[str, str]]]:
    lines = [ln.rstrip() for ln in section_text.splitlines()]
    hdr_idx = None
    for i, ln in enumerate(lines):
        if ln.strip() == header_line_exact:
            hdr_idx = i
            break
    if hdr_idx is None:
        return None
    headers = [h.strip() for h in header_line_exact.split("|")]
    data_rows: List[Dict[str, str]] = []
    i = hdr_idx + 1
    if i < len(lines) and re.search(r"-", lines[i]):
        i += 1
    while i < len(lines):
        ln = lines[i].strip()
        if not ln or "|" not in ln:
            break
        parts = [p.strip() for p in ln.split("|")]
        while parts and parts[0] == "":
            parts = parts[1:]
        while parts and parts[-1] == "":
            parts = parts[:-1]
        if len(parts) != len(headers):
            return None
        row = dict(zip(headers, parts))
        data_rows.append(row)
        i += 1
    if not data_rows:
        return None
    return data_rows


def _float_in_text(val: float, text: str) -> bool:
    s = f"{val:.10g}"
    if "." in s:
        int_part, frac_part = s.split(".")
        frac_part = frac_part.rstrip("0")
        if not frac_part:
            pattern = rf"\b{re.escape(int_part)}(?:\.0+)?\b"
        else:
            pattern = rf"\b{re.escape(int_part)}\.{re.escape(frac_part)}(?:0+)?\b"
    else:
        pattern = rf"\b{re.escape(s)}(?:\.0+)?\b"
    return re.search(pattern, text) is not None


def _split_marked(text: str, start_marker: str, end_marker: str) -> Tuple[str, str, str]:
    start_idx = text.find(start_marker)
    end_idx = text.find(end_marker)
    if start_idx == -1 or end_idx == -1 or end_idx < start_idx:
        raise ValueError("Markers not found")
    before = text[:start_idx]
    between = text[start_idx + len(start_marker):end_idx]
    after = text[end_idx + len(end_marker):]
    return before, between, after


def _compare_business_plan_outside(content: str) -> bool:
    start_marker = "<!-- AUTO-UPDATE:SOURCING_START -->"
    end_marker = "<!-- AUTO-UPDATE:SOURCING_END -->"
    try:
        base_before, _, base_after = _split_marked(BASELINE_BUSINESS_PLAN, start_marker, end_marker)
        cur_before, _, cur_after = _split_marked(content, start_marker, end_marker)
    except ValueError:
        return False
    return base_before == cur_before and base_after == cur_after


def grade(transcript: list, workspace_path: str) -> dict:
