    try:
        data = path.read_text(encoding="utf-8")
        return data, None
    except Exception as e:
        return None, str(e)


def _read_json_safe(path: Path) -> Tuple[Optional[Any], Optional[str]]:
    try:
        text = path.read_text(encoding="utf-8")
        return json.loads(text), None
    except Exception as e:
        return None, str(e)


def _compute_sha256_hex(path: Path) -> Tuple[Optional[str], Optional[str]]:
    try:
        h = hashlib.sha256()
        with path.open("rb") as f:
            for chunk in iter(lambda: f.read(8192), b""):
                h.update(chunk)
        return h.hexdigest(), None
    except Exception as e:
        return None, str(e)


def _run_subprocess(cmd: List[str], cwd: Path) -> Tuple[int, str, str]:
    try:
        p = subprocess.run(
            cmd,
            cwd=str(cwd),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
        )
        return p.returncode, p.stdout, p.stderr
    except Exception as e:
        return -1, "", str(e)


def _relative_posix(path: Path, root: Path) -> str:
    try:
        rel = path.relative_to(root)
    except Exception:
        rel = path
    return rel.as_posix()


def _collect_expected_inventory(workspace: Path) -> Dict[str, Tuple[str, int]]:
    expected: Dict[str, Tuple[str, int]] = {}
    # Collect .py files under crypto_lib
    crypto_dir = workspace / "crypto_lib"
    if crypto_dir.exists():
        for p in sorted(crypto_dir.rglob("*.py")):
            sha, _ = _compute_sha256_hex(p)
            if sha is None:
                continue
            size = p.stat().st_size
            expected[_relative_posix(p, workspace)] = (sha, int(size))
    # Add config/security.json
    cfg = workspace / "config" / "security.json"
    if cfg.exists():
        sha, _ = _compute_sha256_hex(cfg)
        if sha is not None:
            expected[_relative_posix(cfg, workspace)] = (sha, int(cfg.stat().st_size))
    return expected


def _parse_inventory_file(inv_path: Path, workspace: Path) -> Tuple[Optional[Dict[str, Tuple[str, int]]], Optional[str]]:
    text, err = _read_text_safe(inv_path)
    if text is None:
        return None, err or "failed to read inventory"
    lines = [ln for ln in text.splitlines() if ln.strip() != ""]
    parsed: Dict[str, Tuple[str, int]] = {}
    for i, ln in enumerate(lines, 1):
        parts = ln.split("\t")
        if len(parts) != 3:
            return None, f"line {i} does not have 3 tab-separated fields"
        rel_path, sha, size_str = parts
        # Basic validations
        if len(sha) != 64 or any(c not in "0123456789abcdef" for c in sha.lower()):
            return None, f"line {i} sha256 invalid"
        try:
            size = int(size_str)
            if size < 0:
                return None, f"line {i} size negative"
        except Exception:
            return None, f"line {i} size not integer"
        # Ensure file exists
        file_path = workspace / rel_path
        if not file_path.exists():
            return None, f"line {i} references non-existent file {rel_path}"
        parsed[rel_path] = (sha.lower(), size)
    return parsed, None


def _import_crypto_and_list(workspace: Path) -> Tuple[Optional[List[str]], Optional[str]]:
    try:
        if str(workspace) not in sys.path:
            sys.path.insert(0, str(workspace))
        import importlib

        mod = importlib.import_module("crypto_lib")
        mod = importlib.reload(mod)
        if not hasattr(mod, "list_algorithms"):
            return None, "crypto_lib has no list_algorithms"
        algos = mod.list_algorithms()
        if not isinstance(algos, list) or not all(isinstance(a, str) for a in algos):
            return None, "list_algorithms did not return a list of strings"
        return algos, None
    except Exception as e:
        return None, str(e)


def _scan_disallowed_tokens(workspace: Path, tokens: List[str]) -> List[Dict[str, Any]]:
    results: List[Dict[str, Any]] = []
    crypto_dir = workspace / "crypto_lib"
    if not crypto_dir.exists():
        return results
    for file in sorted(crypto_dir.rglob("*")):
        if not file.is_file():
            continue
        try:
            text = file.read_text(encoding="utf-8", errors="replace")
        except Exception:
            continue
        lines = text.splitlines()
        for idx, line in enumerate(lines, 1):
            for token in tokens:
                start = 0
                # If token is empty, skip to avoid infinite loop
                if token == "":
                    continue
                while True:
                    pos = line.find(token, start)
                    if pos == -1:
                        break
                    results.append(
                        {
                            "file": _relative_posix(file, workspace),
                            "line": idx,
                            "match": token,
                        }
                    )
                    start = pos + len(token)
    return results


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "audit_script_runs": 0.0,
        "dir_inventory_correct": 0.0,
        "test_results_verbatim": 0.0,
        "compliance_report_structure": 0.0,
        "policy_fields_match_config": 0.0,
        "algorithms_declared_runtime_match": 0.0,
        "disallowed_scan_correct": 0.0,
        "compliance_logic_correct": 0.0,
    }

    # 1) Run audit script if present
    script_path = workspace / "scripts" / "audit_crypto.py"
    if script_path.exists():
        rc, out, err = _run_subprocess([sys.executable, str(script_path)], cwd=workspace)
        if rc == 0:
            scores["audit_script_runs"] = 1.0
        else:
            scores["audit_script_runs"] = 0.0
    else:
        scores["audit_script_runs"] = 0.0

    # Expected inventory
    expected_inventory = _collect_expected_inventory(workspace)

    # 2) Validate inventory file
    inv_path = workspace / "output" / "dir_inventory.txt"
    parsed_inv, inv_err = _parse_inventory_file(inv_path, workspace) if inv_path.exists() else (None, "missing")
    if parsed_inv is not None:
        # Check exact set equality
        expected_keys = set(expected_inventory.keys())
        parsed_keys = set(parsed_inv.keys())
        if parsed_keys == expected_keys:
            # Check sha and size match
            match_all = True
            for k in expected_keys:
                exp_sha, exp_size = expected_inventory[k]
                got_sha, got_size = parsed_inv[k]
                if exp_sha.lower() != got_sha.lower() or int(exp_size) != int(got_size):
                    match_all = False
                    break
            if match_all:
                scores["dir_inventory_correct"] = 1.0

    # 3) Validate test results are verbatim to validation command stdout
    test_out_path = workspace / "output" / "test_results.json"
    expected_stdout = None
    if (workspace / "tests" / "run_validation.py").exists():
        rc2, stdout2, stderr2 = _run_subprocess([sys.executable, "tests/run_validation.py"], cwd=workspace)
        if rc2 == 0:
            expected_stdout = stdout2
    actual_text, _ = _read_text_safe(test_out_path) if test_out_path.exists() else (None, "missing")
    if expected_stdout is not None and actual_text is not None:
        # Exact verbatim comparison (no normalization)
        if expected_stdout == actual_text:
            scores["test_results_verbatim"] = 1.0

    # 4) Compliance report structure and content
    report_path = workspace / "output" / "compliance_report.json"
    report_obj, _ = _read_json_safe(report_path) if report_path.exists() else (None, "missing")
    cfg_path = workspace / "config" / "security.json"
    cfg_obj, _ = _read_json_safe(cfg_path) if cfg_path.exists() else (None, "missing")
    # Structure check
    if isinstance(report_obj, dict):
        required_fields = [
            "fips_mode",
            "allowed_algorithms",
            "denylist",
            "algorithms_declared",
            "disallowed_references",
            "compliance",
            "reasons",
        ]
        has_all = all(k in report_obj for k in required_fields)
        types_ok = (
            isinstance(report_obj.get("fips_mode"), bool)
            and isinstance(report_obj.get("allowed_algorithms"), list)
            and all(isinstance(x, str) for x in report_obj.get("allowed_algorithms", []))
            and isinstance(report_obj.get("denylist"), list)
            and all(isinstance(x, str) for x in report_obj.get("denylist", []))
            and isinstance(report_obj.get("algorithms_declared"), list)
            and all(isinstance(x, str) for x in report_obj.get("algorithms_declared", []))
            and isinstance(report_obj.get("disallowed_references"), list)
            and all(
                isinstance(x, dict)
                and "file" in x
                and "line" in x
                and "match" in x
                and isinstance(x.get("file"), str)
                and isinstance(x.get("line"), int)
                and isinstance(x.get("match"), str)
                for x in report_obj.get("disallowed_references", [])
            )
            and report_obj.get("compliance") in {"pass", "fail"}
            and isinstance(report_obj.get("reasons"), list)
            and all(isinstance(x, str) for x in report_obj.get("reasons", []))
        )
        reasons_ok = True
        if report_obj.get("compliance") == "fail":
            reasons_ok = len(report_obj.get("reasons", [])) >= 1
        if has_all and types_ok and reasons_ok:
            scores["compliance_report_structure"] = 1.0

    # Policy fields should match config
    if isinstance(report_obj, dict) and isinstance(cfg_obj, dict):
        cfg_fips = cfg_obj.get("fips_mode")
        cfg_allowed = cfg_obj.get("allowed_algorithms", [])
        cfg_deny = cfg_obj.get("denylist", [])
        if (
            report_obj.get("fips_mode") == cfg_fips
            and report_obj.get("allowed_algorithms") == cfg_allowed
            and report_obj.get("denylist") == cfg_deny
        ):
            scores["policy_fields_match_config"] = 1.0

    # Algorithms declared should match runtime import
    runtime_algos, _ = _import_crypto_and_list(workspace)
    if isinstance(report_obj, dict) and runtime_algos is not None:
        if report_obj.get("algorithms_declared") == runtime_algos:
            scores["algorithms_declared_runtime_match"] = 1.0

    # Disallowed scan expected correctness
    if isinstance(report_obj, dict) and isinstance(cfg_obj, dict):
        deny_tokens = list(cfg_obj.get("denylist", []))
        allowed = set(cfg_obj.get("allowed_algorithms", []))
        runtime_algos2, _ = _import_crypto_and_list(workspace)
        non_allowed_names = set()
        if runtime_algos2 is not None:
            non_allowed_names = set(a for a in runtime_algos2 if a not in allowed)
        tokens_to_search = sorted(set(deny_tokens) | non_allowed_names)
        expected_refs = _scan_disallowed_tokens(workspace, tokens_to_search)

        def _to_counts(refs: List[Dict[str, Any]]) -> Dict[Tuple[str, int, str], int]:
            d: Dict[Tuple[str, int, str], int] = {}
            for r in refs:
                key = (r.get("file"), int(r.get("line")), r.get("match"))
                d[key] = d.get(key, 0) + 1
            return d

        reported_refs = report_obj.get("disallowed_references", []) if isinstance(report_obj, dict) else []
        # Validate that all reported matches are valid (file under crypto_lib, line contains the match)
        valid_reported = True
        for r in reported_refs:
            if not isinstance(r, dict):
                valid_reported = False
                break
            f = r.get("file")
            l = r.get("line")
            m = r.get("match")
            if not (isinstance(f, str) and isinstance(l, int) and isinstance(m, str)):
                valid_reported = False
                break
            fpath = workspace / f
            if not fpath.exists():
                valid_reported = False
                break
            rel = _relative_posix(fpath, workspace)
            if not rel.startswith("crypto_lib/"):
                valid_reported = False
                break
            content, err = _read_text_safe(fpath)
            if content is None:
                valid_reported = False
                break
            lines = content.splitlines()
            if l <= 0 or l > len(lines):
                valid_reported = False
                break
            if lines[l - 1].find(m) == -1:
                valid_reported = False
                break
            if m not in tokens_to_search:
                valid_reported = False
                break
        if valid_reported:
            exp_counts = _to_counts(expected_refs)
            rep_counts = _to_counts(reported_refs)
            if exp_counts == rep_counts:
                scores["disallowed_scan_correct"] = 1.0

    # Compliance logic correctness
    if isinstance(report_obj, dict) and isinstance(cfg_obj, dict):
        fips_mode = bool(cfg_obj.get("fips_mode", False))
        allowed_algos = list(cfg_obj.get("allowed_algorithms", []))
        algos_declared = report_obj.get("algorithms_declared", [])
        disallowed_refs = report_obj.get("disallowed_references", [])
        if fips_mode:
            subset_ok = set(algos_declared).issubset(set(allowed_algos))
            disallowed_empty = len(disallowed_refs) == 0
            expected_compliance = "pass" if (subset_ok and disallowed_empty) else "fail"
        else:
            expected_compliance = "pass" if len(disallowed_refs) == 0 else "fail"
        if report_obj.get("compliance") == expected_compliance:
            scores["compliance_logic_correct"] = 1.0

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result))


if __name__ == "__main__":
    main()

import json
import sys
import re
from pathlib import Path
from typing import Optional, List, Dict, Any, Tuple


def _read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        try:
            return path.read_text(encoding="latin-1")
        except Exception:
            return None


def _load_json(path: Path) -> Optional[Any]:
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _list_files_recursive(root: Path) -> List[str]:
    if not root.exists():
        return []
    files: List[str] = []
    for p in sorted(root.rglob("*")):
        if p.is_file():
            rel = p.relative_to(root).as_posix()
            files.append(rel)
    return files


def _find_first_line(text: str, substring: str) -> Optional[int]:
    for idx, line in enumerate(text.splitlines(), start=1):
        if substring in line:
            return idx
    return None


def _find_all_lines(text: str, substring: str) -> List[int]:
    res = []
    for idx, line in enumerate(text.splitlines(), start=1):
        if substring in line:
            res.append(idx)
    return res


def _normalize_rel_path(p: str) -> str:
    return Path(p).as_posix().lstrip("/")


def _validate_findings_schema(findings: Any) -> Tuple[bool, List[Dict[str, Any]]]:
    if not isinstance(findings, list):
        return False, []
    valid = True
    sanitized: List[Dict[str, Any]] = []
    allowed_sev = {"low", "medium", "high", "critical"}
    for item in findings:
        if not isinstance(item, dict):
            valid = False
            continue
        keys = {
            "id",
            "severity",
            "issue_type",
            "file_path",
            "line_start",
            "line_end",
            "description",
            "evidence",
            "recommendation",
        }
        if not keys.issubset(item.keys()):
            valid = False
        id_ok = isinstance(item.get("id"), str)
        sev_ok = isinstance(item.get("severity"), str) and item.get("severity") in allowed_sev
        itype_ok = isinstance(item.get("issue_type"), str)
        fpath_ok = isinstance(item.get("file_path"), str)
        try:
            ls = int(item.get("line_start"))
            le = int(item.get("line_end"))
            lines_ok = ls >= 1 and le >= ls
        except Exception:
            lines_ok = False
        desc_ok = isinstance(item.get("description"), str)
        ev_ok = isinstance(item.get("evidence"), str) and len(item.get("evidence")) > 0
        rec_ok = isinstance(item.get("recommendation"), str)
        if not (id_ok and sev_ok and itype_ok and fpath_ok and lines_ok and desc_ok and ev_ok and rec_ok):
            valid = False
        sanitized.append(item)
    return valid, sanitized


def _ids_unique_and_formatted(findings: List[Dict[str, Any]]) -> bool:
    ids = [f.get("id") for f in findings if isinstance(f.get("id"), str)]
    if len(ids) != len(findings):
        return False
    if len(set(ids)) != len(ids):
        return False
    pattern = re.compile(r"^F\d{3,}$")
    for i in ids:
        if not pattern.match(i):
            return False
    return True


def _file_paths_valid(findings: List[Dict[str, Any]], repo_root: Path) -> bool:
    for f in findings:
        fp = f.get("file_path")
        if not isinstance(fp, str):
            return False
        if fp.startswith("/") or "input/repo" in fp:
            return False
        target = (repo_root / fp).resolve()
        try:
            # Ensure target is within repo_root directory
            rr = repo_root.resolve()
            if rr != target and rr not in target.parents:
                return False
        except Exception:
            return False
        if not target.exists() or not target.is_file():
            return False
        text = _read_text(target)
        if text is None:
            return False
        n_lines = len(text.splitlines())
        try:
            ls = int(f.get("line_start"))
            le = int(f.get("line_end"))
        except Exception:
            return False
        if n_lines <= 0:
            return False
        if ls < 1 or le < ls or le > n_lines:
            return False
    return True


def _match_finding(
    findings: List[Dict[str, Any]],
    file_rel: str,
    issue_types_set: Optional[set] = None,
    expected_line: Optional[int] = None,
    evidence_substring: Optional[str] = None,
) -> bool:
    for f in findings:
        try:
            fpath = f.get("file_path")
            itype = f.get("issue_type")
            ev = f.get("evidence", "")
            ls = int(f.get("line_start"))
            le = int(f.get("line_end"))
        except Exception:
            continue
        if fpath != file_rel:
            continue
        if issue_types_set is not None:
            if not isinstance(itype, str):
                continue
            if itype.lower() not in {s.lower() for s in issue_types_set}:
                continue
        if expected_line is not None:
            if not (ls <= expected_line <= le):
                continue
        if evidence_substring is not None:
            if evidence_substring not in (ev or ""):
                continue
        return True
    return False


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    repo_root = workspace / "input" / "repo"
    out_root = workspace / "output" / "security_audit"

    findings_path = out_root / "findings.json"
    summary_path = out_root / "summary.md"
    inventory_path = out_root / "inventory.txt"

    scores: Dict[str, float] = {
        "findings_json_present": 0.0,
        "findings_json_parseable": 0.0,
        "findings_schema_valid": 0.0,
        "findings_ids_unique_and_formatted": 0.0,
        "findings_file_paths_valid": 0.0,
        "expected_issue_unsafe_yaml_load": 0.0,
        "expected_issue_shell_true": 0.0,
        "expected_issue_pickle_load": 0.0,
        "expected_issue_debug_or_eval_config": 0.0,
        "expected_issue_hardcoded_secret_settings": 0.0,
        "expected_issue_hardcoded_secret_keys": 0.0,
        "expected_issue_insecure_transport": 0.0,
        "expected_issue_world_writable_permissions": 0.0,
        "summary_md_present": 0.0,
        "summary_contains_overview_paragraph": 0.0,
        "summary_lists_all_findings": 0.0,
        "summary_top3_fixes_present": 0.0,
        "inventory_present": 0.0,
        "inventory_complete_and_correct": 0.0,
    }

    # Load and validate findings.json
    findings: Optional[List[Dict[str, Any]]] = None
    if findings_path.exists():
        scores["findings_json_present"] = 1.0
        findings_obj = _load_json(findings_path)
        if isinstance(findings_obj, list):
            scores["findings_json_parseable"] = 1.0
            schema_ok, sanitized = _validate_findings_schema(findings_obj)
            if schema_ok:
                scores["findings_schema_valid"] = 1.0
                findings = sanitized
                if _ids_unique_and_formatted(findings):
                    scores["findings_ids_unique_and_formatted"] = 1.0
                if _file_paths_valid(findings, repo_root):
                    scores["findings_file_paths_valid"] = 1.0
        else:
            scores["findings_json_parseable"] = 0.0

    # Prepare texts for scanning expected issues
    analyze_rel = "src/analyze.py"
    settings_rel = "config/settings.yaml"
    ingest_rel = "scripts/ingest.sh"
    keys_rel = "keys/legacy_credentials.txt"

    analyze_text = _read_text(repo_root / analyze_rel) or ""
    settings_text = _read_text(repo_root / settings_rel) or ""
    ingest_text = _read_text(repo_root / ingest_rel) or ""
    keys_text = _read_text(repo_root / keys_rel) or ""

    yaml_line = _find_first_line(analyze_text, "yaml.load(")
    shell_line = _find_first_line(analyze_text, "shell=True")
    pickle_line = _find_first_line(analyze_text, "pickle.load(")

    debug_flag_lines = _find_all_lines(settings_text, "debug: true")
    eval_flag_lines = _find_all_lines(settings_text, "allow_eval: true")

    api_token_lines = _find_all_lines(settings_text, "api_token:")
    db_url_lines = _find_all_lines(settings_text, "database_url:")

    keys_secret_lines = []
    keys_secret_lines.extend(_find_all_lines(keys_text, "DB_PASSWORD="))
    keys_secret_lines.extend(_find_all_lines(keys_text, "AWS_SECRET_ACCESS_KEY="))
    keys_secret_lines.extend(_find_all_lines(keys_text, "BEGIN RSA PRIVATE KEY"))

    insecure_flag_line = _find_first_line(ingest_text, "--insecure")
    chmod_777_line = _find_first_line(ingest_text, "chmod 777")

    UNSAFE_YAML_TYPES = {
        "unsafe_yaml_load",
        "unsafe_yaml_loading",
        "insecure_yaml_load",
        "yaml_load_unsafe",
        "yaml_unsafe_load",
    }
    UNSAFE_SHELL_TYPES = {
        "unsafe_shell",
        "shell_injection",
        "shell_true",
        "command_injection",
        "subprocess_shell",
    }
    UNSAFE_PICKLE_TYPES = {
        "unsafe_deserialization",
        "insecure_deserialization",
        "pickle_load_untrusted",
        "unsafe_pickle",
        "pickle_deserialization",
    }
    DEBUG_TYPES = {"debug_enabled", "insecure_debug", "debug_mode_enabled"}
    EVAL_FLAG_TYPES = {"eval_enabled", "dangerous_eval", "eval_flag", "eval_usage", "insecure_eval"}
    HARD_CODED_SECRET_TYPES = {
        "hardcoded_secret",
        "hardcoded_credentials",
        "secret_in_repo",
        "sensitive_data_exposure",
        "credential_exposure",
    }
    INSECURE_TRANSPORT_TYPES = {
        "insecure_transport",
        "tls_skip_verify",
        "insecure_curl",
        "curl_insecure",
        "ssl_no_verify",
    }
    WORLD_WRITABLE_TYPES = {
        "world_writable_permissions",
        "chmod_777",
        "insecure_permissions",
        "overly_permissive_permissions",
    }

    # 1) Unsafe YAML loading
    if yaml_line is None:
        scores["expected_issue_unsafe_yaml_load"] = 1.0
    elif findings:
        if _match_finding(findings, analyze_rel, UNSAFE_YAML_TYPES, expected_line=yaml_line, evidence_substring="yaml.load"):
            scores["expected_issue_unsafe_yaml_load"] = 1.0

    # 2) shell=True with user-controlled command
    if shell_line is None:
        scores["expected_issue_shell_true"] = 1.0
    elif findings:
        if _match_finding(findings, analyze_rel, UNSAFE_SHELL_TYPES, expected_line=shell_line, evidence_substring="shell=True"):
            scores["expected_issue_shell_true"] = 1.0

    # 3) pickle.load on untrusted input
    if pickle_line is None:
        scores["expected_issue_pickle_load"] = 1.0
    elif findings:
        if _match_finding(findings, analyze_rel, UNSAFE_PICKLE_TYPES, expected_line=pickle_line, evidence_substring="pickle.load"):
            scores["expected_issue_pickle_load"] = 1.0

    # 4) Debug or eval-like flags enabled via configuration
    if not debug_flag_lines and not eval_flag_lines:
        scores["expected_issue_debug_or_eval_config"] = 1.0
    elif findings:
        matched = False
        for l in debug_flag_lines:
            if _match_finding(findings, settings_rel, DEBUG_TYPES, expected_line=l, evidence_substring="debug: true"):
                matched = True
                break
        if not matched:
            for l in eval_flag_lines:
                if _match_finding(findings, settings_rel, EVAL_FLAG_TYPES, expected_line=l, evidence_substring="allow_eval: true"):
                    matched = True
                    break
        if matched:
            scores["expected_issue_debug_or_eval_config"] = 1.0

    # 5) Hardcoded credentials or tokens in config/settings.yaml
    if not api_token_lines and not db_url_lines:
        scores["expected_issue_hardcoded_secret_settings"] = 1.0
    elif findings:
        matched = False
        for l in api_token_lines:
            if _match_finding(findings, settings_rel, HARD_CODED_SECRET_TYPES, expected_line=l, evidence_substring="api_token"):
                matched = True
                break
        if not matched:
            for l in db_url_lines:
                if _match_finding(findings, settings_rel, HARD_CODED_SECRET_TYPES, expected_line=l, evidence_substring="database_url"):
                    matched = True
                    break
        if matched:
            scores["expected_issue_hardcoded_secret_settings"] = 1.0

    # 6) Hardcoded credentials in keys/legacy_credentials.txt
    if not keys_secret_lines:
        scores["expected_issue_hardcoded_secret_keys"] = 1.0
    elif findings:
        matched = False
        for l in keys_secret_lines:
            substrings = ["DB_PASSWORD=", "AWS_SECRET_ACCESS_KEY=", "BEGIN RSA PRIVATE KEY"]
            for sub in substrings:
                if _match_finding(findings, keys_rel, HARD_CODED_SECRET_TYPES, expected_line=l, evidence_substring=sub):
                    matched = True
                    break
            if matched:
                break
        if matched:
            scores["expected_issue_hardcoded_secret_keys"] = 1.0

    # 7) Insecure transport (--insecure) in ingest.sh
    if insecure_flag_line is None:
        scores["expected_issue_insecure_transport"] = 1.0
    elif findings:
        if _match_finding(findings, ingest_rel, INSECURE_TRANSPORT_TYPES, expected_line=insecure_flag_line, evidence_substring="--insecure"):
            scores["expected_issue_insecure_transport"] = 1.0

    # 8) World-writable permissions (chmod 777) in ingest.sh
    if chmod_777_line is None:
        scores["expected_issue_world_writable_permissions"] = 1.0
    elif findings:
        if _match_finding(findings, ingest_rel, WORLD_WRITABLE_TYPES, expected_line=chmod_777_line, evidence_substring="chmod 777"):
            scores["expected_issue_world_writable_permissions"] = 1.0

    # Summary checks
    if summary_path.exists():
        scores["summary_md_present"] = 1.0
        summary_text = _read_text(summary_path) or ""
        has_overview = False
        for line in summary_text.splitlines():
            s = line.strip()
            if s == "":
                continue
            if s.startswith("- ") or s.startswith("* ") or s.startswith("#"):
                continue
            has_overview = True
            break
        if has_overview:
            scores["summary_contains_overview_paragraph"] = 1.0

        lines_all = summary_text.splitlines()
        idx_phrase = -1
        phrase = "top 3 immediate fixes"
        for i, ln in enumerate(lines_all):
            if phrase in ln.strip().lower():
                idx_phrase = i
                break
        if idx_phrase != -1:
            bullets_after = 0
            for ln in lines_all[idx_phrase + 1 :]:
                st = ln.strip()
                if st.startswith("- ") or st.startswith("* "):
                    bullets_after += 1
                elif st == "":
                    continue
                else:
                    continue
            if bullets_after >= 3:
                scores["summary_top3_fixes_present"] = 1.0

        # Bullet list of identified findings with id, issue_type, severity
        if findings and isinstance(findings, list) and findings:
            bullets = [ln.strip() for ln in summary_text.splitlines() if ln.strip().startswith("- ") or ln.strip().startswith("* ")]
            all_present = True
            for f in findings:
                fid = str(f.get("id"))
                itype = str(f.get("issue_type"))
                sev = str(f.get("severity"))
                found_line = False
                for b in bullets:
                    if fid in b and itype in b and sev in b:
                        found_line = True
                        break
                if not found_line:
                    all_present = False
                    break
            if all_present:
                scores["summary_lists_all_findings"] = 1.0
        else:
            scores["summary_lists_all_findings"] = 1.0

    # Inventory checks
    if inventory_path.exists():
        scores["inventory_present"] = 1.0
        inv_text = _read_text(inventory_path)
        if inv_text is not None:
            inv_lines = [ln.strip() for ln in inv_text.splitlines() if ln.strip() != ""]
            inv_norm = [_normalize_rel_path(ln) for ln in inv_lines]
            has_bad = any(ln.startswith("/") or ln.startswith("input/repo") for ln in inv_norm)
            expected_files = _list_files_recursive(repo_root)
            inv_set = set(inv_norm)
            exp_set = set(expected_files)
            no_dups = len(inv_set) == len(inv_norm)
            if not has_bad and no_dups and inv_set == exp_set:
                scores["inventory_complete_and_correct"] = 1.0

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

import json
import sys
import csv
from pathlib import Path
from datetime import datetime, timedelta, date
from typing import Any, Dict, Optional, Tuple
from zoneinfo import ZoneInfo


def _safe_read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return None


def _safe_load_json(path: Path) -> Optional[Any]:
    try:
        text = _safe_read_text(path)
        if text is None:
            return None
        return json.loads(text)
    except Exception:
        return None


def _parse_number(token: str) -> Any:
    token = token.strip()
    if token == "" or token.lower() in ("null", "none"):
        return None
    try:
        if token.startswith("0") and token != "0" and not token.startswith("0."):
            raise ValueError()
        return int(token)
    except Exception:
        try:
            return float(token)
        except Exception:
            if (token.startswith('"') and token.endswith('"')) or (token.startswith("'") and token.endswith("'")):
                return token[1:-1]
            return token


def _strip_comment(line: str) -> str:
    out = []
    in_single = False
    in_double = False
    for ch in line:
        if ch == "'" and not in_double:
            in_single = not in_single
            out.append(ch)
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            out.append(ch)
            continue
        if ch == "#" and not in_single and not in_double:
            break
        out.append(ch)
    return "".join(out).rstrip("\n")


def _load_simple_yaml(path: Path) -> Optional[dict]:
    text = _safe_read_text(path)
    if text is None:
        return None
    lines = text.splitlines()
    root: Dict[str, Any] = {}
    stack: list[Tuple[int, Dict[str, Any]]] = [(-1, root)]
    for raw_line in lines:
        line = _strip_comment(raw_line).rstrip()
        if not line.strip():
            continue
        indent = len(line) - len(line.lstrip(" "))
        if "\t" in line:
            return None
        while stack and indent <= stack[-1][0]:
            stack.pop()
        if not stack:
            return None
        current_dict = stack[-1][1]
        if ":" not in line:
            return None
        key_part, value_part = line.lstrip().split(":", 1)
        key = key_part.strip()
        value = value_part.strip()
        if value == "":
            new_dict: Dict[str, Any] = {}
            current_dict[key] = new_dict
            stack.append((indent, new_dict))
        else:
            current_dict[key] = _parse_number(value)
    return root


def _safe_parse_csv(path: Path) -> Optional[list]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            rows = [dict(r) for r in reader]
            return rows
    except Exception:
        return None


def _is_bool_string(val: str) -> bool:
    return val in ("true", "false")


def _parse_iso_date(s: str) -> Optional[date]:
    try:
        return datetime.strptime(s, "%Y-%m-%d").date()
    except Exception:
        return None


def _float_equal(a: float, b: float, eps: float = 1e-6) -> bool:
    return abs(a - b) <= eps


def _weekday_index_from_name(name: str) -> Optional[int]:
    mapping = {
        "monday": 0,
        "tuesday": 1,
        "wednesday": 2,
        "thursday": 3,
        "friday": 4,
        "saturday": 5,
        "sunday": 6,
    }
    if not isinstance(name, str):
        return None
    return mapping.get(name.strip().lower())


def _compute_week_start(dt: date, week_start_index: int) -> date:
    delta = (dt.weekday() - week_start_index) % 7
    return dt - timedelta(days=delta)


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores: Dict[str, float] = {
        "web_html_saved": 0.0,
        "web_txt_saved": 0.0,
        "limits_json_valid": 0.0,
        "daily_totals_structure": 0.0,
        "daily_totals_values_match": 0.0,
        "weekly_summary_structure": 0.0,
        "weekly_summary_values_match": 0.0,
        "weekly_start_day_alignment": 0.0,
        "report_includes_data_sources": 0.0,
        "report_includes_conversion_assumptions": 0.0,
        "report_includes_extracted_limits": 0.0,
        "report_notes_baseline_vs_extracted": 0.0,
    }

    html_path = workspace / "web" / "niaaa_low_risk.html"
    txt_path = workspace / "web" / "niaaa_low_risk.txt"
    limits_json_path = workspace / "web" / "niaaa_low_risk_limits.json"
    daily_csv_path = workspace / "output" / "daily_totals.csv"
    weekly_csv_path = workspace / "output" / "weekly_summary.csv"
    report_path = workspace / "output" / "report.md"

    html_text = _safe_read_text(html_path)
    if html_text is not None and len(html_text.strip()) > 0:
        if ("niaaa.nih.gov" in html_text) or ("Rethinking Drinking" in html_text) or ("low-risk" in html_text) or ("Low-Risk" in html_text) or ("NIAAA" in html_text):
            scores["web_html_saved"] = 1.0

    txt_text = _safe_read_text(txt_path)
    if txt_text is not None and len(txt_text.strip()) > 0:
        has_digit = any(ch.isdigit() for ch in txt_text)
        if has_digit or ("low-risk" in txt_text.lower()) or ("limit" in txt_text.lower()):
            scores["web_txt_saved"] = 1.0

    limits_obj = _safe_load_json(limits_json_path)
    limits_ok = False
    men_daily = None
    men_weekly = None
    women_daily = None
    women_weekly = None
    if isinstance(limits_obj, dict) and "men" in limits_obj and "women" in limits_obj:
        men = limits_obj.get("men", {})
        women = limits_obj.get("women", {})
        if isinstance(men, dict) and isinstance(women, dict):
            men_daily = men.get("daily")
            men_weekly = men.get("weekly")
            women_daily = women.get("daily")
            women_weekly = women.get("weekly")

            def _is_num(x): return isinstance(x, (int, float)) and not isinstance(x, bool)
            if _is_num(men_daily) and _is_num(men_weekly) and _is_num(women_daily) and _is_num(women_weekly):
                limits_ok = True
    if limits_ok:
        scores["limits_json_valid"] = 1.0

    sd_yaml_path = workspace / "config" / "standard_drinks.yaml"
    baseline_yaml_path = workspace / "config" / "baseline_limits.yaml"
    profile_yaml_path = workspace / "config" / "profile.yaml"
    sd_cfg = _load_simple_yaml(sd_yaml_path) or {}
    baseline_cfg = _load_simple_yaml(baseline_yaml_path) or {}
    profile_cfg = _load_simple_yaml(profile_yaml_path) or {}

    drink_types_cfg = {}
    default_factor = None
    try:
        drink_types_cfg = (sd_cfg.get("drink_types") or {})
        default_factor = (sd_cfg.get("default") or {}).get("standard_drink_per_oz")
    except Exception:
        drink_types_cfg = {}
        default_factor = None
    factors: Dict[str, float] = {}
    if isinstance(drink_types_cfg, dict):
        for k, v in drink_types_cfg.items():
            try:
                factors[str(k).strip().lower()] = float(v.get("standard_drink_per_oz"))
            except Exception:
                continue
    try:
        default_factor = float(default_factor) if default_factor is not None else None
    except Exception:
        default_factor = None

    sex = None
    tz_name = None
    weekly_start_name = None
    try:
        user = (profile_cfg.get("user") or {})
        sex = str(user.get("sex")).strip().lower() if user.get("sex") is not None else None
        tz_name = str(user.get("timezone")).strip() if user.get("timezone") is not None else None
        weekly_start_name = str(user.get("weekly_start_day")).strip() if user.get("weekly_start_day") is not None else None
    except Exception:
        pass
    week_start_index = _weekday_index_from_name(weekly_start_name) if weekly_start_name else None

    sex_key = None
    if isinstance(sex, str):
        if sex in ("male", "man", "m"):
            sex_key = "men"
        elif sex in ("female", "woman", "f"):
            sex_key = "women"
    daily_limit = None
    weekly_limit = None
    if limits_ok and sex_key:
        if sex_key == "men":
            daily_limit = float(men_daily)
            weekly_limit = float(men_weekly)
        else:
            daily_limit = float(women_daily)
            weekly_limit = float(women_weekly)

    drink_log_path = workspace / "input" / "drink_log.csv"
    drink_rows = _safe_parse_csv(drink_log_path) or []

    expected_daily_totals: Dict[str, float] = {}
    expected_exceeded_by_day: Dict[str, bool] = {}
    tzinfo = None
    if tz_name:
        try:
            tzinfo = ZoneInfo(tz_name)
        except Exception:
            tzinfo = None
    for r in drink_rows:
        try:
            d_str = (r.get("date") or "").strip()
            t_str = (r.get("time") or "").strip()
            drink_type = (r.get("drink_type") or "").strip().lower()
            vol_str = (r.get("volume_oz") or "").strip()
            if not d_str or not t_str or not vol_str:
                continue
            dt_naive = datetime.strptime(f"{d_str} {t_str}", "%Y-%m-%d %H:%M")
            if tzinfo is not None:
                dt_local = dt_naive.replace(tzinfo=tzinfo)
            else:
                dt_local = dt_naive
            day_key = dt_local.date().isoformat()
            factor = factors.get(drink_type, default_factor if default_factor is not None else 0.0)
            vol = float(vol_str)
            std_drinks = vol * float(factor)
            expected_daily_totals[day_key] = expected_daily_totals.get(day_key, 0.0) + std_drinks
        except Exception:
            continue
    if daily_limit is not None:
        for d, total in expected_daily_totals.items():
            expected_exceeded_by_day[d] = total > daily_limit

    daily_structure_ok = False
    daily_values_ok = False
    daily_file_rows = _safe_parse_csv(daily_csv_path)
    if isinstance(daily_file_rows, list):
        try:
            with daily_csv_path.open("r", encoding="utf-8", newline="") as f:
                reader = csv.reader(f)
                header = next(reader, None)
        except Exception:
            header = None
        if header == ["date", "total_standard_drinks", "exceeded_daily_limit"]:
            structure_rows_ok = True
            file_map: Dict[str, Tuple[float, str]] = {}
            for row in daily_file_rows:
                d = (row.get("date") or "").strip()
                tsd = (row.get("total_standard_drinks") or "").strip()
                edl = (row.get("exceeded_daily_limit") or "").strip()
                if _parse_iso_date(d) is None:
                    structure_rows_ok = False
                    break
                try:
                    tsd_val = float(tsd)
                except Exception:
                    structure_rows_ok = False
                    break
                if not _is_bool_string(edl):
                    structure_rows_ok = False
                    break
                file_map[d] = (tsd_val, edl)
            if structure_rows_ok:
                daily_structure_ok = True
                if expected_daily_totals:
                    all_match = True
                    for d, expected_total in expected_daily_totals.items():
                        if d not in file_map:
                            all_match = False
                            break
                        got_total, got_exceeded = file_map[d]
                        if not _float_equal(got_total, expected_total, eps=1e-4):
                            all_match = False
                            break
                        if daily_limit is not None:
                            exp_exceeded = "true" if expected_exceeded_by_day.get(d, False) else "false"
                            if got_exceeded != exp_exceeded:
                                all_match = False
                                break
                    if all_match:
                        daily_values_ok = True
                else:
                    daily_values_ok = False
    scores["daily_totals_structure"] = 1.0 if daily_structure_ok else 0.0
    scores["daily_totals_values_match"] = 1.0 if daily_values_ok else 0.0

    expected_weeks: Dict[str, Dict[str, Any]] = {}
    if week_start_index is not None and expected_daily_totals:
        for d_str, total in expected_daily_totals.items():
            d_obj = _parse_iso_date(d_str)
            if d_obj is None:
                continue
            w_start = _compute_week_start(d_obj, week_start_index)
            w_end = w_start + timedelta(days=6)
            wkey = w_start.isoformat()
            if wkey not in expected_weeks:
                expected_weeks[wkey] = {
                    "week_start": w_start,
                    "week_end": w_end,
                    "total_standard_drinks": 0.0,
                    "days_exceeded_daily_limit": 0,
                }
            expected_weeks[wkey]["total_standard_drinks"] += total
            if daily_limit is not None and expected_exceeded_by_day.get(d_str, False):
                expected_weeks[wkey]["days_exceeded_daily_limit"] += 1
        if weekly_limit is not None:
            for _, rec in expected_weeks.items():
                rec["exceeded_weekly_limit"] = rec["total_standard_drinks"] > weekly_limit

    weekly_structure_ok = False
    weekly_values_ok = False
    weekly_alignment_ok = False
    weekly_rows = _safe_parse_csv(weekly_csv_path)
    if isinstance(weekly_rows, list):
        try:
            with weekly_csv_path.open("r", encoding="utf-8", newline="") as f:
                reader = csv.reader(f)
                header = next(reader, None)
        except Exception:
            header = None
        expected_header = [
            "week_start",
            "week_end",
            "total_standard_drinks",
            "avg_daily_standard_drinks",
            "days_exceeded_daily_limit",
            "exceeded_weekly_limit",
        ]
        if header == expected_header:
            structure_rows_ok = True
            alignment_ok = True
            file_weeks: Dict[str, Dict[str, Any]] = {}
            for row in weekly_rows:
                ws = (row.get("week_start") or "").strip()
                we = (row.get("week_end") or "").strip()
                tsd = (row.get("total_standard_drinks") or "").strip()
                ads = (row.get("avg_daily_standard_drinks") or "").strip()
                ded = (row.get("days_exceeded_daily_limit") or "").strip()
                ewl = (row.get("exceeded_weekly_limit") or "").strip()
                ws_date = _parse_iso_date(ws)
                we_date = _parse_iso_date(we)
                if ws_date is None or we_date is None:
                    structure_rows_ok = False
                    break
                if we_date < ws_date:
                    structure_rows_ok = False
                    break
                try:
                    tsd_val = float(tsd)
                    _ = float(ads)
                except Exception:
                    structure_rows_ok = False
                    break
                try:
                    ded_val = int(ded)
                except Exception:
                    structure_rows_ok = False
                    break
                if not _is_bool_string(ewl):
                    structure_rows_ok = False
                    break
                if week_start_index is not None and ws_date.weekday() != week_start_index:
                    alignment_ok = False
                file_weeks[ws] = {
                    "week_start": ws_date,
                    "week_end": we_date,
                    "total_standard_drinks": tsd_val,
                    "days_exceeded_daily_limit": ded_val,
                    "exceeded_weekly_limit": ewl,
                }
            if structure_rows_ok:
                weekly_structure_ok = True
                weekly_alignment_ok = alignment_ok
                if expected_weeks:
                    all_match = True
                    for wkey, exp in expected_weeks.items():
                        if wkey not in file_weeks:
                            all_match = False
                            break
                        got = file_weeks[wkey]
                        if got["week_end"] != exp["week_end"]:
                            all_match = False
                            break
                        if not _float_equal(got["total_standard_drinks"], exp["total_standard_drinks"], eps=1e-4):
                            all_match = False
                            break
                        if got["days_exceeded_daily_limit"] != exp["days_exceeded_daily_limit"]:
                            all_match = False
                            break
                        if weekly_limit is not None:
                            exp_ewl = "true" if exp.get("exceeded_weekly_limit", False) else "false"
                            if got["exceeded_weekly_limit"] != exp_ewl:
                                all_match = False
                                break
                    if all_match:
                        weekly_values_ok = True
                else:
                    weekly_values_ok = False
    scores["weekly_summary_structure"] = 1.0 if weekly_structure_ok else 0.0
    scores["weekly_summary_values_match"] = 1.0 if weekly_values_ok else 0.0
    scores["weekly_start_day_alignment"] = 1.0 if weekly_alignment_ok else 0.0

    report_text = _safe_read_text(report_path) or ""
    if report_text:
        local_ok = all(p in report_text for p in [
            "config/standard_drinks.yaml",
            "config/baseline_limits.yaml",
            "config/profile.yaml",
            "input/drink_log.csv",
        ])
        web_ok = ("web/niaaa_low_risk.html" in report_text) or ("niaaa.nih.gov" in report_text) or ("web/niaaa_low_risk.txt" in report_text)
        if local_ok and web_ok:
            scores["report_includes_data_sources"] = 1.0

        factors_to_find = []
        try:
            if "drink_types" in sd_cfg:
                dt = sd_cfg["drink_types"]
                if isinstance(dt, dict):
                    for _, meta in dt.items():
                        try:
                            factors_to_find.append(str(meta.get("standard_drink_per_oz")))
                        except Exception:
                            pass
            if "default" in sd_cfg:
                try:
                    factors_to_find.append(str(sd_cfg["default"].get("standard_drink_per_oz")))
                except Exception:
                    pass
        except Exception:
            pass
        found_count = 0
        for f in factors_to_find:
            if f and f in report_text:
                found_count += 1
        if found_count >= 3:
            scores["report_includes_conversion_assumptions"] = 1.0

        extracted_ok = False
        if limits_ok:
            nums = [
                str(men_daily), str(men_weekly),
                str(women_daily), str(women_weekly),
            ]
            path_present = "web/niaaa_low_risk_limits.json" in report_text
            nums_present = all(n in report_text for n in nums)
            if path_present and nums_present:
                extracted_ok = True
        if extracted_ok:
            scores["report_includes_extracted_limits"] = 1.0

        baseline_vs_ok = False
        base_men_daily = None
        base_men_weekly = None
        base_women_daily = None
        base_women_weekly = None
        try:
            b = baseline_cfg.get("baseline") or {}
            base_men_daily = (b.get("men") or {}).get("daily")
            base_men_weekly = (b.get("men") or {}).get("weekly")
            base_women_daily = (b.get("women") or {}).get("daily")
            base_women_weekly = (b.get("women") or {}).get("weekly")
        except Exception:
            pass
        diff_exists = None
        if limits_ok and all(x is not None for x in [base_men_daily, base_men_weekly, base_women_daily, base_women_weekly]):
