import json
import csv
import sys
import re
from pathlib import Path
from typing import List, Tuple, Dict, Optional


def _read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _read_json(path: Path) -> Optional[dict]:
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _read_csv(path: Path) -> Optional[List[Dict[str, str]]]:
    try:
        with path.open("r", encoding="utf-8") as f:
            return list(csv.DictReader(f))
    except Exception:
        return None


def _time_to_minutes(t: str) -> int:
    hh, mm = t.strip().split(":")
    return int(hh) * 60 + int(mm)


def _minutes_to_time(m: int) -> str:
    hh = m // 60
    mm = m % 60
    return f"{hh:02d}:{mm:02d}"


def _merge_intervals(intervals: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda x: (x[0], x[1]))
    merged = [intervals[0]]
    for s, e in intervals[1:]:
        ls, le = merged[-1]
        if s <= le:
            merged[-1] = (ls, max(le, e))
        else:
            merged.append((s, e))
    return merged


def _intersect_intervals(a: List[Tuple[int, int]], b: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    i, j = 0, 0
    result: List[Tuple[int, int]] = []
    a_sorted = sorted(a)
    b_sorted = sorted(b)
    while i < len(a_sorted) and j < len(b_sorted):
        s1, e1 = a_sorted[i]
        s2, e2 = b_sorted[j]
        s = max(s1, s2)
        e = min(e1, e2)
        if s < e:
            result.append((s, e))
        if e1 < e2:
            i += 1
        else:
            j += 1
    return _merge_intervals(result)


def _parse_availability(rows: List[Dict[str, str]], date_key: str, start_key: str, end_key: str) -> Dict[str, List[Tuple[int, int]]]:
    per_date: Dict[str, List[Tuple[int, int]]] = {}
    for r in rows:
        date = r[date_key].strip()
        s = _time_to_minutes(r[start_key].strip())
        e = _time_to_minutes(r[end_key].strip())
        per_date.setdefault(date, []).append((s, e))
    # merge intervals per date
    for d in list(per_date.keys()):
        per_date[d] = _merge_intervals(per_date[d])
    return per_date


def _parse_attendees_availability(rows: List[Dict[str, str]], attendees: List[str]) -> Dict[str, Dict[str, List[Tuple[int, int]]]]:
    # returns mapping person -> date -> intervals
    data: Dict[str, Dict[str, List[Tuple[int, int]]]] = {}
    norm_attendees = set(attendees)
    for r in rows:
        person = r.get("person", "").strip()
        if person not in norm_attendees:
            continue
        date = r["date"].strip()
        s = _time_to_minutes(r["start"].strip())
        e = _time_to_minutes(r["end"].strip())
        data.setdefault(person, {}).setdefault(date, []).append((s, e))
    # merge intervals per date for each person
    for person in list(data.keys()):
        for d in list(data[person].keys()):
            data[person][d] = _merge_intervals(data[person][d])
    return data


def _compute_candidates(workspace: Path) -> Optional[List[Dict[str, str]]]:
    # Returns list of candidates dicts: date, start, end, window_label, score(str or int)
    pref_path = workspace / "input" / "preferences.json"
    owner_path = workspace / "input" / "owner_availability.csv"
    attendees_path = workspace / "input" / "attendees_availability.csv"

    prefs = _read_json(pref_path)
    owner_rows = _read_csv(owner_path)
    att_rows = _read_csv(attendees_path)

    if prefs is None or owner_rows is None or att_rows is None:
        return None

    duration = int(prefs.get("duration_minutes", 0))
    preferred_window = prefs.get("preferred_window", {})
    pw_start = _time_to_minutes(preferred_window.get("start", "00:00"))
    pw_end = _time_to_minutes(preferred_window.get("end", "00:00"))
    morning_weight = prefs.get("morning_weight", 0)
    attendees = prefs.get("attendees", [])

    # Remove "Zen Master" from attendee list for attendees_availability; owner is separate
    non_owner_attendees = [a for a in attendees if a != "Zen Master"]

    owner = _parse_availability(owner_rows, "date", "start", "end")
    att_map = _parse_attendees_availability(att_rows, non_owner_attendees)

    # For each date where there is owner availability and each attendee has at least one interval, compute intersection windows
    dates = sorted(set(owner.keys()) | set().union(*(set(att_map.get(a, {}).keys()) for a in non_owner_attendees)))
    candidates: List[Dict[str, str]] = []
    for d in dates:
        if d not in owner:
            continue
        # Start with owner's intervals on this date
        current = owner[d]
        # Intersect with each attendee's intervals for that date; if any attendee has no intervals on that date, result becomes empty
        feasible = current
        for a in non_owner_attendees:
            att_intervals = att_map.get(a, {}).get(d, [])
            feasible = _intersect_intervals(feasible, att_intervals)
            if not feasible:
                break
        if not feasible:
            continue
        # For each maximal overlap window, take earliest feasible start (window.start) if fits duration
        for (ws, we) in feasible:
            if we - ws >= duration:
                start_min = ws
                end_min = ws + duration
                # Label preferred window (inclusive start, exclusive end on preferred window)
                label = "preferred_window" if (pw_start <= start_min < pw_end) else "off_window"
                score = morning_weight if label == "preferred_window" else 0
                candidates.append({
                    "date": d,
                    "start": _minutes_to_time(start_min),
                    "end": _minutes_to_time(end_min),
                    "window_label": label,
                    "score": str(score),
                })
    # Rank by score desc, date asc, start asc
    candidates.sort(key=lambda x: (-float(x["score"]), x["date"], x["start"]))
    return candidates


def _expected_final_selection(workspace: Path) -> Optional[Dict[str, object]]:
    prefs = _read_json(workspace / "input" / "preferences.json")
    cars = _read_json(workspace / "input" / "cars.json")
    if prefs is None or cars is None:
        return None

    candidates = _compute_candidates(workspace)
    if not candidates:
        return None
    top = candidates[0]
    # choose car by highest priority_score, tie by earliest detailing_due_date then name
    def car_key(c):
        return (-int(c.get("priority_score", 0)),
                c.get("detailing_due_date", ""),
                c.get("name", ""))

    best_car = sorted(cars, key=car_key)[0]
    return {
        "title": prefs.get("meeting_title"),
        "date": top["date"],
        "start": top["start"],
        "end": top["end"],
        "timezone": prefs.get("timezone"),
        "location": prefs.get("location"),
        "attendees": prefs.get("attendees"),
        "car": best_car.get("name"),
        "score": float(top["score"]),
    }


def _expected_filled_file(template_text: str, selection: Dict[str, object], prefs: Dict[str, object], include_duration: bool) -> str:
    attendees_str = ", ".join(prefs.get("attendees", []))
    replacements = {
        "{{TITLE}}": str(selection["title"]),
        "{{DATE}}": str(selection["date"]),
        "{{START}}": str(selection["start"]),
        "{{END}}": str(selection["end"]),
        "{{TIMEZONE}}": str(selection["timezone"]),
        "{{LOCATION}}": str(selection["location"]),
        "{{ATTENDEES}}": attendees_str,
        "{{CAR}}": str(selection["car"]),
    }
    if include_duration:
        replacements["{{DURATION}}"] = str(prefs.get("duration_minutes"))

    filled = template_text
    for k, v in replacements.items():
        filled = filled.replace(k, v)
    return filled


def _parse_csv_exact(path: Path) -> Optional[Tuple[List[str], List[List[str]]]]:
    try:
        with path.open("r", encoding="utf-8") as f:
            reader = csv.reader(f)
            rows = list(reader)
        if not rows:
            return None
        header = rows[0]
        data = rows[1:]
        return header, data
    except Exception:
        return None


def _find_events_blocks(yaml_text: str) -> List[str]:
    # Return list of event item blocks under 'events:'
    lines = yaml_text.splitlines()
    blocks = []
    # find 'events:' line index
    events_idx = None
    for i, line in enumerate(lines):
        if re.match(r'^\s*events\s*:', line):
            events_idx = i
            break
    if events_idx is None:
        return []
    # Determine base indent for events children
    base_indent = len(re.match(r'^(\s*)', lines[events_idx]).group(1)) + 2
    i = events_idx + 1
    current_block = None
    current_block_indent = None
    while i < len(lines):
        line = lines[i]
        # Stop when dedent to less than events indent and a new top-level key starts
        if len(re.match(r'^(\s*)', line).group(1)) < (base_indent - 2) and re.search(r':', line):
            break
        # Identify new item
        m = re.match(r'^(\s*)-\s*(.*)$', line)
        if m and len(m.group(1)) == base_indent:
            # Start a new block
            if current_block is not None:
                blocks.append("\n".join(current_block))
            current_block = [line]
            current_block_indent = len(m.group(1))
        else:
            if current_block is not None:
                # part of current block (including nested lines)
                current_block.append(line)
        i += 1
    if current_block is not None:
        blocks.append("\n".join(current_block))
    return blocks


def _normalize_newlines(s: str) -> str:
    return s.replace("\r\n", "\n").replace("\r", "\n")


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "slots_ranked_csv_valid": 0.0,
        "final_selection_json_valid": 0.0,
        "agenda_filled_correctly": 0.0,
        "invite_filled_correctly": 0.0,
        "scheduler_config_updated": 0.0,
        "retreat_calendar_updated": 0.0,
    }

    # Compute expected candidates and selection
    prefs = _read_json(workspace / "input" / "preferences.json")
    expected_candidates = _compute_candidates(workspace)
    expected_selection = _expected_final_selection(workspace)

    # Check slots_ranked.csv
    slots_path = workspace / "out" / "slots_ranked.csv"
    csv_parsed = _parse_csv_exact(slots_path)
    if expected_candidates is not None and csv_parsed is not None:
        header, rows = csv_parsed
        expected_header = ["date", "start", "end", "window_label", "score"]
        if header == expected_header:
            # Compare rows count and content
            # Normalize provided rows into dicts to compare
            provided = []
            for r in rows:
                if len(r) != 5:
                    provided = None
                    break
                provided.append({
                    "date": r[0],
                    "start": r[1],
                    "end": r[2],
                    "window_label": r[3],
                    "score": r[4],
                })
            if provided is not None:
                # Compare length
                if len(provided) == len(expected_candidates):
                    # Compare each row in order; allow score numeric equivalence
                    all_match = True
                    for p, e in zip(provided, expected_candidates):
                        try:
                            pscore = float(p["score"])
                        except Exception:
                            all_match = False
                            break
                        escore = float(e["score"])
                        if not (
                            p["date"] == e["date"] and
                            p["start"] == e["start"] and
                            p["end"] == e["end"] and
                            p["window_label"] == e["window_label"] and
                            abs(pscore - escore) < 1e-9
                        ):
                            all_match = False
                            break
                    if all_match:
                        scores["slots_ranked_csv_valid"] = 1.0

    # Check final_selection.json
    final_sel_path = workspace / "out" / "final_selection.json"
    student_final = _read_json(final_sel_path)
    if expected_selection is not None and student_final is not None:
        # Must have exactly the required keys
        required_keys = ["title", "date", "start", "end", "timezone", "location", "attendees", "car", "score"]
        if set(student_final.keys()) == set(required_keys):
            try:
                # Compare values strictly
                values_match = True
                for k in ["title", "date", "start", "end", "timezone", "location", "car"]:
                    if str(student_final.get(k)) != str(expected_selection.get(k)):
                        values_match = False
                        break
                if values_match:
                    # attendees exact order and content
                    if student_final.get("attendees") == expected_selection.get("attendees"):
                        # score numeric
                        if abs(float(student_final.get("score")) - float(expected_selection.get("score"))) < 1e-9:
                            scores["final_selection_json_valid"] = 1.0
            except Exception:
                pass

    # Check agenda.md and invite.md
    agenda_template_path = workspace / "docs" / "agenda_template.md"
    invite_template_path = workspace / "notes" / "invite_template.md"
    agenda_out_path = workspace / "out" / "agenda.md"
    invite_out_path = workspace / "out" / "invite.md"

    agenda_template = _read_text(agenda_template_path)
    invite_template = _read_text(invite_template_path)
    agenda_out = _read_text(agenda_out_path)
    invite_out = _read_text(invite_out_path)

    if expected_selection is not None and prefs is not None and agenda_template is not None and agenda_out is not None:
        expected_agenda = _expected_filled_file(agenda_template, expected_selection, prefs, include_duration=False)
        if _normalize_newlines(expected_agenda) == _normalize_newlines(agenda_out):
            scores["agenda_filled_correctly"] = 1.0

    if expected_selection is not None and prefs is not None and invite_template is not None and invite_out is not None:
        expected_invite = _expected_filled_file(invite_template, expected_selection, prefs, include_duration=True)
        if _normalize_newlines(expected_invite) == _normalize_newlines(invite_out):
            scores["invite_filled_correctly"] = 1.0

    # Check scheduler/config.yaml modifications
    config_path = workspace / "scheduler" / "config.yaml"
    config_text = _read_text(config_path)
    if expected_selection is not None and prefs is not None and config_text is not None:
        # Check default_duration_minutes updated
        duration = int(prefs.get("duration_minutes", 0))
        duration_ok = bool(re.search(r'^\s*default_duration_minutes\s*:\s*{}\s*$'.format(re.escape(str(duration))), config_text, flags=re.M))
        # Check event appended under events
        blocks = _find_events_blocks(config_text)
        event_ok = False
        if blocks:
            for b in blocks:
                # Check all required key-value pairs are present in this block
                required_pairs = [
                    ("title", str(expected_selection["title"])),
                    ("date", str(expected_selection["date"])),
                    ("start", str(expected_selection["start"])),
                    ("end", str(expected_selection["end"])),
                    ("timezone", str(expected_selection["timezone"])),
                    ("location", str(expected_selection["location"])),
                    ("car", str(expected_selection["car"])),
                ]
                pairs_ok = True
                for k, v in required_pairs:
                    # Allow key: value with optional quotes and spaces
                    pattern = r'^\s*{}\s*:\s*("?{}"?|\[.*{}\s*,?.*\]|.*)$'.format(re.escape(k), re.escape(v), re.escape(v))
                    if not re.search(pattern, b, flags=re.M):
                        pairs_ok = False
                        break
                # attendees: ensure all names present in block
                attendees_ok = True
                for name in prefs.get("attendees", []):
                    if name not in b:
                        attendees_ok = False
                        break
                if pairs_ok and attendees_ok:
                    event_ok = True
                    break
        if duration_ok and event_ok:
            scores["scheduler_config_updated"] = 1.0

    # Check notes/retreat_calendar.md updated
    calendar_path = workspace / "notes" / "retreat_calendar.md"
    cal_text = _read_text(calendar_path)
    if expected_selection is not None and cal_text is not None and prefs is not None:
        # Find '## Scheduled' section boundaries
        lines = cal_text.splitlines()
        sched_start = None
        sched_end = len(lines)
        for i, line in enumerate(lines):
            if line.strip() == "## Scheduled":
                sched_start = i
                break
        if sched_start is not None:
            for j in range(sched_start + 1, len(lines)):
                if re.match(r'^\s*##\s+', lines[j]) and j > sched_start:
                    sched_end = j
                    break
            scheduled_section = "\n".join(lines[sched_start:sched_end])
            # Build expected line
            # Use en dash U+2013 between times and also before 'Attendees' is em dash U+2014? The example uses "—" (em dash U+2014)
            en_dash = "–"
            em_dash = "—"
            expected_line = f"- {expected_selection['date']} {expected_selection['start']}{en_dash}{expected_selection['end']} (Europe/Rome) - Mindful Detailing Session @ Dojo Garage [Car: {expected_selection['car']}] {em_dash} Attendees: " + ", ".join(prefs.get("attendees", []))
            # Check presence exactly
            if expected_line in scheduled_section:
                scores["retreat_calendar_updated"] = 1.0

    return scores


def main() -> None:
    workspace_path = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace_path)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

import json
import re
import sys
from pathlib import Path
from typing import Dict, List, Tuple, Optional


TRACKED_KEYWORDS = [
    "tariff",
    "subsidy",
    "free trade",
    "sanction",
    "carbon tax",
    "cap-and-trade",
    "capital controls",
    "privatization",
    "state-owned",
    "austerity",
]


def _read_text_safe(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        try:
            return path.read_text(encoding="latin-1")
        except Exception:
            return None


def _load_json_safe(path: Path):
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _normalize_newlines(s: str) -> str:
    return s.replace("\r\n", "\n").replace("\r", "\n")


def _list_input_docs(workspace: Path) -> List[Path]:
    input_dir = workspace / "input" / "drafts"
    if not input_dir.exists() or not input_dir.is_dir():
        return []
    return sorted([p for p in input_dir.glob("*.txt") if p.is_file()])


def _compile_keyword_patterns() -> Dict[str, List[re.Pattern]]:
    patterns: Dict[str, List[re.Pattern]] = {}
    plural_variants = {
        "tariff": ["tariff", "tariffs"],
        "subsidy": ["subsidy", "subsidies"],
        "sanction": ["sanction", "sanctions"],
    }
    for kw in TRACKED_KEYWORDS:
        variants = plural_variants.get(kw, [kw])
        compiled = []
        for v in variants:
            # whole word/phrase: ensure not preceded/followed by word char
            pat = re.compile(rf"(?i)(?<!\w){re.escape(v)}(?!\w)")
            compiled.append(pat)
        patterns[kw] = compiled
    return patterns


def _count_occurrences(text: str, patterns: List[re.Pattern]) -> int:
    count = 0
    for pat in patterns:
        count += len(list(pat.finditer(text)))
    return count


def _compute_doc_metrics(text: str, keyword_patterns: Dict[str, List[re.Pattern]]) -> Tuple[int, Dict[str, int], int, int, bool]:
    norm_text = _normalize_newlines(text)
    total_words = len(norm_text.split())
    keyword_counts: Dict[str, int] = {}
    for kw in TRACKED_KEYWORDS:
        keyword_counts[kw] = _count_occurrences(norm_text, keyword_patterns[kw])
    support_count = len(re.findall(r"(?i)(?<!\w)support(?!\w)", norm_text))
    oppose_count = len(re.findall(r"(?i)(?<!\w)oppose(?!\w)", norm_text))
    has_contradiction = support_count > 0 and oppose_count > 0
    return total_words, keyword_counts, support_count, oppose_count, has_contradiction


def _expected_analysis_for_docs(docs: List[Path], workspace: Path) -> List[Dict]:
    patterns = _compile_keyword_patterns()
    expected = []
    for p in docs:
        text = _read_text_safe(p)
        if text is None:
            # malformed; treat as empty metrics
            total_words = 0
            keyword_counts = {kw: 0 for kw in TRACKED_KEYWORDS}
            support_count = 0
            oppose_count = 0
            has_contradiction = False
        else:
            total_words, keyword_counts, support_count, oppose_count, has_contradiction = _compute_doc_metrics(text, patterns)
        doc_id = p.stem
        rel_path = (Path("input") / "drafts" / p.name).as_posix()
        expected.append({
            "doc_id": doc_id,
            "source_path": rel_path,
            "total_words": total_words,
            "keyword_counts": keyword_counts,
            "support_count": support_count,
            "oppose_count": oppose_count,
            "has_contradiction": has_contradiction,
        })
    # sort expected by doc_id for stable comparisons
    expected.sort(key=lambda d: d["doc_id"])
    return expected


def _safe_get(obj: dict, key: str, default=None):
    try:
        return obj.get(key, default)
    except Exception:
        return default


def _validate_analysis_schema_and_length(actual: List[Dict], expected: List[Dict]) -> bool:
    if not isinstance(actual, list):
        return False
    if len(actual) != len(expected):
        return False
    # schema: exactly specified fields
    required_fields = {"doc_id", "source_path", "total_words", "keyword_counts", "support_count", "oppose_count", "has_contradiction"}
    for item in actual:
        if not isinstance(item, dict):
            return False
        keys = set(item.keys())
        if keys != required_fields:
            return False
        if not isinstance(item["doc_id"], str):
            return False
        if not isinstance(item["source_path"], str):
            return False
        if not isinstance(item["total_words"], int):
            return False
        if not isinstance(item["support_count"], int):
            return False
        if not isinstance(item["oppose_count"], int):
            return False
        if not isinstance(item["has_contradiction"], bool):
            return False
        kc = item["keyword_counts"]
        if not isinstance(kc, dict):
            return False
        if set(kc.keys()) != set(TRACKED_KEYWORDS):
            return False
        for v in kc.values():
            if not isinstance(v, int):
                return False
    return True


def _compare_analysis_content(actual: List[Dict], expected: List[Dict]) -> float:
    # normalize ordering by doc_id
    def sort_key(d): return d["doc_id"]
    try:
        actual_sorted = sorted(actual, key=sort_key)
    except Exception:
        return 0.0
    expected_sorted = expected
    if len(actual_sorted) != len(expected_sorted) or len(expected_sorted) == 0:
        return 0.0 if len(expected_sorted) > 0 else 0.0
    total = len(expected_sorted)
    correct = 0
    for act, exp in zip(actual_sorted, expected_sorted):
        ok = True
        if act["doc_id"] != exp["doc_id"]:
            ok = False
        if act["source_path"] != exp["source_path"]:
            ok = False
        if act["total_words"] != exp["total_words"]:
            ok = False
        if act["support_count"] != exp["support_count"]:
            ok = False
        if act["oppose_count"] != exp["oppose_count"]:
            ok = False
        if act["has_contradiction"] != exp["has_contradiction"]:
            ok = False
        kc_ok = True
        for kw in TRACKED_KEYWORDS:
            if act["keyword_counts"].get(kw) != exp["keyword_counts"].get(kw):
                kc_ok = False
                break
        if not kc_ok:
            ok = False
        if ok:
            correct += 1
    return correct / total if total > 0 else 0.0


def _split_paragraphs(text: str) -> List[str]:
    norm = _normalize_newlines(text).strip()
    if not norm:
        return []
    parts = re.split(r"\n\s*\n", norm)
    # keep non-empty
    return [p.strip() for p in parts if p.strip()]


def _find_paragraph_for_doc(paragraphs: List[str], doc_id: str) -> Optional[str]:
    for p in paragraphs:
        # whole-word match for doc_id in paragraph
        if re.search(rf"(?i)(?<!\w){re.escape(doc_id)}(?!\w)", p):
            return p
    return None


def _top_keywords_for_doc(keyword_counts: Dict[str, int], topn: int = 2) -> List[str]:
    items = list(keyword_counts.items())
    items.sort(key=lambda kv: (-kv[1], kv[0]))
    return [k for k, v in items[:topn]]


def _docfreq_for_keywords(analyses: List[Dict]) -> Dict[str, int]:
    df = {kw: 0 for kw in TRACKED_KEYWORDS}
    for a in analyses:
        for kw in TRACKED_KEYWORDS:
            if a["keyword_counts"].get(kw, 0) > 0:
                df[kw] += 1
    return df


def _startswith_loosely(content: str, prefix: str) -> bool:
    # Normalize newlines; allow optional single trailing newline difference
    c = _normalize_newlines(content)
    p = _normalize_newlines(prefix)
    if c.startswith(p):
        return True
    # Allow exactly one extra newline after original
    if c.startswith(p + "\n"):
        return True
    return False


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "analysis_file_exists_and_schema": 0.0,
        "analysis_counts_correct": 0.0,
        "report_exists_and_doc_sections": 0.0,
        "report_top2_and_overall_metrics_correct": 0.0,
        "revisions_exist_prefix_and_header": 0.0,
        "revisions_bullets_correct": 0.0,
        "action_items_exists_and_sections": 0.0,
        "action_items_bullets_correct_content": 0.0,
    }

    input_docs = _list_input_docs(workspace)
    expected_analysis = _expected_analysis_for_docs(input_docs, workspace)

    # 1) Structured analysis output
    analysis_path = workspace / "output" / "analysis" / "keywords.json"
    actual_analysis = _load_json_safe(analysis_path)
    schema_ok = False
    if actual_analysis is not None and isinstance(actual_analysis, list):
        schema_ok = _validate_analysis_schema_and_length(actual_analysis, expected_analysis)
    if analysis_path.exists() and actual_analysis is not None and schema_ok:
        scores["analysis_file_exists_and_schema"] = 1.0
    else:
        scores["analysis_file_exists_and_schema"] = 0.0

    # Counts/content correctness across docs
    if schema_ok and len(expected_analysis) > 0:
        scores["analysis_counts_correct"] = _compare_analysis_content(actual_analysis, expected_analysis)
    else:
        # If there are expected docs but schema invalid, score 0
        scores["analysis_counts_correct"] = 0.0

    # 2) Status summary report
    report_path = workspace / "output" / "reports" / "status_summary.md"
    report_text = _read_text_safe(report_path)
    if report_text is None:
        scores["report_exists_and_doc_sections"] = 0.0
        scores["report_top2_and_overall_metrics_correct"] = 0.0
    else:
        paras = _split_paragraphs(report_text)
        # Check for each document: a section/paragraph stating doc_id and contradiction and top2 keywords
        if len(expected_analysis) == 0:
            scores["report_exists_and_doc_sections"] = 0.0
            scores["report_top2_and_overall_metrics_correct"] = 0.0
        else:
            found_sections = 0
            doc_checks = 0
            correct_doc_checks = 0
            for exp in expected_analysis:
                doc_id = exp["doc_id"]
                p = _find_paragraph_for_doc(paras, doc_id)
                if p is not None:
                    found_sections += 1
                # For top2 and contradiction correctness
                doc_checks += 1  # one combined check per doc for presence of correct 'true/false' and top two keyword mentions
                exp_bool = "true" if exp["has_contradiction"] else "false"
                # expect 'true'/'false' word present
                bool_present = re.search(rf"(?i)(?<!\w){exp_bool}(?!\w)", p or "") is not None
                top2 = _top_keywords_for_doc(exp["keyword_counts"], topn=2)
                # ensure both keywords are mentioned in paragraph
                top2_present = all(re.search(rf"(?i)(?<!\w){re.escape(kw)}(?!\w)", p or "") is not None for kw in top2)
                if bool_present and top2_present and p is not None:
                    correct_doc_checks += 1
            scores["report_exists_and_doc_sections"] = found_sections / len(expected_analysis)

            # Overall metrics in the final section
            overall_ok = False
            if paras:
                last_para = paras[-1]
                # total documents processed
                total_docs = len(expected_analysis)
                total_line_ok = re.search(rf"(?is)\btotal\b.*\b{total_docs}\b", last_para) is not None
                # per-keyword doc frequency
                exp_df = _docfreq_for_keywords(expected_analysis)
                per_kw_ok = True
                lines = _normalize_newlines(last_para).split("\n")
                for kw, freq in exp_df.items():
                    # look for a line containing keyword and the exact freq number
                    line_has = any((re.search(rf"(?i)(?<!\w){re.escape(kw)}(?!\w)", ln) and re.search(rf"(?<!\d){freq}(?!\d)", ln)) for ln in lines)
                    if not line_has:
                        per_kw_ok = False
                        break
                overall_ok = bool(total_line_ok and per_kw_ok)
            # Combine doc checks and overall metrics: average of (doc correctness across docs) and (overall metrics correctness as 0/1)
            doc_part = (correct_doc_checks / doc_checks) if doc_checks > 0 else 0.0
            overall_part = 1.0 if overall_ok else 0.0
            scores["report_top2_and_overall_metrics_correct"] = (doc_part + overall_part) / 2.0

    # 3) Counterpoint revisions
    # For each input doc, there should be a revision at output/revisions/{doc_id}_counterpoint.md
    if len(expected_analysis) == 0:
        scores["revisions_exist_prefix_and_header"] = 0.0
        scores["revisions_bullets_correct"] = 0.0
    else:
        exist_prefix_header_hits = 0
        bullets_hits = 0
        for exp in expected_analysis:
            doc_id = exp["doc_id"]
            src_path = workspace / "input" / "drafts" / f"{doc_id}.txt"
            rev_path = workspace / "output" / "revisions" / f"{doc_id}_counterpoint.md"
            src_text = _read_text_safe(src_path) or ""
            rev_text = _read_text_safe(rev_path)
            # Check existence, prefix (original text), and header presence
            header_ok = False
            prefix_ok = False
            if rev_text is not None:
                prefix_ok = _startswith_loosely(rev_text, src_text)
                # header line "Counterpoint" exact or "# Counterpoint"
                lines = _normalize_newlines(rev_text).split("\n")
                header_ok = any(ln.strip() == "Counterpoint" or ln.strip() == "# Counterpoint" for ln in lines)
            if rev_text is not None and prefix_ok and header_ok:
                exist_prefix_header_hits += 1

            # Bullets correctness
            bullets_ok = False
            if rev_text is not None:
                lines = _normalize_newlines(rev_text).split("\n")
                # find start of counterpoint section
                start_idx = None
                for i, ln in enumerate(lines):
                    if ln.strip() == "Counterpoint" or ln.strip() == "# Counterpoint":
                        start_idx = i
                        break
                if start_idx is not None:
                    section_lines = lines[start_idx + 1 :]
                    bullets = [ln.strip() for ln in section_lines if ln.strip().startswith("- ")]
                    # Expected bullets: exactly one per keyword with count > 0
                    expected_positive = [kw for kw, cnt in exp["keyword_counts"].items() if cnt > 0]
                    expected_set = set(
                        [f"- Counterpoint on {kw} in {doc_id}: prepare arguments challenging reliance on {kw}." for kw in expected_positive]
                    )
                    bullets_set = set(bullets)
                    # ensure no extra bullets and all expected present exactly once
                    if bullets_set == expected_set and len(bullets) == len(expected_positive):
                        bullets_ok = True
            if bullets_ok:
                bullets_hits += 1

        total_docs = len(expected_analysis)
        scores["revisions_exist_prefix_and_header"] = exist_prefix_header_hits / total_docs
        scores["revisions_bullets_correct"] = bullets_hits / total_docs

    # 4) Action items notes
    notes_path = workspace / "output" / "notes" / "action_items.md"
    notes_text = _read_text_safe(notes_path)
    if len(expected_analysis) == 0 or notes_text is None:
        scores["action_items_exists_and_sections"] = 0.0
        scores["action_items_bullets_correct_content"] = 0.0
    else:
        lines = _normalize_newlines(notes_text).split("\n")
        # Build sections by locating headers
        # Accept either exact "Action Items — {doc_id}" or "# Action Items — {doc_id}"
        def find_section(doc_id: str) -> Tuple[Optional[int], Optional[int]]:
            header_patterns = [
                rf"^\s*Action Items — {re.escape(doc_id)}\s*$",
                rf"^\s*#\s*Action Items — {re.escape(doc_id)}\s*$",
            ]
            header_idx = None
            for i, ln in enumerate(lines):
                if any(re.match(pat, ln) for pat in header_patterns):
                    header_idx = i
                    break
            if header_idx is None:
                return None, None
            # section ends at next header line or EOF
            end_idx = len(lines)
            for j in range(header_idx + 1, len(lines)):
                if lines[j].strip().startswith("# ") or re.match(r"^\s*Action Items — ", lines[j]):
                    end_idx = j
                    break
            return header_idx, end_idx

        sections_found = 0
        bullets_content_correct = 0
        for exp in expected_analysis:
            doc_id = exp["doc_id"]
            start, end = find_section(doc_id)
            if start is not None:
                sections_found += 1
                section_lines = [ln.strip() for ln in lines[start + 1 : end]]
                bullets = [ln for ln in section_lines if ln.startswith("- ")]
                # exactly three bullets
                if len(bullets) == 3:
                    # compute expected bullets
                    # 1) top keyword or none
                    top_items = sorted(exp["keyword_counts"].items(), key=lambda kv: (-kv[1], kv[0]))
                    top_count = top_items[0][1]
                    if top_count == 0:
                        top_kw = "none"
                    else:
                        top_kw = top_items[0][0]
                    b1 = f"- Prepare talking points for the top keyword: {top_kw}"
                    # 2) contradiction
                    if exp["has_contradiction"]:
                        b2 = f"- Clarify stance conflicts detected (support vs oppose) in {doc_id}"
                    else:
                        b2 = f"- Add anticipatory Q&A covering counter-arguments for {doc_id}"
                    # 3) missing keyword: alphabetically first with count 0 or none
                    missing = [kw for kw in TRACKED_KEYWORDS if exp["keyword_counts"].get(kw, 0) == 0]
                    if missing:
                        mk = sorted(missing)[0]
                    else:
                        mk = "none"
                    b3 = f"- Research and draft counterpoints for a missing keyword: {mk}"
                    if bullets[0] == b1 and bullets[1] == b2 and bullets[2] == b3:
                        bullets_content_correct += 1

        total_docs = len(expected_analysis)
        scores["action_items_exists_and_sections"] = sections_found / total_docs
        scores["action_items_bullets_correct_content"] = bullets_content_correct / total_docs

    # Ensure floats are within [0,1]
    for k, v in list(scores.items()):
        try:
            fv = float(v)
        except Exception:
            fv = 0.0
        if fv < 0.0:
            fv = 0.0
        if fv > 1.0:
            fv = 1.0
        scores[k] = fv

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

import sys
import json
import csv
from pathlib import Path
from datetime import datetime, timedelta
from typing import List, Dict, Tuple, Optional


def _read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _parse_simple_yaml(text: str) -> Optional[dict]:
    """
    Minimal YAML parser sufficient for the given task inputs:
    - Top-level key: value pairs
    - Quoted or unquoted scalar values
    - Top-level lists indicated by:
        key:
          - item1
          - item2
    Returns dict or None on error.
    """
    data = {}
    try:
        lines = text.splitlines()
        i = 0
        current_list_key = None
        while i < len(lines):
            raw = lines[i]
            line = raw.rstrip()
            i += 1
            if not line.strip():
                continue
            if line.strip().startswith("#"):
                continue

            # List item
            if current_list_key is not None and line.lstrip().startswith("- "):
                item = line.strip()[2:].strip()
                item = _strip_quotes(item)
                data[current_list_key].append(item)
                continue

            # If we are in a list and encounter a non-list line, close list context
            if current_list_key is not None and not line.lstrip().startswith("- "):
                current_list_key = None  # end list

            # Key: value or Key:
            if ":" in line:
                parts = line.split(":", 1)
                key = parts[0].strip()
                value = parts[1].strip()
                if value == "":
                    # start of list or empty scalar
                    if i < len(lines) and lines[i].lstrip().startswith("- "):
                        data[key] = []
                        current_list_key = key
                    else:
                        data[key] = ""
                        current_list_key = None
                else:
                    value = _strip_quotes(value)
                    parsed = _parse_number(value)
                    data[key] = parsed
                    current_list_key = None
            else:
                # Unsupported line format; ignore gracefully
                continue
        return data
    except Exception:
        return None


def _strip_quotes(s: str) -> str:
    s = s.strip()
    if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
        return s[1:-1]
    return s


def _parse_number(s: str):
    # Try int, then float, else string
    try:
        if s.lower().startswith("0x"):
            return s
        if s.isdigit() or (s.startswith("-") and s[1:].isdigit()):
            return int(s)
        return float(s)
    except Exception:
        return s


def _load_yaml_file(path: Path) -> Optional[dict]:
    text = _read_text(path)
    if text is None:
        return None
    return _parse_simple_yaml(text)


def _read_csv_dicts(path: Path) -> Optional[List[Dict[str, str]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            rows = [dict(row) for row in reader]
            return rows
    except Exception:
        return None


def _read_csv_header_and_rows(path: Path) -> Tuple[Optional[List[str]], Optional[List[Dict[str, str]]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            header = reader.fieldnames[:] if reader.fieldnames else []
            rows = [dict(row) for row in reader]
            return header, rows
    except Exception:
        return None, None


def _compute_payback_months(capex_usd: float, estimated_annual_benefit_usd: float) -> Optional[float]:
    try:
        monthly_benefit = estimated_annual_benefit_usd / 12.0
        if monthly_benefit == 0:
            return None
        return capex_usd / monthly_benefit
    except Exception:
        return None


def _safe_float(x) -> Optional[float]:
    try:
        if isinstance(x, (int, float)):
            return float(x)
        return float(str(x).strip())
    except Exception:
        return None


def _format_one_decimal(x: float) -> float:
    return round(x + 1e-12, 1)


def _discover_proposals(workspace: Path) -> List[Path]:
    proposals_dir = workspace / "input" / "proposals"
    if not proposals_dir.exists():
        return []
    return sorted([p for p in proposals_dir.iterdir() if p.is_file() and p.suffix.lower() == ".yaml"])


def _parse_proposal(path: Path) -> Optional[dict]:
    data = _load_yaml_file(path)
    if data is None:
        return None
    # Extract required fields
    required = [
        "id",
        "title",
        "department",
        "capex_usd",
        "estimated_annual_benefit_usd",
        "readiness_score",
        "risk_score",
        "owner",
        "pilot_site",
    ]
    for k in required:
        if k not in data:
            return None
    # Coerce types
    try:
        capex = _safe_float(data["capex_usd"])
        benefit = _safe_float(data["estimated_annual_benefit_usd"])
        readiness = int(float(data["readiness_score"]))
        risk = int(float(data["risk_score"]))
        if capex is None or benefit is None:
            return None
    except Exception:
        return None
    proposal = {
        "file_path": str(path.as_posix()),
        "id": str(data["id"]),
        "title": str(data["title"]),
        "department": str(data["department"]),
        "capex_usd": float(capex),
        "estimated_annual_benefit_usd": float(benefit),
        "readiness_score": readiness,
        "risk_score": risk,
        "owner": str(data["owner"]),
        "pilot_site": str(data["pilot_site"]),
    }
    pb = _compute_payback_months(proposal["capex_usd"], proposal["estimated_annual_benefit_usd"])
    if pb is None:
        return None
    proposal["payback_months"] = pb
    return proposal


def _load_policy(workspace: Path) -> Optional[dict]:
    policy_path = workspace / "input" / "policy.yaml"
    policy = _load_yaml_file(policy_path)
    if policy is None:
        return None
    # Validate needed keys
    needed = ["max_payback_months", "min_readiness_score", "budget_capex_usd", "top_n", "attendees", "meeting_duration_minutes"]
    for k in needed:
        if k not in policy:
            return None
    # Coerce types
    try:
        policy["max_payback_months"] = float(policy["max_payback_months"])
        policy["min_readiness_score"] = int(float(policy["min_readiness_score"]))
        policy["budget_capex_usd"] = float(policy["budget_capex_usd"])
        policy["top_n"] = int(float(policy["top_n"]))
        if not isinstance(policy.get("attendees"), list):
            return None
        policy["attendees"] = [str(a) for a in policy["attendees"]]
        policy["meeting_duration_minutes"] = int(float(policy["meeting_duration_minutes"]))
    except Exception:
        return None
    return policy


def _load_availability(workspace: Path) -> Optional[List[Dict[str, str]]]:
    path = workspace / "input" / "availability.csv"
    return _read_csv_dicts(path)


def _compute_prioritized(proposals: List[dict], policy: dict) -> Tuple[List[dict], List[dict]]:
    """
    Returns (eligible_sorted, selected_within_budget)
    """
    max_pb = policy["max_payback_months"]
    min_ready = policy["min_readiness_score"]
    eligible = []
    for p in proposals:
        if p is None:
            continue
        if p.get("payback_months") is None:
            continue
        if p["payback_months"] > max_pb:
            continue
        if p["readiness_score"] < min_ready:
            continue
        eligible.append(p)
    # Sort by (payback_months asc), (readiness desc), (risk asc)
    eligible_sorted = sorted(
        eligible,
        key=lambda x: (x["payback_months"], -x["readiness_score"], x["risk_score"])
    )
    # Greedy selection within budget and top_n
    budget = policy["budget_capex_usd"]
    top_n = policy["top_n"]
    selected = []
    total_capex = 0.0
    for p in eligible_sorted:
        if len(selected) >= top_n:
            break
        if total_capex + p["capex_usd"] <= budget + 1e-9:
            selected.append(p)
            total_capex += p["capex_usd"]
        else:
            continue
    return eligible_sorted, selected


def _expected_meeting_slot(availability: List[Dict[str, str]], attendees: List[str]) -> Tuple[Optional[str], int]:
    """
    Returns (slot_datetime_str, attendee_count)
    """
    if availability is None:
        return None, 0
    count_by_slot: Dict[str, int] = {}
    attendee_set = set(attendees)
    for row in availability:
        name = row.get("name", "").strip()
        slot = row.get("slot_datetime", "").strip()
        if name in attendee_set and slot:
            count_by_slot[slot] = count_by_slot.get(slot, 0) + 1
    if not count_by_slot:
        return None, 0
    # pick highest count; break ties by earliest slot (lexicographic works for YYYY-MM-DD HH:MM)
    max_count = max(count_by_slot.values())
    candidates = sorted([s for s, c in count_by_slot.items() if c == max_count])
    chosen = candidates[0] if candidates else None
    return chosen, max_count if chosen is not None else 0


def _parse_date_from_slot(slot: Optional[str]) -> Optional[datetime]:
    if not slot:
        return None
    try:
        return datetime.strptime(slot, "%Y-%m-%d %H:%M")
    except Exception:
        return None


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores: Dict[str, float] = {
        "prioritized_csv_exists_and_header": 0.0,
        "prioritized_csv_eligibility_and_order": 0.0,
        "prioritized_csv_payback_and_ranks": 0.0,
        "top_within_budget_header_and_selection": 0.0,
        "top_within_budget_totals_and_budget": 0.0,
        "inspected_files_list_correct": 0.0,
        "meeting_details_correct": 0.0,
        "meeting_agenda_summaries_complete": 0.0,
        "meeting_actions_and_due_dates": 0.0,
        "meeting_data_checks_section": 0.0,
    }

    # Load inputs
    proposal_paths = _discover_proposals(workspace)
    proposals_parsed = []
    for p in proposal_paths:
        proposals_parsed.append(_parse_proposal(p))
    policy = _load_policy(workspace)
    availability = _load_availability(workspace)

    # Compute expected values only if inputs are valid
    eligible_sorted: List[dict] = []
    selected: List[dict] = []
    if policy is not None and len(proposals_parsed) > 0:
        filtered_parsed = [pp for pp in proposals_parsed if pp is not None]
        if len(filtered_parsed) > 0:
            eligible_sorted, selected = _compute_prioritized(filtered_parsed, policy)
    expected_prioritized_ids = [p["id"] for p in eligible_sorted]
    expected_selected_ids = [p["id"] for p in selected]
    expected_selected_capex_total = sum(p["capex_usd"] for p in selected)
    expected_payback_by_id = {p["id"]: _format_one_decimal(p["payback_months"]) for p in eligible_sorted}

    expected_budget = policy["budget_capex_usd"] if policy is not None else None

    # Meeting expectations
    expected_slot, expected_attendee_count = (None, 0)
    meeting_due_date_str = None
    if policy is not None and availability is not None:
        expected_slot, expected_attendee_count = _expected_meeting_slot(availability, policy["attendees"])
        meeting_dt = _parse_date_from_slot(expected_slot)
        if meeting_dt is not None:
            due_date = meeting_dt.date() + timedelta(days=14)
            meeting_due_date_str = due_date.isoformat()

    # 1) prioritized_pilots.csv checks
    prioritized_path = workspace / "output" / "prioritized_pilots.csv"
    header, rows = _read_csv_header_and_rows(prioritized_path)

    expected_prioritized_header = [
        "proposal_id",
        "title",
        "department",
        "capex_usd",
        "estimated_annual_benefit_usd",
        "payback_months",
        "readiness_score",
        "risk_score",
        "owner",
        "pilot_site",
        "priority_rank",
    ]

    if header is not None and rows is not None:
        # header check
        if header == expected_prioritized_header:
            scores["prioritized_csv_exists_and_header"] = 1.0

        # eligibility and order check
        if len(expected_prioritized_ids) > 0 and len(rows) == len(expected_prioritized_ids):
            ids_in_rows = [r.get("proposal_id", "") for r in rows]
            ranks_ok = True
            for idx, r in enumerate(rows):
                if str(r.get("priority_rank", "")).strip() != str(idx + 1):
                    ranks_ok = False
                    break
            if ids_in_rows == expected_prioritized_ids and ranks_ok:
                scores["prioritized_csv_eligibility_and_order"] = 1.0

        # payback rounding and ranks numeric sanity
        payback_ok = True
        if len(rows) == len(expected_prioritized_ids) and len(expected_prioritized_ids) > 0:
            for r in rows:
                pid = r.get("proposal_id", "")
                if pid not in expected_payback_by_id:
                    payback_ok = False
                    break
                pb_out = _safe_float(r.get("payback_months", ""))
                if pb_out is None:
                    payback_ok = False
                    break
                if _format_one_decimal(pb_out) != expected_payback_by_id[pid]:
                    payback_ok = False
                    break
            for idx, r in enumerate(rows):
                try:
                    pr = int(float(r.get("priority_rank", "")))
                    if pr != idx + 1:
                        payback_ok = False
                        break
                except Exception:
                    payback_ok = False
                    break
        else:
            payback_ok = False
        if payback_ok:
            scores["prioritized_csv_payback_and_ranks"] = 1.0

    # 2) top_within_budget.csv checks
    top_path = workspace / "output" / "top_within_budget.csv"
    top_header, top_rows = _read_csv_header_and_rows(top_path)
    if top_header is not None and top_rows is not None and policy is not None:
        expected_top_header = expected_prioritized_header + ["total_capex_selected"]
        header_ok = (top_header == expected_top_header)
        if len(top_rows) >= 1:
            selected_rows = top_rows[:-1]
            totals_row = top_rows[-1]
        else:
            selected_rows = []
            totals_row = {}
        selection_ok = False
        if len(selected_rows) == len(expected_selected_ids) and len(expected_selected_ids) > 0:
            sel_ids = [r.get("proposal_id", "") for r in selected_rows]
            if sel_ids == expected_selected_ids:
                ranks_ok = True
                for idx, r in enumerate(selected_rows):
                    try:
                        pr = int(float(str(r.get("priority_rank", "")).strip()))
                        if pr != (expected_prioritized_ids.index(r.get("proposal_id", "")) + 1):
                            ranks_ok = False
                            break
                    except Exception:
                        ranks_ok = False
                        break
                if ranks_ok:
                    selection_ok = True

        if header_ok and selection_ok:
            scores["top_within_budget_header_and_selection"] = 1.0

        # totals and budget check
        totals_ok = False
        try:
            total_cap_field = totals_row.get("total_capex_selected", "")
            total_cap_val = _safe_float(total_cap_field)
            sum_capex = 0.0
            for r in selected_rows:
                cap_val = _safe_float(r.get("capex_usd", ""))
                if cap_val is None:
                    raise ValueError("capex parse error")
                sum_capex += cap_val
            within_budget = (sum_capex <= policy["budget_capex_usd"] + 1e-9)
            topn_ok = (len(selected_rows) <= policy["top_n"])
            totals_ok = (
                (expected_selected_capex_total == 0.0 or abs(sum_capex - expected_selected_capex_total) < 1e-6)
                and total_cap_val is not None
                and abs(total_cap_val - sum_capex) < 1e-6
                and within_budget
                and topn_ok
            )
        except Exception:
            totals_ok = False
        if totals_ok:
            scores["top_within_budget_totals_and_budget"] = 1.0

    # 3) inspected_files.txt checks
    inspected_path = workspace / "output" / "inspected_files.txt"
    inspected_text = _read_text(inspected_path)
    if inspected_text is not None:
        lines = [ln.strip() for ln in inspected_text.splitlines() if ln.strip()]
        discovered_count = len(proposal_paths)
        if len(lines) == discovered_count and discovered_count > 0:
            mapping_ok = True
            for p in proposal_paths:
                pdata = _parse_proposal(p)
                if pdata is None:
                    mapping_ok = False
                    break
                pid = pdata["id"]
                pstr = str(p.as_posix())
                if not any((pstr in ln and pid in ln) for ln in lines):
                    mapping_ok = False
                    break
            if mapping_ok:
                scores["inspected_files_list_correct"] = 1.0

    # 4) meeting_agenda_and_actions.md checks
    md_path = workspace / "output" / "meeting_agenda_and_actions.md"
    md_text = _read_text(md_path)

    if md_text is not None and policy is not None:
        # meeting details
        details_ok = False
        if expected_slot is not None and expected_attendee_count is not None:
            if (expected_slot in md_text) and (str(expected_attendee_count) in md_text):
                details_ok = True
        if details_ok:
            scores["meeting_details_correct"] = 1.0

        # agenda summaries
        summaries_ok = True
        if len(selected) > 0:
            for p in selected:
                pid = p["id"]
                title = p["title"]
                dept = p["department"]
                payback_val = _format_one_decimal(p["payback_months"])
                readiness_val = p["readiness_score"]
                risk_val = p["risk_score"]
                capex_val = int(p["capex_usd"]) if abs(p["capex_usd"] - int(p["capex_usd"])) < 1e-9 else p["capex_usd"]
                found_id_title = (pid in md_text) and (title in md_text)
                found_dept = (dept in md_text)
                found_payback = (str(payback_val) in md_text)
                found_ready = (str(readiness_val) in md_text)
                found_risk = (str(risk_val) in md_text)
                found_capex = (str(capex_val) in md_text)
                if not (found_id_title and found_dept and found_payback and found_ready and found_risk and found_capex):
                    summaries_ok = False
                    break
        else:
            summaries_ok = False
        if summaries_ok:
            scores["meeting_agenda_summaries_complete"] = 1.0

        # actions and due dates
        actions_ok = False
        required_actions = [
            "finalize pilot scope",
            "define pilot KPIs and data collection plan",
            "confirm dependencies",
        ]
        try:
            all_actions_present = all(act in md_text for act in required_actions)
            owners_ok = True
            for p in selected:
                owner = p["owner"]
                if owner not in md_text:
                    owners_ok = False
                    break
            due_dates_ok = False
            if meeting_due_date_str is not None:
                due_count = md_text.count(meeting_due_date_str)
                due_dates_ok = (due_count >= max(1, len(selected)))
            actions_ok = all_actions_present and owners_ok and due_dates_ok
        except Exception:
            actions_ok = False
        if actions_ok:
            scores["meeting_actions_and_due_dates"] = 1.0

        # data checks in md
        data_checks_ok = False
        try:
            discovered_n = len(proposal_paths)
            eligible_n = len(eligible_sorted)
            total_capex_sel = int(expected_selected_capex_total) if abs(expected_selected_capex_total - int(expected_selected_capex_total)) < 1e-9 else expected_selected_capex_total
            budget_val = int(expected_budget) if expected_budget is not None and abs(expected_budget - int(expected_budget)) < 1e-9 else expected_budget
            cond1 = (str(discovered_n) in md_text)
            cond2 = (str(eligible_n) in md_text)
            cond3 = (str(total_capex_sel) in md_text) and (str(budget_val) in md_text if budget_val is not None else False)
            cond_words = ("budget" in md_text.lower()) and ("capex" in md_text.lower())
            data_checks_ok = cond1 and cond2 and cond3 and cond_words
        except Exception:
            data_checks_ok = False
        if data_checks_ok:
            scores["meeting_data_checks_section"] = 1.0

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

