import json
import csv
import sys
import re
from pathlib import Path
from typing import Optional, Tuple, List, Dict, Any
from xml.etree import ElementTree as ET


def _read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _load_json(path: Path) -> Tuple[Optional[dict], Optional[str]]:
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f), None
    except Exception as e:
        return None, str(e)


def _load_csv_dict(path: Path) -> Tuple[Optional[List[Dict[str, str]]], Optional[str]]:
    try:
        with path.open("r", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            rows = [dict({k: (v if v is not None else "") for k, v in row.items()}) for row in reader]
        return rows, None
    except Exception as e:
        return None, str(e)


def _parse_gradle_dependencies(text: str) -> List[Tuple[str, str, str]]:
    results: List[Tuple[str, str, str]] = []
    pattern = re.compile(r"^\s*(?:api|implementation|compile|runtimeOnly|compileOnly|testImplementation|androidTestImplementation)\s+['\"]([^'\"\s]+)['\"]", re.MULTILINE)
    for m in pattern.finditer(text):
        coord = m.group(1).strip()
        parts = coord.split(":")
        if len(parts) >= 3:
            group_artifact = ":".join(parts[0:2])
            version = parts[2]
            full = f"{group_artifact}:{version}"
            results.append((group_artifact, version, full))
    return results


def _parse_pubspec_dependencies(text: str) -> List[Tuple[str, str]]:
    lines = text.splitlines()
    deps_started = False
    results: List[Tuple[str, str]] = []
    indent_level: Optional[int] = None
    for raw_line in lines:
        line = raw_line.rstrip("\n")
        if not deps_started:
            if re.match(r"^\s*dependencies\s*:\s*$", line):
                deps_started = True
                continue
        else:
            if re.match(r"^\S.*:\s*$", line) and not line.strip().startswith("-"):
                break
            if not line.strip() or line.strip().startswith("#"):
                continue
            if indent_level is None:
                m = re.match(r"^(\s+)", line)
                indent_level = len(m.group(1)) if m else 2
            if len(line) - len(line.lstrip(" ")) < (indent_level or 0):
                break
            stripped = line.strip()
            if re.match(r"^[\w\-\_]+:\s*$", stripped):
                continue
            kv = re.match(r"^([A-Za-z0-9_\-]+)\s*:\s*([^\s].*)$", stripped)
            if kv:
                name = kv.group(1).strip()
                value = kv.group(2).strip()
                if " #" in value:
                    value = value.split(" #", 1)[0].strip()
                if (value.startswith("'") and value.endswith("'")) or (value.startswith('"') and value.endswith('"')):
                    value = value[1:-1]
                if value and not value.endswith(":"):
                    results.append((name, value))
    return results


def _parse_manifest(xml_text: str) -> Tuple[Optional[bool], Optional[List[str]]]:
    try:
        root = ET.fromstring(xml_text)
        uses_cleartext = False
        app = root.find("application")
        if app is not None:
            v = app.get("{http://schemas.android.com/apk/res/android}usesCleartextTraffic")
            if v is not None:
                uses_cleartext = (v.lower() == "true")
        perms = []
        for perm in root.findall("uses-permission"):
            name = perm.get("{http://schemas.android.com/apk/res/android}name")
            if name:
                perms.append(name)
        return uses_cleartext, perms
    except Exception:
        return None, None


def _load_permission_risk_map(csv_rows: List[Dict[str, str]]) -> Dict[str, Dict[str, str]]:
    m: Dict[str, Dict[str, str]] = {}
    for row in csv_rows:
        perm = (row.get("permission") or "").strip()
        risk = (row.get("risk_level") or "").strip()
        desc = (row.get("description") or "").strip()
        if perm:
            m[perm] = {"risk_level": risk if risk else "unknown", "description": desc}
    return m


def _compute_expected(workspace: Path) -> Tuple[Optional[dict], Optional[str]]:
    gradle_path = workspace / "input" / "android" / "app" / "build.gradle"
    manifest_path = workspace / "input" / "android" / "app" / "src" / "main" / "AndroidManifest.xml"
    pubspec_path = workspace / "input" / "flutter" / "pubspec.yaml"
    advisories_path = workspace / "input" / "security" / "advisories.json"
    perm_csv_path = workspace / "input" / "security" / "permission_risk.csv"

    gradle_text = _read_text(gradle_path)
    manifest_text = _read_text(manifest_path)
    pubspec_text = _read_text(pubspec_path)
    advisories, _ = _load_json(advisories_path)
    perm_rows, _ = _load_csv_dict(perm_csv_path)

    if any(x is None for x in [gradle_text, manifest_text, pubspec_text]) or advisories is None or perm_rows is None:
        return None, "Missing or unreadable input files"

    gradle_deps = _parse_gradle_dependencies(gradle_text)
    pub_deps = _parse_pubspec_dependencies(pubspec_text)
    uses_cleartext, perm_list = _parse_manifest(manifest_text)

    if uses_cleartext is None or perm_list is None:
        return None, "Malformed AndroidManifest.xml"

    perm_map = _load_permission_risk_map(perm_rows)

    expected_dependencies: List[Dict[str, Any]] = []
    gradle_adv: Dict[str, Dict[str, Any]] = advisories.get("gradle", {})
    for group_artifact, version, full in gradle_deps:
        adv_entry = gradle_adv.get(group_artifact)
        vulnerable = False
        advisory_ids: List[str] = []
        min_safe_version = None
        if adv_entry:
            vuln_versions = adv_entry.get("vulnerable_versions") or []
            if version in vuln_versions:
                vulnerable = True
                advisory_ids = list(adv_entry.get("advisory_ids") or [])
                min_safe_version = adv_entry.get("min_safe_version")
        dep = {
            "ecosystem": "gradle",
            "name": full,
            "version": version,
            "vulnerable": vulnerable,
            "advisory_ids": advisory_ids,
            "min_safe_version": min_safe_version if vulnerable else None,
        }
        expected_dependencies.append(dep)

    pub_adv: Dict[str, Dict[str, Any]] = advisories.get("pub", {})
    for name, version in pub_deps:
        adv_entry = pub_adv.get(name)
        vulnerable = False
        advisory_ids: List[str] = []
        min_safe_version = None
        if adv_entry:
            vuln_versions = adv_entry.get("vulnerable_versions") or []
            if version in vuln_versions:
                vulnerable = True
                advisory_ids = list(adv_entry.get("advisory_ids") or [])
                min_safe_version = adv_entry.get("min_safe_version")
        dep = {
            "ecosystem": "pub",
            "name": name,
            "version": version,
            "vulnerable": vulnerable,
            "advisory_ids": advisory_ids,
            "min_safe_version": min_safe_version if vulnerable else None,
        }
        expected_dependencies.append(dep)

    expected_permissions: List[Dict[str, Any]] = []
    for p in perm_list:
        info = perm_map.get(p)
        if info:
            risk_level = info.get("risk_level", "unknown") or "unknown"
            description = info.get("description", "") or ""
        else:
            risk_level = "unknown"
            description = ""
        expected_permissions.append({
            "name": p,
            "risk_level": risk_level,
            "description": description
        })

    total_deps = len(expected_dependencies)
    vulnerable_count = sum(1 for d in expected_dependencies if d.get("vulnerable") is True)
    high_risk_perm_count = sum(1 for perm in expected_permissions if perm.get("risk_level") == "high")
    cleartext_enabled = bool(uses_cleartext)

    expected = {
        "dependencies": expected_dependencies,
        "manifest": {
            "uses_cleartext_traffic": cleartext_enabled,
            "permissions": expected_permissions
        },
        "summary": {
            "total_dependencies": total_deps,
            "vulnerable_dependencies_count": vulnerable_count,
            "high_risk_permissions_count": high_risk_perm_count,
            "cleartext_traffic_enabled": cleartext_enabled
        }
    }
    return expected, None


def _canonicalize_dependencies_list(deps: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    canon = []
    for d in deps:
        canon.append({
            "ecosystem": d.get("ecosystem"),
            "name": d.get("name"),
            "version": d.get("version"),
            "vulnerable": d.get("vulnerable"),
            "advisory_ids": list(d.get("advisory_ids") or []),
            "min_safe_version": d.get("min_safe_version", None),
        })
    return sorted(canon, key=lambda x: (str(x.get("ecosystem")), str(x.get("name")), str(x.get("version"))))


def _canonicalize_permissions_list(perms: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    canon = []
    for p in perms:
        canon.append({
            "name": p.get("name"),
            "risk_level": p.get("risk_level"),
            "description": p.get("description", "") or ""
        })
    return sorted(canon, key=lambda x: str(x.get("name")))


def _normalize_csv_row(row: Dict[str, str]) -> Dict[str, str]:
    ecosystem = (row.get("ecosystem") or "").strip()
    name = (row.get("name") or "").strip()
    version = (row.get("version") or "").strip()
    msv = (row.get("min_safe_version") or "").strip()
    advis = (row.get("advisory_ids") or "").strip()
    if advis:
        parts = [p.strip() for p in advis.split("|") if p.strip()]
        parts_sorted = sorted(parts)
        advis_norm = "|".join(parts_sorted)
    else:
        advis_norm = ""
    return {
        "ecosystem": ecosystem,
        "name": name,
        "version": version,
        "min_safe_version": msv,
        "advisory_ids": advis_norm
    }


def _expected_vulnerable_rows(expected: dict) -> List[Dict[str, str]]:
    rows: List[Dict[str, str]] = []
    for d in expected.get("dependencies", []):
        if d.get("vulnerable") is True:
            advis_ids = d.get("advisory_ids") or []
            advis_sorted = sorted([str(a) for a in advis_ids])
            rows.append({
                "ecosystem": str(d.get("ecosystem")),
                "name": str(d.get("name")),
                "version": str(d.get("version")),
                "min_safe_version": "" if d.get("min_safe_version") in (None, "") else str(d.get("min_safe_version")),
                "advisory_ids": "|".join(advis_sorted)
            })
    rows_sorted = sorted(rows, key=lambda r: (r["ecosystem"], r["name"], r["version"]))
    return rows_sorted


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "security_audit_json_present": 0.0,
        "security_audit_json_dependencies_correct": 0.0,
        "security_audit_json_manifest_correct": 0.0,
        "security_audit_json_summary_correct": 0.0,
        "vulnerable_csv_present": 0.0,
        "vulnerable_csv_content_correct": 0.0,
        "csv_matches_json_vulnerable_set": 0.0,
    }

    expected, _ = _compute_expected(workspace)
    audit_json_path = workspace / "output" / "security_audit.json"
    vuln_csv_path = workspace / "output" / "vulnerable_dependencies.csv"

    produced_json, _ = _load_json(audit_json_path)
    if produced_json is not None:
        scores["security_audit_json_present"] = 1.0
    else:
        scores["security_audit_json_present"] = 0.0

    if expected is not None and produced_json is not None:
        produced_deps = produced_json.get("dependencies")
        if isinstance(produced_deps, list):
            canon_produced = _canonicalize_dependencies_list(produced_deps)
            canon_expected = _canonicalize_dependencies_list(expected.get("dependencies", []))
            for item in canon_produced:
                item["advisory_ids"] = sorted([str(x) for x in item.get("advisory_ids", [])])
                if item.get("min_safe_version", None) == "":
                    item["min_safe_version"] = ""
            for item in canon_expected:
                item["advisory_ids"] = sorted([str(x) for x in item.get("advisory_ids", [])])
                if not item.get("vulnerable"):
                    item["min_safe_version"] = None
            if canon_produced == canon_expected:
                scores["security_audit_json_dependencies_correct"] = 1.0

        produced_manifest = produced_json.get("manifest")
        if isinstance(produced_manifest, dict):
            uct = produced_manifest.get("uses_cleartext_traffic")
            perms = produced_manifest.get("permissions")
            manifest_ok = True
            if not isinstance(uct, bool):
                manifest_ok = False
            if not isinstance(perms, list):
                manifest_ok = False
            else:
                canon_prod_perms = _canonicalize_permissions_list(perms)
                canon_exp_perms = _canonicalize_permissions_list(expected.get("manifest", {}).get("permissions", []))
                if canon_prod_perms != canon_exp_perms:
                    manifest_ok = False
            if manifest_ok:
                if bool(uct) != bool(expected.get("manifest", {}).get("uses_cleartext_traffic")):
                    manifest_ok = False
            if manifest_ok:
                scores["security_audit_json_manifest_correct"] = 1.0

        produced_summary = produced_json.get("summary")
        if isinstance(produced_summary, dict):
            keys_ok = all(k in produced_summary for k in ["total_dependencies", "vulnerable_dependencies_count", "high_risk_permissions_count", "cleartext_traffic_enabled"])
            if keys_ok:
                try:
                    td = int(produced_summary.get("total_dependencies"))
                    vc = int(produced_summary.get("vulnerable_dependencies_count"))
                    hp = int(produced_summary.get("high_risk_permissions_count"))
                    cte = produced_summary.get("cleartext_traffic_enabled")
                    if not isinstance(cte, bool):
                        raise ValueError("cte not bool")
                except Exception:
                    keys_ok = False
            if keys_ok:
                exp_summary = expected.get("summary", {})
                exp_td = int(exp_summary.get("total_dependencies", -1))
                exp_vc = int(exp_summary.get("vulnerable_dependencies_count", -1))
                exp_hp = int(exp_summary.get("high_risk_permissions_count", -1))
                exp_cte = bool(exp_summary.get("cleartext_traffic_enabled"))
                matches_expected = (td == exp_td and vc == exp_vc and hp == exp_hp and cte == exp_cte)

                internal_ok = False
                if isinstance(produced_json.get("dependencies"), list) and isinstance(produced_json.get("manifest"), dict):
                    prod_deps_list = produced_json.get("dependencies")
                    prod_perm_list = produced_json.get("manifest", {}).get("permissions")
                    prod_manifest_cleartext = produced_json.get("manifest", {}).get("uses_cleartext_traffic")
                    try:
                        internal_td = len(prod_deps_list)
                        internal_vc = sum(1 for d in prod_deps_list if isinstance(d, dict) and d.get("vulnerable") is True)
                        internal_hp = sum(1 for p in (prod_perm_list or []) if isinstance(p, dict) and p.get("risk_level") == "high")
                        internal_cte = bool(prod_manifest_cleartext)
                        if internal_td == td and internal_vc == vc and internal_hp == hp and internal_cte == cte:
                            internal_ok = True
                    except Exception:
                        internal_ok = False
                if matches_expected and internal_ok:
                    scores["security_audit_json_summary_correct"] = 1.0

    if vuln_csv_path.exists():
        try:
            with vuln_csv_path.open("r", encoding="utf-8") as f:
                reader = csv.reader(f)
                rows = list(reader)
            if rows and rows[0] == ["ecosystem", "name", "version", "min_safe_version", "advisory_ids"]:
                scores["vulnerable_csv_present"] = 1.0
                csv_rows, _ = _load_csv_dict(vuln_csv_path)
                if csv_rows is not None:
                    norm_rows = [_normalize_csv_row(r) for r in csv_rows]
                    if expected is not None:
                        exp_rows = _expected_vulnerable_rows(expected)
                        exp_norm_rows = []
                        for r in exp_rows:
                            exp_norm_rows.append({
                                "ecosystem": r["ecosystem"],
                                "name": r["name"],
                                "version": r["version"],
                                "min_safe_version": r["min_safe_version"],
                                "advisory_ids": r["advisory_ids"],
                            })
                        norm_rows_sorted = sorted(norm_rows, key=lambda r: (r["ecosystem"], r["name"], r["version"]))
                        exp_norm_rows_sorted = sorted(exp_norm_rows, key=lambda r: (r["ecosystem"], r["name"], r["version"]))
                        if norm_rows_sorted == exp_norm_rows_sorted:
                            scores["vulnerable_csv_content_correct"] = 1.0
            else:
                scores["vulnerable_csv_present"] = 0.0
        except Exception:
            scores["vulnerable_csv_present"] = 0.0
    else:
        scores["vulnerable_csv_present"] = 0.0

    if expected is not None and produced_json is not None and (workspace / "output" / "vulnerable_dependencies.csv").exists():
        csv_rows, _ = _load_csv_dict(vuln_csv_path)
        if csv_rows is not None:
            norm_csv = [_normalize_csv_row(r) for r in csv_rows]
            prod_deps = produced_json.get("dependencies")
            if isinstance(prod_deps, list):
                prod_vuln_rows = []
                for d in prod_deps:
                    if isinstance(d, dict) and d.get("vulnerable") is True:
                        ecosystem = str(d.get("ecosystem"))
                        name = str(d.get("name"))
                        version = str(d.get("version"))
                        msv = "" if d.get("min_safe_version") in (None, "") else str(d.get("min_safe_version"))
                        advis = d.get("advisory_ids") or []
                        advis_norm = "|".join(sorted([str(a) for a in advis]))
                        prod_vuln_rows.append({
                            "ecosystem": ecosystem,
                            "name": name,
                            "version": version,
                            "min_safe_version": msv,
                            "advisory_ids": advis_norm
                        })
                norm_csv_sorted = sorted(norm_csv, key=lambda r: (r["ecosystem"], r["name"], r["version"]))
                prod_vuln_sorted = sorted(prod_vuln_rows, key=lambda r: (r["ecosystem"], r["name"], r["version"]))
                if norm_csv_sorted == prod_vuln_sorted:
                    scores["csv_matches_json_vulnerable_set"] = 1.0

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

import csv
import json
import re
import sys
from datetime import datetime
from html.parser import HTMLParser
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple


AS_OF_DATE = "2026-05-15"
KEYWORDS = ["native", "pollinator", "habitat restoration", "invasive species", "prairie", "riparian"]

# -----------------------------
# Helper functions
# -----------------------------


def safe_read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def safe_json_load(path: Path) -> Optional[Any]:
    try:
        text = path.read_text(encoding="utf-8")
        return json.loads(text)
    except Exception:
        return None


def split_topics(text: str) -> List[str]:
    parts = re.split(r"[;,]", text)
    return [p.strip() for p in parts if p.strip()]


def parse_money_to_int(text: str) -> Optional[int]:
    try:
        # Remove currency symbols and commas/spaces
        cleaned = re.sub(r"[^\d]", "", text)
        if cleaned == "":
            return None
        return int(cleaned)
    except Exception:
        return None


def is_iso_date(date_str: str) -> bool:
    try:
        datetime.strptime(date_str, "%Y-%m-%d")
        return True
    except Exception:
        return False


def format_money_usd(amount: int) -> str:
    return f"${amount:,}"


def to_lower(s: str) -> str:
    return s.lower()


class Page1TableParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.in_table = False
        self.table_id_target = "grants"
        self.in_tbody = False
        self.in_tr = False
        self.in_td = False
        self.current_row: List[str] = []
        self.current_cell_data: List[str] = []
        self.rows: List[List[str]] = []

    def handle_starttag(self, tag: str, attrs: List[Tuple[str, Optional[str]]]) -> None:
        attrs_dict = dict(attrs)
        if tag == "table" and attrs_dict.get("id") == self.table_id_target:
            self.in_table = True
        elif self.in_table and tag == "tbody":
            self.in_tbody = True
        elif self.in_table and self.in_tbody and tag == "tr":
            self.in_tr = True
            self.current_row = []
        elif self.in_table and self.in_tbody and self.in_tr and tag == "td":
            self.in_td = True
            self.current_cell_data = []

    def handle_endtag(self, tag: str) -> None:
        if tag == "table" and self.in_table:
            self.in_table = False
        elif tag == "tbody" and self.in_table and self.in_tbody:
            self.in_tbody = False
        elif tag == "tr" and self.in_table and self.in_tbody and self.in_tr:
            self.in_tr = False
            if self.current_row:
                self.rows.append(self.current_row)
        elif tag == "td" and self.in_table and self.in_tbody and self.in_tr and self.in_td:
            cell_text = "".join(self.current_cell_data).strip()
            self.current_row.append(cell_text)
            self.in_td = False
            self.current_cell_data = []

    def handle_data(self, data: str) -> None:
        if self.in_table and self.in_tbody and self.in_tr and self.in_td:
            self.current_cell_data.append(data)


class Page2DivParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.in_grant_div = False
        self.current_grant: Dict[str, Any] = {}
        self.grants: List[Dict[str, Any]] = []
        self.in_h3 = False
        self.current_text_fragments: List[str] = []
        self.in_dt = False
        self.in_dd = False
        self.current_dt_name: Optional[str] = None

    def handle_starttag(self, tag: str, attrs: List[Tuple[str, Optional[str]]]) -> None:
        attrs_dict = dict(attrs)
        if tag == "div":
            class_attr = attrs_dict.get("class", "")
            if class_attr and "grant" in class_attr.split():
                self.in_grant_div = True
                self.current_grant = {}
        if self.in_grant_div and tag == "h3":
            self.in_h3 = True
            self.current_text_fragments = []
        if self.in_grant_div and tag == "dt":
            self.in_dt = True
            self.current_text_fragments = []
        if self.in_grant_div and tag == "dd":
            self.in_dd = True
            self.current_text_fragments = []

    def handle_endtag(self, tag: str) -> None:
        if tag == "div" and self.in_grant_div:
            # Finish a grant record
            self.in_grant_div = False
            if self.current_grant:
                self.grants.append(self.current_grant)
            self.current_grant = {}
        if tag == "h3" and self.in_grant_div and self.in_h3:
            text = "".join(self.current_text_fragments).strip()
            self.current_grant["Program"] = text
            self.in_h3 = False
            self.current_text_fragments = []
        if tag == "dt" and self.in_grant_div and self.in_dt:
            dt_text = "".join(self.current_text_fragments).strip()
            self.current_dt_name = dt_text
            self.in_dt = False
            self.current_text_fragments = []
        if tag == "dd" and self.in_grant_div and self.in_dd:
            dd_text = "".join(self.current_text_fragments).strip()
            if self.current_dt_name:
                self.current_grant[self.current_dt_name] = dd_text
            self.in_dd = False
            self.current_text_fragments = []

    def handle_data(self, data: str) -> None:
        if self.in_grant_div and (self.in_h3 or self.in_dt or self.in_dd):
            self.current_text_fragments.append(data)


def parse_input_grants(workspace: Path) -> Optional[List[Dict[str, Any]]]:
    # Parse both HTML input files and produce standardized list of grants
    input1 = workspace / "input" / "grants_page1.html"
    input2 = workspace / "input" / "grants_page2.html"

    expected: List[Dict[str, Any]] = []

    # Page 1
    text1 = safe_read_text(input1)
    if text1 is None:
        return None
    p1 = Page1TableParser()
    try:
        p1.feed(text1)
    except Exception:
        return None
    for row in p1.rows:
        # Expect 6 columns: Program, Agency, Topics, Max Award, Deadline, Eligibility
        if len(row) != 6:
            return None
        program, agency, topics_text, max_award_text, deadline_text, eligibility_text = row
        topics_list = split_topics(topics_text)
        max_award = parse_money_to_int(max_award_text)
        if max_award is None:
            return None
        if not is_iso_date(deadline_text):
            return None
        expected.append(
            {
                "program_name": program,
                "agency": agency,
                "topics": topics_list,
                "max_award_usd": max_award,
                "deadline": deadline_text,
                "eligibility": eligibility_text,
                "source_file": "input/grants_page1.html",
            }
        )

    # Page 2
    text2 = safe_read_text(input2)
    if text2 is None:
        return None
    p2 = Page2DivParser()
    try:
        p2.feed(text2)
    except Exception:
        return None
    for g in p2.grants:
        # Normalize keys
        program = g.get("Program")
        agency = g.get("Agency")
        topics_text = g.get("Topics")
        max_award_text = g.get("Max Award")
        deadline_text = g.get("Deadline")
        eligibility_text = g.get("Eligibility")
        if not all(isinstance(x, str) and x.strip() for x in [program, agency, topics_text, max_award_text, deadline_text, eligibility_text]):
            return None
        topics_list = split_topics(topics_text)
        max_award = parse_money_to_int(max_award_text)
        if max_award is None:
            return None
        if not is_iso_date(deadline_text):
            return None
        expected.append(
            {
                "program_name": program.strip(),
                "agency": agency.strip(),
                "topics": topics_list,
                "max_award_usd": max_award,
                "deadline": deadline_text.strip(),
                "eligibility": eligibility_text.strip(),
                "source_file": "input/grants_page2.html",
            }
        )
    return expected


def normalize_record_core(rec: Dict[str, Any]) -> Tuple:
    # Only include required fields, with types normalized
    return (
        rec.get("program_name"),
        rec.get("agency"),
        tuple(rec.get("topics") or []),
        int(rec.get("max_award_usd")) if isinstance(rec.get("max_award_usd"), int) or (isinstance(rec.get("max_award_usd"), str) and rec.get("max_award_usd").isdigit()) else rec.get("max_award_usd"),
        rec.get("deadline"),
        rec.get("eligibility"),
        rec.get("source_file"),
    )


def load_extracted_json(path: Path) -> Optional[List[Dict[str, Any]]]:
    data = safe_json_load(path)
    if not isinstance(data, list):
        return None
    # Ensure all list items are dicts
    for item in data:
        if not isinstance(item, dict):
            return None
    return data


def filter_and_rank(grants: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    # Filter by keywords and eligibility and deadline on/after AS_OF_DATE
    cutoff = datetime.strptime(AS_OF_DATE, "%Y-%m-%d")
    filtered: List[Dict[str, Any]] = []

    for rec in grants:
        topics_field = rec.get("topics")
        if isinstance(topics_field, list):
            topics_text = "; ".join(t for t in topics_field if isinstance(t, str))
        elif isinstance(topics_field, str):
            topics_text = topics_field
        else:
            continue
        topics_lower = topics_text.lower()
        matched = [kw for kw in KEYWORDS if kw in topics_lower]
        eligibility = rec.get("eligibility", "")
        if not isinstance(eligibility, str):
            continue
        eligible_state = ("midvale" in eligibility.lower()) or ("nationwide" in eligibility.lower())
        deadline_str = rec.get("deadline")
        if not isinstance(deadline_str, str) or not is_iso_date(deadline_str):
            continue
        deadline_dt = datetime.strptime(deadline_str, "%Y-%m-%d")
        if matched and eligible_state and deadline_dt >= cutoff:
            new_rec = dict(rec)
            new_rec["_matched_keywords"] = matched
            filtered.append(new_rec)

    # Rank by deadline asc, max_award desc, program_name asc
    filtered.sort(
        key=lambda r: (
            datetime.strptime(r["deadline"], "%Y-%m-%d"),
            -int(r["max_award_usd"]),
            r["program_name"],
        )
    )
    return filtered


def safe_read_csv(path: Path) -> Tuple[Optional[List[str]], Optional[List[Dict[str, str]]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            header = reader.fieldnames
            rows = list(reader)
        return header, rows
    except Exception:
        return None, None


def compute_relevance_keywords(topics: List[str]) -> str:
    # Compute matched keywords in specified order, lowercase, semicolon-separated
    topics_text = "; ".join(topics).lower()
    matched = [kw for kw in KEYWORDS if kw in topics_text]
    return ";".join(matched)


def all_required_fields_present_and_typed(rec: Dict[str, Any]) -> bool:
    # program_name: str
    # agency: str
    # topics: list of str
    # max_award_usd: int
    # deadline: YYYY-MM-DD
    # eligibility: str
    # source_file: str
    if not isinstance(rec, dict):
        return False
    required = ["program_name", "agency", "topics", "max_award_usd", "deadline", "eligibility", "source_file"]
    for k in required:
        if k not in rec:
            return False
    if not isinstance(rec["program_name"], str):
        return False
    if not isinstance(rec["agency"], str):
        return False
    if not isinstance(rec["topics"], list) or not all(isinstance(t, str) for t in rec["topics"]):
        return False
    if not isinstance(rec["max_award_usd"], int):
        return False
    if not isinstance(rec["deadline"], str) or not is_iso_date(rec["deadline"]):
        return False
    if not isinstance(rec["eligibility"], str):
        return False
    if not isinstance(rec["source_file"], str):
        return False
    return True


def find_email_subject_line(text: str, expected_subject: str) -> bool:
    lines = [ln.strip() for ln in text.splitlines()]
    for ln in lines:
        if not ln:
            continue
        if ln == expected_subject:
            return True
        if ln.lower().startswith("subject:"):
            subj = ln[len("subject:"):].strip()
            if subj == expected_subject:
                return True
    return False


def email_contains_criteria(text: str) -> bool:
    t = text.lower()
    # Must mention keywords concept, Midvale or Nationwide, and the as-of date
    has_keywords = ("keyword" in t)
    has_elig = ("midvale" in t) or ("nationwide" in t)
    has_date = (AS_OF_DATE in text)
    return has_keywords and has_elig and has_date


def email_lists_programs(text: str, programs: List[Dict[str, Any]]) -> bool:
    # For each program in order, ensure there is a line that includes program_name, agency, deadline, and max award (formatted)
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    for idx, rec in enumerate(programs, start=1):
        prog = rec["program_name"]
        agency = rec["agency"]
        deadline = rec["deadline"]
        amt = format_money_usd(int(rec["max_award_usd"]))
        found = False
        for ln in lines:
            # Require the line to include program name, agency, deadline date, and amount
            if (prog in ln) and (agency in ln) and (deadline in ln) and (amt in ln):
                # Prefer but not strictly require rank number presence
                if str(idx) in ln:
                    found = True
                    break
                else:
                    # If not present with number, still accept to avoid over-failing if formatting differs
                    found = True
                    break
        if not found:
            return False
    return True


def email_has_closing_and_refs(text: str) -> bool:
    t = text.lower()
    has_matching = ("matching fund" in t)
    has_outreach = ("outreach" in t)
    has_coord = ("coordinat" in t)  # coordinate/coordination
    has_refs = ("output/native_plant_grants_ranked.csv" in text) and ("output/grants_extracted.json" in text)
    return has_matching and has_outreach and has_coord and has_refs


# -----------------------------
# Grader
# -----------------------------


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores: Dict[str, float] = {
        "extracted_json_exists_and_valid": 0.0,
        "extracted_json_record_count_correct": 0.0,
        "extracted_json_field_types_valid": 0.0,
        "extracted_json_content_match": 0.0,
        "ranked_csv_exists_and_header": 0.0,
        "ranked_csv_row_count_and_order": 0.0,
        "ranked_csv_content_values": 0.0,
        "relevance_keywords_correct": 0.0,
        "email_exists_and_subject": 0.0,
        "email_includes_selection_criteria": 0.0,
        "email_lists_top5_matching_csv": 0.0,
        "email_includes_closing_and_data_refs": 0.0,
    }

    # Compute expected dataset by parsing inputs
    expected_grants = parse_input_grants(workspace)
    expected_valid = isinstance(expected_grants, list) and len(expected_grants) > 0
    expected_count = len(expected_grants) if expected_valid else None

    # Expected filtered and ranked top 5
    expected_top5: Optional[List[Dict[str, Any]]] = None
    if expected_valid:
        filtered_ranked = filter_and_rank(expected_grants)
        expected_top5 = filtered_ranked[:5]

    # 1) Validate extracted JSON
    extracted_path = workspace / "output" / "grants_extracted.json"
    extracted_data = load_extracted_json(extracted_path)
    if isinstance(extracted_data, list):
