import json
import csv
import re
import sys
from pathlib import Path
from typing import List, Dict, Optional, Tuple


def _read_text_safe(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _load_csv_dicts(path: Path) -> Optional[List[Dict[str, str]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            rows = [dict(row) for row in reader]
        return rows
    except Exception:
        return None


def _to_int_safe(value: str) -> Optional[int]:
    try:
        return int(value)
    except Exception:
        return None


def _compute_expected_top5(requests_rows: List[Dict[str, str]]) -> Optional[List[Dict[str, str]]]:
    # Filter and sort as specified; return top5 with exact columns in order
    priority_rank = {"High": 3, "Medium": 2, "Low": 1}
    filtered = []
    for row in requests_rows:
        status = row.get("status", "")
        if status not in ("Open", "In Progress"):
            continue
        days_str = row.get("days_overdue", "")
        days_val = _to_int_safe(days_str)
        if days_val is None:
            # malformed numeric for a relevant row -> fail
            return None
        if days_val <= 0:
            continue
        prio = row.get("priority", "")
        if prio not in priority_rank:
            return None
        req_id = row.get("request_id", "")
        title = row.get("title", "")
        owner = row.get("owner", "")
        if not (req_id and title and owner):
            return None
        filtered.append({
            "request_id": req_id,
            "title": title,
            "priority": prio,
            "days_overdue": days_val,
            "owner": owner,
        })
    # Sort by priority (High > Medium > Low), then days_overdue desc, then request_id asc
    filtered.sort(key=lambda r: (-priority_rank[r["priority"]], -r["days_overdue"], r["request_id"]))
    # Top 5
    top5 = filtered[:5]
    # Convert days_overdue back to string for comparison with CSV content
    for r in top5:
        r["days_overdue"] = str(r["days_overdue"])
    return top5


def _list_feedback_files(feedback_dir: Path) -> List[Path]:
    if not feedback_dir.exists() or not feedback_dir.is_dir():
        return []
    files = [p for p in feedback_dir.iterdir() if p.is_file() and p.suffix.lower() == ".txt"]
    files.sort(key=lambda p: p.name)
    return files


def _build_expected_quotes(feedback_dir: Path, request_ids: List[str]) -> Dict[str, Optional[Tuple[str, str]]]:
    files = _list_feedback_files(feedback_dir)
    result: Dict[str, Optional[Tuple[str, str]]] = {}
    for rid in request_ids:
        found: Optional[Tuple[str, str]] = None
        for f in files:
            content = _read_text_safe(f)
            if content is None:
                continue
            for raw_line in content.splitlines():
                line = raw_line.rstrip("\r\n")
                if rid in line:
                    found = (line, f.name)
                    break
            if found is not None:
                break
        result[rid] = found
    return result


def _parse_email_structure(text: str) -> Dict[str, Optional[object]]:
    lines = text.splitlines()
    # Find first non-empty line as Subject
    i = 0
    n = len(lines)
    subject_line = None
    while i < n and (lines[i].strip() == ""):
        i += 1
    if i < n:
        subject_line = lines[i]
        i += 1
    # Next non-empty line as opening
    opening_line = None
    while i < n and (lines[i].strip() == ""):
        i += 1
    if i < n:
        opening_line = lines[i]
        i += 1
    # Find bullets starting from here: contiguous lines starting with "- " or "* "
    bullets: List[str] = []
    # Skip any empty lines before bullets
    while i < n and lines[i].strip() == "":
        i += 1
    # Collect bullets
    j = i
    while j < n:
        l = lines[j]
        stripped = l.lstrip()
        if stripped.startswith("- ") or stripped.startswith("* "):
            bullets.append(l)
            j += 1
        else:
            break
    # Closing lines: remaining non-empty lines after bullets
    closing_lines: List[str] = []
    k = j
    while k < n:
        if lines[k].strip() != "":
            closing_lines.append(lines[k])
        k += 1
    return {
        "subject": subject_line,
        "opening": opening_line,
        "bullets": bullets,
        "closing": closing_lines,
    }


def _extract_request_id(text: str) -> Optional[str]:
    m = re.search(r'\b(REQ-\d+)\b', text)
    if m:
        return m.group(1)
    return None


def _extract_quote_and_source(text: str) -> Optional[Tuple[str, str]]:
    # Find pattern "..." (source: filename)
    m = re.search(r'"([^"]+)"\s*\(source:\s*([^)]+)\)', text)
    if not m:
        return None
    quote = m.group(1)
    src = m.group(2).strip()
    return (quote, src)


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores: Dict[str, float] = {
        "overdue_csv_exists": 0.0,
        "overdue_csv_header": 0.0,
        "overdue_csv_row_count": 0.0,
        "overdue_csv_content_match": 0.0,
        "email_exists": 0.0,
        "email_subject_line": 0.0,
        "email_opening_sentence": 0.0,
        "email_bullet_count": 0.0,
        "email_bullets_ids_order": 0.0,
        "email_bullet_fields": 0.0,
        "email_bullet_quotes": 0.0,
        "email_closing_eta_request": 0.0,
    }

    # Load input for expected computation
    input_csv_path = workspace / "input" / "data" / "requests.csv"
    input_rows = _load_csv_dicts(input_csv_path)
    expected_top5: Optional[List[Dict[str, str]]] = None
    if input_rows is not None:
        expected_top5 = _compute_expected_top5(input_rows)

    # Compute expected quotes for top5 request IDs
    expected_quotes: Dict[str, Optional[Tuple[str, str]]] = {}
    if expected_top5 is not None:
        req_ids = [r["request_id"] for r in expected_top5]
        expected_quotes = _build_expected_quotes(workspace / "input" / "feedback", req_ids)

    # Check overdue_top5.csv
    out_csv_path = workspace / "output" / "overdue_top5.csv"
    if out_csv_path.exists() and out_csv_path.is_file():
        scores["overdue_csv_exists"] = 1.0
        # Read and validate header and rows
        try:
            with out_csv_path.open("r", encoding="utf-8", newline="") as f:
                reader = csv.reader(f)
                rows = list(reader)
            if len(rows) >= 1:
                header = rows[0]
                expected_header = ["request_id", "title", "priority", "days_overdue", "owner"]
                if header == expected_header:
                    scores["overdue_csv_header"] = 1.0
                # Validate row count equals 5
                data_rows = rows[1:]
                if len(data_rows) == 5:
                    scores["overdue_csv_row_count"] = 1.0
                # Validate content matches expected
                if expected_top5 is not None and header == expected_header and len(data_rows) == 5:
                    # Build list of dicts from actual file for comparison
                    actual_dicts = []
                    for r in data_rows:
                        if len(r) != len(expected_header):
                            actual_dicts = None  # malformed row
                            break
                        d = dict(zip(expected_header, r))
                        actual_dicts.append(d)
                    if actual_dicts is not None:
                        # Compare element-wise equality
                        match = True
                        for idx, exp in enumerate(expected_top5):
                            act = actual_dicts[idx]
                            for k in expected_header:
                                if act.get(k, "") != exp.get(k, ""):
                                    match = False
                                    break
                            if not match:
                                break
                        if match:
                            scores["overdue_csv_content_match"] = 1.0
        except Exception:
            # Leave scores as is for header/content if unreadable
            pass
    else:
        # Missing file; leave zeros
        pass

    # Check email_draft.txt
    email_path = workspace / "output" / "email_draft.txt"
    email_text = _read_text_safe(email_path)
    if email_text is not None:
        scores["email_exists"] = 1.0
        email_struct = _parse_email_structure(email_text)
        subject_line = email_struct.get("subject")
        opening_line = email_struct.get("opening")
        bullets: List[str] = email_struct.get("bullets") or []
        closing_lines: List[str] = email_struct.get("closing") or []

        # Subject line check: first non-empty line starts with "Subject:"
        if isinstance(subject_line, str) and subject_line.strip().startswith("Subject:"):
            scores["email_subject_line"] = 1.0

        # Opening sentence: next non-empty line exists and ends with a period
        if isinstance(opening_line, str):
            open_stripped = opening_line.strip()
            if open_stripped.endswith(".") and ('* ' not in open_stripped and '- ' not in open_stripped):
                scores["email_opening_sentence"] = 1.0

        # Bullet count: exactly 5
        if len(bullets) == 5:
            scores["email_bullet_count"] = 1.0

        # Bullets ID order and fields and quotes
        ids_order_ok = False
        fields_ok = False
        quotes_ok = False

        if expected_top5 is not None and len(bullets) == 5:
            expected_ids = [r["request_id"] for r in expected_top5]
            found_ids: List[Optional[str]] = [_extract_request_id(b) for b in bullets]
            ids_order_ok = (found_ids == expected_ids)

            # Fields present check for each bullet
            fields_ok_local = True
            quotes_ok_local = True
            for idx, b in enumerate(bullets):
                exp = expected_top5[idx]
                rid = exp["request_id"]
                title = exp["title"]
                prio = exp["priority"]
                days = exp["days_overdue"]
                owner = exp["owner"]

                # Check presence of required fields in bullet
                # ensure the bullet contains the exact request_id, title, priority, owner, and "[days] days"
                if rid not in b:
                    fields_ok_local = False
                if title not in b:
                    fields_ok_local = False
                # priority as whole word
                if not re.search(r'\b' + re.escape(prio) + r'\b', b):
                    fields_ok_local = False
                # days with word "days"
                if f"{days} days" not in b:
                    fields_ok_local = False
                if owner not in b:
                    fields_ok_local = False

                # Quote check
                extracted = _extract_quote_and_source(b)
                expected_q = expected_quotes.get(rid) if expected_quotes is not None else None
                if expected_q is None:
                    # Expect "No feedback quote found"
                    if extracted is not None:
                        quotes_ok_local = False
                    else:
                        # Ensure literal phrase appears
                        if "No feedback quote found" not in b:
                            quotes_ok_local = False
                else:
                    # Must have a quote and source file name match
                    if extracted is None:
                        quotes_ok_local = False
                    else:
                        q_text, q_src = extracted
                        exp_text, exp_src = expected_q
                        # Compare verbatim quote text and source filename
                        if q_text != exp_text or q_src != exp_src:
                            quotes_ok_local = False

            fields_ok = fields_ok_local
            quotes_ok = quotes_ok_local

        scores["email_bullets_ids_order"] = 1.0 if ids_order_ok else 0.0
        scores["email_bullet_fields"] = 1.0 if fields_ok else 0.0
        scores["email_bullet_quotes"] = 1.0 if quotes_ok else 0.0

        # Closing sentence asking owners to reply with an ETA
        closing_ok = False
        for cl in closing_lines:
            s = cl.strip()
            if s == "":
                continue
            # Look for both words "reply" and "ETA" (case-insensitive)
            if re.search(r'\breply\b', s, flags=re.IGNORECASE) and re.search(r'\bETA\b', s, flags=re.IGNORECASE):
                closing_ok = True
                break
        scores["email_closing_eta_request"] = 1.0 if closing_ok else 0.0
    else:
        # email doesn't exist
        pass

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

import csv
import json
import math
import re
import sys
from pathlib import Path
from statistics import median
from typing import Any, Dict, List, Optional, Tuple


def _read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _load_json(path: Path) -> Optional[Any]:
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _load_csv(path: Path) -> Tuple[Optional[List[Dict[str, str]]], Optional[List[str]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            rows = [dict(r) for r in reader]
            return rows, reader.fieldnames or []
    except Exception:
        return None, None


def _to_float(value: Any) -> Optional[float]:
    try:
        return float(value)
    except Exception:
        return None


def _median(nums: List[float]) -> float:
    if not nums:
        return float("nan")
    return float(median(nums))


def _nearly_equal(a: float, b: float, tol: float) -> bool:
    try:
        return abs(a - b) <= tol
    except Exception:
        return False


def _compute_expected_from_runs(rows: List[Dict[str, str]]) -> Dict[str, Any]:
    team_runs: Dict[str, List[Dict[str, Any]]] = {}
    total_runs = 0
    completed_runs_global: List[Dict[str, Any]] = []
    drop_counts: Dict[str, int] = {}
    for r in rows:
        team = r.get("team", "")
        ck_c = r.get("checkpoints_completed", "")
        ck_t = r.get("total_checkpoints", "")
        time_min = r.get("time_min", "")
        dist_km = r.get("distance_km", "")
        drop_at = r.get("dropped_at_checkpoint", "")

        ck_c_i = _to_float(ck_c)
        ck_t_i = _to_float(ck_t)
        t = _to_float(time_min)
        d = _to_float(dist_km)

        team_key = str(team)
        if team_key not in team_runs:
            team_runs[team_key] = []
        team_runs[team_key].append({
            "completed": (ck_c_i is not None and ck_t_i is not None and ck_c_i == ck_t_i),
            "time_min": t,
            "distance_km": d,
        })
        total_runs += 1

        if (ck_c_i is not None and ck_t_i is not None and ck_c_i == ck_t_i) and (t is not None):
            completed_runs_global.append({"time_min": t})

        drop_idx = _to_float(drop_at)
        if (drop_idx is not None) and (ck_c_i is not None and ck_t_i is not None and ck_c_i < ck_t_i):
            k = str(int(drop_idx))
            drop_counts[k] = drop_counts.get(k, 0) + 1

    team_stats: Dict[str, Dict[str, Any]] = {}
    for team, runs in team_runs.items():
        total = len(runs)
        completed = [r for r in runs if r["completed"] and (r["time_min"] is not None) and (r["distance_km"] is not None)]
        completed_count = len([r for r in runs if r["completed"]])
        completion_rate = (completed_count / total) if total > 0 else float("nan")
        times = [float(r["time_min"]) for r in completed]
        dists = [float(r["distance_km"]) for r in completed]
        paces = []
        for t, d in zip(times, dists):
            if d > 0:
                paces.append(t / d)
        avg_time = (sum(times) / len(times)) if times else float("nan")
        med_time = _median(times) if times else float("nan")
        avg_pace = (sum(paces) / len(paces)) if paces else float("nan")
        team_stats[team] = {
            "team": team,
            "total_runs": total,
            "completed_runs": completed_count,
            "completion_rate": completion_rate,
            "avg_time_min": avg_time,
            "median_time_min": med_time,
            "avg_pace_min_per_km": avg_pace,
        }

    completed_total = len([r for r in rows if _to_float(r.get("checkpoints_completed")) is not None
                           and _to_float(r.get("total_checkpoints")) is not None
                           and _to_float(r.get("checkpoints_completed")) == _to_float(r.get("total_checkpoints"))])
    overall_completion_rate = (completed_total / total_runs) if total_runs > 0 else float("nan")
    overall_avg_time = (sum([r["time_min"] for r in completed_runs_global]) / len(completed_runs_global)) if completed_runs_global else float("nan")

    expected = {
        "team_stats": team_stats,
        "drops": drop_counts,
        "total_runs": total_runs,
        "overall_completion_rate": overall_completion_rate,
        "overall_avg_time_min": overall_avg_time,
    }
    return expected


def _parse_markdown_section(text: str, header: str) -> List[str]:
    lines = text.splitlines()
    start_idx = None
    for i, line in enumerate(lines):
        if line.strip().lower() == header.lower():
            start_idx = i + 1
            break
    if start_idx is None:
        return []
    known_headers = {"objective:", "key findings:", "issues observed:", "action items:"}
    section: List[str] = []
    for j in range(start_idx, len(lines)):
        l = lines[j]
        if l.strip().lower() in known_headers:
            break
        section.append(l)
    return section


def _extract_bullet_lines(section_lines: List[str]) -> List[str]:
    return [ln for ln in section_lines if ln.strip().startswith("- ") or ln.strip().startswith("* ")]


def _split_run_log_sections(text: str) -> Dict[str, str]:
    sections = {}
    pattern = r"^===\s*(VALID RUN|MALFORMED RUN)\s*===\s*$"
    matches = list(re.finditer(pattern, text, flags=re.MULTILINE))
    for i, m in enumerate(matches):
        title = m.group(1).split()[0].lower()
        start = m.end()
        end = matches[i + 1].start() if i + 1 < len(matches) else len(text)
        content = text[start:end].strip()
        sections[title] = content
    return sections


def _extract_exit_code(section_text: str) -> Optional[int]:
    m = re.search(r"exit\s*code[^-\d]*(-?\d+)", section_text, flags=re.IGNORECASE)
    if not m:
        return None
    try:
        return int(m.group(1))
    except Exception:
        return None


def _section_contains_input_path(section_text: str, rel_path: str) -> bool:
    return rel_path in section_text


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)

    cli_path = workspace / "prototype" / "nav_analyzer"
    stats_csv_path = workspace / "output" / "stats_summary.csv"
    checkpoint_json_path = workspace / "output" / "checkpoint_stats.json"
    run_log_path = workspace / "output" / "run_log.txt"
    notes_md_path = workspace / "deliverables" / "briefing_notes.md"
    input_clean_path = workspace / "input" / "logs" / "nav_runs.csv"
    input_bad_path = workspace / "input" / "logs" / "nav_runs_bad.csv"

    scores: Dict[str, float] = {
        "cli_entry_point_present": 0.0,
        "output_stats_summary_exists": 0.0,
        "output_checkpoint_stats_exists": 0.0,
        "output_run_log_exists": 0.0,
        "stats_summary_structure_correct": 0.0,
        "stats_summary_values_correct": 0.0,
        "checkpoint_stats_structure_correct": 0.0,
        "checkpoint_stats_values_correct": 0.0,
        "run_log_valid_section_present_with_success_exit": 0.0,
        "run_log_malformed_section_present_with_failure_exit": 0.0,
        "run_log_malformed_includes_error_detail": 0.0,
        "briefing_notes_sections_present": 0.0,
        "briefing_key_findings_has_3_bullets": 0.0,
        "briefing_key_findings_references_outputs": 0.0,
        "briefing_issues_quotes_error_and_explains": 0.0,
        "briefing_action_items_3_to_5_with_owner_due": 0.0,
    }

    if cli_path.exists() and cli_path.is_file():
        scores["cli_entry_point_present"] = 1.0

    if stats_csv_path.exists() and stats_csv_path.is_file():
        scores["output_stats_summary_exists"] = 1.0
    if checkpoint_json_path.exists() and checkpoint_json_path.is_file():
        scores["output_checkpoint_stats_exists"] = 1.0
    if run_log_path.exists() and run_log_path.is_file():
        scores["output_run_log_exists"] = 1.0

    clean_rows, clean_headers = _load_csv(input_clean_path) if input_clean_path.exists() else (None, None)

    stats_rows, stats_headers = _load_csv(stats_csv_path) if stats_csv_path.exists() else (None, None)
    if stats_rows is not None and stats_headers is not None:
        expected_headers = [
            "team",
            "total_runs",
            "completed_runs",
            "completion_rate",
            "avg_time_min",
            "median_time_min",
            "avg_pace_min_per_km",
        ]
        if stats_headers == expected_headers:
            scores["stats_summary_structure_correct"] = 1.0

        if clean_rows is not None:
            expected = _compute_expected_from_runs(clean_rows)
            exp_team_stats = expected["team_stats"]  # type: ignore
            try:
                file_team_stats: Dict[str, Dict[str, Any]] = {}
                for r in stats_rows:
                    team = r.get("team")
                    if not team:
                        raise ValueError("missing team")
                    tr = int(float(r.get("total_runs", "nan")))
                    cr = int(float(r.get("completed_runs", "nan")))
                    comp_rate = float(r.get("completion_rate", "nan"))
                    avg_time = float(r.get("avg_time_min", "nan"))
                    med_time = float(r.get("median_time_min", "nan"))
                    avg_pace = float(r.get("avg_pace_min_per_km", "nan"))
                    file_team_stats[team] = {
                        "total_runs": tr,
                        "completed_runs": cr,
                        "completion_rate": comp_rate,
                        "avg_time_min": avg_time,
                        "median_time_min": med_time,
                        "avg_pace_min_per_km": avg_pace,
                    }
                if set(file_team_stats.keys()) == set(exp_team_stats.keys()):
                    all_ok = True
                    for team, exp in exp_team_stats.items():
                        got = file_team_stats.get(team)
                        if got is None:
                            all_ok = False
                            break
                        if got["total_runs"] != exp["total_runs"]:
                            all_ok = False
                            break
                        if got["completed_runs"] != exp["completed_runs"]:
                            all_ok = False
                            break
                        if not _nearly_equal(float(got["completion_rate"]), float(exp["completion_rate"]), 0.001):
                            all_ok = False
                            break
                        if not _nearly_equal(float(got["avg_time_min"]), float(exp["avg_time_min"]), 0.02):
                            all_ok = False
                            break
                        if not _nearly_equal(float(got["median_time_min"]), float(exp["median_time_min"]), 0.02):
                            all_ok = False
                            break
                        if not _nearly_equal(float(got["avg_pace_min_per_km"]), float(exp["avg_pace_min_per_km"]), 0.02):
                            all_ok = False
                            break
                    if all_ok:
                        scores["stats_summary_values_correct"] = 1.0
            except Exception:
                pass

    chk = _load_json(checkpoint_json_path) if checkpoint_json_path.exists() else None
    if chk is not None and isinstance(chk, dict):
        structure_ok = True
        if "overall" not in chk or not isinstance(chk["overall"], dict):
            structure_ok = False
        else:
            overall = chk["overall"]
            if "completion_rate" not in overall or "avg_time_min" not in overall:
                structure_ok = False
        if structure_ok:
            scores["checkpoint_stats_structure_correct"] = 1.0

        if clean_rows is not None:
            expected = _compute_expected_from_runs(clean_rows)
            exp_total_runs = expected["total_runs"]  # type: ignore
            exp_drops: Dict[str, int] = expected["drops"]  # type: ignore
            exp_overall_comp_rate = expected["overall_completion_rate"]  # type: ignore
            exp_overall_avg_time = expected["overall_avg_time_min"]  # type: ignore
            try:
                got_overall = chk.get("overall", {})
                got_comp = float(got_overall.get("completion_rate"))
                got_avg_time = float(got_overall.get("avg_time_min"))
                exp_comp_rounded = round(float(exp_overall_comp_rate), 3) if not math.isnan(float(exp_overall_comp_rate)) else float("nan")
                exp_time_rounded = round(float(exp_overall_avg_time), 2) if not math.isnan(float(exp_overall_avg_time)) else float("nan")
                values_ok = _nearly_equal(got_comp, exp_comp_rounded, 0.0005) and _nearly_equal(got_avg_time, exp_time_rounded, 0.005)
                drops_ok = True
                for cp_idx, drops_count in exp_drops.items():
                    node = chk.get(str(cp_idx))
                    if not isinstance(node, dict):
                        drops_ok = False
                        break
                    got_drops = node.get("drops")
                    got_total = node.get("total_runs")
                    got_rate = node.get("failure_rate")
                    try:
                        got_drops = int(got_drops)
                        got_total = int(got_total)
                        got_rate = float(got_rate)
                    except Exception:
                        drops_ok = False
                        break
                    if got_drops != drops_count:
                        drops_ok = False
                        break
                    if got_total != exp_total_runs:
                        drops_ok = False
                        break
                    exp_rate = round(drops_count / exp_total_runs, 3) if exp_total_runs > 0 else float("nan")
                    if not _nearly_equal(got_rate, exp_rate, 0.0005):
                        drops_ok = False
                        break
                if values_ok and drops_ok:
                    scores["checkpoint_stats_values_correct"] = 1.0
            except Exception:
                pass

    log_text = _read_text(run_log_path) if run_log_path.exists() else None
    if log_text is not None:
        sections = _split_run_log_sections(log_text)
        valid_sec = sections.get("valid", "")
        malformed_sec = sections.get("malformed", "")

        if valid_sec:
            has_input_path = _section_contains_input_path(valid_sec, "input/logs/nav_runs.csv")
            exit_code = _extract_exit_code(valid_sec)
            if has_input_path and exit_code == 0:
                scores["run_log_valid_section_present_with_success_exit"] = 1.0

        if malformed_sec:
            has_input_path_bad = _section_contains_input_path(malformed_sec, "input/logs/nav_runs_bad.csv")
            exit_code_bad = _extract_exit_code(malformed_sec)
            if has_input_path_bad and (exit_code_bad is not None) and (exit_code_bad != 0):
                scores["run_log_malformed_section_present_with_failure_exit"] = 1.0

            if re.search(r"row\s*[:#]?\s*\d+.*?(team|distance_km|time_min)", malformed_sec, flags=re.IGNORECASE | re.DOTALL):
                scores["run_log_malformed_includes_error_detail"] = 1.0

    notes_text = _read_text(notes_md_path) if notes_md_path.exists() else None
    if notes_text is not None:
        obj_sec = _parse_markdown_section(notes_text, "Objective:")
        kf_sec = _parse_markdown_section(notes_text, "Key Findings:")
        issues_sec = _parse_markdown_section(notes_text, "Issues Observed:")
        action_sec = _parse_markdown_section(notes_text, "Action Items:")

        if obj_sec or kf_sec or issues_sec or action_sec:
            has_all = True
            for h in ("Objective:", "Key Findings:", "Issues Observed:", "Action Items:"):
                if h.lower() not in [ln.strip().lower() for ln in notes_text.splitlines()]:
                    has_all = False
                    break
            if has_all:
                scores["briefing_notes_sections_present"] = 1.0

        kf_bullets = _extract_bullet_lines(kf_sec)
        if len(kf_bullets) >= 3:
            scores["briefing_key_findings_has_3_bullets"] = 1.0

        referenced = 0.0
        if checkpoint_json_path.exists():
            chk_json = _load_json(checkpoint_json_path)
            if isinstance(chk_json, dict):
                overall = chk_json.get("overall", {})
                comp = overall.get("completion_rate")
                avg_t = overall.get("avg_time_min")
                overall_strings = set()
                try:
                    comp_f = float(comp)
                    avg_t_f = float(avg_t)
                    overall_strings.update({
                        f"{comp_f}",
                        f"{comp_f:.3f}",
                        f"{comp_f:.2f}",
                        f"{round(comp_f,3)}",
                        f"{avg_t_f}",
                        f"{avg_t_f:.2f}",
                        f"{avg_t_f:.3f}",
                        f"{round(avg_t_f,2)}",
                    })
                except Exception:
                    pass

                team_number_bullets = 0
                for b in kf_bullets:
                    if re.search(r"\b(Alpha|Bravo|Charlie)\b", b) and re.search(r"\d", b):
                        team_number_bullets += 1
                has_overall_number = any(any(s in b for s in overall_strings) for b in kf_bullets) if overall_strings else False

                if team_number_bullets >= 1 and has_overall_number:
                    referenced = 1.0
        scores["briefing_key_findings_references_outputs"] = referenced

        issues_ok = 0.0
        if log_text is not None:
            sections = _split_run_log_sections(log_text)
            malformed_sec = sections.get("malformed", "")
            malformed_lines = [ln for ln in malformed_sec.splitlines() if re.search(r"row\s*[:#]?\s*\d+.*?(team|distance_km|time_min)", ln, flags=re.IGNORECASE)]
            issues_text = "\n".join(issues_sec)
            found_quote = False
            for ln in malformed_lines:
                if ln.strip() and ln.strip() in issues_text:
                    found_quote = True
                    break
            explains = bool(re.search(r"row\s*\d+.*?(team|distance_km|time_min)", issues_text, flags=re.IGNORECASE))
            suggestion = bool(re.search(r"(suggest|harden|validate|validation|guard|improve|checklist|error handling)", issues_text, flags=re.IGNORECASE))
            if (found_quote or explains) and suggestion:
                issues_ok = 1.0
        scores["briefing_issues_quotes_error_and_explains"] = issues_ok

        action_bullets = _extract_bullet_lines(action_sec)
        if 3 <= len(action_bullets) <= 5:
            all_with_owner_due = all(("Owner:" in b and "Due:" in b) for b in action_bullets)
            if all_with_owner_due:
                scores["briefing_action_items_3_to_5_with_owner_due"] = 1.0

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

import csv
import json
import re
import sys
from pathlib import Path
from typing import Dict, List, Optional, Tuple


def safe_read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(utf-8)
    except Exception:
        try:
            return path.read_text(encoding="utf-8")
        except Exception:
            return None


def safe_load_csv(path: Path) -> Tuple[Optional[List[Dict[str, str]]], Optional[List[str]]]:
    if not path.exists():
        return None, None
    try:
        with path.open(newline="", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            rows = list(reader)
            fields = reader.fieldnames
            return rows, fields
    except Exception:
        return None, None


def email_is_valid(email: str) -> bool:
    if not email:
        return False
    return re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", email) is not None


def parse_team_history(path: Path) -> Optional[Dict[str, str]]:
    text = safe_read_text(path)
    if text is None:
        return None
    coach_name = None
    tournament_year = None
    tournament_venue = None
    for line in text.splitlines():
        l = line.strip()
        if l.lower().startswith("coach name:"):
            coach_name = l.split(":", 1)[1].strip()
        elif l.lower().startswith("tournament year:"):
            tournament_year = l.split(":", 1)[1].strip()
        elif l.lower().startswith("tournament venue:"):
            tournament_venue = l.split(":", 1)[1].strip()
    if not (coach_name and tournament_year and tournament_venue):
        return None
    coach_last = coach_name.split()[-1] if coach_name.split() else ""
    return {
        "COACH_FULL": coach_name,
        "COACH_LAST": coach_last,
        "TOURNAMENT_YEAR": tournament_year,
        "VENUE": tournament_venue,
    }


def parse_template_file(path: Path) -> Optional[Tuple[str, str]]:
    text = safe_read_text(path)
    if text is None:
        return None
    lines = text.splitlines()
    if not lines:
        return None
    first = lines[0]
    if not first.startswith("Subject: "):
        return None
    subject_template = first[len("Subject: "):]
    body_lines = lines[1:]
    if body_lines and body_lines[0].strip() == "":
        body_lines = body_lines[1:]
    body_template = "\n".join(body_lines)
    return subject_template, body_template


def fill_template(template: str, values: Dict[str, str]) -> str:
    result = template
    for k, v in values.items():
        result = result.replace("{" + k + "}", v)
    return result


def normalize_text_for_body(s: str) -> str:
    return " ".join((s or "").split())


def parse_draft_file(path: Path) -> Optional[Tuple[str, str, str]]:
    text = safe_read_text(path)
    if text is None:
        return None
    lines = text.splitlines()
    if len(lines) != 3:
        return None
    if not lines[0].startswith("To: ") or not lines[1].startswith("Subject: ") or not lines[2].startswith("Body: "):
        return None
    to_email = lines[0][len("To: "):].strip()
    subject = lines[1][len("Subject: "):].strip()
    body = lines[2][len("Body: "):].strip()
    return to_email, subject, body


def parse_validation_log(path: Path) -> Optional[Dict[str, int]]:
    text = safe_read_text(path)
    if text is None:
        return None
    total = None
    valid = None
    invalid = None
    for line in text.splitlines():
        line = line.strip()
        if line.startswith("total="):
            try:
                total = int(line.split("=", 1)[1].strip())
            except Exception:
                return None
        elif line.startswith("valid="):
            try:
                valid = int(line.split("=", 1)[1].strip())
            except Exception:
                return None
        elif line.startswith("invalid="):
            try:
                invalid = int(line.split("=", 1)[1].strip())
            except Exception:
                return None
    if total is None or valid is None or invalid is None:
        return None
    return {"total": total, "valid": valid, "invalid": invalid}


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "clean_csv_exists_and_structure": 0.0,
        "clean_csv_validity_correct": 0.0,
        "validation_log_consistency": 0.0,
        "drafts_for_all_valid": 0.0,
        "no_invalid_drafts": 0.0,
        "drafts_structure_valid": 0.0,
        "drafts_content_correct": 0.0,
        "summary_csv_correct": 0.0,
        "report_json_correct": 0.0,
    }

    # Load inputs and outputs
    contacts_path = workspace / "input" / "contacts.csv"
    contacts_rows, contacts_fields = safe_load_csv(contacts_path)

    clean_csv_path = workspace / "output" / "clean" / "contacts_clean.csv"
    clean_rows, clean_fields = safe_load_csv(clean_csv_path)

    # Check clean CSV structure and existence
    clean_exists = clean_rows is not None and clean_fields is not None
    if clean_exists and contacts_rows is not None:
        has_valid_col = "valid" in clean_fields
        same_count = len(clean_rows) == len(contacts_rows)
        scores["clean_csv_exists_and_structure"] = 1.0 if (has_valid_col and same_count) else 0.0
    else:
        scores["clean_csv_exists_and_structure"] = 0.0

    # Check validity column correctness (only if row counts match)
    if clean_exists and contacts_rows is not None and len(clean_rows) == len(contacts_rows):
        correctness = []
        for c_row, cl_row in zip(contacts_rows, clean_rows):
            email = c_row.get("email", "")
            expected_valid = "true" if email_is_valid(email) else "false"
            got_valid = (cl_row.get("valid", "") or "").strip().lower()
            correctness.append(1.0 if got_valid == expected_valid else 0.0)
        scores["clean_csv_validity_correct"] = (sum(correctness) / len(correctness)) if correctness else 0.0
    else:
        scores["clean_csv_validity_correct"] = 0.0

    # Validation log consistency
    log_path = workspace / "output" / "logs" / "validation.log"
    log_counts = parse_validation_log(log_path)
    if log_counts is not None and clean_exists and contacts_rows is not None:
        clean_valid_count = sum(1 for r in clean_rows if str(r.get("valid", "")).strip().lower() == "true")
        clean_total = len(clean_rows)
        clean_invalid_count = clean_total - clean_valid_count
        ok = (
            log_counts.get("total") == clean_total
            and log_counts.get("valid") == clean_valid_count
            and log_counts.get("invalid") == clean_invalid_count
            and clean_total == len(contacts_rows)
        )
        scores["validation_log_consistency"] = 1.0 if ok else 0.0
    else:
        scores["validation_log_consistency"] = 0.0

    # Parse team info and templates for content checks
    team_history_path = workspace / "input" / "team_history.md"
    team_info = parse_team_history(team_history_path)

    template_player_path = workspace / "input" / "templates" / "template_player.txt"
    template_supporter_path = workspace / "input" / "templates" / "template_supporter.txt"
    tpl_player = parse_template_file(template_player_path)
    tpl_supporter = parse_template_file(template_supporter_path)

    # Gather valid/invalid contacts from clean CSV
    valid_contacts: List[Dict[str, str]] = []
    invalid_contacts: List[Dict[str, str]] = []
    if clean_exists:
        for row in clean_rows:
            if str(row.get("valid", "")).strip().lower() == "true":
                valid_contacts.append(row)
            else:
                invalid_contacts.append(row)

    # Draft files
    drafts_dir = workspace / "output" / "drafts"
    draft_files = []
    if drafts_dir.exists() and drafts_dir.is_dir():
        draft_files = sorted([p for p in drafts_dir.iterdir() if p.is_file() and p.suffix == ".txt"])

    # Expected filenames for valid contacts
    expected_filenames = set()
    valid_map_by_filename = {}
    for r in valid_contacts:
        fn = f"{(r.get('last_name','') or '').strip()}_{(r.get('first_name','') or '').strip()}.txt"
        expected_filenames.add(fn)
        valid_map_by_filename[fn] = r

    actual_filenames = set([p.name for p in draft_files])

    present_valid = expected_filenames.intersection(actual_filenames)
    if clean_exists and len(valid_contacts) > 0:
        scores["drafts_for_all_valid"] = len(present_valid) / len(valid_contacts)
    else:
        scores["drafts_for_all_valid"] = 0.0

    # Ensure no drafts for invalid contacts
    invalid_filenames = set()
    for r in invalid_contacts:
        fn = f"{(r.get('last_name','') or '').strip()}_{(r.get('first_name','') or '').strip()}.txt"
        invalid_filenames.add(fn)
    extra_invalid = invalid_filenames.intersection(actual_filenames)
    if clean_exists:
        scores["no_invalid_drafts"] = 1.0 if len(extra_invalid) == 0 else 0.0
    else:
        scores["no_invalid_drafts"] = 0.0

    # Drafts structure check
    structures = []
    for p in draft_files:
        parsed = parse_draft_file(p)
        structures.append(1.0 if parsed is not None else 0.0)
    scores["drafts_structure_valid"] = (sum(structures) / len(structures)) if draft_files else 0.0

    # Drafts content correctness
    content_correct_flags = []
    if team_info and tpl_player and tpl_supporter and draft_files:
        subj_player, body_player = tpl_player
        subj_support, body_support = tpl_supporter
        for p in draft_files:
            parsed = parse_draft_file(p)
            if parsed is None:
                content_correct_flags.append(0.0)
                continue
            to_email, subj_actual, body_actual_line = parsed
            base = p.name
            contact_row = valid_map_by_filename.get(base)
            if contact_row is None:
                # If a draft corresponds to an invalid contact, content cannot be correct
                content_correct_flags.append(0.0)
                continue
            role = (contact_row.get("role") or "").strip()
            first_name = (contact_row.get("first_name") or "").strip()
            years = (contact_row.get("years") or "").strip()
            email = (contact_row.get("email") or "").strip()
            values = {
                "FIRST": first_name,
                "YEARS_PLAYED": years,
                "TOURNAMENT_YEAR": team_info["TOURNAMENT_YEAR"],
                "VENUE": team_info["VENUE"],
                "COACH_FULL": team_info["COACH_FULL"],
                "COACH_LAST": team_info["COACH_LAST"],
            }
            if role == "player":
                subj_expected = fill_template(subj_player, values)
                body_expected = fill_template(body_player, values)
            else:
                subj_expected = fill_template(subj_support, values)
                body_expected = fill_template(body_support, values)
            subj_ok = subj_actual == subj_expected
            body_ok = normalize_text_for_body(body_actual_line) == normalize_text_for_body(body_expected)
            to_ok = to_email == email
            no_placeholders = ("{" not in subj_actual and "}" not in subj_actual and "{" not in body_actual_line and "}" not in body_actual_line)
            flag = 1.0 if (subj_ok and body_ok and to_ok and no_placeholders) else 0.0
            content_correct_flags.append(flag)
    elif draft_files:
        content_correct_flags = [0.0 for _ in draft_files]

    scores["drafts_content_correct"] = (sum(content_correct_flags) / len(content_correct_flags)) if draft_files else 0.0

    # Summary CSV checks
    summary_csv_path = workspace / "output" / "summary" / "recipients.csv"
    summary_rows, summary_fields = safe_load_csv(summary_csv_path)
    draft_subjects_by_name = {}
    draft_to_emails_by_name = {}
    for p in draft_files:
        parsed = parse_draft_file(p)
        if parsed:
            to_email, subj, _ = parsed
            draft_subjects_by_name[p.name] = subj
            draft_to_emails_by_name[p.name] = to_email

    summary_ok = 0.0
    if summary_rows is not None and summary_fields is not None and draft_files:
        required_cols = ["first_name", "last_name", "email", "role", "template_used", "subject"]
        cols_ok = summary_fields == required_cols
        count_ok = len(summary_rows) == len(draft_files)
        row_flags = []
        if cols_ok and count_ok:
            for row in summary_rows:
                fn = f"{(row.get('last_name') or '').strip()}_{(row.get('first_name') or '').strip()}.txt"
                email = (row.get("email") or "").strip()
                role = (row.get("role") or "").strip()
                template_used = (row.get("template_used") or "").strip()
                subj = (row.get("subject") or "").strip()
                draft_present = fn in draft_subjects_by_name
                subj_match = draft_present and subj == draft_subjects_by_name.get(fn, "")
                email_match = draft_present and email == draft_to_emails_by_name.get(fn, "")
                expected_basename = "template_player.txt" if role == "player" else "template_supporter.txt"
                template_ok = template_used.endswith(expected_basename)
                row_flags.append(1.0 if (draft_present and subj_match and email_match and template_ok) else 0.0)
            per_row = (sum(row_flags) / len(row_flags)) if row_flags else 0.0
            summary_ok = 1.0 if per_row == 1.0 else per_row
        else:
            summary_ok = 0.0
    else:
        summary_ok = 0.0
    scores["summary_csv_correct"] = summary_ok

    # Report JSON checks
    report_json_path = workspace / "output" / "report" / "summary.json"
    report_ok = 0.0
    report = None
    report_text = safe_read_text(report_json_path)
    if report_text is not None:
        try:
            report = json.loads(report_text)
        except Exception:
            report = None
    if report is not None and contacts_rows is not None and clean_exists and log_counts is not None:
        expected_total_contacts = len(contacts_rows)
        expected_total_valid = sum(1 for r in clean_rows if str(r.get("valid", "")).strip().lower() == "true")
        expected_invalid = expected_total_contacts - expected_total_valid
        drafts_by_role: Dict[str, int] = {}
        for p in draft_files:
            r = valid_map_by_filename.get(p.name)
            if r:
                role = (r.get("role") or "").strip()
                drafts_by_role[role] = drafts_by_role.get(role, 0) + 1
        keys_present = all(k in report for k in ["total_contacts", "total_valid", "invalid_skipped", "drafts_written", "by_role"])
        if keys_present:
            conds = []
            conds.append(report.get("total_contacts") == expected_total_contacts)
            conds.append(report.get("total_valid") == expected_total_valid)
            conds.append(report.get("invalid_skipped") == expected_invalid)
            conds.append(report.get("drafts_written") == len(draft_files))
            conds.append(isinstance(report.get("by_role"), dict))
            conds.append(report.get("by_role") == drafts_by_role)
            conds.append(report.get("invalid_skipped") == log_counts.get("invalid"))
            report_ok = 1.0 if all(conds) else 0.0
        else:
            report_ok = 0.0
    else:
        report_ok = 0.0
    scores["report_json_correct"] = report_ok

    # Clamp scores
    for k, v in list(scores.items()):
        try:
            vv = float(v)
        except Exception:
            vv = 0.0
        if vv < 0.0:
            vv = 0.0
        if vv > 1.0:
            vv = 1.0
        scores[k] = vv

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

task_files.content:
import sys
import csv
from datetime import datetime

REQUIRED_COLUMNS = [
    "task_id",
    "title",
    "category",
    "priority",
    "effort_mins",
    "due_datetime",
    "depends_on",
]

ISO_FMT = "%Y-%m-%dT%H:%M"


def validate(csv_path: str) -> int:
    errors = []
    warns = []
    seen_ids = set()
    rows = []

    try:
        with open(csv_path, newline="", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            header = reader.fieldnames or []
            missing = [c for c in REQUIRED_COLUMNS if c not in header]
            if missing:
                errors.append({
                    "task_id": None,
                    "field": "header",
                    "msg": f"missing columns: {', '.join(missing)}"
                })
                # Still attempt to read rows to report more issues
            for row in reader:
                rows.append(row)
    except FileNotFoundError:
        print(f"ERROR could not open file: {csv_path}", file=sys.stderr)
        return 2

    # Row-level checks
    for idx, row in enumerate(rows, start=2):  # header is line 1
        tid = row.get("task_id", "").strip()
        if not tid:
            errors.append({"task_id": None, "field": "task_id", "msg": f"blank task_id at CSV line {idx}"})
        elif tid in seen_ids:
            errors.append({"task_id": tid, "field": "task_id", "msg": "duplicate task_id"})
        else:
            seen_ids.add(tid)

        # priority
        pr_raw = (row.get("priority") or "").strip()
        try:
            pr = int(pr_raw)
            if pr < 1 or pr > 5:
                errors.append({"task_id": tid, "field": "priority", "msg": f"out of range 1-5: {pr_raw}"})
        except ValueError:
            errors.append({"task_id": tid, "field": "priority", "msg": f"not an integer: {pr_raw}"})

        # effort_mins
        em_raw = (row.get("effort_mins") or "").strip()
        if em_raw == "":
            errors.append({"task_id": tid, "field": "effort_mins", "msg": "missing"})
        else:
            try:
                em = int(em_raw)
                if em <= 0:
                    errors.append({"task_id": tid, "field": "effort_mins", "msg": f"must be > 0: {em_raw}"})
            except ValueError:
                errors.append({"task_id": tid, "field": "effort_mins", "msg": f"not an integer: {em_raw}"})

        # due_datetime
        dd_raw = (row.get("due_datetime") or "").strip()
        try:
            datetime.strptime(dd_raw, ISO_FMT)
        except Exception:
            errors.append({"task_id": tid, "field": "due_datetime", "msg": f"not ISO local '{ISO_FMT}': {dd_raw}"})

    # depends_on existence (warning only)
    id_set = set(r.get("task_id", "").strip() for r in rows)
    for row in rows:
        tid = row.get("task_id", "").strip()
        dep = (row.get("depends_on") or "").strip()
        if dep and dep not in id_set:
            warns.append({"task_id": tid, "field": "depends_on", "msg": f"references unknown task_id: {dep}"})

    # Emit details to stderr
    for e in errors:
        print(
            f"ERROR task_id={e.get('task_id')} field={e.get('field')} msg=\"{e.get('msg')}\"",
            file=sys.stderr,
        )
    for w in warns:
        print(
            f"WARN task_id={w.get('task_id')} field={w.get('field')} msg=\"{w.get('msg')}\"",
            file=sys.stderr,
        )

    # Emit summary to stdout
    print(
        f"Validation complete: rows={len(rows)}, errors={len(errors)}, warnings={len(warns)}"
    )

    return 1 if errors else 0


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python validate_tasks.py <tasks.csv>", file=sys.stderr)
        sys.exit(2)
    sys.exit(validate(sys.argv[1]))

