                                break
                        except Exception:
                            # invalid original should have been set to 60
                            if em_cl != 60:
                                cleaned_ok = False
                                break
                    # due_datetime ISO and normalized
                    dd_in = (orig.get("due_datetime") or "").strip()
                    dd_cl = (clean.get("due_datetime") or "").strip()
                    if not _iso_local(dd_cl):
