                        if pq_ids != exp_ids:
                            pq_ok = False
                        else:
                            # Map cleaned fields
                            cl_map = {r["task_id"]: r for r in cl_rows}
                            for idx, row in enumerate(pq_rows, start=1):
                                tid = row.get("task_id")
                                cr = cl_map.get(tid, {})
                                # window_rank
                                try:
                                    wr = int(row.get("window_rank", ""))
                                except Exception:
                                    pq_ok = False
                                    break
                                if wr != idx:
                                    pq_ok = False
                                    break
                                # field equality
                                for fld in ["title", "category", "priority", "effort_mins", "due_datetime"]:
                                    if str(row.get(fld, "")) != str(cr.get(fld, "")):
                                        pq_ok = False
                                        break
                                if not pq_ok:
