import json
import os
import sys
import csv
from datetime import datetime, timezone

def workspace_paths(root):
    return (
        os.path.join(root, "input"),
        os.path.join(root, "output"),
        os.path.join(root, "reward"),
    )

def read_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

def parse_jsonl(path):
    items = []
    if not os.path.isfile(path):
        return items
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
                items.append(obj)
            except json.JSONDecodeError:
                # Skip malformed lines deterministically
                continue
    return items

def to_int(value):
    try:
        if value is None:
            return None
        if isinstance(value, bool):
            return int(value)
        if isinstance(value, (int, float)):
            return int(value)
        s = str(value).strip()
        if s == "":
            return None
        return int(float(s))
    except Exception:
        return None

def iso_utc_from_ms(ms):
    iv = to_int(ms)
    if iv is None:
        return ""
    try:
        dt = datetime.fromtimestamp(iv / 1000.0, tz=timezone.utc)
        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")
    except Exception:
        return ""

def starts_with(s, prefix):
    if s is None or prefix is None:
        return False
    return str(s).startswith(str(prefix))

def safe_str(v):
    if v is None:
        return ""
    return str(v)

def compute_content_length_from_data(data_obj):
    # Rule:
    # - If data.parts is a non-empty array: sum len(text) for items where type == "text"
    # - Else if data.content present: len(content)
    # - Else 0
    try:
        parts = data_obj.get("parts", None)
    except Exception:
        parts = None
    if isinstance(parts, list) and len(parts) > 0:
        total = 0
        for item in parts:
            try:
                if isinstance(item, dict) and item.get("type") == "text":
                    t = item.get("text")
                    if isinstance(t, str):
                        total += len(t)
            except Exception:
                continue
        return int(total)
    content = data_obj.get("content", None)
    if isinstance(content, str):
        return len(content)
    return 0

def main():
    workspace_root = sys.argv[1] if len(sys.argv) > 1 else "/root/.openclaw/workspace"
    input_dir, output_dir, reward_dir = workspace_paths(workspace_root)

    # Initialize checks
    checks = {
        "sessions_csv_exists": False,
        "sessions_header_ok": False,
        "sessions_row_count_match": False,
        "sessions_sorted_desc": False,
        "sessions_values_match": False,
        "messages_file_exists": False,
        "messages_filename_matches_sid": False,
        "messages_line_count_match": False,
        "messages_order_ok": False,
        "messages_values_match": False,
    }

    # Read inputs
    params_path = os.path.join(input_dir, "params.json")
    session_path = os.path.join(input_dir, "session.jsonl")
    project_path = os.path.join(input_dir, "project.jsonl")
    message_path = os.path.join(input_dir, "message.jsonl")

    try:
        params = read_json(params_path)
    except Exception:
        params = {}

    sessions = parse_jsonl(session_path)
    projects = parse_jsonl(project_path)
    messages = parse_jsonl(message_path)

    # Build project index by id
    project_by_id = {}
    for p in projects:
        pid = p.get("id")
        if pid is not None:
            project_by_id[str(pid)] = p

    # Extract filter parameters
    directory_prefix = params.get("directory_prefix")
    since_ms = to_int(params.get("since_ms"))
    until_ms = to_int(params.get("until_ms"))

    # Filter sessions
    filtered = []
    for s in sessions:
        directory = s.get("directory")
        time_updated = to_int(s.get("time_updated"))
        if directory_prefix is not None and not starts_with(directory, directory_prefix):
            continue
        if since_ms is not None and (time_updated is None or time_updated < since_ms):
            continue
        if until_ms is not None and (time_updated is None or time_updated > until_ms):
            continue
        filtered.append(s)

    # Sort by time_updated descending
    filtered_sorted = sorted(filtered, key=lambda x: (to_int(x.get("time_updated")) or -10**20), reverse=True)

    # Build expected CSV rows
    expected_rows = []
    for s in filtered_sorted:
        pid = s.get("project_id")
        proj = project_by_id.get(str(pid), {})
        row = {
            "id": safe_str(s.get("id")),
            "title": safe_str(s.get("title")),
            "project_name": safe_str(proj.get("name")),
            "worktree": safe_str(proj.get("worktree")),
            "updated_utc": iso_utc_from_ms(s.get("time_updated")),
            "summary_files": safe_str(s.get("summary_files") if s.get("summary_files") is not None else ""),
            "summary_additions": safe_str(s.get("summary_additions") if s.get("summary_additions") is not None else ""),
            "summary_deletions": safe_str(s.get("summary_deletions") if s.get("summary_deletions") is not None else ""),
        }
        expected_rows.append(row)

    # Validate sessions_report.csv
    sessions_csv_path = os.path.join(output_dir, "sessions_report.csv")
    if os.path.isfile(sessions_csv_path):
        checks["sessions_csv_exists"] = True
        header_expected = ["id","title","project_name","worktree","updated_utc","summary_files","summary_additions","summary_deletions"]
        try:
            with open(sessions_csv_path, "r", encoding="utf-8", newline="") as f:
                reader = csv.reader(f)
                rows = list(reader)
            if rows:
                header = rows[0]
                if header == header_expected:
                    checks["sessions_header_ok"] = True
                # Parse body rows with csv.DictReader for robust parsing
                with open(sessions_csv_path, "r", encoding="utf-8", newline="") as f2:
                    dict_reader = csv.DictReader(f2)
                    actual_rows = [ {k: v if v is not None else "" for k,v in r.items()} for r in dict_reader ]
                # Count check
                if len(actual_rows) == len(expected_rows):
                    checks["sessions_row_count_match"] = True
                # Order check (by time_updated desc): check id sequence equals expected
                actual_ids = [r.get("id","") for r in actual_rows]
                expected_ids = [r["id"] for r in expected_rows]
                if actual_ids == expected_ids:
                    checks["sessions_sorted_desc"] = True
                # Values check
                values_match = True
                if len(actual_rows) != len(expected_rows):
                    values_match = False
                else:
                    for ar, er in zip(actual_rows, expected_rows):
                        for key in header_expected:
                            av = ar.get(key, "")
                            ev = er.get(key, "")
                            # Normalize None/empty
                            if av is None: av = ""
                            if ev is None: ev = ""
                            if str(av) != str(ev):
                                values_match = False
                                break
                        if not values_match:
                            break
                if values_match and checks["sessions_header_ok"]:
                    checks["sessions_values_match"] = True
        except Exception:
            # Keep checks as False if any error in reading/parsing
            pass

    # Determine SID for most recent filtered session
    sid = filtered_sorted[0].get("id") if filtered_sorted else None
    sid_str = safe_str(sid) if sid is not None else None

    # Build expected messages for SID
    expected_msg_lines = []
    if sid_str:
        msgs_for_sid = [m for m in messages if safe_str(m.get("session_id")) == sid_str]
        msgs_for_sid_sorted = sorted(msgs_for_sid, key=lambda m: (to_int(m.get("time_created")) or -10**20))
        for m in msgs_for_sid_sorted:
            # Parse data JSON-encoded string
            raw_data = m.get("data")
            data_obj = {}
            if isinstance(raw_data, str):
                try:
                    data_obj = json.loads(raw_data)
                except Exception:
                    data_obj = {}
            elif isinstance(raw_data, dict):
                data_obj = raw_data
            else:
                data_obj = {}
            role = data_obj.get("role", None)
            modelID = data_obj.get("modelID", None)
            content_length = compute_content_length_from_data(data_obj)
            line_obj = {
                "id": safe_str(m.get("id")),
                "created_utc": iso_utc_from_ms(m.get("time_created")),
                "role": role,
                "modelID": modelID,
                "content_length": int(content_length),
            }
            expected_msg_lines.append(line_obj)

    # Validate messages_<SID>.jsonl
    messages_file_name = None
    if sid_str:
        messages_file_name = f"messages_{sid_str}.jsonl"
    if messages_file_name:
        messages_file_path = os.path.join(output_dir, messages_file_name)
        if os.path.isfile(messages_file_path):
            checks["messages_file_exists"] = True
            # Filename matches SID if sessions exist
            if sid_str:
                checks["messages_filename_matches_sid"] = True
            try:
                actual_lines = []
                with open(messages_file_path, "r", encoding="utf-8") as f:
                    for line in f:
                        line = line.strip()
                        if not line:
                            continue
                        try:
                            obj = json.loads(line)
                            actual_lines.append(obj)
                        except json.JSONDecodeError:
                            # Malformed line fails checks later
                            actual_lines.append("__MALFORMED__")
                # Count
                if isinstance(actual_lines, list) and "__MALFORMED__" not in actual_lines:
                    if len(actual_lines) == len(expected_msg_lines):
                        checks["messages_line_count_match"] = True
                # Order: compare created_utc sequence
                if "__MALFORMED__" not in actual_lines and len(actual_lines) == len(expected_msg_lines):
                    actual_created = [al.get("created_utc", None) for al in actual_lines]
                    expected_created = [el.get("created_utc", None) for el in expected_msg_lines]
                    if actual_created == expected_created:
                        checks["messages_order_ok"] = True
                # Values and keys exactness
                fields_ok = True
                if "__MALFORMED__" in actual_lines or len(actual_lines) != len(expected_msg_lines):
                    fields_ok = False
                else:
                    for al, el in zip(actual_lines, expected_msg_lines):
                        if not isinstance(al, dict):
                            fields_ok = False
                            break
                        # Exactly these keys
                        wanted_keys = {"id", "created_utc", "role", "modelID", "content_length"}
                        if set(al.keys()) != wanted_keys:
                            fields_ok = False
                            break
                        # Compare values
                        if safe_str(al.get("id")) != safe_str(el.get("id")):
                            fields_ok = False
                            break
                        if al.get("created_utc") != el.get("created_utc"):
                            fields_ok = False
                            break
                        # role and modelID can be None or strings; compare directly
                        if al.get("role") != el.get("role"):
                            fields_ok = False
                            break
                        if al.get("modelID") != el.get("modelID"):
                            fields_ok = False
                            break
                        # content_length must be int equal
                        try:
                            al_len = int(al.get("content_length"))
                        except Exception:
                            fields_ok = False
                            break
                        if al_len != int(el.get("content_length")):
                            fields_ok = False
                            break
                if fields_ok:
                    checks["messages_values_match"] = True
            except Exception:
                # Keep as False on errors
                pass

    # Compute reward
    total_checks = len(checks)
    passed = sum(1 for v in checks.values() if v)
    if not checks["sessions_csv_exists"] and not checks["messages_file_exists"]:
        reward = 0.0
    else:
        reward = passed / total_checks if total_checks > 0 else 0.0
    # Clamp
    if reward < 0:
        reward = 0.0
    if reward > 1:
        reward = 1.0

    # Output JSON result
    result = {"reward": reward}
    result.update(checks)
    print(json.dumps(result))

if __name__ == "__main__":
    main()

import json
import os
import sys
import csv
from datetime import datetime, timedelta, date

def get_workspace_root():
    if len(sys.argv) > 1 and sys.argv[1]:
        return sys.argv[1]
    return "/root/.openclaw/workspace"

def read_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

def normalize_header(header):
    return header.strip().lower()

def read_csv_dicts(path):
    rows = []
    with open(path, "r", encoding="utf-8") as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return []
        keys = [normalize_header(h) for h in header]
        for parts in reader:
            # Pad or trim to header length
            if len(parts) < len(keys):
                parts = parts + [""] * (len(keys) - len(parts))
            elif len(parts) > len(keys):
                parts = parts[:len(keys)]
            row = {}
            for i, key in enumerate(keys):
                row[key] = parts[i].strip()
            rows.append(row)
    return rows

def parse_number(val):
    if val is None:
        return 0.0
    s = str(val).strip()
    if s == "":
        return 0.0
    # Remove common currency and thousands markers
    # Keep minus sign and dot
    cleaned = []
    for ch in s:
        if ch.isdigit() or ch in ['.', '-', '+', 'e', 'E']:
            cleaned.append(ch)
        elif ch in [',', '$', '€', '£']:
            continue
        else:
            # skip other symbols/spaces
            continue
    cleaned_s = "".join(cleaned)
    if cleaned_s in ("", "-", "+"):
        return 0.0
    try:
        return float(cleaned_s)
    except ValueError:
        # Fallback: try to remove non-numeric except dot and minus
        try:
            return float("".join([c for c in s if (c.isdigit() or c in ".-")]))
        except Exception:
            return 0.0

def parse_date_yyyy_mm_dd(s):
    s = (s or "").strip()
    if not s:
        return None
    try:
        dt = datetime.strptime(s, "%Y-%m-%d").date()
        return dt
    except ValueError:
        return None

def get_anchor_date(cfg):
    # Prefer 'anchor_date', then 'anchorDate', then 'today', then 'date'
    for key in ["anchor_date", "anchorDate", "today", "date"]:
        if key in cfg:
            d = parse_date_yyyy_mm_dd(str(cfg[key]))
            if d:
                return d
    return None

def build_expected(workspace_root):
    input_dir = os.path.join(workspace_root, "input")
    contacts_path = os.path.join(input_dir, "contacts.csv")
    deals_path = os.path.join(input_dir, "deals.csv")
    config_path = os.path.join(input_dir, "config.json")

    contacts = read_csv_dicts(contacts_path)
    deals = read_csv_dicts(deals_path)
    config = read_json(config_path)

    # Contacts mapping by email (lowercased)
    email_to_name = {}
    for c in contacts:
        email = (c.get("email") or "").strip().lower()
        name = (c.get("name") or "").strip()
        if email and email not in email_to_name:
            email_to_name[email] = name

    # Pipeline stages
    stages = ["prospect", "qualified", "proposal", "negotiation", "closed-won", "closed-lost"]
    stage_counts = {s: 0 for s in stages}
    stage_totals = {s: 0.0 for s in stages}

    # Build tags per deal and followups
    expected_tags_rows = []  # list of (title, normalized_tags)
    followup_lines = []  # list of tuples (due_date, line_str)

    anchor = get_anchor_date(config)
    # window inclusive [anchor, anchor+7]
    if anchor:
        end_date = anchor + timedelta(days=7)
    else:
        end_date = None

    open_stages = set(["prospect", "qualified", "proposal", "negotiation"])

    for d in deals:
        title = (d.get("title") or "").strip()
        stage = (d.get("stage") or "").strip().lower()
        value = parse_number(d.get("value"))

        if stage in stage_counts:
            stage_counts[stage] += 1
            stage_totals[stage] += value

        # tags normalization
        tags_field = d.get("tags") or ""
        parts = [p.strip().lower() for p in tags_field.split(";")] if tags_field != "" else []
        parts = [p for p in parts if p != ""]
        # de-dup and sort
        unique_sorted = sorted(set(parts))
        tags_norm = ";".join(unique_sorted)
        expected_tags_rows.append((title, tags_norm))

        # followups within next 7d for open stages
        if stage in open_stages and anchor is not None:
            due_str = d.get("followup_due") or ""
            due = parse_date_yyyy_mm_dd(due_str)
            if due is not None and anchor <= due <= end_date:
                contact_email = (d.get("contact_email") or "").strip().lower()
                contact_name = email_to_name.get(contact_email)
                if not contact_name or contact_name.strip() == "":
                    # Fallback to email if no match
                    contact_name = d.get("contact_email") or ""
                note = d.get("followup_note") or ""
                line = f"{due.strftime('%Y-%m-%d')} | {title} | {contact_name} | {note}"
                followup_lines.append((due, line))

    # Prepare expected pipeline report
    stages_obj = {s: {"count": stage_counts[s], "total_value": float(stage_totals[s])} for s in stages}
    grand_total_count = sum(stage_counts.values())
    grand_total_value = float(sum(stage_totals.values()))
    expected_pipeline = {
        "stages": stages_obj,
        "grand_total_count": grand_total_count,
        "grand_total_value": grand_total_value
    }

    # Sort expected followups by due date ascending
    followup_lines_sorted = sorted(followup_lines, key=lambda x: (x[0].toordinal(),))
    expected_followups_lines = [line for _, line in followup_lines_sorted]
    expected_followups_header1 = f"Follow-ups due in next 7 days (anchor: {anchor.strftime('%Y-%m-%d') if anchor else ''})"
    expected_followups_header2 = "due_date | deal_title | contact_name | note"

    # Prepare expected tags csv rows sorted by title ascending
    expected_tags_rows_sorted = sorted(expected_tags_rows, key=lambda x: (x[0] or "").lower())

    expected = {
        "pipeline": expected_pipeline,
        "followups": {
            "header1": expected_followups_header1,
            "header2": expected_followups_header2,
            "lines": expected_followups_lines
        },
        "tags": expected_tags_rows_sorted
    }
    return expected

def float_eq(a, b, tol=1e-6):
    return abs(float(a) - float(b)) <= tol

def main():
    workspace_root = get_workspace_root()
    input_dir = os.path.join(workspace_root, "input")
    output_dir = os.path.join(workspace_root, "output")
    # reward_dir not used for scoring, but path kept for completeness
    reward_dir = os.path.join(workspace_root, "reward")

    checks = {
        "pipeline_file_exists": False,
        "pipeline_structure_ok": False,
        "pipeline_counts_values_ok": False,
        "pipeline_grand_totals_ok": False,
        "followups_file_exists": False,
        "followups_header_ok": False,
        "followups_lines_match_set": False,
        "followups_sorted": False,
        "tags_file_exists": False,
        "tags_header_ok": False,
        "tags_rows_ok": False
    }

    # Default reward is 0.0 (no-op baseline)
    try:
        expected = build_expected(workspace_root)
    except Exception:
        # If inputs are unreadable, we cannot compute expectations; keep reward 0
        expected = None

    # 1) pipeline_report.json
    pipeline_path = os.path.join(output_dir, "pipeline_report.json")
    if os.path.isfile(pipeline_path):
        checks["pipeline_file_exists"] = True
        try:
            with open(pipeline_path, "r", encoding="utf-8") as f:
                pipeline_out = json.load(f)
            # Structure: stages (exact six), counts numeric, total_value numeric, grand totals
            stages_required = ["prospect", "qualified", "proposal", "negotiation", "closed-won", "closed-lost"]
            structure_ok = isinstance(pipeline_out, dict) and "stages" in pipeline_out and isinstance(pipeline_out["stages"], dict)
            if structure_ok:
                out_stages_keys = sorted(list(pipeline_out["stages"].keys()))
                structure_ok = (out_stages_keys == sorted(stages_required))
            if structure_ok:
                # validate numeric types and presence
                for s in stages_required:
                    v = pipeline_out["stages"].get(s, {})
                    if not isinstance(v, dict):
                        structure_ok = False
                        break
                    if "count" not in v or "total_value" not in v:
                        structure_ok = False
                        break
                    # ensure numbers
                    if not isinstance(v["count"], (int, float)) or not isinstance(v["total_value"], (int, float)):
                        structure_ok = False
                        break
                if "grand_total_count" not in pipeline_out or "grand_total_value" not in pipeline_out:
                    structure_ok = False
                else:
                    if not isinstance(pipeline_out["grand_total_count"], (int, float)) or not isinstance(pipeline_out["grand_total_value"], (int, float)):
                        structure_ok = False
            checks["pipeline_structure_ok"] = bool(structure_ok)
            if expected and structure_ok:
                # compare per-stage counts and totals
                per_ok = True
                for s in stages_required:
                    exp_c = expected["pipeline"]["stages"][s]["count"]
                    exp_v = expected["pipeline"]["stages"][s]["total_value"]
                    got_c = pipeline_out["stages"][s]["count"]
                    got_v = pipeline_out["stages"][s]["total_value"]
                    if not (int(got_c) == int(exp_c) and float_eq(got_v, exp_v)):
                        per_ok = False
                        break
                checks["pipeline_counts_values_ok"] = per_ok
                # compare grand totals equal to sums across stages and equal to expected
                gt_ok = False
                if per_ok:
                    # compute sums from out
                    sum_c = sum(int(pipeline_out["stages"][s]["count"]) for s in stages_required)
                    sum_v = sum(float(pipeline_out["stages"][s]["total_value"]) for s in stages_required)
                    gt_ok = (int(pipeline_out["grand_total_count"]) == int(sum_c)) and float_eq(pipeline_out["grand_total_value"], sum_v) \
                            and (int(pipeline_out["grand_total_count"]) == int(expected["pipeline"]["grand_total_count"])) \
                            and float_eq(pipeline_out["grand_total_value"], expected["pipeline"]["grand_total_value"])
                checks["pipeline_grand_totals_ok"] = gt_ok
        except Exception:
            # leave checks as is
            pass

    # 2) followups_due_7d.md
    followups_path = os.path.join(output_dir, "followups_due_7d.md")
    if os.path.isfile(followups_path):
        checks["followups_file_exists"] = True
        try:
            with open(followups_path, "r", encoding="utf-8") as f:
                lines = [ln.rstrip("\n").strip() for ln in f.readlines()]
            # Need at least 2 lines (header + columns header)
            header_ok = False
            if expected:
                header1 = expected["followups"]["header1"]
                header2 = expected["followups"]["header2"]
                if len(lines) >= 2 and lines[0] == header1 and lines[1] == header2:
                    header_ok = True
            checks["followups_header_ok"] = header_ok
            if expected and header_ok:
                body_lines = lines[2:] if len(lines) > 2 else []
                # Compare set equality with expected lines
                exp_set = set(expected["followups"]["lines"])
                out_set = set([ln for ln in body_lines if ln != ""])
                checks["followups_lines_match_set"] = (exp_set == out_set)
                # Check sorted by due date ascending
                def extract_date(ln):
                    # Expected format: YYYY-MM-DD | Deal Title | Contact Name | Note
                    # Take first 10 chars
                    if len(ln) >= 10:
                        dstr = ln[:10]
                        try:
                            return datetime.strptime(dstr, "%Y-%m-%d").date()
                        except Exception:
                            return date.min
                    return date.min
                sorted_ok = True
                prev = None
                for ln in body_lines:
                    d = extract_date(ln)
                    if prev is not None and d < prev:
                        sorted_ok = False
                        break
                    prev = d
                checks["followups_sorted"] = sorted_ok
        except Exception:
            pass

    # 3) deal_tags.csv
    tags_path = os.path.join(output_dir, "deal_tags.csv")
    if os.path.isfile(tags_path):
        checks["tags_file_exists"] = True
        try:
            with open(tags_path, "r", encoding="utf-8") as f:
                reader = csv.reader(f)
                rows = list(reader)
            header_ok = False
            if rows:
                hdr = [h.strip() for h in rows[0]]
                header_ok = (len(hdr) >= 2 and hdr[0] == "title" and hdr[1] == "tags")
            checks["tags_header_ok"] = header_ok
            if header_ok and expected:
                out_map = {}
                for r in rows[1:]:
                    if not r:
                        continue
                    title = (r[0] if len(r) > 0 else "").strip()
                    tags_val = (r[1] if len(r) > 1 else "").strip()
                    out_map[title] = tags_val
                exp_pairs = expected["tags"]
                # Verify titles set matches exactly and tags match
                titles_ok = set(out_map.keys()) == set([t for (t, _) in exp_pairs])
                tags_ok = titles_ok and all(out_map.get(t, None) == tg for (t, tg) in exp_pairs)
                checks["tags_rows_ok"] = bool(tags_ok)
        except Exception:
            pass

    # Aggregate reward
    pipeline_pass = checks["pipeline_file_exists"] and checks["pipeline_structure_ok"] and checks["pipeline_counts_values_ok"] and checks["pipeline_grand_totals_ok"]
    followups_pass = checks["followups_file_exists"] and checks["followups_header_ok"] and checks["followups_lines_match_set"] and checks["followups_sorted"]
    tags_pass = checks["tags_file_exists"] and checks["tags_header_ok"] and checks["tags_rows_ok"]

    total_pass = sum([1 if pipeline_pass else 0, 1 if followups_pass else 0, 1 if tags_pass else 0])
    reward = total_pass / 3.0

    result = {"reward": reward}
    result.update(checks)
    print(json.dumps(result))

if __name__ == "__main__":
    main()

