import sys
import json
import csv
import re
from html import unescape
from pathlib import Path
from typing import Optional, Tuple, List, Dict, Any


def _read_text_safe(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return None


def _load_json_safe(path: Path) -> Optional[Any]:
    try:
        return json.loads(path.read_text(encoding="utf-8", errors="replace"))
    except Exception:
        return None


def _load_csv_dicts_safe(path: Path) -> Tuple[Optional[List[Dict[str, str]]], Optional[List[str]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            rows = list(reader)
            return rows, reader.fieldnames
    except Exception:
        return None, None


def _normalize_whitespace(s: str) -> str:
    return re.sub(r"\s+", " ", s).strip()


def _html_to_text_normalized(html_content: str) -> str:
    # Remove script and style content
    content = re.sub(r"(?is)<(script|style)[^>]*>.*?</\1>", " ", html_content)
    # Remove all tags
    content = re.sub(r"(?is)<[^>]+>", " ", content)
    # Unescape HTML entities
    content = unescape(content)
    # Normalize whitespace and lower-case
    return _normalize_whitespace(content).lower()


def _string_normalized(s: str) -> str:
    return _normalize_whitespace(unescape(s)).lower()


def _approx_equal(a: float, b: float, tol: float = 1e-6) -> bool:
    return abs(a - b) <= tol


def _parse_config(workspace: Path) -> Tuple[Optional[List[str]], Optional[int]]:
    cfg_path = workspace / "input" / "config.json"
    cfg = _load_json_safe(cfg_path)
    if not isinstance(cfg, dict):
        return None, None
    selected = cfg.get("selected_tags")
    top_n = cfg.get("top_n")
    if not isinstance(selected, list) or not all(isinstance(t, str) for t in selected):
        return None, None
    if not isinstance(top_n, int) or top_n <= 0:
        return None, None
    return selected, top_n


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "raw_html_mdn_en_us": 0.0,
        "elements_all_json_valid": 0.0,
        "elements_all_summaries_in_html": 0.0,
        "filtered_csv_valid_and_consistent": 0.0,
        "stats_json_correct": 0.0,
        "topn_md_matches_stats": 0.0,
        "topn_stats_consistent_with_csv": 0.0,
    }

    # Paths
    raw_html_path = workspace / "output" / "raw" / "elements_reference.html"
    elements_json_path = workspace / "output" / "data" / "elements_all.json"
    filtered_csv_path = workspace / "output" / "data" / "elements_filtered.csv"
    stats_json_path = workspace / "output" / "reports" / "stats.json"
    topn_md_path = workspace / "output" / "reports" / "topN.md"

    # Config
    selected_tags, top_n = _parse_config(workspace)

    # Check raw HTML presence and MDN en-US characteristics
    raw_html_text = _read_text_safe(raw_html_path)
    if isinstance(raw_html_text, str):
        cond_domain = "developer.mozilla.org" in raw_html_text
        cond_locale = ('lang="en-US"' in raw_html_text) or ("/en-US/" in raw_html_text)
        cond_title = re.search(r"HTML elements reference", raw_html_text, flags=re.IGNORECASE) is not None
        if cond_domain and cond_locale and cond_title:
            scores["raw_html_mdn_en_us"] = 1.0

    # Load elements_all.json and validate structure
    elements_data = _load_json_safe(elements_json_path)
    elements_valid = False
    elements_list: List[Dict[str, Any]] = []
    tag_to_summary: Dict[str, str] = {}
    if isinstance(elements_data, list) and len(elements_data) > 0:
        ok = True
        for item in elements_data:
            if not isinstance(item, dict):
                ok = False
                break
            tag = item.get("tag")
            summary = item.get("summary")
            if not isinstance(tag, str) or not isinstance(summary, str):
                ok = False
                break
            if len(tag.strip()) == 0 or len(summary.strip()) == 0:
                ok = False
                break
            elements_list.append({"tag": tag, "summary": summary})
            tag_to_summary[tag] = summary
        if ok:
            elements_valid = True
            scores["elements_all_json_valid"] = 1.0

    # Cross-check that summaries appear in the raw HTML (derived from saved page)
    if elements_valid and isinstance(raw_html_text, str):
        html_norm = _html_to_text_normalized(raw_html_text)
        all_match = True
        for item in elements_list:
            summ_norm = _string_normalized(item["summary"])
            if summ_norm and summ_norm not in html_norm:
                all_match = False
                break
        if all_match:
            scores["elements_all_summaries_in_html"] = 1.0

    # Validate filtered CSV against config and elements_all.json
    filtered_rows, filtered_headers = _load_csv_dicts_safe(filtered_csv_path)
    csv_ok = False
    if elements_valid and isinstance(filtered_rows, list) and isinstance(filtered_headers, list) and selected_tags is not None:
        # Check exact headers order and names
        if filtered_headers == ["tag", "summary_length"]:
            # Build expected tag set (intersection)
            present_selected = [t for t in selected_tags if t in tag_to_summary]
            expected_set = set(present_selected)
            # Parse CSV content
            csv_set = set()
            ok_rows = True
            for row in filtered_rows:
                if set(row.keys()) != set(filtered_headers):
                    ok_rows = False
                    break
                tag = row.get("tag")
                slen_str = row.get("summary_length")
                if not isinstance(tag, str) or tag not in selected_tags:
                    ok_rows = False
                    break
                try:
                    slen_val = int(slen_str)
                except Exception:
                    ok_rows = False
                    break
                # Must match summary length from elements_all.json for this tag
                if tag not in tag_to_summary:
                    ok_rows = False
                    break
                expected_len = len(tag_to_summary[tag])
                if slen_val != expected_len:
                    ok_rows = False
                    break
                csv_set.add(tag)
            if ok_rows and csv_set == expected_set:
                csv_ok = True
                scores["filtered_csv_valid_and_consistent"] = 1.0

    # Validate stats.json correctness against recomputation
    stats = _load_json_safe(stats_json_path)
    stats_ok = False
    if elements_valid and isinstance(stats, dict) and selected_tags is not None and isinstance(top_n, int):
        # Compute expected metrics
        # total_elements
        total_elements_exp = len(elements_list)
        # counts_by_initial_letter
        counts_exp: Dict[str, int] = {}
        for item in elements_list:
            tag = item["tag"]
            if not tag:
                continue
            initial = tag[0].lower()
            counts_exp[initial] = counts_exp.get(initial, 0) + 1
        # average_summary_length_all
        lengths = [len(item["summary"]) for item in elements_list]
        avg_len_exp = (sum(lengths) / len(lengths)) if lengths else 0.0
        # filtered block
        present_tags = [t for t in selected_tags if t in tag_to_summary]
        total_filtered_exp = len(present_tags)
        coverage_rate_exp = (total_filtered_exp / len(selected_tags)) if selected_tags else 0.0
        missing_exp = [t for t in selected_tags if t not in tag_to_summary]
        # top_n_by_summary_length among present_tags
        tagged_lengths = [{"tag": t, "summary_length": len(tag_to_summary[t])} for t in present_tags]
        tagged_lengths_sorted = sorted(tagged_lengths, key=lambda x: (-x["summary_length"], x["tag"]))
        topn_exp = tagged_lengths_sorted[:top_n]

        # Extract stats fields
        try:
            total_elements_act = stats.get("total_elements")
            counts_act = stats.get("counts_by_initial_letter")
            avg_len_act = stats.get("average_summary_length_all")
            filtered_act = stats.get("filtered")
            ok = True
            if not isinstance(total_elements_act, int) or total_elements_act != total_elements_exp:
                ok = False
            if not isinstance(counts_act, dict) or {str(k): int(v) for k, v in counts_act.items()} != {k: v for k, v in counts_exp.items()}:
                ok = False
            if not (isinstance(avg_len_act, (int, float)) and _approx_equal(float(avg_len_act), float(avg_len_exp))):
                ok = False
            if not isinstance(filtered_act, dict):
                ok = False
            else:
                tf_act = filtered_act.get("total_filtered")
                cr_act = filtered_act.get("coverage_rate")
                miss_act = filtered_act.get("missing_selected_tags")
                topn_act = filtered_act.get("top_n_by_summary_length")
                if not isinstance(tf_act, int) or tf_act != total_filtered_exp:
                    ok = False
                if not isinstance(cr_act, (int, float)) or not _approx_equal(float(cr_act), float(coverage_rate_exp)):
                    ok = False
                if not isinstance(miss_act, list) or set(miss_act) != set(missing_exp):
                    ok = False
                if not isinstance(topn_act, list):
                    ok = False
                else:
                    # Require exact length equal to top_n from config
                    if len(topn_act) != len(topn_exp):
                        ok = False
                    else:
                        # Compare list of dicts
                        for exp_item, act_item in zip(topn_exp, topn_act):
                            if not isinstance(act_item, dict):
                                ok = False
                                break
                            if act_item.get("tag") != exp_item.get("tag"):
                                ok = False
                                break
                            if act_item.get("summary_length") != exp_item.get("summary_length"):
                                ok = False
                                break
            if ok:
                stats_ok = True
                scores["stats_json_correct"] = 1.0
        except Exception:
            stats_ok = False

    # Validate topN.md corresponds to stats.filtered.top_n_by_summary_length
    if stats_ok:
        md_text = _read_text_safe(topn_md_path)
        filtered_block = stats.get("filtered", {}) if isinstance(stats, dict) else {}
        topn_list = filtered_block.get("top_n_by_summary_length") if isinstance(filtered_block, dict) else None
        if isinstance(md_text, str) and isinstance(topn_list, list):
            lines = md_text.splitlines()
            # Build expected sequence of (rank, tag, summary_length)
            expected_seq = []
            for idx, item in enumerate(topn_list, start=1):
                if isinstance(item, dict) and "tag" in item and "summary_length" in item:
                    expected_seq.append((idx, str(item["tag"]), int(item["summary_length"])))
                else:
                    expected_seq = []
                    break
            if expected_seq:
                ok = True
                line_index = 0
                for rank, tag, slen in expected_seq:
                    # Find next line starting with the rank and containing tag and slen
                    found = False
                    rank_pattern = re.compile(rf"^\s*{rank}[\.\)]?\s*")
                    tag_pattern = re.compile(rf"\b{re.escape(tag)}\b")
                    slen_pattern = re.compile(rf"\b{slen}\b")
                    while line_index < len(lines):
                        line = lines[line_index]
                        line_index += 1
                        if rank_pattern.search(line):
                            # Check same line contains tag and slen
                            if tag_pattern.search(line) and slen_pattern.search(line):
                                found = True
                                break
                            else:
                                # If rank matched but not tag/length, fail
                                found = False
                                break
                    if not found:
                        ok = False
                        break
                if ok:
                    scores["topn_md_matches_stats"] = 1.0

    # Validate that stats.top_n_by_summary_length is consistent with filtered CSV
    if stats_ok and csv_ok:
        filtered_block = stats.get("filtered", {}) if isinstance(stats, dict) else {}
        topn_list = filtered_block.get("top_n_by_summary_length") if isinstance(filtered_block, dict) else None
        if isinstance(topn_list, list):
            # Compute ranking from CSV
            try:
                csv_items = []
                for row in filtered_rows:  # type: ignore
                    tag = row["tag"]
                    slen = int(row["summary_length"])
                    csv_items.append({"tag": tag, "summary_length": slen})
                csv_sorted = sorted(csv_items, key=lambda x: (-x["summary_length"], x["tag"]))
                csv_topn = csv_sorted[:top_n]  # type: ignore
                # Compare to stats topn_list
                ok = True
                if len(csv_topn) != len(topn_list):
                    ok = False
                else:
                    for exp_item, act_item in zip(csv_topn, topn_list):
                        if not isinstance(act_item, dict):
                            ok = False
                            break
                        if act_item.get("tag") != exp_item.get("tag") or act_item.get("summary_length") != exp_item.get("summary_length"):
                            ok = False
                            break
                if ok:
                    scores["topn_stats_consistent_with_csv"] = 1.0
            except Exception:
                pass

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

import sys
import json
import csv
import re
from pathlib import Path
from typing import List, Dict, Tuple, Optional, Set


def _read_csv_dicts(path: Path) -> Optional[List[Dict[str, str]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            return list(reader)
    except Exception:
        return None


def _read_text_lines(path: Path) -> Optional[List[str]]:
    try:
        with path.open("r", encoding="utf-8") as f:
            return f.read().splitlines()
    except Exception:
        return None


def _to_int(val: str) -> Optional[int]:
    try:
        return int(str(val).strip())
    except Exception:
        return None


def _to_float(val: str) -> Optional[float]:
    try:
        return float(str(val).strip())
    except Exception:
        return None


def _float_close(a: float, b: float, tol: float = 1e-6) -> bool:
    return abs(a - b) <= tol


def _parse_error_log(lines: List[str]) -> Tuple[Set[int], Dict[str, Dict[str, object]]]:
    excluded_ids: Set[int] = set()
    # error_summary_map: error_type -> {"count": int, "ids": set[int]}
    error_summary_map: Dict[str, Dict[str, object]] = {}
    for line in lines:
        # Consider lines that contain the ERROR level token
        if not re.search(r"\bERROR\b", line):
            continue
        # Extract player_id
        m = re.search(r"player_id=(\d+)", line)
        if not m:
            continue
        pid = int(m.group(1))
        excluded_ids.add(pid)
        # Tokenize by whitespace to get token right after player_id=...
        tokens = line.strip().split()
        error_type = None
        for i, tok in enumerate(tokens):
            if tok.startswith("player_id=") and i + 1 < len(tokens):
                error_type = tokens[i + 1]
                break
        if error_type is None:
            # Fallback: if not found via tokenization, try regex for trailing word
            tail = line[line.find(m.group(0)) + len(m.group(0)) :].strip()
            parts = tail.split()
            if parts:
                error_type = parts[0]
        if error_type is None:
            continue
        if error_type not in error_summary_map:
            error_summary_map[error_type] = {"count": 0, "ids": set()}
        error_summary_map[error_type]["count"] = int(error_summary_map[error_type]["count"]) + 1
        error_summary_map[error_type]["ids"].add(pid)
    return excluded_ids, error_summary_map


def _compute_expected(workspace: Path) -> Tuple[Optional[List[Dict[str, object]]], Optional[Dict[str, Dict[str, object]]], Optional[Set[int]]]:
    # Load inputs
    players_path = workspace / "input" / "players.csv"
    fitness_path = workspace / "input" / "fitness_tests.csv"
    attendance_path = workspace / "input" / "attendance.csv"
    log_path = workspace / "logs" / "hr_import_output.txt"

    players_rows = _read_csv_dicts(players_path)
    fitness_rows = _read_csv_dicts(fitness_path)
    attendance_rows = _read_csv_dicts(attendance_path)
    log_lines = _read_text_lines(log_path)

    if players_rows is None or fitness_rows is None or attendance_rows is None or log_lines is None:
        return None, None, None

    excluded_ids, error_summary_map = _parse_error_log(log_lines)

    # Age filter (14 to 16 inclusive)
    eligible_players: Dict[int, Dict[str, object]] = {}
    for row in players_rows:
        pid = _to_int(row.get("player_id", ""))
        age = _to_int(row.get("age", ""))
        name = row.get("name", "")
        if pid is None or age is None:
            continue
        if 14 <= age <= 16:
            eligible_players[pid] = {"player_id": pid, "name": name, "age": age}

    # Exclude ERROR player_ids
    for pid in list(eligible_players.keys()):
        if pid in excluded_ids:
            eligible_players.pop(pid, None)

    # Build fitness and attendance maps
    fit_map: Dict[int, Dict[str, float]] = {}
    for row in fitness_rows:
        pid = _to_int(row.get("player_id", ""))
        beep = _to_float(row.get("beep_level", ""))
        sprint = _to_float(row.get("sprint_40m_sec", ""))
        if pid is None or beep is None or sprint is None:
            continue
        fit_map[pid] = {"beep_level": beep, "sprint_40m_sec": sprint}

    att_map: Dict[int, Dict[str, float]] = {}
    for row in attendance_rows:
        pid = _to_int(row.get("player_id", ""))
        attended = _to_float(row.get("sessions_attended", ""))
        total = _to_float(row.get("sessions_total", ""))
        if pid is None or attended is None or total is None:
            continue
        att_map[pid] = {"sessions_attended": attended, "sessions_total": total}

    # Join and compute metrics
    cohort: List[Dict[str, object]] = []
    for pid, pdata in eligible_players.items():
        if pid not in fit_map or pid not in att_map:
            continue
        beep = float(fit_map[pid]["beep_level"])
        sprint = float(fit_map[pid]["sprint_40m_sec"])
        attended = float(att_map[pid]["sessions_attended"])
        total = float(att_map[pid]["sessions_total"])
        attendance_rate = (attended / total) if total != 0 else 0.0
        cohort.append({
            "player_id": pid,
            "name": pdata["name"],
            "age": pdata["age"],
            "beep_level": beep,
            "sprint_40m_sec": sprint,
            "attendance_rate": attendance_rate
        })

    if not cohort:
        # No eligible data
        return [], error_summary_map, excluded_ids

    # Normalization ranges over cohort
    beeps = [c["beep_level"] for c in cohort]  # type: ignore
    sprints = [c["sprint_40m_sec"] for c in cohort]  # type: ignore
    min_beep = min(beeps)
    max_beep = max(beeps)
    min_sprint = min(sprints)
    max_sprint = max(sprints)
    beep_range = max_beep - min_beep
    sprint_range = max_sprint - min_sprint

    for c in cohort:
        nb = ((c["beep_level"] - min_beep) / beep_range) if beep_range != 0 else 0.0  # type: ignore
        ns = ((max_sprint - c["sprint_40m_sec"]) / sprint_range) if sprint_range != 0 else 0.0  # type: ignore
        comp = 0.45 * nb + 0.35 * ns + 0.20 * c["attendance_rate"]  # type: ignore
        c["normalized_beep"] = nb
        c["normalized_speed"] = ns
        c["composite_score"] = comp

    # Sort per requirements:
    # - composite_score desc
    # - tie-breakers: faster sprint (asc), then higher attendance_rate, then higher beep_level, then alphabetical by name
    cohort_sorted = sorted(
        cohort,
        key=lambda c: (
            -c["composite_score"],  # type: ignore
            c["sprint_40m_sec"],    # type: ignore
            -c["attendance_rate"],  # type: ignore
            -c["beep_level"],       # type: ignore
            str(c["name"])
        )
    )
    top5 = cohort_sorted[:5]

    expected_top_rows: List[Dict[str, object]] = []
    for c in top5:
        expected_top_rows.append({
            "player_id": c["player_id"],
            "name": c["name"],
            "age": c["age"],
            "attendance_rate": c["attendance_rate"],
            "beep_level": c["beep_level"],
            "sprint_40m_sec": c["sprint_40m_sec"],
            "composite_score": c["composite_score"]
        })

    return expected_top_rows, error_summary_map, excluded_ids


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)

    scores = {
        "top_u16_prospects_structure": 0.0,
        "top_u16_prospects_content": 0.0,
        "ranking_order_strict": 0.0,
        "error_summary_structure": 0.0,
        "error_summary_content": 0.0,
        "exclusion_applied_in_prospects": 0.0,
        "age_filter_applied_in_prospects": 0.0,
    }

    expected_top, expected_error_summary_map, excluded_ids = _compute_expected(workspace)

    # Paths to outputs
    top_path = workspace / "output" / "top_u16_prospects.csv"
    err_path = workspace / "output" / "error_summary.csv"

    # Read actual top prospects file
    actual_top_rows = _read_csv_dicts(top_path)
    header_expected_top = ["player_id", "name", "age", "attendance_rate", "beep_level", "sprint_40m_sec", "composite_score"]

    # Structure check for top_u16_prospects.csv
    if actual_top_rows is not None:
        try:
            with top_path.open("r", encoding="utf-8", newline="") as f:
                reader = csv.reader(f)
                header = next(reader, None)
        except Exception:
            header = None
        if header == header_expected_top and expected_top is not None:
            # Row count must match expected (min(5, eligible))
            if len(actual_top_rows) == len(expected_top):
                scores["top_u16_prospects_structure"] = 1.0

    # Content check for top_u16_prospects.csv
    if scores["top_u16_prospects_structure"] == 1.0 and actual_top_rows is not None and expected_top is not None:
        content_ok = True
        # Compare row by row
        for idx, (act, exp) in enumerate(zip(actual_top_rows, expected_top)):
            # player_id
            act_pid = _to_int(act.get("player_id", ""))
            exp_pid = int(exp["player_id"])
            if act_pid != exp_pid:
                content_ok = False
                break
            # name
            act_name = (act.get("name", "") or "").strip()
            if act_name != str(exp["name"]):
                content_ok = False
                break
            # age
            act_age = _to_int(act.get("age", ""))
            if act_age != int(exp["age"]):
                content_ok = False
                break
            # attendance_rate
            act_att = _to_float(act.get("attendance_rate", ""))
            if act_att is None or not _float_close(act_att, float(exp["attendance_rate"]), tol=1e-3):
                content_ok = False
                break
            # beep_level
            act_beep = _to_float(act.get("beep_level", ""))
            if act_beep is None or not _float_close(act_beep, float(exp["beep_level"]), tol=1e-6):
                content_ok = False
                break
            # sprint_40m_sec
            act_sprint = _to_float(act.get("sprint_40m_sec", ""))
            if act_sprint is None or not _float_close(act_sprint, float(exp["sprint_40m_sec"]), tol=1e-6):
                content_ok = False
                break
            # composite_score
            act_comp = _to_float(act.get("composite_score", ""))
            if act_comp is None or not _float_close(act_comp, float(exp["composite_score"]), tol=1e-3):
                content_ok = False
                break
        if content_ok and len(actual_top_rows) == len(expected_top):
            scores["top_u16_prospects_content"] = 1.0

    # ranking_order_strict (internal consistency with tie-breakers based on provided values)
    if actual_top_rows is not None:
        # Check header
        try:
            with top_path.open("r", encoding="utf-8", newline="") as f:
                reader = csv.DictReader(f)
                if reader.fieldnames == header_expected_top:
                    act_rows_typed = []
                    parse_ok = True
                    for r in actual_top_rows:
                        pid = _to_int(r.get("player_id", ""))
                        name = (r.get("name", "") or "").strip()
                        age = _to_int(r.get("age", ""))
                        att = _to_float(r.get("attendance_rate", ""))
                        beep = _to_float(r.get("beep_level", ""))
                        sprint = _to_float(r.get("sprint_40m_sec", ""))
                        comp = _to_float(r.get("composite_score", ""))
                        if None in (pid, age, att, beep, sprint, comp):
                            parse_ok = False
                            break
                        act_rows_typed.append({
                            "player_id": pid,
                            "name": name,
                            "age": age,
                            "attendance_rate": att,
                            "beep_level": beep,
                            "sprint_40m_sec": sprint,
                            "composite_score": comp
                        })
                    if parse_ok:
                        # Compute sorted order according to criteria
                        sorted_rows = sorted(
                            act_rows_typed,
                            key=lambda c: (
                                -c["composite_score"],
                                c["sprint_40m_sec"],
                                -c["attendance_rate"],
                                -c["beep_level"],
                                str(c["name"])
                            )
                        )
                        # Compare sequence equality
                        same_order = True
                        for i in range(len(act_rows_typed)):
                            a = act_rows_typed[i]
                            b = sorted_rows[i]
                            if not (
                                a["player_id"] == b["player_id"]
                                and a["name"] == b["name"]
                                and a["age"] == b["age"]
                                and _float_close(a["attendance_rate"], b["attendance_rate"], tol=1e-6)
                                and _float_close(a["beep_level"], b["beep_level"], tol=1e-6)
                                and _float_close(a["sprint_40m_sec"], b["sprint_40m_sec"], tol=1e-6)
                                and _float_close(a["composite_score"], b["composite_score"], tol=1e-6)
                            ):
                                same_order = False
                                break
                        if same_order:
                            scores["ranking_order_strict"] = 1.0
        except Exception:
            pass

    # error_summary_structure
    error_rows = _read_csv_dicts(err_path)
    header_expected_err = ["error_type", "count", "player_ids"]
    if error_rows is not None:
        try:
            with err_path.open("r", encoding="utf-8", newline="") as f:
                reader = csv.reader(f)
                header = next(reader, None)
        except Exception:
            header = None
        # Check header and that each row has valid count int and player_ids parseable
        if header == header_expected_err:
            structure_ok = True
            for r in error_rows:
                et = (r.get("error_type", "") or "").strip()
                if et == "":
                    structure_ok = False
                    break
                cnt = _to_int(r.get("count", ""))
                if cnt is None or cnt < 0:
                    structure_ok = False
                    break
                # player_ids can be empty string if no IDs? In our case errors have ids, but allow empty == no ids
                pids_str = (r.get("player_ids", "") or "").strip()
                if pids_str != "":
                    parts = pids_str.split(";")
                    # ensure all ints parse
                    for p in parts:
                        if _to_int(p) is None:
                            structure_ok = False
                            break
                    if not structure_ok:
                        break
            if structure_ok:
                scores["error_summary_structure"] = 1.0

    # error_summary_content
    if error_rows is not None and expected_error_summary_map is not None:
        # Build actual map
        actual_map: Dict[str, Dict[str, object]] = {}
        for r in error_rows:
            et = (r.get("error_type", "") or "").strip()
            cnt = _to_int(r.get("count", ""))
            pids_str = (r.get("player_ids", "") or "").strip()
            if et == "" or cnt is None or cnt < 0:
                actual_map = {}
                break
            if pids_str == "":
                pid_list: List[int] = []
            else:
                parts = [p for p in pids_str.split(";") if p != ""]
                pid_list = []
                parse_ok = True
                for p in parts:
                    vi = _to_int(p)
                    if vi is None:
                        parse_ok = False
                        break
                    pid_list.append(vi)
                if not parse_ok:
                    actual_map = {}
                    break
            actual_map[et] = {"count": cnt, "player_ids": pid_list}
        content_ok = True
        # Compare sets of error types
        exp_types = set(expected_error_summary_map.keys())
        act_types = set(actual_map.keys())
        if exp_types != act_types:
            content_ok = False
        else:
            # For each type compare count and player_ids unique ascending
            for et in exp_types:
                exp_count = int(expected_error_summary_map[et]["count"])  # type: ignore
                exp_ids_sorted = sorted(list(expected_error_summary_map[et]["ids"]))  # type: ignore
                act_entry = actual_map.get(et, None)
                if act_entry is None:
                    content_ok = False
                    break
                act_count = int(act_entry["count"])  # type: ignore
                act_ids_list = list(act_entry["player_ids"])  # type: ignore
                # counts must equal
                if act_count != exp_count:
                    content_ok = False
                    break
                # player_ids must be unique and equal set to expected
                if sorted(set(act_ids_list)) != exp_ids_sorted:
                    content_ok = False
                    break
                # Must be in ascending numeric order in the CSV output
                if act_ids_list != sorted(act_ids_list):
                    content_ok = False
                    break
        if content_ok:
            scores["error_summary_content"] = 1.0

    # exclusion_applied_in_prospects
    if actual_top_rows is not None and excluded_ids is not None:
        excl_ok = True
        for r in actual_top_rows:
            pid = _to_int(r.get("player_id", ""))
            if pid is None:
                excl_ok = False
                break
            if pid in excluded_ids:
                excl_ok = False
                break
        if excl_ok:
            scores["exclusion_applied_in_prospects"] = 1.0

    # age_filter_applied_in_prospects
    if actual_top_rows is not None:
        ages_ok = True
        for r in actual_top_rows:
            age = _to_int(r.get("age", ""))
            if age is None or not (14 <= age <= 16):
                ages_ok = False
                break
        if ages_ok:
            scores["age_filter_applied_in_prospects"] = 1.0

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

