                if lg.get("end_date"):
                    tokens.append(lg["end_date"])
                for t in tokens:
                    if t and t in eo_sec:
                        ref_count += 1
                eo_ok = enough_bullets and (ref_count >= 2)
            scores["final_module_expected_outcomes_updated"] = 1.0 if eo_ok else 0.0

    return scores


