import json
import sys
import csv
import re
from pathlib import Path
from typing import List, Dict, Any, Optional


def _read_text_lines(path: Path) -> Optional[List[str]]:
    try:
        return path.read_text(encoding="utf-8").splitlines()
    except Exception:
        return None


def _load_json(path: Path) -> Optional[Any]:
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _read_csv_dicts(path: Path) -> Optional[List[Dict[str, str]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            if reader.fieldnames is None:
                return None
            rows = [dict(row) for row in reader]
            return rows
    except Exception:
        return None


def _parse_roster(roster_path: Path) -> Optional[Dict[str, Dict[str, str]]]:
    rows = _read_csv_dicts(roster_path)
    if rows is None:
        return None
    roster = {}
    for r in rows:
        name = r.get("name")
        email = r.get("email")
        role = r.get("role")
        if name is None or email is None or role is None:
            return None
        roster[name] = {"email": email, "role": role}
    return roster


def _parse_agenda(agenda_lines: List[str]) -> Dict[str, Any]:
    # Extract meeting name (from first line starting with "# ")
    meeting_name = None
    date_str = None
    # Extract "Agenda" bullet lines
    agenda_bullets: List[str] = []
    in_agenda = False
    action_items: List[Dict[str, str]] = []
    action_re = re.compile(
        r'\[ACTION\]\s*(.*?)\s*\(assignee:\s*([^;]+);\s*due:\s*([0-9]{4}-[0-9]{2}-[0-9]{2})\)',
        re.IGNORECASE,
    )
    for line in agenda_lines:
        if meeting_name is None and line.lstrip().startswith("# "):
            meeting_name = line.lstrip()[2:].strip()
        if date_str is None:
            m = re.match(r'\s*Date:\s*([0-9]{4}-[0-9]{2}-[0-9]{2})\s*$', line)
            if m:
                date_str = m.group(1)
        if not in_agenda and line.strip() == "Agenda":
            in_agenda = True
            continue
        if in_agenda:
            # Collect all agenda bullet lines as-is (preserve indentation)
            if line.startswith("- ") or line.startswith("  - "):
                agenda_bullets.append(line.rstrip())
                # Parse ACTION items
                if "[ACTION]" in line:
                    m2 = action_re.search(line)
                    if m2:
                        task = m2.group(1).strip()
                        assignee = m2.group(2).strip()
                        due = m2.group(3).strip()
                        action_items.append(
                            {"task": task, "assignee": assignee, "due_date": due, "source": "agenda",
                             "origin_file": "input/agendas/next_meeting_agenda.md"}
                        )
            else:
                # Stop if we encounter a non-bullet after Agenda start (defensive)
                # In provided input, agenda continues to EOF; but keep permissive.
                pass
    return {
        "meeting_name": meeting_name,
        "date": date_str,
        "agenda_bullets": agenda_bullets,
        "agenda_actions": action_items,
    }


def _parse_notes_actions(notes_lines: List[str]) -> List[Dict[str, Any]]:
    # Find all lines with checkbox pattern anywhere in file
    # Pattern: - [ ] Task (Assignee: Name, due: YYYY-MM-DD)
    pattern = re.compile(
        r'- \[( |x)\]\s*(.*?)\s*\(Assignee:\s*([^,]+),\s*due:\s*([0-9]{4}-[0-9]{2}-[0-9]{2})\)',
        re.IGNORECASE,
    )
    items: List[Dict[str, Any]] = []
    for line in notes_lines:
        m = pattern.search(line)
        if m:
            checked_char = m.group(1)
            task = m.group(2).strip()
            assignee = m.group(3).strip()
            due = m.group(4).strip()
            status = "done" if checked_char.lower() == "x" else "open"
            items.append(
                {
                    "task": task,
                    "assignee": assignee,
                    "due_date": due,
                    "status": status,
                    "source": "last_meeting_notes",
                    "origin_file": "input/notes/last_meeting_notes.md",
                }
            )
    # Only unchecked (open) items are considered
    return [i for i in items if i["status"] == "open"]


def _parse_prior_commitments(prior_obj: Any) -> Optional[List[Dict[str, Any]]]:
    if not isinstance(prior_obj, list):
        return None
    items: List[Dict[str, Any]] = []
    for rec in prior_obj:
        if not isinstance(rec, dict):
            return None
        task = rec.get("task")
        assignee = rec.get("assignee")
        due = rec.get("due")
        status = rec.get("status")
        if None in (task, assignee, due, status):
            return None
        if status == "open":
            items.append(
                {
                    "task": str(task),
                    "assignee": str(assignee),
                    "due_date": str(due),
                    "source": "prior_commitments",
                    "origin_file": "input/committees/prior_commitments.json",
                }
            )
    return items


def _digit_lines_first_three(policy_lines: List[str]) -> List[str]:
    digit_lines = [ln.rstrip() for ln in policy_lines if any(ch.isdigit() for ch in ln)]
    return digit_lines[:3]


def _build_expected(workspace: Path) -> Optional[Dict[str, Any]]:
    # Paths
    agenda_path = workspace / "input" / "agendas" / "next_meeting_agenda.md"
    notes_path = workspace / "input" / "notes" / "last_meeting_notes.md"
    roster_path = workspace / "input" / "committees" / "volunteer_roster.csv"
    prior_path = workspace / "input" / "committees" / "prior_commitments.json"
    policy_path = workspace / "input" / "research" / "policy_brief.txt"

    # Read and parse all inputs
    agenda_lines = _read_text_lines(agenda_path)
    notes_lines = _read_text_lines(notes_path)
    roster = _parse_roster(roster_path)
    prior_obj = _load_json(prior_path)
    policy_lines = _read_text_lines(policy_path)

    if None in (agenda_lines, notes_lines, roster, prior_obj, policy_lines):
        return None

    agenda_info = _parse_agenda(agenda_lines)  # includes name, date, bullets, actions
    if agenda_info.get("meeting_name") is None or agenda_info.get("date") is None:
        return None
    meeting_title = f"{agenda_info['meeting_name']} ({agenda_info['date']})"

    notes_actions = _parse_notes_actions(notes_lines)
    prior_actions = _parse_prior_commitments(prior_obj)
    if prior_actions is None:
        return None

    # Annotate with roster info
    roster_matched: List[Dict[str, Any]] = []
    missing_contacts: List[Dict[str, Any]] = []

    def _attach_roster(items: List[Dict[str, Any]]):
        for item in items:
            name = item["assignee"]
            if name in roster:
                item_full = {
                    "source": item["source"],
                    "task": item["task"],
                    "assignee": name,
                    "email": roster[name]["email"],
                    "role": roster[name]["role"],
                    "due_date": item["due_date"],
                    "origin_file": item["origin_file"],
                }
                roster_matched.append(item_full)
            else:
                missing_contacts.append(
                    {
                        "assignee": name,
                        "task": item["task"],
                        "due_date": item["due_date"],
                        "source": item["source"],
                        "origin_file": item["origin_file"],
                    }
                )

    # Only open items from prior and unchecked from notes, and all [ACTION] from agenda
    _attach_roster(prior_actions)
    _attach_roster(notes_actions)
    _attach_roster(agenda_info["agenda_actions"])

    # Build grouped missing contacts JSON expected structure
    grouped_missing: Dict[str, List[Dict[str, str]]] = {}
    for it in missing_contacts:
        grouped_missing.setdefault(it["assignee"], []).append(
            {
                "task": it["task"],
                "due_date": it["due_date"],
                "source": it["source"],
                "origin_file": it["origin_file"],
            }
        )
    expected_missing_json = [{"assignee": k, "items": v} for k, v in grouped_missing.items()]
    # Ensure deterministic order for expected comparison
    expected_missing_json.sort(key=lambda x: x["assignee"])
    for entry in expected_missing_json:
        entry["items"].sort(key=lambda y: (y["source"], y["task"], y["due_date"], y["origin_file"]))

    # Context lines: first three lines with digits
    context_lines = _digit_lines_first_three(policy_lines)

    return {
        "meeting_title": meeting_title,
        "agenda_bullets": agenda_info["agenda_bullets"],
        "context_lines": context_lines,
        "roster_items": roster_matched,
        "missing_contacts": missing_contacts,
        "missing_contacts_grouped": expected_missing_json,
        "roster": roster,
    }


def _extract_minutes_sections(minutes_lines: List[str]) -> Dict[str, List[str]]:
    headers = [
        "Agenda:",
        "Context:",
        "Carryover Action Items (roster-matched):",
        "New Action Items from Agenda (roster-matched):",
        "Unassigned or Missing Contacts:",
    ]
    indices = {}
    for i, ln in enumerate(minutes_lines):
        if ln.strip() in headers:
            indices[ln.strip()] = i

    # Sort headers by their appearance in file
    ordered = [h for h in headers if h in indices]
    ordered_sorted = sorted(ordered, key=lambda h: indices[h])
    sections: Dict[str, List[str]] = {}
    for idx, header in enumerate(ordered_sorted):
        start = indices[header] + 1
        end = len(minutes_lines)
        if idx + 1 < len(ordered_sorted):
            end = indices[ordered_sorted[idx + 1]]
        content = [line.rstrip() for line in minutes_lines[start:end]]
        sections[header] = content
    return sections


def _first_nonempty_line(lines: List[str]) -> Optional[str]:
    for ln in lines:
        if ln.strip() != "":
            return ln.rstrip()
    return None


def _section_contains_line_with_substrings(section_lines: List[str], substrings: List[str]) -> bool:
    for ln in section_lines:
        if all(sub in ln for sub in substrings):
            return True
    return False


def _strip_blank_lines(lines: List[str]) -> List[str]:
    return [ln.rstrip() for ln in lines if ln.strip() != ""]


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "meeting_minutes_title_line": 0.0,
        "agenda_section_lines": 0.0,
        "context_section_lines": 0.0,
        "carryover_items_in_minutes": 0.0,
        "new_action_items_in_minutes": 0.0,
        "missing_contacts_in_minutes": 0.0,
        "action_items_csv_header": 0.0,
        "action_items_csv_rows": 0.0,
        "missing_contacts_json_structure": 0.0,
        "missing_contacts_json_contents": 0.0,
    }

    expected = _build_expected(workspace)
    # Paths to outputs
    minutes_path = workspace / "output" / "meeting_minutes_draft.md"
    csv_path = workspace / "output" / "action_items.csv"
    missing_json_path = workspace / "output" / "missing_contacts.json"

    minutes_lines = _read_text_lines(minutes_path)
    # Title line check
    if expected is not None and minutes_lines is not None:
        expected_title = expected["meeting_title"]
        got_title = _first_nonempty_line(minutes_lines)
        if got_title == expected_title:
            scores["meeting_minutes_title_line"] = 1.0

    # Agenda section lines check
    if expected is not None and minutes_lines is not None:
        sections = _extract_minutes_sections(minutes_lines)
        agenda_section = sections.get("Agenda:")
        if agenda_section is not None:
            expected_agenda = expected["agenda_bullets"]
            # Remove blank lines for comparison
            if _strip_blank_lines(agenda_section) == _strip_blank_lines(expected_agenda):
                scores["agenda_section_lines"] = 1.0

    # Context section lines check
    if expected is not None and minutes_lines is not None:
        sections = _extract_minutes_sections(minutes_lines)
        context_section = sections.get("Context:")
        if context_section is not None:
            if _strip_blank_lines(context_section) == _strip_blank_lines(expected["context_lines"]):
                scores["context_section_lines"] = 1.0

    # Carryover items in minutes check (from prior_commitments open + last_meeting_notes unchecked, roster-matched)
    if expected is not None and minutes_lines is not None:
        sections = _extract_minutes_sections(minutes_lines)
        carry_section = sections.get("Carryover Action Items (roster-matched):")
        if carry_section is not None:
            # Build expected carryover roster-matched items
            roster_items: List[Dict[str, Any]] = expected["roster_items"]
            expected_carry = [
                it for it in roster_items if it["source"] in ("prior_commitments", "last_meeting_notes")
            ]
            all_present = True
            for it in expected_carry:
                substrs = [it["assignee"], it["email"], it["role"], it["task"], it["due_date"], it["source"]]
                if not _section_contains_line_with_substrings(carry_section, substrs):
                    all_present = False
                    break
            # Ensure no non-roster names present (e.g., Casey Brooks)
            section_text = "\n".join(carry_section)
            no_disallowed = True
            for miss in expected["missing_contacts"]:
                if miss["assignee"] in section_text:
                    no_disallowed = False
                    break
            if all_present and no_disallowed:
                scores["carryover_items_in_minutes"] = 1.0

    # New action items from agenda (roster-matched)
    if expected is not None and minutes_lines is not None:
        sections = _extract_minutes_sections(minutes_lines)
        new_section = sections.get("New Action Items from Agenda (roster-matched):")
        if new_section is not None:
            roster_items: List[Dict[str, Any]] = expected["roster_items"]
            expected_new = [it for it in roster_items if it["source"] == "agenda"]
            all_present = True
            for it in expected_new:
                substrs = [it["assignee"], it["email"], it["role"], it["task"], it["due_date"], it["source"]]
                if not _section_contains_line_with_substrings(new_section, substrs):
                    all_present = False
                    break
            # Ensure no disallowed names (e.g., Casey Brooks) here
            section_text = "\n".join(new_section)
            no_disallowed = True
            for miss in expected["missing_contacts"]:
                if miss["assignee"] in section_text:
                    no_disallowed = False
                    break
            if all_present and no_disallowed:
                scores["new_action_items_in_minutes"] = 1.0

    # Missing contacts in minutes
    if expected is not None and minutes_lines is not None:
        sections = _extract_minutes_sections(minutes_lines)
        miss_section = sections.get("Unassigned or Missing Contacts:")
        if miss_section is not None:
            # Expected missing grouped items flattened
            expected_missing_flat = expected["missing_contacts"]
            all_present = True
            for it in expected_missing_flat:
                substrs = [it["assignee"], it["task"], it["due_date"], it["source"]]
                if not _section_contains_line_with_substrings(miss_section, substrs):
                    all_present = False
                    break
            # Ensure no roster-matched names appear here
            section_text = "\n".join(miss_section)
            roster_names = set(expected["roster"].keys())
            no_roster_names = not any(name in section_text for name in roster_names)
            if all_present and no_roster_names:
                scores["missing_contacts_in_minutes"] = 1.0

    # action_items.csv header and rows
    if expected is not None and csv_path.exists():
        try:
            with csv_path.open("r", encoding="utf-8", newline="") as f:
                reader = csv.reader(f)
                rows = list(reader)
        except Exception:
            rows = None
        if rows:
            header = rows[0]
            expected_header = ["source", "task", "assignee", "email", "role", "due_date", "origin_file"]
            if header == expected_header:
                scores["action_items_csv_header"] = 1.0
                # Compare rows ignoring order
                actual_rows = rows[1:]
                # Build expected rows
                exp_items: List[Dict[str, Any]] = expected["roster_items"]
                exp_rows = [
                    [it["source"], it["task"], it["assignee"], it["email"], it["role"], it["due_date"], it["origin_file"]]
                    for it in exp_items
                ]
                # Sort both lists deterministically
                def _sort_key(r):
                    return tuple(r)

                actual_sorted = sorted(actual_rows, key=_sort_key)
                expected_sorted = sorted(exp_rows, key=_sort_key)
                if actual_sorted == expected_sorted:
                    scores["action_items_csv_rows"] = 1.0

    # missing_contacts.json structure and contents
    if expected is not None and missing_json_path.exists():
        actual_json = _load_json(missing_json_path)
        # Structure check
        struct_ok = True
        if not isinstance(actual_json, list):
            struct_ok = False
        else:
            for entry in actual_json:
                if not isinstance(entry, dict):
                    struct_ok = False
                    break
                # Enforce exact keys
                if set(entry.keys()) != {"assignee", "items"}:
                    struct_ok = False
                    break
                if not isinstance(entry["assignee"], str):
                    struct_ok = False
                    break
                if not isinstance(entry["items"], list):
                    struct_ok = False
                    break
                for it in entry["items"]:
                    if not isinstance(it, dict):
                        struct_ok = False
                        break
                    if set(it.keys()) != {"task", "due_date", "source", "origin_file"}:
                        struct_ok = False
                        break
                if not struct_ok:
                    break
        if struct_ok:
            scores["missing_contacts_json_structure"] = 1.0
            # Contents check (order-insensitive)
            expected_entries = expected["missing_contacts_grouped"]
            # Normalize actual for comparison
            try:
                actual_norm = []
                for entry in actual_json:
                    items = list(entry["items"])
                    items_sorted = sorted(
                        items,
                        key=lambda y: (y.get("source"), y.get("task"), y.get("due_date"), y.get("origin_file")),
                    )
                    actual_norm.append({"assignee": entry["assignee"], "items": items_sorted})
                actual_norm.sort(key=lambda x: x["assignee"])
                if actual_norm == expected_entries:
                    scores["missing_contacts_json_contents"] = 1.0
            except Exception:
                pass

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

import sys
import json
import csv
import re
from pathlib import Path
from html.parser import HTMLParser
from email import policy
from email.parser import BytesParser


def read_text(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        try:
            return path.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            return ""


def load_csv_rows(path: Path):
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            headers = reader.fieldnames or []
            rows = list(reader)
            return headers, rows
    except Exception:
        return None, None


def write_json_stdout(obj: dict) -> None:
    print(json.dumps(obj, ensure_ascii=False))


def normalize_email(email: str) -> str:
    if email is None:
        return ""
    return email.strip().lower()


def split_races(value: str):
    if not value:
        return []
    parts = re.split(r"[;,/]", value)
    return [p.strip() for p in parts if p.strip()]


def normalize_races(value: str) -> str:
    items = split_races(value)
    return "; ".join(items)


class SignupsTableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_table = False
        self.in_thead = False
        self.in_tbody = False
        self.in_row = False
        self.in_cell = False
        self.current_cell_data = []
        self.current_row = []
        self.rows = []
        self.table_id_stack = []

    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)
        if tag == "table":
            self.table_id_stack.append(attrs_dict.get("id", ""))
            if attrs_dict.get("id") == "signups":
                self.in_table = True
        if self.in_table:
            if tag == "thead":
                self.in_thead = True
            elif tag == "tbody":
                self.in_tbody = True
            elif tag == "tr":
                self.in_row = True
                self.current_row = []
            elif tag in ("td", "th"):
                self.in_cell = True
                self.current_cell_data = []

    def handle_endtag(self, tag):
        if tag == "table":
            # Pop stack and exit signups table if applicable
            last_id = self.table_id_stack.pop() if self.table_id_stack else ""
            if last_id == "signups":
                self.in_table = False
        if self.in_table:
            if tag == "thead":
                self.in_thead = False
            elif tag == "tbody":
                self.in_tbody = False
            elif tag == "tr":
                if self.in_row and self.in_tbody and self.current_row:
                    self.rows.append([cell.strip() for cell in self.current_row])
                self.in_row = False
                self.current_row = []
            elif tag in ("td", "th"):
                if self.in_cell:
                    cell_text = "".join(self.current_cell_data).strip()
                    self.current_row.append(cell_text)
                    self.current_cell_data = []
                self.in_cell = False

    def handle_data(self, data):
        if self.in_table and self.in_row and self.in_cell:
            self.current_cell_data.append(data)


def parse_form_signups(path: Path):
    """
    Returns list of dicts with keys:
    full_name, email, self_identified_races, partner_races, availability, city, consent, message
    """
    if not path.exists():
        return []
    text = read_text(path)
    if not text:
        return []
    parser = SignupsTableParser()
    try:
        parser.feed(text)
    except Exception:
        return []
    records = []
    for row in parser.rows:
        # Expect 8 columns per spec
        if len(row) != 8:
            # Skip malformed rows strictly
            return []  # fail parsing if structure unexpected
        name, email, self_race, partner_race, availability, city, consent, message = row
        records.append({
            "full_name": name.strip(),
            "email": email.strip(),
            "self_identified_races": self_race.strip(),
            "partner_races": partner_race.strip(),
            "availability": availability.strip(),
            "city": city.strip(),
            "consent": consent.strip(),
            "message": message.strip(),
            "source": "form",
        })
    return records


def parse_eml_file(path: Path):
    try:
        with path.open("rb") as f:
            msg = BytesParser(policy=policy.default).parse(f)
    except Exception:
        return None
    subject = msg.get("Subject", "").strip()
    # Get body text
    body = ""
    if msg.is_multipart():
        for part in msg.walk():
            ctype = part.get_content_type()
            if ctype == "text/plain":
                try:
                    body = part.get_content().strip()
                    break
                except Exception:
                    try:
                        body = part.get_payload(decode=True).decode("utf-8", errors="ignore").strip()
                        break
                    except Exception:
                        continue
    else:
        try:
            body = msg.get_content().strip()
        except Exception:
            try:
                body = msg.get_payload(decode=True).decode("utf-8", errors="ignore").strip()
            except Exception:
                body = ""
    # Parse key-value lines
    fields = {
        "Name": "",
        "Email": "",
        "Self-Identified Race(s)": "",
        "Partner Race(s)": "",
        "Availability": "",
        "Consent": "",
        "Message": "",
    }
    for line in body.splitlines():
        if ":" in line:
            key, val = line.split(":", 1)
            key = key.strip()
            val = val.strip()
            # Match keys case-insensitively
            for canonical in list(fields.keys()):
                if key.lower() == canonical.lower():
                    fields[canonical] = val
                    break
    record = {
        "full_name": fields["Name"].strip(),
        "email": fields["Email"].strip(),
        "self_identified_races": fields["Self-Identified Race(s)"].strip(),
        "partner_races": fields["Partner Race(s)"].strip(),
        "availability": fields["Availability"].strip(),
        "city": "",  # emails don't include city by spec
        "consent": fields["Consent"].strip(),
        "message": fields["Message"].strip() if fields["Message"].strip() else "",
        "thread_subject": subject,
        "body": body,
        "source": "email",
    }
    return record


def parse_emails(dir_path: Path):
    if not dir_path.exists():
        return []
    records = []
    try:
        for p in sorted(dir_path.glob("*.eml")):
            rec = parse_eml_file(p)
            if rec:
                records.append(rec)
    except Exception:
        return []
    return records


def compute_expected(workspace: Path):
    # Parse inputs
    form_path = workspace / "input" / "signups.html"
    inbox_dir = workspace / "input" / "inbox"
    form_records = parse_form_signups(form_path)
    email_records = parse_emails(inbox_dir)

    # Counts
    total_form = len(form_records)
    total_emails_parsed = len(email_records)

    # Consent filtering (case-insensitive "yes")
    def is_yes(v: str):
        return isinstance(v, str) and v.strip().lower() == "yes"

    consenting_form = [r for r in form_records if is_yes(r.get("consent", ""))]
    consenting_email = [r for r in email_records if is_yes(r.get("consent", ""))]

    number_consenting = len(consenting_form) + len(consenting_email)

    # Missing race exclusions among consenting (self or partner empty after stripping)
    def has_both_races(r):
        return bool(r.get("self_identified_races", "").strip()) and bool(r.get("partner_races", "").strip())

    missing_race_exclusions = 0
    for r in consenting_form:
        if not has_both_races(r):
            missing_race_exclusions += 1
    for r in consenting_email:
        if not has_both_races(r):
            missing_race_exclusions += 1

    # Merge by email lowercase
    merged = {}
    sources = {}
    for r in consenting_form:
        if not has_both_races(r):
            continue
        key = normalize_email(r.get("email", ""))
        if not key:
            continue
        # Prepare normalized fields
        merged[key] = {
            "full_name": r.get("full_name", "").strip(),
            "email": r.get("email", "").strip(),
            "self_identified_races": normalize_races(r.get("self_identified_races", "")),
            "partner_races": normalize_races(r.get("partner_races", "")),
            "availability": r.get("availability", "").strip(),
            "city": r.get("city", "").strip(),
            "consent": r.get("consent", "").strip(),
            "thread_subject": "",
            "message_form": r.get("message", "").strip(),
            "message_email": None,
            "source": "form",
        }
        sources[key] = {"form": True, "email": False}
    for r in consenting_email:
        if not has_both_races(r):
            continue
        key = normalize_email(r.get("email", ""))
        if not key:
            continue
        if key in merged:
            # Update merged to reflect both sources
            merged[key]["source"] = "both"
            merged[key]["thread_subject"] = r.get("thread_subject", "").strip()
            merged[key]["message_email"] = r.get("message", "").strip() if r.get("message", "").strip() else ""
            # Prefer form demographics and availability if present; city already from form
            # Keep name from whichever present; default to existing
            if not merged[key].get("full_name"):
                merged[key]["full_name"] = r.get("full_name", "").strip()
        else:
            merged[key] = {
                "full_name": r.get("full_name", "").strip(),
                "email": r.get("email", "").strip(),
                "self_identified_races": normalize_races(r.get("self_identified_races", "")),
                "partner_races": normalize_races(r.get("partner_races", "")),
                "availability": r.get("availability", "").strip(),
                "city": "",
                "consent": r.get("consent", "").strip(),
                "thread_subject": r.get("thread_subject", "").strip(),
                "message_form": None,
                "message_email": r.get("message", "").strip() if r.get("message", "").strip() else "",
                "source": "email",
            }
        src = sources.get(key, {"form": False, "email": False})
        src["email"] = True
        sources[key] = src

    # Update 'source' field from recorded sources flags
    for k, flags in sources.items():
        if k in merged:
            if flags["form"] and flags["email"]:
                merged[k]["source"] = "both"
            elif flags["form"]:
                merged[k]["source"] = "form"
            elif flags["email"]:
                merged[k]["source"] = "email"

    # Build expected order list
    included_emails_sorted = sorted(list(merged.keys()))
    number_after_dedup = len(included_emails_sorted)

    # For message_preview expectations:
    # For form-only: use form message truncated to 60 chars
    # For email-only: use "Message:" content if present else first 60 non-whitespace chars of body
    # For both: ambiguous; accept either form or email approach. We'll compute both.
    expected_records = {}
    # Also need email subjects available for records (for email or both)
    # We already stored thread_subject in merged map.
    # For email-only and both: we may need to compute email-derived preview when message field absent: In inputs provided, all have "Message:" line; ok.

    # Build a helper to compute email message preview if message line missing
    def compute_email_preview(record_email: dict, raw_email_records: list) -> str:
        # Find matching raw email record by email address
        for reml in raw_email_records:
            if normalize_email(reml.get("email", "")) == normalize_email(record_email.get("email", "")):
                # Use message field if present
                msg_val = reml.get("message", "").strip()
                if msg_val:
                    preview = msg_val[:60]
                    return preview
                # Fallback: first 60 non-whitespace characters of body
                body = reml.get("body", "")
                # Remove whitespace characters when counting
                non_ws_chars = "".join(ch for ch in body if not ch.isspace())
                return non_ws_chars[:60]
        return ""

    # Build expected for each merged record
    for email_key in included_emails_sorted:
        rec = merged[email_key]
        source = rec["source"]
        # Compute previews
        form_preview = None
        email_preview = None
        if rec.get("message_form") is not None:
            form_preview = rec.get("message_form", "")
            form_preview = form_preview[:60]
        email_preview = compute_email_preview(rec, email_records)
        # Store expected
        expected_records[email_key] = {
            "full_name": rec.get("full_name", ""),
            "email": rec.get("email", ""),
            "self_identified_races": rec.get("self_identified_races", ""),
            "partner_races": rec.get("partner_races", ""),
            "availability": rec.get("availability", ""),
            "city": rec.get("city", ""),
            "consent": rec.get("consent", ""),
            "source": source,
            "thread_subject": rec.get("thread_subject", "") if source in ("email", "both") else "",
            "acceptable_message_previews": [p for p in [form_preview, email_preview] if p is not None],
        }

    return {
        "form_records": form_records,
        "email_records": email_records,
        "expected_records": expected_records,
        "included_emails_sorted": included_emails_sorted,
        "counts": {
            "total_form": total_form,
            "total_emails_parsed": total_emails_parsed,
            "number_consenting": number_consenting,
            "missing_race_exclusions": missing_race_exclusions,
            "number_after_dedup": number_after_dedup,
        },
    }


def parse_sentence_count(text: str) -> int:
    # Count sentences by splitting on ., !, ?; tolerate newlines as sentence ends if punctuation missing
    body = text.strip()
    # Remove the headers if present (handled by caller usually)
    # Split on punctuation
    candidates = re.split(r"[.!?]+(?:\s+|$)", body)
    parts = [p for p in candidates if p.strip()]
    if parts:
        return len(parts)
    # Fallback to lines
    lines = [l for l in body.splitlines() if l.strip()]
    return len(lines)


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "script_exists": 0.0,
        "merged_csv_exists_with_header": 0.0,
        "merged_csv_records_correct": 0.0,
        "followups_present_and_headers": 0.0,
        "followups_body_references_and_sentences": 0.0,
        "summary_counts_correct": 0.0,
    }

    # Check script exists
    script_path = workspace / "scripts" / "merge_contacts.py"
    if script_path.exists() and script_path.is_file():
        try:
            content = script_path.read_text(encoding="utf-8", errors="ignore")
            if content.strip():
                scores["script_exists"] = 1.0
        except Exception:
            scores["script_exists"] = 0.0

    # Compute expected from inputs
    expected_bundle = compute_expected(workspace)
    expected_records = expected_bundle.get("expected_records", {})
    included_emails_sorted = expected_bundle.get("included_emails_sorted", [])
    expected_counts = expected_bundle.get("counts", {})

    # Check merged_contacts.csv
    csv_path = workspace / "output" / "merged_contacts.csv"
    headers, rows = load_csv_rows(csv_path)
    expected_header = [
        "full_name",
        "email",
        "self_identified_races",
        "partner_races",
        "availability",
        "city",
        "consent",
        "source",
        "thread_subject",
        "message_preview",
    ]
    if headers == expected_header:
        scores["merged_csv_exists_with_header"] = 1.0
    else:
        scores["merged_csv_exists_with_header"] = 0.0

    # Validate CSV content strictly
    csv_ok = False
    if headers is not None and rows is not None and headers == expected_header:
        try:
            # Build actual map by email lower-case
            actual_map = {}
            for r in rows:
                email_val = r.get("email", "").strip()
                if email_val:
                    actual_map[normalize_email(email_val)] = r
            # Check set of emails equals expected set
            if set(actual_map.keys()) == set(included_emails_sorted) and len(rows) == len(included_emails_sorted):
                all_match = True
                for email_key in included_emails_sorted:
                    ar = actual_map[email_key]
                    er = expected_records.get(email_key, {})
                    # Check fields
                    # full_name exact
                    if ar.get("full_name", "").strip() != er.get("full_name", "").strip():
                        all_match = False
                        break
                    # email exact
                    if ar.get("email", "").strip() != er.get("email", "").strip():
                        all_match = False
                        break
                    # races normalized exact
                    if ar.get("self_identified_races", "").strip() != er.get("self_identified_races", "").strip():
                        all_match = False
                        break
                    if ar.get("partner_races", "").strip() != er.get("partner_races", "").strip():
                        all_match = False
                        break
                    # availability exact
                    if ar.get("availability", "").strip() != er.get("availability", "").strip():
                        all_match = False
                        break
                    # city exact
                    if ar.get("city", "").strip() != er.get("city", "").strip():
                        all_match = False
                        break
                    # consent must be "yes" case-insensitive
                    if ar.get("consent", "").strip().lower() != "yes":
                        all_match = False
                        break
                    # source exact
                    if ar.get("source", "").strip() != er.get("source", "").strip():
                        all_match = False
                        break
                    # thread_subject
                    if er.get("source") in ("email", "both"):
                        if ar.get("thread_subject", "").strip() != er.get("thread_subject", "").strip():
                            all_match = False
                            break
                    else:
                        if ar.get("thread_subject", "").strip() != "":
                            all_match = False
                            break
                    # message_preview: accept either form or email-derived preview if both sources
                    acceptable_previews = er.get("acceptable_message_previews", [])
                    actual_preview = ar.get("message_preview", "")
                    # For "form" only or "email" only, acceptable_previews should include exactly one appropriate preview
                    # We accept if actual equals any acceptable preview
                    if actual_preview not in acceptable_previews:
                        all_match = False
                        break
                if all_match:
                    csv_ok = True
        except Exception:
            csv_ok = False
    scores["merged_csv_records_correct"] = 1.0 if csv_ok else 0.0

    # Validate followups files and headers
    followups_dir = workspace / "output" / "followups"
    followups_ok_headers = False
    followups_ok_body = False
    if followups_dir.exists() and followups_dir.is_dir():
        try:
            header_checks = []
            body_checks = []
            for email_key in included_emails_sorted:
                er = expected_records[email_key]
                local_part = er["email"].split("@")[0]
                fpath = followups_dir / f"{local_part}.txt"
                if not fpath.exists():
                    header_checks.append(False)
                    body_checks.append(False)
                    continue
                content = read_text(fpath)
                if not content:
                    header_checks.append(False)
                    body_checks.append(False)
                    continue
                lines = content.splitlines()
                # Need at least two lines
                if len(lines) < 2:
                    header_checks.append(False)
                    body_checks.append(False)
                    continue
                # Exact header line checks
                line1_expected = f"To: {er['email']}"
                line2_expected = f"Subject: Interview Scheduling – {er['full_name']}"
                header_pass = (lines[0].strip() == line1_expected and lines[1].strip() == line2_expected)
                header_checks.append(header_pass)
                # Body checks: references to races and availability, 2–4 short sentences
                body_text = "\n".join(lines[2:]).strip()
                # Must reference self races terms (split into items)
                self_items = split_races(er["self_identified_races"])
                partner_items = split_races(er["partner_races"])
                availability = er["availability"]
                def contains_all(items, text):
                    t = text.lower()
                    return all(it.lower() in t for it in items)
                # Ensure all partner items present; self at least one item present (all ideally)
                ref_pass = contains_all(self_items, body_text) and contains_all(partner_items, body_text) and (availability.lower() in body_text.lower())
                # Sentence count
                sent_count = parse_sentence_count(body_text)
                sentence_pass = 2 <= sent_count <= 4
                body_checks.append(ref_pass and sentence_pass)
            followups_ok_headers = all(header_checks) if header_checks else False
            followups_ok_body = all(body_checks) if body_checks else False
        except Exception:
            followups_ok_headers = False
            followups_ok_body = False
    scores["followups_present_and_headers"] = 1.0 if followups_ok_headers else 0.0
    scores["followups_body_references_and_sentences"] = 1.0 if followups_ok_body else 0.0

    # Validate summary.txt
    summary_ok = False
    summary_path = workspace / "output" / "summary.txt"
    if summary_path.exists() and summary_path.is_file():
        try:
            stext = read_text(summary_path)
            lines = [ln for ln in stext.splitlines()]
            # Need at least 5 lines for counts
            if len(lines) >= 5:
                # Extract first integer from each of first 5 lines
                def first_int(line):
                    m = re.search(r"-?\d+", line)
                    return int(m.group(0)) if m else None
                a = first_int(lines[0])
                b = first_int(lines[1])
                c = first_int(lines[2])
                d = first_int(lines[3])
                e = first_int(lines[4])
                counts_match = (
                    a == expected_counts.get("total_form") and
                    b == expected_counts.get("total_emails_parsed") and
                    c == expected_counts.get("number_consenting") and
                    d == expected_counts.get("missing_race_exclusions") and
                    e == expected_counts.get("number_after_dedup")
                )
                # Next lines should be included emails sorted alphabetically
                listed_emails = [ln.strip() for ln in lines[5:] if ln.strip()]
                emails_match = listed_emails == expected_bundle.get("included_emails_sorted", [])
                summary_ok = counts_match and emails_match
        except Exception:
            summary_ok = False
    scores["summary_counts_correct"] = 1.0 if summary_ok else 0.0

