    except Exception:
        return None


def _read_bytes(path: Path) -> Optional[bytes]:
    try:
        return path.read_bytes()
    except Exception:
        return None


def _strip_html(html: str) -> str:
    # Remove script/style
    html = re.sub(r"(?is)<(script|style).*?>.*?</\1>", "", html)
    # Remove tags
    text = re.sub(r"(?s)<[^>]+>", "", html)
    # Unescape entities
    text = html_module.unescape(text)
    return text


def _decode_mime_header(value: Optional[str]) -> str:
    if value is None:
        return ""
    try:
        dh = decode_header(value)
        return str(make_header(dh))
    except Exception:
        # Fallback: return raw
        return value


def _parse_filters_yaml(path: Path) -> Optional[Dict[str, List[str]]]:
    """
    Minimal YAML parser for the provided simple structure:
    categories:
      category1:
        - keyword1
        - keyword2
      category2:
        - keywordA
    Returns dict {category: [keywords...]} all lowercased and stripped.
    """
    text = _read_text(path)
    if text is None:
        return None
    lines = text.splitlines()
    state = "start"
    categories: Dict[str, List[str]] = {}
    current_category: Optional[str] = None
    try:
        for raw_line in lines:
            line = raw_line.rstrip()
            if not line.strip():
                continue
            if state == "start":
                # Expect "categories:"
                if re.match(r"^\s*categories\s*:\s*$", line):
                    state = "in_categories"
                    continue
                else:
                    # If file begins directly with categories mapping, be lenient
                    if re.match(r"^\s*[A-Za-z0-9_\-]+\s*:\s*$", line):
                        # Assume it is the first category (missing "categories:"), but the provided file has it.
                        # To stay robust, switch to in_categories and handle as category next iterations.
                        state = "in_categories"
                        # fall through to handle as category
                    else:
                        # Unexpected
                        return None
            if state == "in_categories":
                # Category line: two-space indent + name + colon (be lenient on indent)
                m = re.match(r"^\s{0,4}([A-Za-z0-9_\-]+)\s*:\s*$", line)
                if m:
                    current_category = m.group(1).strip().lower()
                    categories[current_category] = []
                    continue
                # Keyword item line: dash with optional indent
                m2 = re.match(r"^\s*-\s*(.+?)\s*$", line)
                if m2 and current_category is not None:
                    kw = m2.group(1).strip().lower()
                    if kw:
                        categories[current_category].append(kw)
                    continue
                # Otherwise ignore unknown line types to be robust
                # but if it's a new key not under the categories block, continue
                # For simplicity, we won't support deeper nesting
        if not categories:
            return None
        # Deduplicate keywords per category and preserve insertion order (but order not critical)
        for cat, kws in list(categories.items()):
            seen: Set[str] = set()
            deduped: List[str] = []
            for k in kws:
                if k not in seen:
                    seen.add(k)
                    deduped.append(k)
            categories[cat] = deduped
        return categories
    except Exception:
        return None


def _parse_eml(path: Path) -> Optional[Dict[str, Any]]:
    data = _read_bytes(path)
    if data is None:
        return None
    try:
        msg = BytesParser(policy=policy.default).parsebytes(data)
    except Exception:
        return None
    try:
        # Headers
        raw_subject = msg["Subject"]
        subject = _decode_mime_header(raw_subject)
        raw_from = msg["From"]
        name, addr = parseaddr(raw_from if raw_from is not None else "")
        from_name = _decode_mime_header(name)
        from_email = addr or ""
        raw_msg_id = msg["Message-ID"] or ""
        message_id = raw_msg_id.strip()
        raw_date = msg["Date"]
        dt = None
        if raw_date:
            try:
                dt = parsedate_to_datetime(raw_date)
                if dt is not None:
                    if dt.tzinfo is None:
                        # Assume UTC if no timezone present
                        dt = dt.replace(tzinfo=timezone.utc)
                    dt = dt.astimezone(timezone.utc)
            except Exception:
                dt = None

        # Body extraction
        body_text = ""
        if msg.is_multipart():
            # Prefer text/plain
            text_part = None
            html_part = None
            for part in msg.walk():
                ctype = part.get_content_type()
                if ctype == "text/plain" and text_part is None:
                    text_part = part
                elif ctype == "text/html" and html_part is None:
                    html_part = part
            if text_part is not None:
                try:
                    body_text = text_part.get_content()
                except Exception:
                    payload = text_part.get_payload(decode=True) or b""
                    body_text = payload.decode(text_part.get_content_charset() or "utf-8", errors="replace")
            elif html_part is not None:
                try:
                    html_content = html_part.get_content()
                except Exception:
                    payload = html_part.get_payload(decode=True) or b""
                    html_content = payload.decode(html_part.get_content_charset() or "utf-8", errors="replace")
                body_text = _strip_html(html_content)
            else:
                # Fallback to entire payload as string
                body_text = msg.get_body(preferencelist=("plain", "html")).get_content() if msg.get_body() else ""
        else:
            ctype = msg.get_content_type()
            try:
                content = msg.get_content()
            except Exception:
                payload = msg.get_payload(decode=True) or b""
                content = payload.decode(msg.get_content_charset() or "utf-8", errors="replace")
            if ctype == "text/html":
                body_text = _strip_html(content)
            else:
                body_text = content

        # Normalize line endings
        if not isinstance(body_text, str):
            body_text = str(body_text)
        body_text = body_text.replace("\r\n", "\n").replace("\r", "\n")

        return {
            "message_id": message_id,
            "date_dt_utc": dt,
            "from_name": from_name,
            "from_email": from_email,
            "subject": subject,
            "body_text": body_text,
        }
    except Exception:
        return None


def _format_iso_utc(dt: datetime) -> str:
    # Return ISO8601 UTC with Z
    return dt.replace(tzinfo=timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")


def _parse_iso_datetime_utc(s: str) -> Optional[datetime]:
    # Accept formats with Z or offset
    try:
        if s.endswith("Z"):
            # Replace Z with +00:00 for fromisoformat
            s2 = s[:-1] + "+00:00"
            return datetime.fromisoformat(s2).astimezone(timezone.utc)
        else:
            dt = datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return dt.astimezone(timezone.utc)
    except Exception:
        # Try common variants without seconds
        try:
            # If it lacks timezone info, assume UTC
            dt = datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return dt.astimezone(timezone.utc)
        except Exception:
            return None


def _collect_emails(workspace: Path) -> List[Path]:
    emails_dir = workspace / "input" / "emails"
    if not emails_dir.exists():
        return []
    return sorted(p for p in emails_dir.glob("*.eml") if p.is_file())


def _compute_expected(workspace: Path) -> Tuple[int, Dict[str, Dict[str, Any]]]:
    """
    Returns:
      total_count (int),
      included_by_message_id (dict of message_id -> expected fields dict)
    """
    filters_path = workspace / "input" / "filters.yaml"
    filters = _parse_filters_yaml(filters_path)
    eml_paths = _collect_emails(workspace)
    total_count = len(eml_paths)
    included: Dict[str, Dict[str, Any]] = {}
    if filters is None:
        # Cannot compute expected included set without filters
        return total_count, included

    # Build flat keyword->categories map for quick lookup
    category_by_keyword: Dict[str, Set[str]] = {}
    all_keywords: Set[str] = set()
    for cat, kw_list in filters.items():
        for kw in kw_list:
            all_keywords.add(kw)
            category_by_keyword.setdefault(kw, set()).add(cat)

    for p in eml_paths:
        parsed = _parse_eml(p)
        if parsed is None:
            # Skip malformed files for inclusion purposes; still count as processed
            continue
        subject = parsed["subject"]
        body = parsed["body_text"]
        combined = (subject + "\n" + body).lower()
        matched_kws: Set[str] = set()
        matched_cats: Set[str] = set()
        for kw in all_keywords:
            if kw in combined:
                matched_kws.add(kw.lower())
                for cat in category_by_keyword.get(kw, set()):
                    matched_cats.add(cat)
        if matched_kws:
            msg_id = parsed["message_id"]
            dt: Optional[datetime] = parsed["date_dt_utc"]
            date_iso = _format_iso_utc(dt) if isinstance(dt, datetime) else ""
            # Prepare categories and matched keywords sorted and formatted
            cats_sorted = sorted(matched_cats)
            kws_sorted = sorted({k.lower() for k in matched_kws})
            body_text = parsed["body_text"]
            snippet = body_text[:200]
            included[msg_id] = {
                "message_id": msg_id,
                "date_iso": date_iso,
                "from_name": parsed["from_name"],
                "from_email": parsed["from_email"],
                "subject": subject,
                "categories_list": cats_sorted,
                "matched_keywords_list": kws_sorted,
                "categories_str": ",".join(cats_sorted),
                "matched_keywords_str": ",".join(kws_sorted),
                "snippet": snippet,
                "message_id_stripped": msg_id.strip("<>"),
            }
    return total_count, included


def _load_csv_records(csv_path: Path) -> Tuple[Optional[List[str]], Optional[List[Dict[str, str]]]]:
    if not csv_path.exists():
        return None, None
    try:
        with csv_path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            header = reader.fieldnames
            rows = [row for row in reader]
        return header, rows
    except Exception:
        return None, None


def _split_commas_normalized(s: str) -> List[str]:
    parts = [p.strip() for p in s.split(",")] if s else []
    parts = [p for p in parts if p != ""]
    return parts


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "inquiries_csv_exists": 0.0,
        "inquiries_csv_header_correct": 0.0,
        "inquiries_csv_included_message_ids_correct": 0.0,
        "inquiries_csv_content_correct": 0.0,
        "replies_files_exist": 0.0,
        "replies_content_correct": 0.0,
        "summary_counts_correct": 0.0,
    }

    # Compute expected
    total_count, expected_included = _compute_expected(workspace)

    # Check inquiries.csv
    inquiries_csv = workspace / "output" / "inquiries.csv"
    header, rows = _load_csv_records(inquiries_csv)
    if header is not None and rows is not None:
        scores["inquiries_csv_exists"] = 1.0
        expected_header = [
            "message_id",
            "date",
            "from_name",
            "from_email",
            "subject",
            "categories",
            "matched_keywords",
            "snippet",
        ]
        if header == expected_header:
            scores["inquiries_csv_header_correct"] = 1.0

        # Compare included message_ids
        actual_ids = [r.get("message_id", "") for r in rows]
        actual_id_set = set(actual_ids)
        expected_id_set = set(expected_included.keys())
        if actual_id_set == expected_id_set:
            scores["inquiries_csv_included_message_ids_correct"] = 1.0

        # Validate row-by-row content
        content_ok = True
        # Build map for quick lookup
        actual_by_id: Dict[str, Dict[str, str]] = {r.get("message_id", ""): r for r in rows}
        for msg_id, exp in expected_included.items():
            row = actual_by_id.get(msg_id)
            if row is None:
                content_ok = False
                break
            # date
            exp_date_dt = _parse_iso_datetime_utc(exp["date_iso"]) if exp["date_iso"] else None
            got_date_str = row.get("date", "") or ""
            got_date_dt = _parse_iso_datetime_utc(got_date_str)
            if not (exp_date_dt and got_date_dt and exp_date_dt == got_date_dt):
                content_ok = False
                break
            # from_name, from_email, subject
            if (row.get("from_name", "") or "") != exp["from_name"]:
                content_ok = False
                break
            if (row.get("from_email", "") or "") != exp["from_email"]:
                content_ok = False
                break
            if (row.get("subject", "") or "") != exp["subject"]:
                content_ok = False
                break
            # categories: allow optional spaces after comma, ensure alphabetical and exact membership
            got_cats_list = _split_commas_normalized(row.get("categories", "") or "")
            if got_cats_list != sorted(got_cats_list):
                content_ok = False
                break
            if got_cats_list != exp["categories_list"]:
                content_ok = False
                break
            # matched_keywords: must be lowercase, unique, alphabetical
            got_kws_list = _split_commas_normalized(row.get("matched_keywords", "") or "")
            if got_kws_list != sorted(got_kws_list):
                content_ok = False
                break
            if any(k != k.lower() for k in got_kws_list):
                content_ok = False
                break
            if got_kws_list != exp["matched_keywords_list"]:
                content_ok = False
                break
            # snippet: must equal first 200 chars
            if (row.get("snippet", "") or "") != exp["snippet"]:
                content_ok = False
                break
        # Also ensure there are no unexpected extra rows (already checked ids set equality)
        if content_ok and actual_id_set == set(expected_included.keys()):
            scores["inquiries_csv_content_correct"] = 1.0

    # Check replies for each included email
    replies_dir = workspace / "output" / "replies"
    replies_exist_ok = True
    replies_content_ok = True
    # Load CSV-derived authoritative values when available; else use expected
    csv_authoritative: Dict[str, Dict[str, str]] = {}
    if rows is not None:
        for r in rows:
            mid = r.get("message_id", "")
            if mid:
                csv_authoritative[mid] = r

    for msg_id, exp in expected_included.items():
        fname = exp["message_id_stripped"] + ".txt"
        reply_path = replies_dir / fname
        content = _read_text(reply_path)
        if content is None:
            replies_exist_ok = False
            replies_content_ok = False
            continue
        # Content checks: placeholders filled, fields inserted
        # Prefer CSV values to ensure consistency with what they wrote
        source = csv_authoritative.get(msg_id, {})
        subj = source.get("subject", exp["subject"])
        recip = source.get("from_name", exp["from_name"])
        cats_str = source.get("categories", exp["categories_str"])
        snip = source.get("snippet", exp["snippet"])

        lines = content.splitlines()
        # First line check
        expected_first_line = f"Subject: Re: {subj}"
        if not lines:
            replies_content_ok = False
        else:
            if lines[0].strip() != expected_first_line:
                replies_content_ok = False
        # Greeting line
        greeting_found = False
        for ln in lines[1:6]:
            if ln.strip() == f"Hi {recip},":
                greeting_found = True
                break
        if not greeting_found:
            replies_content_ok = False
        # Categories presence in template context
        if cats_str not in content:
            replies_content_ok = False
        # Snippet presence (quoted in the template, but we accept presence of snippet)
        if snip and snip not in content:
            replies_content_ok = False
        # No unreplaced placeholders like {{...}}
        if "{{" in content or "}}" in content:
            replies_content_ok = False

    if expected_included:
        if replies_exist_ok:
            scores["replies_files_exist"] = 1.0
        if replies_content_ok:
            scores["replies_content_correct"] = 1.0
    else:
        # If no expected included, define replies checks as pass if no reply files exist
        if not (replies_dir.exists() and any(replies_dir.glob("*.txt"))):
            scores["replies_files_exist"] = 1.0
            scores["replies_content_correct"] = 1.0

    # Check summary.txt
    summary_path = workspace / "output" / "summary.txt"
    summary_text = _read_text(summary_path)
    if summary_text is not None:
        lines = [ln.strip() for ln in summary_text.splitlines()]
        # Spec: two lines: total processed and number included in CSV
        if len(lines) >= 2:
            # Extract first integer from each line
            def _extract_first_int(s: str) -> Optional[int]:
                m = re.search(r"-?\d+", s)
                return int(m.group(0)) if m else None

            total_val = _extract_first_int(lines[0])
            included_val = _extract_first_int(lines[1])
            expected_total = total_count
            expected_included_count = len(expected_included)
            if total_val == expected_total and included_val == expected_included_count:
                scores["summary_counts_correct"] = 1.0

    return scores


def main() -> None:
    workspace_path = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace_path)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

import sys
import json
import csv
from pathlib import Path
from datetime import datetime, timedelta, date
from decimal import Decimal, InvalidOperation
from typing import Any, Dict, List, Tuple, Optional


def _safe_read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _is_blank_or_comment(line: str) -> bool:
    stripped = line.strip()
    return stripped == "" or stripped.startswith("#")


def _parse_yaml_simple(text: str) -> Optional[dict]:
    # Minimal YAML parser for simple structures with mappings and lists using 2-space indentation.
    root: dict = {}
    stack: List[Dict[str, Any]] = [{"indent": 0, "container": root, "parent": None, "parent_key": None}]

    lines = text.splitlines()
    for raw in lines:
        if _is_blank_or_comment(raw):
            continue
        indent = len(raw) - len(raw.lstrip(" "))
        line = raw.strip()

        while stack and indent < stack[-1]["indent"]:
            stack.pop()
        if not stack:
            return None

        ctx = stack[-1]["container"]
        ctx_indent = stack[-1]["indent"]

        if indent != ctx_indent:
            return None

        if line.startswith("- "):
            value_str = line[2:].strip()
            if isinstance(ctx, dict):
                holder = stack[-1]
                parent = holder["parent"]
                parent_key = holder["parent_key"]
                if parent is None or parent_key is None:
                    return None
                if isinstance(parent[parent_key], dict) and len(parent[parent_key]) == 0:
                    new_list: list = []
                    parent[parent_key] = new_list
                    stack[-1]["container"] = new_list
                    ctx = new_list
                else:
                    return None
            if not isinstance(ctx, list):
                return None
            ctx.append(value_str)
            continue

        if ":" in line:
            key_part, val_part = line.split(":", 1)
            key = key_part.strip()
            val = val_part.strip()
            if not isinstance(ctx, dict):
                return None
            if val == "":
                new_child: dict = {}
                ctx[key] = new_child
                stack.append({"indent": indent + 2, "container": new_child, "parent": ctx, "parent_key": key})
            else:
                ctx[key] = val
            continue

        return None

    return root


def _load_yaml_config(path: Path) -> Optional[dict]:
    text = _safe_read_text(path)
    if text is None:
        return None
    data = _parse_yaml_simple(text)
    return data


def _safe_load_csv(path: Path) -> Optional[List[Dict[str, str]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            rows = [dict(row) for row in reader]
            return rows
    except Exception:
        return None


def _parse_date(date_str: str) -> Optional[date]:
    try:
        return datetime.strptime(date_str, "%Y-%m-%d").date()
    except Exception:
        return None


def _daterange(start_date: date, end_date: date):
    current = start_date
    while current <= end_date:
        yield current
        current = current + timedelta(days=1)


def _to_decimal(value: Any) -> Decimal:
    if isinstance(value, Decimal):
        return value
    if isinstance(value, (int, float)):
        return Decimal(str(value))
    if isinstance(value, str):
        s = value.strip()
        if s == "":
            raise InvalidOperation("Empty string for decimal")
        return Decimal(s)
    raise InvalidOperation(f"Unsupported type for decimal: {type(value)}")


def _round_money(d: Decimal) -> Decimal:
    return d.quantize(Decimal("0.01"))


def _decimal_equal(a: Decimal, b: Decimal, quant: str = "0.01") -> bool:
    try:
        return a.quantize(Decimal(quant)) == b.quantize(Decimal(quant))
    except Exception:
        return False


def _float_almost_equal(a: float, b: float, tol: float = 1e-6) -> bool:
    return abs(a - b) <= tol


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores: Dict[str, float] = {
        "childcare_vs_revenue_file_structure": 0.0,
        "childcare_vs_revenue_date_coverage": 0.0,
        "childcare_vs_revenue_values": 0.0,
        "providers_summary_file_structure": 0.0,
        "providers_summary_values": 0.0,
        "checks_json_file_structure": 0.0,
        "checks_json_values": 0.0,
    }

    config_path = workspace / "config" / "report.yaml"
    config = _load_yaml_config(config_path)
    if not isinstance(config, dict):
        return scores

    try:
        rp = config.get("reporting_period", {})
        start_str = rp.get("start_date")
        end_str = rp.get("end_date")
        childcare_categories = config.get("childcare_categories", [])
        expenses_cfg = config.get("expenses", {})
        sales_cfg = config.get("sales", {})
        outputs_cfg = config.get("outputs", {})

        if not (isinstance(start_str, str) and isinstance(end_str, str)):
            raise ValueError("Missing start_date or end_date")
        start_date = _parse_date(start_str)
        end_date = _parse_date(end_str)
        if start_date is None or end_date is None or start_date > end_date:
            raise ValueError("Invalid reporting period")

        if not isinstance(childcare_categories, list) or not all(isinstance(x, str) for x in childcare_categories):
            raise ValueError("Invalid childcare_categories")

        exp_file = expenses_cfg.get("file")
        exp_date_field = expenses_cfg.get("date_field")
        exp_category_field = expenses_cfg.get("category_field")
        exp_amount_field = expenses_cfg.get("amount_field")
        exp_provider_field = expenses_cfg.get("provider_field")
        if not all(isinstance(x, str) for x in [exp_file, exp_date_field, exp_category_field, exp_amount_field, exp_provider_field]):
            raise ValueError("Invalid expenses config fields")

        sales_file = sales_cfg.get("file")
        sales_date_field = sales_cfg.get("date_field")
        sales_gross_field = sales_cfg.get("gross_field")
        sales_fees_field = sales_cfg.get("fees_field")
        sales_refunds_field = sales_cfg.get("refunds_field")
        if not all(isinstance(x, str) for x in [sales_file, sales_date_field, sales_gross_field, sales_fees_field, sales_refunds_field]):
            raise ValueError("Invalid sales config fields")

        out_childcare_vs_revenue = outputs_cfg.get("childcare_vs_revenue")
        out_providers_summary = outputs_cfg.get("providers_summary")
        out_checks = outputs_cfg.get("checks")
        if not all(isinstance(x, str) for x in [out_childcare_vs_revenue, out_providers_summary, out_checks]):
            raise ValueError("Invalid outputs config paths")
    except Exception:
        return scores

    expenses_rows = _safe_load_csv(workspace / exp_file) if exp_file else None
    sales_rows = _safe_load_csv(workspace / sales_file) if sales_file else None

    expected_dates = [d for d in _daterange(start_date, end_date)]
    expected_date_strs = [d.isoformat() for d in expected_dates]
    date_set = set(expected_date_strs)

    childcare_by_date: Dict[str, Decimal] = {ds: Decimal("0") for ds in expected_date_strs}
    netrev_by_date: Dict[str, Decimal] = {ds: Decimal("0") for ds in expected_date_strs}
    providers_amounts: Dict[str, Decimal] = {}
    providers_dates: Dict[str, set] = {}

    compute_ok = True
    try:
        if expenses_rows is None:
            raise ValueError("Expenses file missing or unreadable")
        for row in expenses_rows:
            ds = row.get(exp_date_field, "")
            cat = row.get(exp_category_field, "")
            prov = row.get(exp_provider_field, "")
            amt_str = row.get(exp_amount_field, "")
            dval = _parse_date(ds) if isinstance(ds, str) else None
            if dval is None:
                raise ValueError("Invalid date in expenses")
            ds_iso = dval.isoformat()
            if ds_iso not in date_set:
                continue
            if cat not in childcare_categories:
                continue
            try:
                amt = _to_decimal(amt_str)
            except InvalidOperation:
                raise ValueError("Invalid amount in expenses")
            childcare_by_date[ds_iso] += amt
            if prov:
                providers_amounts[prov] = providers_amounts.get(prov, Decimal("0")) + amt
                if prov not in providers_dates:
                    providers_dates[prov] = set()
                if amt != Decimal("0"):
                    providers_dates[prov].add(ds_iso)

        if sales_rows is None:
            raise ValueError("Sales file missing or unreadable")
        for row in sales_rows:
            ds = row.get(sales_date_field, "")
            dval = _parse_date(ds) if isinstance(ds, str) else None
            if dval is None:
                raise ValueError("Invalid date in sales")
            ds_iso = dval.isoformat()
            if ds_iso not in date_set:
                continue
            try:
                gross = _to_decimal(row.get(sales_gross_field, "0"))
                fees = _to_decimal(row.get(sales_fees_field, "0"))
                refunds = _to_decimal(row.get(sales_refunds_field, "0"))
            except InvalidOperation:
                raise ValueError("Invalid numeric in sales")
            net = gross - fees - refunds
            netrev_by_date[ds_iso] += net

        expected_rows_by_date: Dict[str, Dict[str, Any]] = {}
        childcare_total = Decimal("0")
        netrev_total = Decimal("0")
        unique_childcare_dates_count = 0
        for ds in expected_date_strs:
            c = _round_money(childcare_by_date.get(ds, Decimal("0")))
            n = _round_money(netrev_by_date.get(ds, Decimal("0")))
            if n == Decimal("0"):
                share = 0.0
            else:
                share = float((c / n))
            expected_rows_by_date[ds] = {
                "childcare_spend": c,
                "net_revenue": n,
                "childcare_share_of_revenue": share,
            }
            childcare_total += c
            netrev_total += n
            if c > Decimal("0"):
                unique_childcare_dates_count += 1

        if netrev_total == Decimal("0"):
            share_over_period = 0.0
        else:
            share_over_period = float(childcare_total / netrev_total)

        expected_providers: Dict[str, Dict[str, Any]] = {}
        for prov, total in providers_amounts.items():
            days_set = providers_dates.get(prov, set())
            days_count = len(days_set)
            if days_count == 0:
                continue
            total_r = _round_money(total)
            avg = _round_money(total_r / Decimal(days_count))
            expected_providers[prov] = {
                "total_spend": total_r,
                "days_with_spend": days_count,
                "avg_spend_per_day": avg,
            }

        expected_summary = {
            "reporting_period_start": start_date.isoformat(),
            "reporting_period_end": end_date.isoformat(),
            "childcare_total": _round_money(childcare_total),
            "net_revenue_total": _round_money(netrev_total),
            "childcare_share_over_period": share_over_period,
            "unique_childcare_dates_count": unique_childcare_dates_count,
            "unique_providers_count": len(expected_providers),
        }

    except Exception:
        compute_ok = False

    childcare_vs_revenue_path = workspace / out_childcare_vs_revenue
    providers_summary_path = workspace / out_providers_summary
    checks_json_path = workspace / out_checks

    structure_ok = False
    cvs_rows: List[Dict[str, str]] = []
    if childcare_vs_revenue_path.exists():
        try:
            with childcare_vs_revenue_path.open("r", encoding="utf-8", newline="") as f:
                reader = csv.DictReader(f)
                expected_headers = ["date", "childcare_spend", "net_revenue", "childcare_share_of_revenue"]
                if reader.fieldnames == expected_headers:
                    cvs_rows = [dict(row) for row in reader]
                    structure_ok = True
        except Exception:
            structure_ok = False
    scores["childcare_vs_revenue_file_structure"] = 1.0 if structure_ok else 0.0

    date_coverage_ok = False
    if structure_ok:
        try:
            if len(cvs_rows) == len(expected_date_strs):
                dates_in_file = [row["date"] for row in cvs_rows]
                if dates_in_file == expected_date_strs:
                    date_coverage_ok = True
        except Exception:
            date_coverage_ok = False
    scores["childcare_vs_revenue_date_coverage"] = 1.0 if date_coverage_ok else 0.0

    values_ok = False
    if structure_ok and date_coverage_ok and compute_ok:
        try:
            ok_vals = True
            for row in cvs_rows:
                ds = row["date"]
                exp = expected_rows_by_date.get(ds)
                if exp is None:
                    ok_vals = False
                    break
                try:
                    c_spend = _to_decimal(row["childcare_spend"])
                    n_rev = _to_decimal(row["net_revenue"])
                    share_val = float(row["childcare_share_of_revenue"])
                except Exception:
                    ok_vals = False
                    break
                if not _decimal_equal(_round_money(c_spend), exp["childcare_spend"]):
                    ok_vals = False
                    break
                if not _decimal_equal(_round_money(n_rev), exp["net_revenue"]):
                    ok_vals = False
                    break
                if not _float_almost_equal(share_val, exp["childcare_share_of_revenue"], tol=1e-6):
                    ok_vals = False
                    break
            values_ok = ok_vals
        except Exception:
            values_ok = False
    scores["childcare_vs_revenue_values"] = 1.0 if values_ok else 0.0

    ps_structure_ok = False
    ps_rows: List[Dict[str, str]] = []
    if providers_summary_path.exists():
        try:
            with providers_summary_path.open("r", encoding="utf-8", newline="") as f:
                reader = csv.DictReader(f)
                expected_headers = ["provider", "total_spend", "days_with_spend", "avg_spend_per_day"]
                if reader.fieldnames == expected_headers:
                    ps_rows = [dict(row) for row in reader]
                    ps_structure_ok = True
        except Exception:
            ps_structure_ok = False
    scores["providers_summary_file_structure"] = 1.0 if ps_structure_ok else 0.0

    ps_values_ok = False
    if ps_structure_ok and compute_ok:
        try:
            file_providers: Dict[str, Dict[str, Any]] = {}
            for row in ps_rows:
                prov = row["provider"]
                try:
                    total_spend = _to_decimal(row["total_spend"])
                    days_with = int(row["days_with_spend"])
                    avg_spend = _to_decimal(row["avg_spend_per_day"])
                except Exception:
                    ps_values_ok = False
                    break
                file_providers[prov] = {
                    "total_spend": _round_money(total_spend),
                    "days_with_spend": days_with,
                    "avg_spend_per_day": _round_money(avg_spend),
                }
            else:
                exp_prov_set = set(expected_providers.keys())
                file_prov_set = set(file_providers.keys())
                if exp_prov_set != file_prov_set:
                    ps_values_ok = False
                else:
                    ok = True
                    for prov in exp_prov_set:
                        expv = expected_providers[prov]
                        fiv = file_providers[prov]
                        if expv["days_with_spend"] != fiv["days_with_spend"]:
                            ok = False
                            break
                        if not _decimal_equal(expv["total_spend"], fiv["total_spend"]):
                            ok = False
                            break
                        if not _decimal_equal(expv["avg_spend_per_day"], fiv["avg_spend_per_day"]):
                            ok = False
                            break
                    ps_values_ok = ok
        except Exception:
            ps_values_ok = False
    scores["providers_summary_values"] = 1.0 if ps_values_ok else 0.0

    cj_structure_ok = False
    cj_values_ok = False
    cj_data: Dict[str, Any] = {}
    if checks_json_path.exists():
        try:
            cj_text = _safe_read_text(checks_json_path)
            if cj_text is not None:
                data = json.loads(cj_text)
                if isinstance(data, dict):
                    required_keys = [
                        "reporting_period_start",
                        "reporting_period_end",
                        "childcare_total",
                        "net_revenue_total",
                        "childcare_share_over_period",
                        "unique_childcare_dates_count",
                        "unique_providers_count",
                    ]
                    if all(k in data for k in required_keys):
                        cj_data = data
                        cj_structure_ok = True
        except Exception:
            cj_structure_ok = False
    scores["checks_json_file_structure"] = 1.0 if cj_structure_ok else 0.0

    if cj_structure_ok and compute_ok:
        try:
            if cj_data.get("reporting_period_start") != start_date.isoformat():
                cj_values_ok = False
            elif cj_data.get("reporting_period_end") != end_date.isoformat():
                cj_values_ok = False
            else:
                try:
                    cj_childcare_total = _to_decimal(str(cj_data.get("childcare_total")))
                    cj_netrev_total = _to_decimal(str(cj_data.get("net_revenue_total")))
                    cj_share = float(cj_data.get("childcare_share_over_period"))
                    cj_unique_dates = int(cj_data.get("unique_childcare_dates_count"))
                    cj_unique_providers = int(cj_data.get("unique_providers_count"))
                except Exception:
                    cj_values_ok = False
                else:
                    if not _decimal_equal(_round_money(cj_childcare_total), expected_summary["childcare_total"]):
                        cj_values_ok = False
                    elif not _decimal_equal(_round_money(cj_netrev_total), expected_summary["net_revenue_total"]):
                        cj_values_ok = False
                    elif not _float_almost_equal(cj_share, expected_summary["childcare_share_over_period"], tol=1e-6):
                        cj_values_ok = False
                    elif cj_unique_dates != expected_summary["unique_childcare_dates_count"]:
                        cj_values_ok = False
                    elif cj_unique_providers != expected_summary["unique_providers_count"]:
                        cj_values_ok = False
                    else:
                        cj_values_ok = True
        except Exception:
            cj_values_ok = False
    scores["checks_json_values"] = 1.0 if cj_values_ok else 0.0

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

import json
import csv
import re
import sys
from pathlib import Path
from typing import List, Dict, Tuple, Optional


def normalize_text(s: str) -> str:
    if s is None:
        return ""
    s = s.replace("\r\n", "\n").replace("\r", "\n")
    lines = [ln.rstrip() for ln in s.split("\n")]
    return "\n".join(lines).strip("\n")


def safe_read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def safe_read_csv(path: Path) -> Optional[List[Dict[str, str]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            rows = []
            for r in reader:
                rows.append(dict(r))
        return rows
    except Exception:
        return None


def parse_int(s: str) -> Optional[int]:
    try:
        return int(s)
    except Exception:
        return None


def compute_expected_aggregates(input_rows: List[Dict[str, str]]) -> Dict[Tuple[str, str, str, str], Dict[str, str]]:
    typed = []
    for r in input_rows:
        year = parse_int(r.get("year", ""))
        county = r.get("county", "")
        disease = r.get("disease", "")
        deaths = parse_int(r.get("deaths", ""))
        population = parse_int(r.get("population", ""))
        if year is None or deaths is None or population is None or not county or not disease:
            return {}
        typed.append({"year": year, "county": county, "disease": disease, "deaths": deaths, "population": population})

    def sum_for(disease: str, years_set: set, counties: Optional[set] = None) -> Tuple[int, int]:
        total_deaths = 0
        total_pop = 0
        for r in typed:
            if r["disease"] != disease:
                continue
            if r["year"] not in years_set:
                continue
            if counties is not None and r["county"] not in counties:
                continue
            total_deaths += r["deaths"]
            total_pop += r["population"]
        return total_deaths, total_pop

    y_1918_1920 = {1918, 1919, 1920}
    y_1919_1920 = {1919, 1920}
    y_1918 = {1918}

    all_counties = set(r["county"] for r in typed)

    expected: Dict[Tuple[str, str, str, str], Dict[str, str]] = {}

    d, p = sum_for("influenza", y_1918_1920, {"Lublin"})
    rate = (d / p * 10000.0) if p > 0 else 0.0
    expected[("influenza", "county", "Lublin", "1918-1920")] = {
        "deaths": str(d),
        "population": str(p),
        "rate_per_10k": f"{rate:.2f}",
    }

    d, p = sum_for("cholera", y_1919_1920, {"Lublin"})
    rate = (d / p * 10000.0) if p > 0 else 0.0
    expected[("cholera", "county", "Lublin", "1919-1920")] = {
        "deaths": str(d),
        "population": str(p),
        "rate_per_10k": f"{rate:.2f}",
    }

    d, p = sum_for("typhus", y_1918_1920, all_counties)
    rate = (d / p * 10000.0) if p > 0 else 0.0
    expected[("typhus", "voivodeship", "Lublin Voivodeship", "1918-1920")] = {
        "deaths": str(d),
        "population": str(p),
        "rate_per_10k": f"{rate:.2f}",
    }

    d, p = sum_for("influenza", y_1918, {"Zamosc"})
    rate = (d / p * 10000.0) if p > 0 else 0.0
    expected[("influenza", "county", "Zamosc", "1918")] = {
        "deaths": str(d),
        "population": str(p),
        "rate_per_10k": f"{rate:.2f}",
    }

    d, p = sum_for("influenza", y_1918, {"Chelm"})
    rate = (d / p * 10000.0) if p > 0 else 0.0
    expected[("influenza", "county", "Chelm", "1918")] = {
        "deaths": str(d),
        "population": str(p),
        "rate_per_10k": f"{rate:.2f}",
    }

    return expected


def split_findings_section(text: str) -> Optional[Tuple[str, str, str, str]]:
    norm = normalize_text(text)
    lines = norm.split("\n")
    idx = None
    for i, ln in enumerate(lines):
        if ln.strip() == "## Findings":
            idx = i
            break
    if idx is None:
        return None
    next_idx = None
    for j in range(idx + 1, len(lines)):
        if lines[j].startswith("## "):
            next_idx = j
            break
    prefix = "\n".join(lines[:idx])
    findings_header = lines[idx]
    findings_body = "\n".join(lines[idx + 1: next_idx]) if next_idx is not None else "\n".join(lines[idx + 1:])
    suffix = "\n".join(lines[next_idx:]) if next_idx is not None else ""
    return prefix, findings_header, findings_body, suffix


def contains_all(text: str, keywords: List[str]) -> bool:
    t = text.lower()
    return all(k.lower() in t for k in keywords)


def has_number(text: str, number: int) -> bool:
    pattern = r"\b{}\b".format(re.escape(str(number)))
    return re.search(pattern, text) is not None


def word_count(text: str) -> int:
    return len(re.findall(r"\b\w+\b", text))


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores: Dict[str, float] = {
        "analysis_summary_structure": 0.0,
        "analysis_summary_values": 0.0,
        "analysis_summary_rate_format": 0.0,
        "revised_pamphlet_structure": 0.0,
        "revised_pamphlet_findings_reference": 0.0,
        "revised_pamphlet_numeric_consistency": 0.0,
        "status_update_structure_and_length": 0.0,
        "status_update_numeric_consistency": 0.0,
        "email_basic_requirements": 0.0,
    }

    input_csv_path = workspace / "input" / "morbidity_lublin_1918_1920.csv"
    input_rows = safe_read_csv(input_csv_path)

    expected_agg: Dict[Tuple[str, str, str, str], Dict[str, str]] = {}
    if input_rows is not None:
        expected_agg = compute_expected_aggregates(input_rows)

    analysis_path = workspace / "output" / "analysis_summary.csv"
    analysis_rows = safe_read_csv(analysis_path)
    expected_header = ["disease", "area_type", "area_name", "years", "deaths", "population", "rate_per_10k"]

    if analysis_rows is not None and input_rows is not None and expected_agg:
        try:
            with analysis_path.open("r", encoding="utf-8", newline="") as f:
                reader = csv.reader(f)
                header = next(reader, [])
        except Exception:
            header = []
        header_ok = header == expected_header

        keys_expected = set(expected_agg.keys())
        keys_actual = set()
        values_ok = True
        rate_format_ok = True
        rows_count_ok = len(analysis_rows) == 5

        for r in analysis_rows:
            key = (r.get("disease", ""), r.get("area_type", ""), r.get("area_name", ""), r.get("years", ""))
            keys_actual.add(key)
            exp = expected_agg.get(key)
            if exp is None:
                values_ok = False
                continue
            d_str = r.get("deaths", "")
            p_str = r.get("population", "")
            rate_str = r.get("rate_per_10k", "")
            d_val = parse_int(d_str)
            p_val = parse_int(p_str)
            if d_val is None or p_val is None:
                values_ok = False
            else:
                if str(d_val) != exp["deaths"] or str(p_val) != exp["population"]:
                    values_ok = False
            try:
                if rate_str != exp["rate_per_10k"]:
                    values_ok = False
                if not re.match(r"^-?\d+\.\d{2}$", rate_str):
                    rate_format_ok = False
            except Exception:
                values_ok = False
                rate_format_ok = False

        rows_keys_ok = (keys_actual == keys_expected)
        if header_ok and rows_count_ok and rows_keys_ok:
            scores["analysis_summary_structure"] = 1.0
        else:
            scores["analysis_summary_structure"] = 0.0
        if values_ok and rows_count_ok and rows_keys_ok:
            scores["analysis_summary_values"] = 1.0
        else:
            scores["analysis_summary_values"] = 0.0
        if rate_format_ok and rows_count_ok and rows_keys_ok:
            scores["analysis_summary_rate_format"] = 1.0
        else:
            scores["analysis_summary_rate_format"] = 0.0
    else:
        scores["analysis_summary_structure"] = 0.0
        scores["analysis_summary_values"] = 0.0
        scores["analysis_summary_rate_format"] = 0.0

    orig_pamphlet_path = workspace / "input" / "pamphlet_draft.md"
    revised_pamphlet_path = workspace / "output" / "revised_pamphlet.md"
    orig_text = safe_read_text(orig_pamphlet_path)
    revised_text = safe_read_text(revised_pamphlet_path)

    if orig_text is not None and revised_text is not None and expected_agg:
        orig_split = split_findings_section(orig_text)
        rev_split = split_findings_section(revised_text)
        if orig_split is not None and rev_split is not None:
            orig_prefix, orig_header, orig_findings_body, orig_suffix = orig_split
            rev_prefix, rev_header, rev_findings_body, rev_suffix = rev_split
            if normalize_text(orig_prefix) == normalize_text(rev_prefix) and normalize_text(orig_suffix) == normalize_text(rev_suffix) and normalize_text(orig_header) == normalize_text(rev_header):
                if normalize_text(orig_findings_body) != normalize_text(rev_findings_body):
                    scores["revised_pamphlet_structure"] = 1.0
            findings_lower = normalize_text(rev_findings_body).lower()
            if "see output/analysis_summary.csv" in findings_lower:
                scores["revised_pamphlet_findings_reference"] = 1.0

            exp_li = expected_agg.get(("influenza", "county", "Lublin", "1918-1920"))
            exp_ch = expected_agg.get(("cholera", "county", "Lublin", "1919-1920"))
            exp_ty = expected_agg.get(("typhus", "voivodeship", "Lublin Voivodeship", "1918-1920"))
            exp_z1918 = expected_agg.get(("influenza", "county", "Zamosc", "1918"))
            exp_c1918 = expected_agg.get(("influenza", "county", "Chelm", "1918"))

            findings_ok = True
            if not (exp_li and exp_ch and exp_ty and exp_z1918 and exp_c1918):
                findings_ok = False
            else:
                cond1 = contains_all(rev_findings_body, ["Lublin", "influenza", "1918-1920"]) and has_number(rev_findings_body, int(exp_li["deaths"]))
                cond2 = contains_all(rev_findings_body, ["Lublin", "cholera", "1919-1920"]) and has_number(rev_findings_body, int(exp_ch["deaths"]))
                cond3 = contains_all(rev_findings_body, ["Lublin Voivodeship", "typhus", "1918-1920"]) and has_number(rev_findings_body, int(exp_ty["deaths"]))
                cond4 = contains_all(rev_findings_body, ["Zamosc", "Chelm", "influenza", "1918"]) and has_number(rev_findings_body, int(exp_z1918["deaths"])) and has_number(rev_findings_body, int(exp_c1918["deaths"]))
                findings_ok = cond1 and cond2 and cond3 and cond4

            if findings_ok:
                scores["revised_pamphlet_numeric_consistency"] = 1.0
        else:
            scores["revised_pamphlet_structure"] = 0.0
            scores["revised_pamphlet_findings_reference"] = 0.0
            scores["revised_pamphlet_numeric_consistency"] = 0.0
    else:
        scores["revised_pamphlet_structure"] = 0.0
        scores["revised_pamphlet_findings_reference"] = 0.0
        scores["revised_pamphlet_numeric_consistency"] = 0.0

    status_path = workspace / "output" / "status_update.md"
    status_text = safe_read_text(status_path)
    if status_text is not None and expected_agg:
        wc = word_count(status_text)
        lines_with_arrow = [ln for ln in normalize_text(status_text).split("\n") if "->" in ln]
        has_csv_reference = ("input/morbidity_lublin_1918_1920.csv" in status_text) or ("csv" in status_text.lower())
        structure_ok = (wc <= 300 and len(lines_with_arrow) >= 4 and has_csv_reference)
        if structure_ok:
            scores["status_update_structure_and_length"] = 1.0

        exp_li = expected_agg.get(("influenza", "county", "Lublin", "1918-1920"))
        exp_ch = expected_agg.get(("cholera", "county", "Lublin", "1919-1920"))
        exp_ty = expected_agg.get(("typhus", "voivodeship", "Lublin Voivodeship", "1918-1920"))
        exp_z1918 = expected_agg.get(("influenza", "county", "Zamosc", "1918"))
        exp_c1918 = expected_agg.get(("influenza", "county", "Chelm", "1918"))

        num_ok = all([exp_li, exp_ch, exp_ty, exp_z1918, exp_c1918])
        if num_ok:
            num_ok = num_ok and contains_all(status_text, ["Lublin", "influenza", "1918-1920"]) and has_number(status_text, int(exp_li["deaths"]))
            num_ok = num_ok and contains_all(status_text, ["Lublin", "cholera", "1919-1920"]) and has_number(status_text, int(exp_ch["deaths"]))
            num_ok = num_ok and contains_all(status_text, ["Lublin Voivodeship", "typhus", "1918-1920"]) and has_number(status_text, int(exp_ty["deaths"]))
            num_ok = num_ok and contains_all(status_text, ["Zamosc", "Chelm", "influenza", "1918"]) and has_number(status_text, int(exp_z1918["deaths"])) and has_number(status_text, int(exp_c1918["deaths"]))
        if num_ok:
            scores["status_update_numeric_consistency"] = 1.0
    else:
        scores["status_update_structure_and_length"] = 0.0
        scores["status_update_numeric_consistency"] = 0.0

    email_path = workspace / "output" / "email_to_archive.txt"
    email_text = safe_read_text(email_path)
    if email_text is not None:
        t = email_text
        has_to = bool(re.search(r"(?im)^To:", t))
        subj_match = re.search(r"(?im)^Subject:\s*(.*)$", t)
        has_subject = subj_match is not None
        subject_ok = False
        if has_subject:
            subject_val = subj_match.group(1).strip().lower()
            subject_ok = "revisions to 1918-1920 health exhibit text" in subject_val
        lists_files = all(s in t for s in ["output/analysis_summary.csv", "output/revised_pamphlet.md", "output/status_update.md"])
        asks_review = "review" in t.lower()
        if has_to and subject_ok and lists_files and asks_review:
            scores["email_basic_requirements"] = 1.0
        else:
            scores["email_basic_requirements"] = 0.0
    else:
        scores["email_basic_requirements"] = 0.0

    return scores


def main() -> None:
