import sys
import json
import csv
import re
from pathlib import Path
from html.parser import HTMLParser


def _safe_read_text(path: Path) -> str | None:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _safe_read_csv(path: Path) -> list | None:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            rows = [dict(r) for r in reader]
        return rows
    except Exception:
        return None


def _safe_load_json(path: Path) -> dict | None:
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


class TrainingTableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_training_table = False
        self.current_table_id = None
        self.in_tbody = False
        self.in_tr = False
        self.in_td = False
        self.col_index = -1
        self.current_row = []
        self.data = {}
        self._table_stack = []

    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)
        if tag.lower() == "table":
            self._table_stack.append(attrs_dict.get("id"))
            if attrs_dict.get("id") == "training":
                self.in_training_table = True
        if not self.in_training_table:
            return
        if tag.lower() == "tbody":
            self.in_tbody = True
        if tag.lower() == "tr" and self.in_tbody:
            self.in_tr = True
            self.col_index = -1
            self.current_row = []
        if tag.lower() == "td" and self.in_tr:
            self.in_td = True
            self.col_index += 1

    def handle_endtag(self, tag):
        if tag.lower() == "table":
            table_id = self._table_stack.pop() if self._table_stack else None
            if table_id == "training":
                self.in_training_table = False
        if not self.in_training_table:
            return
        if tag.lower() == "tbody":
            self.in_tbody = False
        if tag.lower() == "tr" and self.in_tr:
            self.in_tr = False
            # Expect exactly two columns: facility_id and training_completion_percent
            if len(self.current_row) >= 2:
                fid = self.current_row[0].strip()
                perc = self.current_row[1].strip()
                if fid:
                    try:
                        self.data[fid] = int(perc)
                    except Exception:
                        # Ignore invalid row
                        pass
        if tag.lower() == "td":
            self.in_td = False

    def handle_data(self, data):
        if self.in_training_table and self.in_tr and self.in_td:
            self.current_row.append(data)


def _parse_training_html(path: Path) -> dict | None:
    text = _safe_read_text(path)
    if text is None:
        return None
    try:
        parser = TrainingTableParser()
        parser.feed(text)
        return parser.data
    except Exception:
        return None


def _fmt2(x: float) -> str:
    return f"{x:.2f}"


def _extract_section_lines(text: str, title_substring: str) -> list[str] | None:
    """
    Returns lines of a section that starts with a line containing title_substring (case-insensitive),
    stopping at the next blank line or the next line that contains the start of another known section.
    """
    lines = text.splitlines()
    start_idx = None
    title_lower = title_substring.lower()
    for i, line in enumerate(lines):
        if title_lower in line.lower():
            start_idx = i
            break
    if start_idx is None:
        return None
    # Collect subsequent lines until a blank line or another section header
    out = []
    known_headers = [
        "present audit files:",
        "facilities missing audit files:",
        "top 3 facilities by composite risk score",
        "gaps/notes",
        "company-wide totals",
        "overview",
        "brief overview",
    ]
    for j in range(start_idx + 1, len(lines)):
        ln = lines[j]
        if not ln.strip():
            break
        is_header = any(h in ln.lower() for h in known_headers)
        if is_header:
            break
        out.append(ln)
    return out


def _parse_audit_inventory(text: str) -> tuple[list[str], list[str]] | None:
    """
    Returns (present_files, missing_facility_ids)
    """
    lines = text.splitlines()
    present_idx = None
    missing_idx = None
    for i, line in enumerate(lines):
        if line.strip().lower() == "present audit files:":
            present_idx = i
        if line.strip().lower() == "facilities missing audit files:":
            missing_idx = i
    if present_idx is None or missing_idx is None:
        return None
    # Present files: lines after present_idx up to missing_idx
    present_files = []
    for i in range(present_idx + 1, missing_idx):
        ln = lines[i].strip()
        if ln:
            present_files.append(ln)
    # Missing facilities: lines after missing_idx to end
    missing_ids = []
    for i in range(missing_idx + 1, len(lines)):
        ln = lines[i].strip()
        if ln:
            missing_ids.append(ln)
    return (present_files, missing_ids)


def _compute_expected(workspace: Path) -> dict:
    """
    Compute expected aggregates from input files.
    Returns dict with keys:
    - ok: bool
    - facilities: dict | None
    - incidents: dict | None
    - assets: dict | None
    - audits: dict | None
    - training: dict | None
    - present_audit_files: list
    """
    input_dir = workspace / "input"
    facilities_csv = input_dir / "facilities.csv"
    incidents_csv = input_dir / "incidents.csv"
    assets_jsonl = input_dir / "assets.jsonl"
    audits_dir = input_dir / "audits"
    training_html = input_dir / "training.html"

    # Facilities
    facilities_rows = _safe_read_csv(facilities_csv)
    facilities_ok = facilities_rows is not None
    facilities = {}
    if facilities_ok:
        try:
            for r in facilities_rows:
                fid = r.get("facility_id", "").strip()
                name = r.get("name", "").strip()
                location = r.get("location", "").strip()
                employees = int(r.get("employees", "").strip())
                if fid:
                    facilities[fid] = {
                        "facility_id": fid,
                        "facility_name": name,
                        "location": location,
                        "employees": employees,
                    }
        except Exception:
            facilities_ok = False
            facilities = {}

    # Incidents
    incidents_rows = _safe_read_csv(incidents_csv)
    incidents_ok = incidents_rows is not None
    incidents = {}
    if incidents_ok:
        try:
            for r in incidents_rows:
                fid = r.get("facility_id", "").strip()
                if not fid:
                    raise ValueError("Missing facility_id in incidents row")
                try:
                    ltd = float(r.get("lost_time_days", "0").strip())
                    cost = float(r.get("direct_cost_usd", "0").strip())
                except Exception:
                    raise
                agg = incidents.setdefault(fid, {"total_incidents": 0, "total_direct_cost_usd": 0.0, "total_lost_time_days": 0.0})
                agg["total_incidents"] += 1
                agg["total_direct_cost_usd"] += cost
                agg["total_lost_time_days"] += ltd
            # Convert lost time to int if integral
            for fid, agg in incidents.items():
                # Keep as integer if it's whole number; else keep as integer rounding? Spec not explicit; input gives ints.
                # We'll round to nearest integer for comparison assuming source is integer days.
                agg["total_lost_time_days"] = int(round(agg["total_lost_time_days"]))
        except Exception:
            incidents_ok = False
            incidents = {}

    # Assets (JSONL)
    assets_ok = True
    assets = {}
    if assets_jsonl.exists():
        try:
            with assets_jsonl.open("r", encoding="utf-8") as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    obj = json.loads(line)
                    fid = str(obj.get("facility_id", "")).strip()
                    val = float(obj.get("asset_value_usd", 0.0))
                    if not fid:
                        raise ValueError("Missing facility_id in assets line")
                    assets[fid] = assets.get(fid, 0.0) + val
        except Exception:
            assets_ok = False
            assets = {}
    else:
        # Assets file missing is treated as zero assets for all facilities
        # But since requirement explicitly uses this file, if missing we'll still compute zero but mark ok False to fail precision checks.
        assets_ok = False
        assets = {}

    # Audits directory and files
    present_audit_files = []
    audits = {}
    audits_ok = True
    if audits_dir.exists() and audits_dir.is_dir():
        try:
            for p in sorted(audits_dir.iterdir()):
                if p.is_file() and p.suffix.lower() == ".json":
                    present_audit_files.append(p.name)
            # Map by facility from expected filename pattern
            for fid in facilities.keys():
                expected_name = f"facility_{fid}.json"
                p = audits_dir / expected_name
                if p.exists():
                    obj = _safe_load_json(p)
                    if obj is None:
                        audits_ok = False
                    else:
                        cp = obj.get("compliance_percent", None)
                        try:
                            if cp is None:
                                audits[fid] = None
                            else:
                                audits[fid] = int(cp)
                        except Exception:
                            audits_ok = False
                else:
                    audits[fid] = None
        except Exception:
            audits_ok = False
            audits = {}
            present_audit_files = []
    else:
        # No audits directory: none present
        audits_ok = True  # directory missing is acceptable; missing audits marked accordingly
        for fid in facilities.keys():
            audits[fid] = None
        present_audit_files = []

    # Training HTML
    training_map = _parse_training_html(training_html)
    training_ok = training_map is not None or not training_html.exists()
    if training_map is None:
        training_map = {}

    ok = facilities_ok and incidents_ok and assets_ok and audits_ok and training_ok

    return {
        "ok": ok,
        "facilities_ok": facilities_ok,
        "incidents_ok": incidents_ok,
        "assets_ok": assets_ok,
        "audits_ok": audits_ok,
        "training_ok": training_ok,
        "facilities": facilities,
        "incidents": incidents,
        "assets": assets,
        "audits": audits,
        "training": training_map,
        "present_audit_files": present_audit_files,
    }


def _build_expected_risk_metrics(expected: dict) -> list[dict] | None:
    if not (expected["facilities_ok"] and expected["incidents_ok"] and expected["audits_ok"] and expected["training_ok"]):
        return None
    # assets_ok is required too per spec; if False, we cannot fully validate
    if not expected["assets_ok"]:
        return None

    facilities = expected["facilities"]
    incidents = expected["incidents"]
    assets = expected["assets"]
    audits = expected["audits"]
    training = expected["training"]

    rows = []
    for fid, finfo in facilities.items():
        name = finfo["facility_name"]
        location = finfo["location"]
        employees = finfo["employees"]

        inc = incidents.get(fid, {"total_incidents": 0, "total_direct_cost_usd": 0.0, "total_lost_time_days": 0})
        total_incidents = inc["total_incidents"]
        total_direct_cost = float(inc["total_direct_cost_usd"])
        total_lost_time_days = int(inc["total_lost_time_days"])

        incident_rate = (total_incidents / employees) * 100.0 if employees > 0 else 0.0
        avg_cost = (total_direct_cost / total_incidents) if total_incidents > 0 else 0.0

        asset_total = float(assets.get(fid, 0.0))

        audit_cp = audits.get(fid, None)
        if audit_cp is None:
            audit_str = "MISSING"
            audit_gap = 100.0
        else:
            audit_str = str(int(audit_cp))
            audit_gap = float(100 - int(audit_cp))

        training_cp = training.get(fid, None)
        if training_cp is None:
            training_str = "UNKNOWN"
            training_gap = 100.0
        else:
            training_str = str(int(training_cp))
            training_gap = float(100 - int(training_cp))

        cost_factor = min(10.0, total_direct_cost / 10000.0)
        composite = incident_rate + 0.2 * audit_gap + 0.1 * training_gap + cost_factor

        row = {
            "facility_id": fid,
            "facility_name": name,
            "location": location,
            "employees": str(int(employees)),
            "total_incidents": str(int(total_incidents)),
            "incident_rate_per_100_employees": _fmt2(incident_rate),
            "total_direct_cost_usd": _fmt2(total_direct_cost),
            "avg_cost_per_incident_usd": _fmt2(avg_cost),
            "total_lost_time_days": str(int(total_lost_time_days)),
            "asset_value_usd_total": _fmt2(asset_total),
            "audit_compliance_percent": audit_str,
            "training_completion_percent": training_str,
            "composite_risk_score": _fmt2(composite),
        }
        rows.append(row)
    return rows


def _compare_csv_rows(expected_rows: list[dict], actual_rows: list[dict], header: list[str]) -> bool:
    # Build dicts by facility_id for comparison
    exp_by_id = {r["facility_id"]: r for r in expected_rows}
    act_by_id = {r["facility_id"]: r for r in actual_rows if "facility_id" in r}

    if set(exp_by_id.keys()) != set(act_by_id.keys()):
        return False

    for fid, exp in exp_by_id.items():
        act = act_by_id.get(fid)
        if act is None:
            return False
        # Check each column value equality as string trimming whitespace
        for col in header:
            ev = exp.get(col, "")
            av = (act.get(col, "") or "").strip()
            if av != ev:
                return False
    return True


def _tokens_from_lines(lines: list[str]) -> list[str]:
    tokens = []
    for ln in lines:
        tokens.extend(re.findall(r"[A-Za-z0-9_.-]+", ln))
    return tokens


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)

    scores = {
        "risk_metrics_exists_and_header": 0.0,
        "risk_metrics_row_count": 0.0,
        "risk_metrics_values_accuracy": 0.0,
        "audit_inventory_exists_and_structure": 0.0,
        "audit_inventory_present_files_list": 0.0,
        "audit_inventory_missing_facilities_list": 0.0,
        "risk_summary_exists_and_overview": 0.0,
        "risk_summary_company_totals": 0.0,
        "risk_summary_top3_section": 0.0,
        "risk_summary_gaps_notes": 0.0,
    }

    expected = _compute_expected(workspace)

    # Prepare expected risk_metrics rows (if possible)
    expected_rows = _build_expected_risk_metrics(expected)

    # Paths
    output_dir = workspace / "output"
    risk_metrics_csv = output_dir / "risk_metrics.csv"
    audit_inventory_txt = output_dir / "audit_inventory.txt"
    risk_summary_md = output_dir / "risk_summary.md"

    # Check risk_metrics.csv existence and header
    rm_rows = _safe_read_csv(risk_metrics_csv)
    expected_header = [
        "facility_id",
        "facility_name",
        "location",
        "employees",
        "total_incidents",
        "incident_rate_per_100_employees",
        "total_direct_cost_usd",
        "avg_cost_per_incident_usd",
        "total_lost_time_days",
        "asset_value_usd_total",
        "audit_compliance_percent",
        "training_completion_percent",
        "composite_risk_score",
    ]
    if rm_rows is not None:
        # Re-open to get header
        try:
            with risk_metrics_csv.open("r", encoding="utf-8", newline="") as f:
                reader = csv.reader(f)
                header = next(reader, [])
            if header == expected_header:
                scores["risk_metrics_exists_and_header"] = 1.0
        except Exception:
            pass

    # risk_metrics_row_count
    if rm_rows is not None and expected["facilities_ok"]:
        actual_count = len(rm_rows)
        expected_count = len(expected["facilities"])
        if actual_count == expected_count and expected_count > 0:
            scores["risk_metrics_row_count"] = 1.0

    # risk_metrics_values_accuracy
    if rm_rows is not None and expected_rows is not None:
        # Compare all rows
        # Ensure actual rows have all required columns
        actual_has_all_cols = True
        for r in rm_rows:
            for col in expected_header:
                if col not in r:
                    actual_has_all_cols = False
                    break
            if not actual_has_all_cols:
                break
        if actual_has_all_cols and _compare_csv_rows(expected_rows, rm_rows, expected_header):
            scores["risk_metrics_values_accuracy"] = 1.0

    # audit_inventory.txt existence and structure
    ai_text = _safe_read_text(audit_inventory_txt)
    if ai_text is not None:
        if ("Present audit files:" in ai_text) and ("Facilities missing audit files:" in ai_text):
            # ensure present section appears before missing section
            if ai_text.lower().find("present audit files:") < ai_text.lower().find("facilities missing audit files:"):
                scores["audit_inventory_exists_and_structure"] = 1.0

    # audit_inventory present files list correctness
    if ai_text is not None:
        parsed = _parse_audit_inventory(ai_text)
        if parsed is not None:
            present_files_list, missing_ids_list = parsed
            # Expected present files: JSON files under input/audits (names only)
            expected_present_files = expected["present_audit_files"]
            # Compare as sets (order not specified)
            if set(present_files_list) == set(expected_present_files):
                scores["audit_inventory_present_files_list"] = 1.0

            # audit_inventory missing facilities list correctness
            if expected["facilities_ok"]:
                expected_missing = []
                audits_dir = workspace / "input" / "audits"
                for fid in expected["facilities"].keys():
                    expected_name = f"facility_{fid}.json"
                    if not audits_dir.joinpath(expected_name).exists():
                        expected_missing.append(fid)
                if set(missing_ids_list) == set(expected_missing):
                    scores["audit_inventory_missing_facilities_list"] = 1.0

    # risk_summary.md existence and overview
    rs_text = _safe_read_text(risk_summary_md)
    if rs_text is not None:
        # Look for brief overview mentioning inputs and insurance
        first_lines = rs_text.splitlines()[:10]
        joined = "\n".join(first_lines).lower()
        if ("input" in joined) and ("insurance" in joined):
            scores["risk_summary_exists_and_overview"] = 1.0

    # risk_summary company totals
    if rs_text is not None and expected["facilities_ok"] and expected["incidents_ok"]:
        # Compute totals
        total_incidents = 0
        total_cost = 0.0
        # Aggregate incidents across all facilities
        inc_map = expected["incidents"]
        for fid in expected["facilities"].keys():
            agg = inc_map.get(fid, {"total_incidents": 0, "total_direct_cost_usd": 0.0})
            total_incidents += int(agg["total_incidents"])
            total_cost += float(agg["total_direct_cost_usd"])
        total_incidents_str = str(int(total_incidents))
        total_cost_str = _fmt2(total_cost)

        section_lines = _extract_section_lines(rs_text, "Company-wide totals")
        if section_lines is None:
            section_lines = _extract_section_lines(rs_text, "Company wide totals")
        if section_lines:
            tokens = _tokens_from_lines(section_lines)
            if (total_incidents_str in tokens) and (total_cost_str in tokens):
                scores["risk_summary_company_totals"] = 1.0

    # risk_summary top 3 section
    if rs_text is not None and expected_rows is not None:
        # Compute top 3 by composite_risk_score
        comp = []
        for r in expected_rows:
            comp.append((r["facility_id"], r["facility_name"], float(r["composite_risk_score"]), r))
        comp.sort(key=lambda x: (-x[2], x[0]))
        top3 = comp[:3]
        lines = rs_text.splitlines()
        top_idx = None
        for i, ln in enumerate(lines):
            if "Top 3 facilities by composite risk score".lower() in ln.lower():
                top_idx = i
                break
        top_lines = []
        if top_idx is not None:
            # Collect bullet lines after this index
            for j in range(top_idx + 1, len(lines)):
                ln = lines[j]
                if not ln.strip():
                    if top_lines:
                        break
                    else:
                        continue
                if ln.strip().startswith("-") or ln.strip().startswith("*"):
                    top_lines.append(ln.strip())
                else:
                    if top_lines:
                        break
                    # continue otherwise to skip non-bullets until first bullet
        if len(top_lines) == 3:
            # Validate content for each of the expected top 3 in order
            ok = True
            for i, (fid, name, comp_score, row) in enumerate(top3):
                ln = top_lines[i]
                # Required fields: facility_id, facility_name, composite_risk_score (2d), total_incidents, total_direct_cost_usd (2d), audit_compliance_percent/MISSING, training_completion_percent/UNKNOWN
                required_substrings = [
                    fid,
                    name,
                    _fmt2(comp_score),
                    row["total_incidents"],
                    row["total_direct_cost_usd"],
                ]
                # audit
                if row["audit_compliance_percent"] == "MISSING":
                    required_substrings.append("MISSING")
                else:
                    required_substrings.append(row["audit_compliance_percent"])
                # training
                if row["training_completion_percent"] == "UNKNOWN":
                    required_substrings.append("UNKNOWN")
                else:
                    required_substrings.append(row["training_completion_percent"])
                for sub in required_substrings:
                    if str(sub) not in ln:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                scores["risk_summary_top3_section"] = 1.0

    # risk_summary gaps/notes
    if rs_text is not None and expected["facilities_ok"]:
        gaps_lines = _extract_section_lines(rs_text, "Gaps/Notes")
        if gaps_lines is None:
            gaps_lines = _extract_section_lines(rs_text, "Gaps")
        if gaps_lines is not None:
            gaps_text = "\n".join(gaps_lines)
            audits_dir = workspace / "input" / "audits"
            missing_audit_ids = []
            for fid in expected["facilities"].keys():
                expected_name = f"facility_{fid}.json"
                if not audits_dir.joinpath(expected_name).exists():
                    missing_audit_ids.append(fid)
            # Facilities lacking training
            training_map = expected["training"]
            lacking_training_ids = []
            for fid in expected["facilities"].keys():
                if fid not in training_map:
                    lacking_training_ids.append(fid)
            ok_audit_listed = all(fid in gaps_text for fid in missing_audit_ids)
            ok_training_listed = all(fid in gaps_text for fid in lacking_training_ids)
            if ok_audit_listed and ok_training_listed:
                scores["risk_summary_gaps_notes"] = 1.0

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, indent=None, separators=(",", ":")))


if __name__ == "__main__":
    main()

import csv
import hashlib
import json
import re
import sys
from pathlib import Path
from typing import Dict, List, Optional, Tuple


def _read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _read_csv(path: Path) -> Optional[Tuple[List[str], List[List[str]]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.reader(f)
            rows = list(reader)
        if not rows:
            return None
        header = rows[0]
        data = rows[1:]
        return header, data
    except Exception:
        return None


def _compute_sha256(path: Path) -> Optional[str]:
    try:
        h = hashlib.sha256()
        with path.open("rb") as f:
            for chunk in iter(lambda: f.read(8192), b""):
                h.update(chunk)
        return h.hexdigest()
    except Exception:
        return None


def _count_nonempty_lines(path: Path) -> Optional[int]:
    try:
        count = 0
        with path.open("r", encoding="utf-8", newline="") as f:
            for line in f:
                if line.strip():
                    count += 1
        return count
    except Exception:
        return None


def _parse_recipients_emails(path: Path) -> Optional[List[str]]:
    parsed = _read_csv(path)
    if not parsed:
        return None
    header, rows = parsed
    try:
        email_idx = header.index("email")
    except ValueError:
        return None
    emails: List[str] = []
    for r in rows:
        if len(r) <= email_idx:
            return None
        emails.append(r[email_idx].strip())
    if not emails:
        return None
    return emails


def _parse_iris_csv_numeric(path: Path) -> Optional[Tuple[List[str], List[Tuple[float, float, float, float, str]]]]:
    parsed = _read_csv(path)
    if not parsed:
        return None
    header, rows = parsed
    expected_header = ["sepal_length", "sepal_width", "petal_length", "petal_width", "species"]
    if header != expected_header:
        return None
    parsed_rows: List[Tuple[float, float, float, float, str]] = []
    for r in rows:
        if len(r) != 5:
            return None
        try:
            sl = float(r[0].strip())
            sw = float(r[1].strip())
            pl = float(r[2].strip())
            pw = float(r[3].strip())
        except Exception:
            return None
        species = r[4].strip()
        if species == "":
            return None
        # Ensure species is categorical: not purely numeric
        try:
            _ = float(species)
            return None
        except Exception:
            pass
        parsed_rows.append((sl, sw, pl, pw, species))
    return header, parsed_rows


def _compute_species_stats(rows: List[Tuple[float, float, float, float, str]]) -> Dict[str, Dict[str, str]]:
    # Returns mapping: species -> {'count': str(int), 'mean_sepal_length': 'x.xxx', ...}
    agg: Dict[str, Dict[str, float]] = {}
    counts: Dict[str, int] = {}
    for sl, sw, pl, pw, sp in rows:
        if sp not in agg:
            agg[sp] = {"sl": 0.0, "sw": 0.0, "pl": 0.0, "pw": 0.0}
            counts[sp] = 0
        agg[sp]["sl"] += sl
        agg[sp]["sw"] += sw
        agg[sp]["pl"] += pl
        agg[sp]["pw"] += pw
        counts[sp] += 1
    out: Dict[str, Dict[str, str]] = {}
    for sp in sorted(agg.keys()):
        c = counts[sp]
        if c == 0:
            # Avoid division by zero: leave out
            continue
        msl = agg[sp]["sl"] / c
        msw = agg[sp]["sw"] / c
        mpl = agg[sp]["pl"] / c
        mpw = agg[sp]["pw"] / c
        out[sp] = {
            "count": str(c),
            "mean_sepal_length": f"{msl:.3f}",
            "mean_sepal_width": f"{msw:.3f}",
            "mean_petal_length": f"{mpl:.3f}",
            "mean_petal_width": f"{mpw:.3f}",
        }
    return out


def _parse_species_stats_csv(path: Path) -> Optional[Tuple[List[str], Dict[str, Dict[str, str]]]]:
    parsed = _read_csv(path)
    if not parsed:
        return None
    header, rows = parsed
    expected_header = [
        "species",
        "count",
        "mean_sepal_length",
        "mean_sepal_width",
        "mean_petal_length",
        "mean_petal_width",
    ]
    if header != expected_header:
        return None
    result: Dict[str, Dict[str, str]] = {}
    for r in rows:
        if len(r) != 6:
            return None
        species = r[0].strip()
        count_str = r[1].strip()
        msl_str = r[2].strip()
        msw_str = r[3].strip()
        mpl_str = r[4].strip()
        mpw_str = r[5].strip()
        # Validate count is integer
        if not re.fullmatch(r"\d+", count_str):
            return None
        # Validate means are numeric and with 3 decimals when formatted
        try:
            msl_val = float(msl_str)
            msw_val = float(msw_str)
            mpl_val = float(mpl_str)
            mpw_val = float(mpw_str)
        except Exception:
            return None
        # Ensure they have exactly 3 decimal places (string format or match pattern)
        # Accept if the string representation exactly equals formatted with 3 decimals
        if msl_str != f"{msl_val:.3f}" or msw_str != f"{msw_val:.3f}" or mpl_str != f"{mpl_val:.3f}" or mpw_str != f"{mpw_val:.3f}":
            return None
        result[species] = {
            "count": count_str,
            "mean_sepal_length": msl_str,
            "mean_sepal_width": msw_str,
            "mean_petal_length": mpl_str,
            "mean_petal_width": mpw_str,
        }
    return header, result


def _parse_email_draft_lines(path: Path) -> Optional[List[str]]:
    txt = _read_text(path)
    if txt is None:
        return None
    # Normalize newlines to '\n', strip trailing spaces on each line for robust comparison where appropriate.
    lines = [line.rstrip("\r\n") for line in txt.splitlines()]
    return lines


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores: Dict[str, float] = {
        "iris_raw_file_exists": 0.0,
        "iris_sha256_correct": 0.0,
        "iris_csv_header_and_types_valid": 0.0,
        "iris_csv_row_count_matches_raw": 0.0,
        "species_stats_header_and_format_valid": 0.0,
        "species_stats_matches_computed": 0.0,
        "species_count_total_matches_rows": 0.0,
        "email_to_and_subject_valid": 0.0,
        "email_includes_source_line": 0.0,
        "email_totals_checksum_and_species_lines_valid": 0.0,
    }

    # Paths
    raw_path = workspace / "downloads" / "iris.data"
    sha_path = workspace / "outputs" / "iris.sha256"
    iris_csv_path = workspace / "data" / "iris.csv"
    stats_csv_path = workspace / "outputs" / "species_stats.csv"
    email_path = workspace / "outputs" / "email_draft.txt"
    recipients_path = workspace / "input" / "recipients.csv"

    # 1) Raw file presence
    if raw_path.exists() and raw_path.is_file():
        # Non-empty check
        nonempty = False
        try:
            with raw_path.open("rb") as f:
                chunk = f.read(1)
                if chunk:
                    nonempty = True
        except Exception:
            nonempty = False
        if nonempty:
            scores["iris_raw_file_exists"] = 1.0

    # 1) SHA-256 correctness
    sha_expected = None
    raw_hash = None
    if sha_path.exists() and sha_path.is_file() and raw_path.exists():
        sha_text = _read_text(sha_path)
        raw_hash = _compute_sha256(raw_path)
        if sha_text is not None and raw_hash is not None:
            digest = sha_text.strip()
            # Must be exactly 64 hex chars
            if re.fullmatch(r"[0-9a-f]{64}", digest) is not None:
                sha_expected = digest
                if digest == raw_hash:
                    scores["iris_sha256_correct"] = 1.0

    # 2) Parse data/iris.csv header and numeric types
    iris_parsed = _parse_iris_csv_numeric(iris_csv_path)
    total_rows_csv = None
    if iris_parsed is not None:
        _, iris_rows = iris_parsed
        total_rows_csv = len(iris_rows)
        # Validity already enforced by parser
        scores["iris_csv_header_and_types_valid"] = 1.0

    # 2) Row count matches raw
    if raw_path.exists() and iris_parsed is not None:
        raw_nonempty_count = _count_nonempty_lines(raw_path)
        if raw_nonempty_count is not None and total_rows_csv is not None:
            if raw_nonempty_count == total_rows_csv:
                scores["iris_csv_row_count_matches_raw"] = 1.0

    # 3) Species stats header and format validity
    stats_parsed = _parse_species_stats_csv(stats_csv_path)
    if stats_parsed is not None:
        scores["species_stats_header_and_format_valid"] = 1.0

    # 3) Aggregates match computed from iris.csv
    if iris_parsed is not None and stats_parsed is not None:
        _, iris_rows = iris_parsed
        _, stats_map = stats_parsed
        computed = _compute_species_stats(iris_rows)
        # Ensure sets equal
        if set(computed.keys()) == set(stats_map.keys()):
            # Compare per species values exactly
            all_ok = True
            for sp, vals in computed.items():
                target = stats_map.get(sp)
                if target is None:
                    all_ok = False
                    break
                if target.get("count") != vals.get("count"):
                    all_ok = False
                    break
                for k in ["mean_sepal_length", "mean_sepal_width", "mean_petal_length", "mean_petal_width"]:
                    if target.get(k) != vals.get(k):
                        all_ok = False
                        break
                if not all_ok:
                    break
            if all_ok:
                scores["species_stats_matches_computed"] = 1.0

    # 3) Counts sum equals total rows in data/iris.csv
    if stats_parsed is not None and iris_parsed is not None:
        _, stats_map2 = stats_parsed
        try:
            sum_counts = sum(int(v["count"]) for v in stats_map2.values())
            if total_rows_csv is not None and sum_counts == total_rows_csv:
                scores["species_count_total_matches_rows"] = 1.0
        except Exception:
            pass

    # 4) Email draft checks
    email_lines = _parse_email_draft_lines(email_path) if email_path.exists() else None
    recipients_emails = _parse_recipients_emails(recipients_path) if recipients_path.exists() else None

    # To and Subject validity
    if email_lines is not None and len(email_lines) >= 2 and recipients_emails is not None:
        # To: line
        to_line = email_lines[0].strip()
        if to_line.startswith("To:"):
            # accept "To: " with optional space after colon
            to_payload = to_line[len("To:"):].strip()
            split_emails = [e.strip() for e in to_payload.split(",")] if to_payload else []
            if split_emails == recipients_emails:
                # Subject line: accept both ASCII hyphen and non-breaking hyphen variants
                subject_line = email_lines[1].strip()
                subj_ok_variants = [
                    "Subject: Iris dataset summary for cross-platform demo",
                    "Subject: Iris dataset summary for cross‑platform demo",
                ]
                if subject_line in subj_ok_variants:
                    scores["email_to_and_subject_valid"] = 1.0

    # Source line presence
    if email_lines is not None:
        source_ok = False
        for line in email_lines[2:] if len(email_lines) > 2 else []:
            lwr = line.strip()
            if "UCI Machine Learning Repository" in lwr and "Iris dataset" in lwr:
                source_ok = True
                break
        if source_ok:
            scores["email_includes_source_line"] = 1.0

    # Totals, checksum, and species lines validation
    # This check depends on email, iris.csv, species_stats.csv, and iris.sha256 being present/valid
    if email_lines is not None and iris_parsed is not None and stats_parsed is not None:
        _, iris_rows2 = iris_parsed
        _, stats_map3 = stats_parsed
        total_expected = len(iris_rows2)

        # Find Total rows line
        total_line_n = None
        for line in email_lines:
            m = re.fullmatch(r"Total rows:\s*(\d+)\s*", line.strip())
            if m:
                try:
                    total_line_n = int(m.group(1))
                    break
                except Exception:
                    total_line_n = None
        # Find checksum line
        checksum_line_hex = None
        for line in email_lines:
            m = re.fullmatch(r"Checksum\s*\(SHA-256\):\s*([0-9a-fA-F]{64})\s*", line.strip())
            if m:
                checksum_line_hex = m.group(1).lower()
                break

        # Prepare expected species lines strings exactly
        expected_species_lines = set()
        for sp, vals in stats_map3.items():
            expected_line = (
                f"{sp}: count={vals['count']}, "
                f"mean_sepal_length={vals['mean_sepal_length']}, "
                f"mean_sepal_width={vals['mean_sepal_width']}, "
                f"mean_petal_length={vals['mean_petal_length']}, "
                f"mean_petal_width={vals['mean_petal_width']}"
            )
            expected_species_lines.add(expected_line)

        # Check presence of all expected lines (order not enforced)
        email_body_lines = set([l.strip() for l in email_lines])
        species_lines_ok = expected_species_lines.issubset(email_body_lines)

        # Check checksum consistency with outputs/iris.sha256
        sha_file_hex = None
        if sha_path.exists():
            sha_text2 = _read_text(sha_path)
            if sha_text2 is not None:
                dt = sha_text2.strip()
                if re.fullmatch(r"[0-9a-f]{64}", dt):
                    sha_file_hex = dt

        checks_ok = True
        if total_line_n is None or total_line_n != total_expected:
            checks_ok = False
        if sha_file_hex is None or checksum_line_hex is None or checksum_line_hex != sha_file_hex:
            checks_ok = False
        if not species_lines_ok:
            checks_ok = False

        if checks_ok:
            # Also verify that the sum of species counts equals the "Total rows" reported in email
            try:
                sum_counts_email = sum(int(v["count"]) for v in stats_map3.values())
                if sum_counts_email != total_line_n:
                    checks_ok = False
            except Exception:
                checks_ok = False

        if checks_ok:
            scores["email_totals_checksum_and_species_lines_valid"] = 1.0

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

import csv
import json
import sys
import re
from datetime import datetime, timedelta
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Any


EXPECTED_HEADER = [
    "contact_name",
    "community",
    "preferred_channel",
    "due_date",
    "subject",
    "message",
    "source_file",
]

INTERVIEW_KEYS = {
    "contact_name",
    "community",
    "last_contacted",
    "preferred_channel",
    "time_zone",
    "consent_status",
    "priority",
    "archived",
    "follow_up_required",
    "subject_hint",
    "message_hint",
}

MD_START_MARKER = "<!-- PENDING-FOLLOWUPS:START -->"
MD_END_MARKER = "<!-- PENDING-FOLLOWUPS:END -->"


def _read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _safe_load_json(path: Path) -> Optional[Any]:
    if not path.exists():
        return None
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None


def _safe_parse_csv(path: Path) -> Tuple[Optional[List[str]], Optional[List[Dict[str, str]]]]:
    if not path.exists():
        return None, None
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.reader(f)
            rows = list(reader)
        if not rows:
            return None, None
        header = rows[0]
        data_rows: List[Dict[str, str]] = []
        for row in rows[1:]:
            if len(row) != len(header):
                return None, None
            data_rows.append({header[j]: row[j] for j in range(len(header))})
        return header, data_rows
    except Exception:
        return None, None


def _list_md_files(dir_path: Path) -> List[Path]:
    if not dir_path.exists():
        return []
    try:
        return sorted([p for p in dir_path.iterdir() if p.is_file() and p.suffix.lower() == ".md"])
    except Exception:
        return []


def _parse_interview_metadata(md_text: str) -> Dict[str, str]:
    meta: Dict[str, str] = {}
    for line in md_text.splitlines():
        if ":" not in line:
            continue
        key_part, value_part = line.split(":", 1)
        key = key_part.strip()
        value = value_part.strip()
        if key in INTERVIEW_KEYS:
            meta[key] = value
    return meta


def _parse_date(date_str: str) -> Optional[datetime]:
    try:
        return datetime.strptime(date_str, "%Y-%m-%d")
    except Exception:
        return None


def _compute_due_date(last_contacted: str, priority: str) -> Optional[str]:
    base = _parse_date(last_contacted)
    if base is None:
        return None
    pr = (priority or "").strip().lower()
    delta_days = {"high": 7, "normal": 14, "low": 21}.get(pr)
    if delta_days is None:
        return None
    due = base + timedelta(days=delta_days)
    return due.strftime("%Y-%m-%d")


def _eligible(meta: Dict[str, str]) -> bool:
    archived = (meta.get("archived", "").strip().lower() == "true")
    consent_declined = (meta.get("consent_status", "").strip().lower() == "declined")
    follow_up_required = (meta.get("follow_up_required", "").strip().lower() == "yes")
    return (not archived) and (not consent_declined) and follow_up_required


def _compute_expected_reminders(workspace: Path) -> List[Dict[str, str]]:
    interviews_dir = workspace / "input" / "interviews"
    reminders: List[Dict[str, str]] = []
    for md_path in _list_md_files(interviews_dir):
        text = _read_text(md_path)
        if text is None:
            continue
        meta = _parse_interview_metadata(text)
        if not _eligible(meta):
            continue
        cn = meta.get("contact_name")
        comm = meta.get("community")
        lc = meta.get("last_contacted")
        ch = meta.get("preferred_channel")
        pr = meta.get("priority")
        subj = meta.get("subject_hint")
        msg = meta.get("message_hint")
        if not all([cn, comm, lc, ch, pr, subj, msg]):
            continue
        due = _compute_due_date(lc, pr)
        if due is None:
            continue
        reminders.append({
            "contact_name": cn,
            "community": comm,
            "preferred_channel": ch,
            "due_date": due,
            "subject": subj,
            "message": msg,
            "source_file": str(Path("input") / "interviews" / md_path.name),
        })
    reminders.sort(key=lambda r: r["due_date"])
    return reminders


def _extract_followup_section(text: str) -> Optional[str]:
    start_idx = text.find(MD_START_MARKER)
    end_idx = text.find(MD_END_MARKER)
    if start_idx == -1 or end_idx == -1 or end_idx < start_idx:
        return None
    start_end = start_idx + len(MD_START_MARKER)
    return text[start_end:end_idx]


def _get_bullet_lines_in_section(text: str) -> Optional[List[str]]:
    section = _extract_followup_section(text)
    if section is None:
        return None
    lines = [line.strip() for line in section.splitlines()]
    bullets = [line for line in lines if line.startswith("- [ ]")]
    return bullets


def _build_expected_bullets(reminders: List[Dict[str, str]]) -> List[str]:
    bullets: List[str] = []
    for r in reminders:
        bullets.append(f"- [ ] {r['due_date']} {r['contact_name']} via {r['preferred_channel']} ({r['community']}) — {r['subject']}")
    return bullets


def _csv_rows_to_tuples(rows: List[Dict[str, str]]) -> List[Tuple[str, str, str, str, str, str, str]]:
    tuples: List[Tuple[str, str, str, str, str, str, str]] = []
    for row in rows:
        try:
            tuples.append((
                row["contact_name"],
                row["community"],
                row["preferred_channel"],
                row["due_date"],
                row["subject"],
                row["message"],
                row["source_file"],
            ))
        except KeyError:
            return []
    return tuples


def _expected_rows_to_tuples(reminders: List[Dict[str, str]]) -> List[Tuple[str, str, str, str, str, str, str]]:
    return [
        (
            r["contact_name"],
            r["community"],
            r["preferred_channel"],
            r["due_date"],
            r["subject"],
            r["message"],
            r["source_file"],
        )
        for r in reminders
    ]


def _counts_from_rows(rows: List[Dict[str, str]]) -> Tuple[int, Dict[str, int], Dict[str, int]]:
    total = len(rows)
    by_comm: Dict[str, int] = {}
    by_channel: Dict[str, int] = {}
    for r in rows:
        c = r.get("community", "")
        ch = r.get("preferred_channel", "")
        by_comm[c] = by_comm.get(c, 0) + 1
        by_channel[ch] = by_channel.get(ch, 0) + 1
    return total, by_comm, by_channel


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores: Dict[str, float] = {
        "csv_header_correct": 0.0,
        "csv_rows_count_expected": 0.0,
        "csv_rows_match_expected_content": 0.0,
        "csv_sorted_by_due_date": 0.0,
        "md_bullets_count_matches_csv": 0.0,
        "md_bullets_exact_expected_ordered": 0.0,
        "summary_json_shape_valid": 0.0,
        "summary_counts_match_csv": 0.0,
        "cross_counts_consistent": 0.0,
        "summary_total_matches_expected": 0.0,
    }

    expected_reminders = _compute_expected_reminders(workspace)
    expected_count = len(expected_reminders)
    expected_bullets = _build_expected_bullets(expected_reminders)
    expected_tuples = _expected_rows_to_tuples(expected_reminders)

    csv_path = workspace / "output" / "followups" / "reminders.csv"
    header, csv_rows = _safe_parse_csv(csv_path)

    if header is not None and header == EXPECTED_HEADER:
        scores["csv_header_correct"] = 1.0

    if csv_rows is not None and len(csv_rows) == expected_count:
        scores["csv_rows_count_expected"] = 1.0

    if csv_rows is not None and header == EXPECTED_HEADER:
        actual_tuples = _csv_rows_to_tuples(csv_rows)
        if actual_tuples and expected_tuples and actual_tuples == expected_tuples:
            scores["csv_rows_match_expected_content"] = 1.0
        elif actual_tuples and expected_tuples:
            # Allow set equality if order check is handled separately
            if set(actual_tuples) == set(expected_tuples) and len(actual_tuples) == len(expected_tuples):
                scores["csv_rows_match_expected_content"] = 1.0

    if csv_rows is not None and header is not None and "due_date" in header:
        due_dates: List[Optional[datetime]] = []
        ok = True
        for r in csv_rows:
            dt = _parse_date(r.get("due_date", ""))
            if dt is None:
                ok = False
                break
            due_dates.append(dt)
        if ok and all(due_dates[i] <= due_dates[i + 1] for i in range(len(due_dates) - 1)):
            scores["csv_sorted_by_due_date"] = 1.0

    md_path = workspace / "docs" / "Follow-Up.md"
    md_text = _read_text(md_path)
    bullets = _get_bullet_lines_in_section(md_text) if md_text is not None else None

    if bullets is not None and csv_rows is not None:
        if len(bullets) == len(csv_rows):
            scores["md_bullets_count_matches_csv"] = 1.0

    if bullets is not None and expected_bullets:
        if bullets == expected_bullets:
            scores["md_bullets_exact_expected_ordered"] = 1.0

    summary_path = workspace / "output" / "followups" / "summary.json"
    summary = _safe_load_json(summary_path)

    if isinstance(summary, dict):
        has_keys = all(k in summary for k in ["total_reminders", "by_community", "by_channel"])
        types_ok = (
            isinstance(summary.get("total_reminders"), int)
            and isinstance(summary.get("by_community"), dict)
            and isinstance(summary.get("by_channel"), dict)
        )
        if has_keys and types_ok:
            by_comm_ok = all(isinstance(v, int) for v in summary.get("by_community", {}).values())
            by_chan_ok = all(isinstance(v, int) for v in summary.get("by_channel", {}).values())
            if by_comm_ok and by_chan_ok:
                scores["summary_json_shape_valid"] = 1.0

    if isinstance(summary, dict) and csv_rows is not None:
        total, by_comm, by_chan = _counts_from_rows(csv_rows)
        if summary.get("total_reminders") == total and summary.get("by_community") == by_comm and summary.get("by_channel") == by_chan:
            scores["summary_counts_match_csv"] = 1.0

    if isinstance(summary, dict) and csv_rows is not None and bullets is not None:
        if summary.get("total_reminders") == len(csv_rows) == len(bullets):
            scores["cross_counts_consistent"] = 1.0

    if isinstance(summary, dict):
        if summary.get("total_reminders") == expected_count:
            scores["summary_total_matches_expected"] = 1.0

    return scores


def main() -> None:
    workspace_path = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace_path)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

import json
import sys
import csv
import re
from pathlib import Path
from typing import List, Dict, Tuple, Optional


def _read_text_lines(path: Path) -> Optional[List[str]]:
    try:
        return path.read_text(encoding="utf-8", errors="replace").splitlines()
    except Exception:
        return None


def _load_json(path: Path) -> Optional[dict]:
    try:
        return json.loads(path.read_text(encoding="utf-8", errors="replace"))
    except Exception:
        return None


def _load_csv_rows(path: Path) -> Optional[Tuple[List[str], List[List[str]]]]:
    try:
        text = path.read_text(encoding="utf-8", errors="replace").splitlines()
        if not text:
            return None
        reader = csv.reader(text)
        rows = list(reader)
        if not rows:
            return None
        header = rows[0]
        data = rows[1:]
        return header, data
    except Exception:
        return None


def _to_gb(size_str: str) -> Optional[float]:
    # Converts human-readable sizes like "120G" to GB float
    try:
        s = size_str.strip()
        if not s:
            return None
        # Extract number and unit
        match = re.match(r"^\s*([\d\.]+)\s*([KMGTP]?)(i?B)?\s*$", s, re.IGNORECASE)
        if match:
            num = float(match.group(1))
            unit = match.group(2).upper()
            # Convert to GB
            if unit == "T":
                return num * 1024.0
            if unit == "G" or unit == "":
                return num
            if unit == "M":
                return num / 1024.0
            if unit == "K":
                return num / (1024.0 * 1024.0)
            if unit == "P":
                return num * 1024.0 * 1024.0
            return num
        # If pure number
        return float(s)
    except Exception:
        return None


def _parse_df_output(path: Path) -> Optional[Dict[str, float]]:
    lines = _read_text_lines(path)
    if lines is None:
        return None
    for line in lines:
        if not line.strip():
            continue
        if line.strip().startswith("Filesystem"):
            continue
        parts = line.split()
        # Expect: Filesystem Size Used Avail Use% Mounted_on
        if len(parts) < 6:
            continue
        mount = parts[-1]
        if mount == "/":
            size = _to_gb(parts[1])
            used = _to_gb(parts[2])
            use_pct_str = parts[4].strip()
            if use_pct_str.endswith("%"):
                use_pct_str = use_pct_str[:-1]
            try:
                used_pct = float(use_pct_str)
            except Exception:
                return None
            if size is None or used is None:
                return None
            return {"total_gb": float(size), "used_gb": float(used), "used_pct": float(used_pct)}
    return None


def _parse_free_output(path: Path) -> Optional[Dict[str, float]]:
    lines = _read_text_lines(path)
    if lines is None:
        return None
    for line in lines:
        if line.strip().startswith("Mem:"):
            parts = line.split()
            # parts: ["Mem:", total, used, free, shared, buff/cache, available]
            if len(parts) < 3:
                return None
            try:
                total = float(parts[1])
                used = float(parts[2])
            except Exception:
                return None
            used_pct = round((used / total) * 100.0, 1) if total > 0 else 0.0
            return {"total_mb": total, "used_mb": used, "used_pct": used_pct}
    return None


def _parse_ps_output(path: Path) -> Optional[Dict[str, object]]:
    lines = _read_text_lines(path)
    if lines is None or not lines:
        return None
    header_line = None
    for i, line in enumerate(lines):
        if line.strip().startswith("USER"):
            header_line = line
            start_idx = i + 1
            break
    if header_line is None:
        return None
    header_tokens = header_line.split()
    if "USER" not in header_tokens or "PID" not in header_tokens or "%MEM" not in header_tokens or "COMMAND" not in header_tokens:
        return None
    idx_user = header_tokens.index("USER")
    idx_pid = header_tokens.index("PID")
    idx_mem = header_tokens.index("%MEM")
    idx_cmd = header_tokens.index("COMMAND")
    top = None  # tuple (mem_pct, user, pid, command)
    for line in lines[start_idx:]:
        if not line.strip():
            continue
        tokens = line.split()
        if len(tokens) <= idx_cmd:
            continue
        try:
            user = tokens[idx_user]
            pid = int(tokens[idx_pid])
            mem_pct = float(tokens[idx_mem])
            command = " ".join(tokens[idx_cmd:])
        except Exception:
            continue
        if (top is None) or (mem_pct > top[0]):
            top = (mem_pct, user, pid, command)
    if top is None:
        return None
    return {"user": top[1], "pid": top[2], "mem_pct": top[0], "command": top[3]}


def _list_log_files(logs_dir: Path) -> List[Path]:
    if not logs_dir.exists() or not logs_dir.is_dir():
        return []
    return sorted([p for p in logs_dir.iterdir() if p.is_file() and p.name.endswith(".log")])


def _count_logs_and_errors(log_files: List[Path]) -> Tuple[Dict[str, Dict[str, int]], Dict[str, int]]:
    per_file_counts: Dict[str, Dict[str, int]] = {}
    error_messages: Dict[str, int] = {}
    for lf in log_files:
        lines = _read_text_lines(lf) or []
        fcounts = {"ERROR": 0, "WARN": 0}
        for line in lines:
            if "ERROR" in line:
                fcounts["ERROR"] += 1
                # Extract message after literal "ERROR:"
                idx = line.find("ERROR:")
                if idx != -1:
                    msg = line[idx + len("ERROR:"):].strip()
                    if msg:
                        error_messages[msg] = error_messages.get(msg, 0) + 1
            if "WARN" in line:
                fcounts["WARN"] += 1
        # Only include levels that appear (count > 0)
        per_file_counts[lf.name] = {k: v for k, v in fcounts.items() if v > 0}
    return per_file_counts, error_messages


def _parse_du_tours(path: Path) -> Optional[List[Tuple[str, float]]]:
    lines = _read_text_lines(path)
    if lines is None:
        return None
    result: List[Tuple[str, float]] = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        m = re.match(r"^\s*([\d\.]+)\s+(.+)$", line)
        if not m:
            return None
        try:
            size_mb = float(m.group(1))
            subdir = m.group(2).strip()
            result.append((subdir, size_mb))
        except Exception:
            return None
    if not result:
        return None
    return result


def _approx_equal(a: float, b: float, tol: float = 0.05) -> bool:
    return abs(float(a) - float(b)) <= tol


def _approx_equal_1dp(a: float, b: float) -> bool:
    # tighter tolerance for values rounded to 1 decimal place
    return abs(float(a) - float(b)) <= 0.1


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "health_summary_disk": 0.0,
        "health_summary_memory": 0.0,
        "health_summary_top_process": 0.0,
        "health_summary_log_totals": 0.0,
        "tours_storage_csv": 0.0,
        "log_summary_csv": 0.0,
        "top_errors_csv": 0.0,
        "health_report_opener": 0.0,
        "health_report_disk_summary": 0.0,
        "health_report_memory_summary": 0.0,
        "health_report_top_process": 0.0,
        "health_report_log_totals": 0.0,
        "health_report_top_three_errors": 0.0,
        "health_report_references": 0.0,
    }

    # Input paths
    df_path = workspace / "input" / "snapshots" / "df_output.txt"
    free_path = workspace / "input" / "snapshots" / "free_output.txt"
    ps_path = workspace / "input" / "snapshots" / "ps_output.txt"
    du_tours_path = workspace / "input" / "snapshots" / "du_tours_mb.txt"
    logs_dir = workspace / "input" / "logs"

    # Output paths
    health_summary_path = workspace / "output" / "health_summary.json"
    tours_storage_path = workspace / "output" / "tours_storage.csv"
    log_summary_path = workspace / "output" / "log_summary.csv"
    top_errors_path = workspace / "output" / "top_errors.csv"
    health_report_path = workspace / "output" / "health_report.md"

    # Compute expected values
    expected_disk = _parse_df_output(df_path)
    expected_mem = _parse_free_output(free_path)
    expected_top_proc = _parse_ps_output(ps_path)

    log_files = _list_log_files(logs_dir)
    per_file_counts, error_messages = _count_logs_and_errors(log_files)

    expected_errors_total = None
    expected_warnings_total = None
    if log_files:
        expected_errors_total = sum(per_file_counts.get(p.name, {}).get("ERROR", 0) for p in log_files)
        expected_warnings_total = sum(per_file_counts.get(p.name, {}).get("WARN", 0) for p in log_files)

    # 1) health_summary.json checks
    hs = _load_json(health_summary_path)
    if hs and isinstance(hs, dict):
        # Disk
        if expected_disk is not None and isinstance(hs.get("disk"), dict):
            disk = hs.get("disk")
            try:
                tg = float(disk.get("total_gb"))
                ug = float(disk.get("used_gb"))
                up = float(disk.get("used_pct"))
                if _approx_equal(tg, expected_disk["total_gb"]) and _approx_equal(ug, expected_disk["used_gb"]) and _approx_equal(up, expected_disk["used_pct"]):
                    scores["health_summary_disk"] = 1.0
            except Exception:
                pass
        # Memory
        if expected_mem is not None and isinstance(hs.get("memory"), dict):
            mem = hs.get("memory")
            try:
                tm = float(mem.get("total_mb"))
                um = float(mem.get("used_mb"))
                upct = float(mem.get("used_pct"))
                if _approx_equal(tm, expected_mem["total_mb"]) and _approx_equal(um, expected_mem["used_mb"]) and _approx_equal_1dp(upct, expected_mem["used_pct"]):
                    scores["health_summary_memory"] = 1.0
            except Exception:
                pass
        # Top memory process
        if expected_top_proc is not None and isinstance(hs.get("top_memory_process"), dict):
            tp = hs.get("top_memory_process")
            try:
                user_ok = str(tp.get("user")) == expected_top_proc["user"]
                pid_ok = int(tp.get("pid")) == int(expected_top_proc["pid"])
                mem_ok = _approx_equal(float(tp.get("mem_pct")), float(expected_top_proc["mem_pct"]))
                cmd_ok = str(tp.get("command")) == expected_top_proc["command"]
                if user_ok and pid_ok and mem_ok and cmd_ok:
                    scores["health_summary_top_process"] = 1.0
            except Exception:
                pass
        # Logs totals
        if expected_errors_total is not None and expected_warnings_total is not None and isinstance(hs.get("logs"), dict):
            lg = hs.get("logs")
            try:
                eok = int(lg.get("errors_total")) == int(expected_errors_total)
                wok = int(lg.get("warnings_total")) == int(expected_warnings_total)
                if eok and wok:
                    scores["health_summary_log_totals"] = 1.0
            except Exception:
                pass

    # 2) tours_storage.csv checks
    expected_tours = _parse_du_tours(du_tours_path)
    if expected_tours is not None:
        # Build expected map: subdir -> (size_mb, percent_rounded_1dp)
        total_mb = sum(v for _, v in expected_tours)
        expected_rows = []
        for subdir, size in expected_tours:
            pct = round((size / total_mb) * 100.0, 1) if total_mb > 0 else 0.0
            expected_rows.append((subdir, size, pct))
        loaded = _load_csv_rows(tours_storage_path)
        if loaded:
            header, data = loaded
            if header == ["subdir", "size_mb", "percent_of_total"]:
                # Parse rows
                got_rows = []
                ok_parse = True
                for row in data:
                    if len(row) != 3:
                        ok_parse = False
                        break
                    subdir = row[0]
                    try:
                        size_mb = float(row[1])
                        pct = float(row[2])
                    except Exception:
                        ok_parse = False
                        break
                    got_rows.append((subdir, size_mb, pct))
                if ok_parse:
                    # Compare ignoring order; require all expected and no extras
                    def match_row(g, exp):
                        return (g[0] == exp[0]) and _approx_equal(g[1], exp[1]) and _approx_equal_1dp(g[2], exp[2])
                    unmatched_expected = expected_rows.copy()
                    matched = []
                    for g in got_rows:
                        found = None
                        for e in unmatched_expected:
                            if match_row(g, e):
                                found = e
                                break
                        if found:
                            matched.append(g)
                            unmatched_expected.remove(found)
                        else:
                            # extra or mismatched row
                            unmatched_expected = None
                            break
                    if unmatched_expected == [] and len(matched) == len(expected_rows):
                        scores["tours_storage_csv"] = 1.0

    # 3) log_summary.csv checks
    if log_files:
        # Build expected rows sorted by file asc, level asc ("ERROR" then "WARN")
        expected_log_rows = []
        for f in sorted([p.name for p in log_files]):
            counts = per_file_counts.get(f, {})
            for level in ["ERROR", "WARN"]:
                if counts.get(level, 0) > 0:
                    expected_log_rows.append([f, level, str(counts[level])])
        loaded = _load_csv_rows(log_summary_path)
        if loaded:
            header, data = loaded
            if header == ["file", "level", "count"]:
                # Verify sorting: by file asc, then level asc
                sorted_data = sorted(data, key=lambda r: (r[0], r[1]))
                if data == sorted_data:
                    # Compare equality with expected
                    # Also ensure counts are exact integers
                    try:
                        ok_int = all(row[2].strip().isdigit() for row in data)
                    except Exception:
                        ok_int = False
                    if ok_int and data == expected_log_rows:
                        scores["log_summary_csv"] = 1.0

    # 4) top_errors.csv checks
    if log_files:
        # Aggregate and sort: count desc, message asc
        items = list(error_messages.items())
        items.sort(key=lambda kv: (-kv[1], kv[0]))
        expected_top_errors = [[msg, str(cnt)] for msg, cnt in items]
        loaded = _load_csv_rows(top_errors_path)
        if loaded:
            header, data = loaded
            if header == ["message", "count"]:
                # Validate counts as integers and exact order/content
                try:
                    counts_ok = all(row[1].strip().isdigit() for row in data)
                except Exception:
                    counts_ok = False
                if counts_ok and data == expected_top_errors:
                    scores["top_errors_csv"] = 1.0

    # 5) health_report.md checks
    # Build expected facts for matching
    expected_top3_msgs = []
    if log_files:
        items = list(error_messages.items())
        items.sort(key=lambda kv: (-kv[1], kv[0]))
        expected_top3_msgs = items[:3]

    report_lines = _read_text_lines(health_report_path)
    if report_lines is not None:
        text = "\n".join(report_lines)
        # opener: first line contains "Keelung" (case-insensitive)
        if report_lines:
            first_line = report_lines[0].strip()
            if first_line and re.search(r"keelung", first_line, re.IGNORECASE):
                scores["health_report_opener"] = 1.0
        # disk summary: line containing "Disk" and expected numbers
        if expected_disk is not None:
            numbers_ok = False
            for line in report_lines:
                if re.search(r"disk", line, re.IGNORECASE):
                    if all(str(int(expected_disk[k] if k != "used_pct" else int(expected_disk[k]))) in line for k in ["total_gb", "used_gb", "used_pct"]):
                        numbers_ok = True
                        break
                    # fallback for float formatting: check as plain numbers
                    if (str(int(expected_disk["total_gb"])) in line and
                        str(int(expected_disk["used_gb"])) in line and
                        re.search(rf"\b{int(expected_disk['used_pct'])}\b", line)):
                        numbers_ok = True
                        break
            if numbers_ok:
                scores["health_report_disk_summary"] = 1.0
        # memory summary: line containing "Memory" and expected numbers including 1dp percent
        if expected_mem is not None:
            mem_ok = False
            upct_str = f"{expected_mem['used_pct']:.1f}"
            for line in report_lines:
                if re.search(r"memory", line, re.IGNORECASE):
                    if (str(int(expected_mem["total_mb"])) in line and
                        str(int(expected_mem["used_mb"])) in line and
                        upct_str in line):
                        mem_ok = True
                        break
            if mem_ok:
                scores["health_report_memory_summary"] = 1.0
        # top process presence: ensure user, pid, mem_pct, and command all present in file
        if expected_top_proc is not None:
            try:
                if (re.search(rf"\b{re.escape(str(expected_top_proc['user']))}\b", text) and
                    re.search(rf"\b{int(expected_top_proc['pid'])}\b", text) and
                    re.search(rf"\b{float(expected_top_proc['mem_pct']):.1f}\b", text) and
                    expected_top_proc["command"] in text):
                    scores["health_report_top_process"] = 1.0
            except Exception:
                pass
        # totals of ERROR and WARN
        if expected_errors_total is not None and expected_warnings_total is not None:
            err_ok = any(("ERROR" in line and re.search(rf"\b{expected_errors_total}\b", line)) for line in report_lines)
            warn_ok = any(("WARN" in line and re.search(rf"\b{expected_warnings_total}\b", line)) for line in report_lines)
            if err_ok and warn_ok:
                scores["health_report_log_totals"] = 1.0
        # top three error messages with their counts in order
        if expected_top3_msgs:
            # Find lines that contain these messages and verify order and that count appears in the same line
            order_indices = []
            success = True
            for msg, cnt in expected_top3_msgs:
                found_idx = -1
                for idx, line in enumerate(report_lines):
                    if msg in line and re.search(rf"\b{cnt}\b", line):
                        found_idx = idx
                        break
                if found_idx == -1:
                    success = False
                    break
                order_indices.append(found_idx)
            if success and order_indices == sorted(order_indices):
                scores["health_report_top_three_errors"] = 1.0
        # references to CSV files
        refs_ok = ("output/tours_storage.csv" in text) and ("output/log_summary.csv" in text)
        if refs_ok:
            scores["health_report_references"] = 1.0

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

