import json
import os
import sys
import csv
from decimal import Decimal, getcontext, ROUND_HALF_UP
import re

def read_json(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None

def read_csv_rows(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            reader = csv.reader(f)
            rows = list(reader)
        return rows
    except Exception:
        return None

def dquant(value, q="0.01"):
    # ensure Decimal with string constructor to avoid float artifacts
    if isinstance(value, Decimal):
        d = value
    else:
        d = Decimal(str(value))
    return d.quantize(Decimal(q), rounding=ROUND_HALF_UP)

def fmt2(value):
    return format(dquant(value), "f")

def parse_decimal_safe(s):
    try:
        return Decimal(str(s))
    except Exception:
        # Try stripping commas or spaces
        try:
            return Decimal(str(s).replace(",", "").strip())
        except Exception:
            return None

def compute_fv(principal, rate, years, freq):
    # high precision for compounding
    getcontext().prec = 50
    p = Decimal(str(principal))
    r = Decimal(str(rate))
    f = Decimal(str(freq))
    # (1 + r/f) ** (f * years)
    try:
        base = Decimal("1") + (r / f)
        exp = int(Decimal(str(freq)) * Decimal(str(years)))
        factor = base ** exp
        fv = p * factor
        return fv
    except Exception:
        return None

def build_expected_fv_table(inv):
    # inv expected keys: principal, rates (list), periods (list) or years (list), frequency (int)
    principal = inv.get("principal")
    rates = inv.get("rates", [])
    periods = inv.get("periods", inv.get("years", []))
    freq = inv.get("frequency", inv.get("compounding_frequency", 1))
    try:
        freq_int = int(freq)
    except Exception:
        return None

    try:
        principal_d = Decimal(str(principal))
    except Exception:
        return None

    expected = {}
    for rate in rates:
        try:
            rate_d = Decimal(str(rate))
        except Exception:
            return None
        for yrs in periods:
            try:
                years_int = int(yrs)
            except Exception:
                return None
            fv = compute_fv(principal_d, rate_d, years_int, freq_int)
            if fv is None:
                return None
            total_gain = fv - principal_d
            gain_percent = (total_gain / principal_d) * Decimal("100")
            expected[(rate_d, years_int)] = {
                "final_value": fmt2(fv),
                "total_gain": fmt2(total_gain),
                "gain_percent": fmt2(gain_percent),
            }
    return expected

def check_fv_table(output_fv_path, input_investment_path):
    rows = read_csv_rows(output_fv_path)
    if not rows or len(rows) < 2:
        return False
    header = rows[0]
    if header != ["rate", "years", "final_value", "total_gain", "gain_percent"]:
        return False

    inv = read_json(input_investment_path)
    if not isinstance(inv, dict):
        return False
    expected = build_expected_fv_table(inv)
    if expected is None:
        return False

    found = set()
    for row in rows[1:]:
        if len(row) != 5:
            continue
        rate_s, years_s, fv_s, tg_s, gp_s = [c.strip() for c in row]
        rate_d = parse_decimal_safe(rate_s)
        try:
            years_i = int(years_s)
        except Exception:
            continue
        if rate_d is None:
            continue
        key = None
        # match by numeric equality with expected keys (Decimal exact)
        for (erate, eyears) in expected.keys():
            if eyears == years_i and erate == rate_d:
                key = (erate, eyears)
                break
        if key is None:
            continue
        exp_vals = expected[key]
        # Compare strings exactly for 2-decimal formatting
        if fv_s == exp_vals["final_value"] and tg_s == exp_vals["total_gain"] and gp_s == exp_vals["gain_percent"]:
            found.add(key)

    # All expected combos must be present
    return found == set(expected.keys())

def compute_pricing_for_services(input_services_path):
    rows = read_csv_rows(input_services_path)
    if not rows or len(rows) < 2:
        return None
    header = [h.strip() for h in rows[0]]
    if header != ["service", "cost", "markup_percent"]:
        # The task specifies this exact input format
        return None
    expected = {}
    for row in rows[1:]:
        if len(row) < 3:
            continue
        service = row[0].strip()
        cost = parse_decimal_safe(row[1])
        mp = parse_decimal_safe(row[2])
        if service == "" or cost is None or mp is None:
            continue
        markup_amount = cost * (mp / Decimal("100"))
        selling_price = cost + markup_amount
        margin_percent = (markup_amount / selling_price) * Decimal("100") if selling_price != 0 else Decimal("0")
        expected[service] = {
            "service": service,
            "cost": row[1].strip(),
            "markup_percent": row[2].strip(),
            "markup_amount": fmt2(markup_amount),
            "selling_price": fmt2(selling_price),
            "margin_percent": fmt2(margin_percent),
        }
    return expected

def check_services_pricing(output_pricing_path, input_services_path):
    out_rows = read_csv_rows(output_pricing_path)
    if not out_rows or len(out_rows) < 2:
        return False
    header = out_rows[0]
    if header != ["service", "cost", "markup_percent", "markup_amount", "selling_price", "margin_percent"]:
        return False

    expected = compute_pricing_for_services(input_services_path)
    if expected is None or not expected:
        return False

    # Build lookup from output by service name
    out_map = {}
    for row in out_rows[1:]:
        if len(row) != 6:
            continue
        svc = row[0].strip()
        out_map[svc] = {
            "service": row[0].strip(),
            "cost": row[1].strip(),
            "markup_percent": row[2].strip(),
            "markup_amount": row[3].strip(),
            "selling_price": row[4].strip(),
            "margin_percent": row[5].strip(),
        }

    # Verify every input row appears correctly in output
    for svc, exp in expected.items():
        got = out_map.get(svc)
        if not got:
            return False
        # cost and markup_percent can be formatted differently; compare numerically
        cost_ok = False
        mp_ok = False
        try:
            cost_ok = dquant(parse_decimal_safe(got["cost"])) == dquant(parse_decimal_safe(exp["cost"]))
            mp_ok = dquant(parse_decimal_safe(got["markup_percent"])) == dquant(parse_decimal_safe(exp["markup_percent"]))
        except Exception:
            cost_ok = False
            mp_ok = False
        if not cost_ok or not mp_ok:
            return False
        # The computed fields must match exactly as 2-decimal strings
        if got["markup_amount"] != exp["markup_amount"]:
            return False
        if got["selling_price"] != exp["selling_price"]:
            return False
        if got["margin_percent"] != exp["margin_percent"]:
            return False
    return True

def extract_investment_line_amount(text):
    # Find the line that starts with "- **Investment:** "
    for line in text.splitlines():
        if line.strip().startswith("- **Investment:**"):
            # Extract $amount pattern
            m = re.search(r"\$[0-9,]+\.[0-9]{2}", line)
            if m:
                amt_str = m.group(0)
                # remove $ and commas
                amt_num = amt_str.replace("$", "").replace(",", "")
                try:
                    return dquant(Decimal(amt_num))
                except Exception:
                    return None
            return None
    return None

def check_proposal(output_proposal_path, input_client_path, input_services_path):
    try:
        with open(output_proposal_path, "r", encoding="utf-8") as f:
            content = f.read()
    except Exception:
        return False

    client = read_json(input_client_path)
    if not isinstance(client, dict):
        return False

    # Compute expected selling price for the selected package
    package = client.get("package_to_quote", "")
    pricing = compute_pricing_for_services(input_services_path)
    if not pricing or package not in pricing:
        return False
    expected_price = dquant(Decimal(pricing[package]["selling_price"]))

    # Verify core structure and placeholders
    project_name = client.get("project_name", "")
    client_name = client.get("client_name", "")
    timeline = client.get("timeline", "")
    scope = client.get("project_scope", [])
    freelancer_name = client.get("freelancer_name", "")

    lines = content.splitlines()

    # Basic structure checks
    if not lines:
        return False
    if lines[0].strip() != f"Subject: Proposal for {project_name}":
        return False

    # Ensure greeting line present after a blank line
    # Allow some flexibility in blank lines
    try:
        # Find "Hi {client_name},"
        greeting_idx = None
        for i, ln in enumerate(lines[1:], start=1):
            if ln.strip() == f"Hi {client_name},":
                greeting_idx = i
                break
        if greeting_idx is None:
            return False
    except Exception:
        return False

    # Required labeled lines
    required_project_line = f"- **Project:** {project_name}"
    if required_project_line not in content:
        return False

    if "- **Scope:**" not in content:
        return False

    # Scope items each as its own bulleted line (accept 2 or 4 spaces indent before "-")
    for item in scope:
        pattern_ok = False
        for ln in lines:
            stripped = ln.lstrip()
            # must be a line starting with "- " then the item
            if stripped.startswith(f"- {item}"):
                # Ensure it's under Scope section by position: find scope line then items after it
                pattern_ok = True
                break
        if not pattern_ok:
            return False

    # Investment line and amount
    if "- **Investment:**" not in content:
        return False
    inv_amount = extract_investment_line_amount(content)
    if inv_amount is None:
        return False
    if inv_amount != expected_price:
        return False

    # Timeline line
    if f"- **Timeline:** {timeline}" not in content:
        return False

    # Closing lines
    closing_sentence = ("I am confident that we can achieve the goals we discussed. Please let me know "
                        "if you have any questions or would like to proceed with the next steps.")
    if closing_sentence not in content:
        return False
    if "Best regards," not in content:
        return False
    # Freelancer signature line present
    if freelancer_name not in [ln.strip() for ln in lines]:
        return False

    return True

def check_retainer_gl(output_gl_path, input_client_path, input_services_path):
    data = read_json(output_gl_path)
    if not isinstance(data, dict):
        return False

    client = read_json(input_client_path)
    if not isinstance(client, dict):
        return False

    # Verify voucher fields
    for key in ["voucher_type", "voucher_id", "posting_date", "entries"]:
        if key not in data:
            return False

    if data["voucher_type"] != client.get("voucher_type"):
        return False
    if data["voucher_id"] != client.get("voucher_id"):
        return False
    if data["posting_date"] != client.get("posting_date"):
        return False

    entries = data.get("entries")
    if not isinstance(entries, list) or len(entries) != 2:
        return False

    # Compute expected amounts
    package = client.get("package_to_quote", "")
    pricing = compute_pricing_for_services(input_services_path)
    if not pricing or package not in pricing:
        return False
    selling_price = dquant(Decimal(pricing[package]["selling_price"]))
    retainer_percent = parse_decimal_safe(client.get("retainer_percent", 0))
    if retainer_percent is None:
        return False
    retainer_amount = dquant(selling_price * (retainer_percent / Decimal("100")))

    bank_account_name = client.get("bank_account_name", "")
    unearned_revenue_account_name = client.get("unearned_revenue_account_name", "")

    # Validate two entries
    has_bank_debit = False
    has_unearned_credit = False
    total_debit = Decimal("0")
    total_credit = Decimal("0")

    for e in entries:
        if not isinstance(e, dict):
            return False
        if set(e.keys()) != {"account_name", "debit", "credit"}:
            return False
        # amounts as Decimals
        debit = parse_decimal_safe(e.get("debit", 0))
        credit = parse_decimal_safe(e.get("credit", 0))
        if debit is None or credit is None:
            return False
        # Sum totals
        total_debit += dquant(debit)
        total_credit += dquant(credit)
        # Check bank line
        if e.get("account_name") == bank_account_name:
            if dquant(debit) == retainer_amount and dquant(credit) == dquant(0):
                has_bank_debit = True
        # Check unearned revenue line
        if e.get("account_name") == unearned_revenue_account_name:
            if dquant(debit) == dquant(0) and dquant(credit) == retainer_amount:
                has_unearned_credit = True

    if not has_bank_debit or not has_unearned_credit:
        return False

    if total_debit != total_credit:
        return False
    if total_debit != retainer_amount:
        return False

    return True

def main():
    workspace_root = sys.argv[1] if len(sys.argv) > 1 else "/root/.openclaw/workspace"
    input_dir = os.path.join(workspace_root, "input")
    output_dir = os.path.join(workspace_root, "output")

    # Paths
    investment_path = os.path.join(input_dir, "investment.json")
    services_input_path = os.path.join(input_dir, "services.csv")
    client_path = os.path.join(input_dir, "client.json")

    fv_table_path = os.path.join(output_dir, "fv_table.csv")
    services_pricing_path = os.path.join(output_dir, "pricing", "services_pricing.csv")
    proposal_path = os.path.join(output_dir, "proposal", "proposal.txt")
    retainer_gl_path = os.path.join(output_dir, "accounting", "retainer_gl.json")

    fv_ok = False
    pricing_ok = False
    proposal_ok = False
    gl_ok = False

    # Check 1: FV table
    if os.path.isfile(fv_table_path) and os.path.isfile(investment_path):
        fv_ok = check_fv_table(fv_table_path, investment_path)

    # Check 2: Services pricing
    if os.path.isfile(services_pricing_path) and os.path.isfile(services_input_path):
        pricing_ok = check_services_pricing(services_pricing_path, services_input_path)

    # Check 3: Proposal
    if os.path.isfile(proposal_path) and os.path.isfile(client_path) and os.path.isfile(services_input_path):
        proposal_ok = check_proposal(proposal_path, client_path, services_input_path)

    # Check 4: Retainer GL
    if os.path.isfile(retainer_gl_path) and os.path.isfile(client_path) and os.path.isfile(services_input_path):
        gl_ok = check_retainer_gl(retainer_gl_path, client_path, services_input_path)

    # Reward: equal weight
    total_checks = 4
    passed = sum([fv_ok, pricing_ok, proposal_ok, gl_ok])
    reward = passed / total_checks if passed > 0 else 0.0

    result = {
        "reward": reward,
        "fv_table_ok": bool(fv_ok),
        "services_pricing_ok": bool(pricing_ok),
        "proposal_ok": bool(proposal_ok),
        "retainer_gl_ok": bool(gl_ok),
    }
    print(json.dumps(result))

if __name__ == "__main__":
    main()

import csv
import json
import sys
from html.parser import HTMLParser
from pathlib import Path
from typing import Dict, List, Tuple, Optional, Any


class VerbClassTableParser(HTMLParser):
    def __init__(self, target_id: str):
        super().__init__()
        self.target_id = target_id
        self.in_table = False
        self.in_td = False
        self.current_row: List[str] = []
        self.current_cell: List[str] = []
        self.rows: List[List[str]] = []
        self._table_depth = 0  # handle nested tables if any

    def handle_starttag(self, tag: str, attrs: List[Tuple[str, Optional[str]]]):
        if tag.lower() == "table":
            attrs_dict = dict(attrs)
            if not self.in_table and attrs_dict.get("id") == self.target_id:
                self.in_table = True
                self._table_depth = 1
            elif self.in_table:
                # nested table inside target table
                self._table_depth += 1
        if self.in_table and tag.lower() == "tr":
            self.current_row = []
        if self.in_table and tag.lower() == "td":
            self.in_td = True
            self.current_cell = []

    def handle_endtag(self, tag: str):
        if self.in_table and tag.lower() == "td":
            self.in_td = False
            cell_text = "".join(self.current_cell).strip()
            self.current_row.append(cell_text)
            self.current_cell = []
        if self.in_table and tag.lower() == "tr":
            # only collect body rows (should have 3 columns)
            if self.current_row:
                self.rows.append(self.current_row)
            self.current_row = []
        if tag.lower() == "table" and self.in_table:
            self._table_depth -= 1
            if self._table_depth <= 0:
                self.in_table = False

    def handle_data(self, data: str):
        if self.in_table and self.in_td:
            self.current_cell.append(data)


def _read_all_corpus_tsvs(corpus_dir: Path) -> Tuple[bool, List[Dict[str, str]]]:
    rows: List[Dict[str, str]] = []
    if not corpus_dir.exists() or not corpus_dir.is_dir():
        return False, rows
    tsv_files = sorted([p for p in corpus_dir.glob("*.tsv") if p.is_file()])
    if not tsv_files:
        return False, rows
    expected_fields = ["sentence_id", "verb_lemma", "frame", "genre"]
    for path in tsv_files:
        try:
            with path.open("r", encoding="utf-8") as f:
                reader = csv.DictReader(f, delimiter="\t")
                if reader.fieldnames is None:
                    return False, []
                # Require exact fields in any order? The input spec provides exact columns.
                # We'll ensure the required columns are present.
                for field in expected_fields:
                    if field not in reader.fieldnames:
                        return False, []
                for rec in reader:
                    # ensure required fields exist
                    if not all(k in rec for k in expected_fields):
                        return False, []
                    rows.append({
                        "sentence_id": rec["sentence_id"],
                        "verb_lemma": rec["verb_lemma"],
                        "frame": rec["frame"],
                        "genre": rec["genre"],
                    })
        except Exception:
            return False, []
    return True, rows


def _parse_mapping_html(html_path: Path) -> Tuple[bool, Dict[str, Dict[str, Any]]]:
    if not html_path.exists() or not html_path.is_file():
        return False, {}
    try:
        content = html_path.read_text(encoding="utf-8", errors="ignore")
        parser = VerbClassTableParser(target_id="verb-classes")
        parser.feed(content)
        # Expect rows with 3 columns: lemma, alternation_class, ditransitive_possible
        mapping: Dict[str, Dict[str, Any]] = {}
        for row in parser.rows:
            # Filter header rows by checking cells length and header names not numeric; We'll rely on tbody
            if len(row) != 3:
                # Keep only rows with exactly 3 cells
                continue
            lemma, alternation_class, ditransitive_possible = row
            lemma = lemma.strip()
            alternation_class = alternation_class.strip()
            dtr = ditransitive_possible.strip().lower()
            if lemma:
                mapping[lemma] = {
                    "alternation_class": alternation_class,
                    "ditransitive_possible": True if dtr == "yes" else False if dtr == "no" else None,
                }
        if not mapping:
            return False, {}
        return True, mapping
    except Exception:
        return False, {}


def _round3(x: float) -> float:
    return round(x + 0.0, 3)


def _safe_load_csv(path: Path) -> Tuple[bool, List[str], List[Dict[str, str]]]:
    if not path.exists() or not path.is_file():
        return False, [], []
    try:
        with path.open("r", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            headers = reader.fieldnames or []
            rows = [row for row in reader]
        return True, headers, rows
    except Exception:
        return False, [], []


def _compute_expected(corpus_rows: List[Dict[str, str]], mapping: Dict[str, Dict[str, Any]]) -> Tuple[
    List[Tuple[str, str, str, int, int, float]],
    List[Tuple[str, int, int, float]],
    List[str]
]:
    # Determine mapped and unmapped
    lemmas_in_corpus = set()
    for r in corpus_rows:
        lemmas_in_corpus.add(r["verb_lemma"])
    unmapped = sorted([l for l in lemmas_in_corpus if l not in mapping])

    # Filter to mapped tokens
    mapped_tokens = [r for r in corpus_rows if r["verb_lemma"] in mapping]

    # Counts per verb and frame
    by_verb_counts: Dict[str, Dict[str, int]] = {}
    totals_per_verb: Dict[str, int] = {}
    for r in mapped_tokens:
        v = r["verb_lemma"]
        f = r["frame"]
        by_verb_counts.setdefault(v, {})
        by_verb_counts[v][f] = by_verb_counts[v].get(f, 0) + 1
        totals_per_verb[v] = totals_per_verb.get(v, 0) + 1

    # Build by_verb_frame expected rows
    by_verb_frame_rows: List[Tuple[str, str, str, int, int, float]] = []
    for verb, frame_counts in by_verb_counts.items():
        total = totals_per_verb[verb]
        alt_class = mapping[verb]["alternation_class"]
        for frame, cnt in frame_counts.items():
            prop = _round3(cnt / total if total > 0 else 0.0)
            by_verb_frame_rows.append((verb, alt_class, frame, cnt, total, prop))

    # Build by_class_summary expected rows
    # Aggregate total tokens and DITRANS tokens per class, and distinct verbs per class
    class_totals: Dict[str, int] = {}
    class_ditrans: Dict[str, int] = {}
    class_verbs: Dict[str, set] = {}
    for r in mapped_tokens:
        verb = r["verb_lemma"]
        frame = r["frame"]
        alt_class = mapping[verb]["alternation_class"]
        class_totals[alt_class] = class_totals.get(alt_class, 0) + 1
        if frame == "DITRANS":
            class_ditrans[alt_class] = class_ditrans.get(alt_class, 0) + 1
        class_verbs.setdefault(alt_class, set()).add(verb)

    by_class_summary_rows: List[Tuple[str, int, int, float]] = []
    for alt_class, total_tokens in class_totals.items():
        ditrans_tokens = class_ditrans.get(alt_class, 0)
        distinct_verbs = len(class_verbs.get(alt_class, set()))
        share = _round3(ditrans_tokens / total_tokens if total_tokens > 0 else 0.0)
        by_class_summary_rows.append((alt_class, total_tokens, distinct_verbs, share))

    return by_verb_frame_rows, by_class_summary_rows, unmapped


def _parse_float(value: str) -> Optional[float]:
    try:
        return float(value.strip())
    except Exception:
        return None


def _parse_int(value: str) -> Optional[int]:
    try:
        # Allow floats formatted as integers; but require strict integer
        if isinstance(value, str):
            v = value.strip()
        else:
            v = str(value)
        if v.lower().startswith("+"):
            v = v[1:]
        if "." in v:
            # explicitly reject floats
            return None
        return int(v)
    except Exception:
        return None


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "by_verb_frame_file_exists": 0.0,
        "by_verb_frame_header_valid": 0.0,
        "by_verb_frame_content_correct": 0.0,
        "by_class_summary_file_exists": 0.0,
        "by_class_summary_header_valid": 0.0,
        "by_class_summary_content_correct": 0.0,
        "unmapped_verbs_file_exists": 0.0,
        "unmapped_verbs_content_correct": 0.0,
    }

    # Compute expected from inputs
    corpus_ok, corpus_rows = _read_all_corpus_tsvs(workspace / "input" / "corpus")
    mapping_ok, mapping = _parse_mapping_html(workspace / "input" / "resources" / "verb_classes.html")

    expected_by_verb_frame: List[Tuple[str, str, str, int, int, float]] = []
    expected_by_class_summary: List[Tuple[str, int, int, float]] = []
    expected_unmapped: List[str] = []

    if corpus_ok and mapping_ok:
        expected_by_verb_frame, expected_by_class_summary, expected_unmapped = _compute_expected(corpus_rows, mapping)

    # Paths to outputs
    by_verb_frame_path = workspace / "output" / "by_verb_frame.csv"
    by_class_summary_path = workspace / "output" / "by_class_summary.csv"
    unmapped_verbs_path = workspace / "output" / "unmapped_verbs.txt"

    # Check by_verb_frame.csv
    bvf_ok, bvf_headers, bvf_rows = _safe_load_csv(by_verb_frame_path)
    if bvf_ok:
        scores["by_verb_frame_file_exists"] = 1.0
        expected_headers = ["verb_lemma", "alternation_class", "frame", "token_count", "total_tokens_for_verb", "token_proportion"]
        if bvf_headers == expected_headers:
            scores["by_verb_frame_header_valid"] = 1.0
            # Content check only if we have expected
            if corpus_ok and mapping_ok:
                # Build observed set
                observed: List[Tuple[str, str, str, int, int, float]] = []
                valid = True
                for row in bvf_rows:
                    try:
                        verb_lemma = row["verb_lemma"].strip()
                        alt_class = row["alternation_class"].strip()
                        frame = row["frame"].strip()
                        token_count = _parse_int(row["token_count"])
                        total_tokens = _parse_int(row["total_tokens_for_verb"])
                        prop = _parse_float(row["token_proportion"])
                        if verb_lemma == "" or alt_class == "" or frame == "":
                            valid = False
                            break
                        if token_count is None or total_tokens is None or prop is None:
                            valid = False
                            break
                        # Check internal proportion consistency
                        expected_prop = _round3(token_count / total_tokens if total_tokens > 0 else 0.0)
                        if _round3(prop) != expected_prop:
                            valid = False
                            break
                        observed.append((verb_lemma, alt_class, frame, token_count, total_tokens, expected_prop))
                    except Exception:
                        valid = False
                        break
                if valid:
                    # Compare sets exactly
                    if set(observed) == set(expected_by_verb_frame):
                        scores["by_verb_frame_content_correct"] = 1.0
        else:
            # header invalid
            scores["by_verb_frame_header_valid"] = 0.0

    # Check by_class_summary.csv
    bcs_ok, bcs_headers, bcs_rows = _safe_load_csv(by_class_summary_path)
    if bcs_ok:
        scores["by_class_summary_file_exists"] = 1.0
        expected_headers = ["alternation_class", "total_tokens", "distinct_verbs", "ditransitive_token_share"]
        if bcs_headers == expected_headers:
            scores["by_class_summary_header_valid"] = 1.0
            if corpus_ok and mapping_ok:
                valid = True
                observed: List[Tuple[str, int, int, float]] = []
                for row in bcs_rows:
                    try:
                        alt_class = row["alternation_class"].strip()
                        total_tokens = _parse_int(row["total_tokens"])
                        distinct_verbs = _parse_int(row["distinct_verbs"])
                        share = _parse_float(row["ditransitive_token_share"])
                        if alt_class == "" or total_tokens is None or distinct_verbs is None or share is None:
                            valid = False
                            break
                        # Share should be rounded to 3 decimals; don't recompute here since we don't have details per row.
                        share_r = _round3(share)
                        observed.append((alt_class, total_tokens, distinct_verbs, share_r))
                    except Exception:
                        valid = False
                        break
                if valid:
                    if set(observed) == set(expected_by_class_summary):
                        scores["by_class_summary_content_correct"] = 1.0
        else:
            scores["by_class_summary_header_valid"] = 0.0

    # Check unmapped_verbs.txt
    if unmapped_verbs_path.exists() and unmapped_verbs_path.is_file():
        scores["unmapped_verbs_file_exists"] = 1.0
        try:
            content = unmapped_verbs_path.read_text(encoding="utf-8")
            lines = [ln.strip() for ln in content.splitlines() if ln.strip() != ""]
            # Ensure sorted and unique
            if lines == sorted(set(lines)):
                if corpus_ok and mapping_ok:
                    if lines == expected_unmapped:
                        scores["unmapped_verbs_content_correct"] = 1.0
                else:
                    # If we cannot compute expected, we cannot verify content; leave at 0.0
                    pass
            else:
                # either not sorted or duplicates present
                pass
        except Exception:
            pass

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade(transcript=[], workspace_path=workspace)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

