import sys
import json
import csv
import re
from math import ceil, isclose
from datetime import datetime, date, time, timedelta, timezone
from pathlib import Path
from typing import List, Dict, Tuple, Optional

try:
    from zoneinfo import ZoneInfo  # Python 3.9+
except Exception:
    ZoneInfo = None  # Fallback handled below


def _safe_read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _safe_read_csv(path: Path) -> Optional[Tuple[List[str], List[Dict[str, str]]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            headers = reader.fieldnames
            if headers is None:
                return None
            rows = [row for row in reader]
            return headers, rows
    except Exception:
        return None


def _safe_read_json(path: Path) -> Optional[dict]:
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _parse_iso_dt(s: str) -> Optional[datetime]:
    try:
        dt = datetime.fromisoformat(s)
        return dt
    except Exception:
        return None


def _slugify(title: str) -> str:
    s = title.strip().lower()
    s = re.sub(r'[^a-z0-9]+', '-', s)
    s = re.sub(r'-{2,}', '-', s)
    s = s.strip('-')
    return s


def _get_tz(name: str):
    if ZoneInfo is not None:
        try:
            return ZoneInfo(name)
        except Exception:
            pass
    # Fallback: assume ET for the specific window which is -04:00 in Oct 2024
    return timezone(timedelta(hours=-4))


def _parse_availability_yaml(text: str) -> Optional[dict]:
    # Minimal parser for the provided simple YAML structure
    tz = None
    window_start = None
    window_end = None
    availability: Dict[str, List[Tuple[str, str]]] = {}
    mode = None
    current_day = None
    for raw_line in text.splitlines():
        line = raw_line.rstrip("\n")
        if not line.strip():
            continue
        if mode is None:
            m = re.match(r'^\s*timezone:\s*(.+)\s*$', line)
            if m:
                tz = m.group(1).strip()
                continue
            m = re.match(r'^\s*window_start:\s*(.+)\s*$', line)
            if m:
                window_start = m.group(1).strip()
                continue
            m = re.match(r'^\s*window_end:\s*(.+)\s*$', line)
            if m:
                window_end = m.group(1).strip()
                continue
            if re.match(r'^\s*availability:\s*$', line):
                mode = 'availability'
                continue
        elif mode == 'availability':
            mday = re.match(r'^\s{2}([A-Za-z]+):\s*$', line)
            if mday:
                current_day = mday.group(1)
                availability[current_day] = []
                continue
            mslot = re.match(r'^\s{4}-\s*"?(\d{2}:\d{2})-(\d{2}:\d{2})"?\s*$', line)
            if mslot and current_day:
                start_t, end_t = mslot.group(1), mslot.group(2)
                availability[current_day].append((start_t, end_t))
                continue
            # ignore other lines
    if tz is None or window_start is None or window_end is None or not availability:
        return None
    return {
        "timezone": tz,
        "window_start": window_start,
        "window_end": window_end,
        "availability": availability,
    }


def _weekday_name(d: date) -> str:
    # Monday, Tuesday...
    return ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"][d.weekday()]


def _build_availability_windows(tz, window_start: date, window_end: date, weekly: Dict[str, List[Tuple[str, str]]]) -> Dict[date, List[Tuple[datetime, datetime]]]:
    windows: Dict[date, List[Tuple[datetime, datetime]]] = {}
    current = window_start
    one_day = timedelta(days=1)
    while current <= window_end:
        name = _weekday_name(current)
        slots = weekly.get(name, [])
        day_windows: List[Tuple[datetime, datetime]] = []
        for st_str, en_str in slots:
            st_parts = [int(x) for x in st_str.split(":")]
            en_parts = [int(x) for x in en_str.split(":")]
            st_dt = datetime.combine(current, time(st_parts[0], st_parts[1]), tzinfo=tz)
            en_dt = datetime.combine(current, time(en_parts[0], en_parts[1]), tzinfo=tz)
            day_windows.append((st_dt, en_dt))
        windows[current] = day_windows
        current = current + one_day
    return windows


def _parse_newsletter(html: str) -> List[Tuple[str, str]]:
    # returns list of (title, iso_str)
    items = []
    # Regex for rows with class="drop" and capture title and data-iso
    pattern = re.compile(
        r'<tr\s+class="drop"[^>]*>.*?<td\s+class="title"\s*>(.*?)</td>.*?<td\s+class="datetime"[^>]*data-iso="([^"]+)"[^>]*>.*?</td>',
        re.IGNORECASE | re.DOTALL,
    )
    for m in pattern.finditer(html):
        title = re.sub(r'\s+', ' ', m.group(1)).strip()
        iso = m.group(2).strip()
        items.append((title, iso))
    return items


def _overlap(a_start: datetime, a_end: datetime, b_start: datetime, b_end: datetime) -> bool:
    # half-open intervals [start, end)
    latest_start = a_start if a_start >= b_start else b_start
    earliest_end = a_end if a_end <= b_end else b_end
    return earliest_end > latest_start


def _within_window(dt: datetime, window_start_dt: datetime, window_end_dt: datetime) -> bool:
    return (dt >= window_start_dt) and (dt <= window_end_dt)


def _event_within_availability(start: datetime, end: datetime, availability_by_date: Dict[date, List[Tuple[datetime, datetime]]], tz) -> bool:
    # Must be fully within a single availability window on the same local date
    local_start = start.astimezone(tz)
    local_end = end.astimezone(tz)
    if local_start.date() != local_end.date():
        return False
    slots = availability_by_date.get(local_start.date(), [])
    for s, e in slots:
        if local_start >= s and local_end <= e:
            return True
    return False


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "merged_schedule_exists_and_schema": 0.0,
        "sources_and_ref_ids_valid": 0.0,
        "times_timezone_aware_and_within_window": 0.0,
        "non_deadline_within_availability": 0.0,
        "no_overlaps_across_events": 0.0,
        "assignment_blocks_one_hour_and_count": 0.0,
        "assignment_last_block_before_due": 0.0,
        "deadlines_present_and_exact": 0.0,
        "releases_watch_blocks_one_hour_and_within_48h": 0.0,
        "release_starts_align_when_available": 0.0,
        "summary_json_consistency": 0.0,
        "validation_report_present_and_consistent": 0.0,
    }

    # Load inputs
    assignments_path = workspace / "input" / "assignments.csv"
    newsletter_path = workspace / "input" / "fan_newsletter.html"
    availability_path = workspace / "input" / "availability.yaml"

    assignments_csv = _safe_read_csv(assignments_path)
    newsletter_html = _safe_read_text(newsletter_path)
    availability_text = _safe_read_text(availability_path)

    # Baseline parse of inputs; if any missing/malformed, many checks will fail gracefully
    assignments: List[dict] = []
    assignments_by_id: Dict[str, dict] = {}
    tzname = "America/New_York"
    tz = _get_tz(tzname)
    window_start_date = None
    window_end_date = None
    availability_by_date: Dict[date, List[Tuple[datetime, datetime]]] = {}

    if availability_text is not None:
        av = _parse_availability_yaml(availability_text)
        if av:
            tzname = av["timezone"]
            tz = _get_tz(tzname)
            try:
                window_start_date = datetime.fromisoformat(av["window_start"]).date()
                window_end_date = datetime.fromisoformat(av["window_end"]).date()
            except Exception:
                window_start_date = None
                window_end_date = None
            if window_start_date and window_end_date:
                availability_by_date = _build_availability_windows(tz, window_start_date, window_end_date, av["availability"])

    if assignments_csv is not None:
        headers, rows = assignments_csv
        # Expect columns assignment_id,course,assignment,due_at,estimate_hours
        for r in rows:
            try:
                aid = r["assignment_id"].strip()
                course = r["course"].strip()
                aname = r["assignment"].strip()
                due = _parse_iso_dt(r["due_at"].strip())
                est = float(r["estimate_hours"].strip())
                if not aid or due is None:
                    continue
                obj = {"assignment_id": aid, "course": course, "assignment": aname, "due_at": due, "estimate_hours": est}
                assignments.append(obj)
                assignments_by_id[aid] = obj
            except Exception:
                continue

    releases: List[dict] = []
    if newsletter_html is not None:
        items = _parse_newsletter(newsletter_html)
        for title, iso in items:
            dt = _parse_iso_dt(iso)
            if dt is None:
                continue
            releases.append({"title": title, "release_at": dt, "slug": _slugify(title)})

    # Define window start and end datetimes (inclusive)
    window_start_dt = None
    window_end_dt = None
    if window_start_date and window_end_date:
        window_start_dt = datetime.combine(window_start_date, time(0, 0), tzinfo=tz)
        # inclusive end: 23:59:59.999999
        window_end_dt = datetime.combine(window_end_date, time(23, 59, 59, 999999), tzinfo=tz)

    # Load outputs
    merged_path = workspace / "output" / "merged_schedule.csv"
    summary_path = workspace / "output" / "summary.json"
    validation_path = workspace / "output" / "validation_report.json"

    merged_csv = _safe_read_csv(merged_path)

    # Prepare structures for evaluation
    merged_ok = False
    events: List[dict] = []
    schema_ok = False
    sources_ok = False
    tz_and_window_ok = False
    availability_ok = False
    overlaps_ok = False
    assignment_blocks_ok = False
    assignment_last_block_ok = False
    deadlines_ok = False
    releases_blocks_ok = False
    release_align_ok = False
    summary_ok = False
    validation_ok = False

    # Parse merged schedule
    if merged_csv is not None:
        headers, rows = merged_csv
        expected_headers = ["start_iso", "end_iso", "title", "source", "ref_id", "notes"]
        schema_ok = headers == expected_headers
        # Build event list if schema ok
        if schema_ok:
            parse_fail = False
            for r in rows:
                s = r.get("start_iso", "")
                e = r.get("end_iso", "")
                title = (r.get("title") or "").strip()
                source = (r.get("source") or "").strip()
                ref_id = (r.get("ref_id") or "").strip()
                notes = (r.get("notes") or "")
                sd = _parse_iso_dt(s.strip())
                ed = _parse_iso_dt(e.strip())
                if sd is None or ed is None:
                    parse_fail = True
                    break
                events.append({
                    "start": sd,
                    "end": ed,
                    "title": title,
                    "source": source,
                    "ref_id": ref_id,
                    "notes": notes,
                })
            merged_ok = not parse_fail

    # Evaluate events if we parsed them
    if merged_ok and events and window_start_dt and window_end_dt and availability_by_date:
        # Check sources and ref_ids validity
        valid_sources = {"assignment_work", "release_watch", "deadline"}
        sources_ok = True
        for ev in events:
            if ev["source"] not in valid_sources:
                sources_ok = False
                break
            if ev["source"] == "assignment_work":
                # ref_id must be assignment id
                if ev["ref_id"] not in assignments_by_id:
                    sources_ok = False
                    break
            elif ev["source"] == "release_watch":
                # ref_id should be slug of some release title
                slug = ev["ref_id"]
                if slug not in {r["slug"] for r in releases}:
                    sources_ok = False
                    break
            elif ev["source"] == "deadline":
                # ref_id must be assignment id
                if ev["ref_id"] not in assignments_by_id:
                    sources_ok = False
                    break

        # Times timezone-aware and within window
        tz_and_window_ok = True
        for ev in events:
            sd = ev["start"]
            ed = ev["end"]
            # timezone-aware
            if sd.tzinfo is None or ed.tzinfo is None:
                tz_and_window_ok = False
                break
            # start <= end
            if ed < sd:
                tz_and_window_ok = False
                break
            # All events should be within the date window (inclusive)
            if not _within_window(sd, window_start_dt, window_end_dt) or not _within_window(ed, window_start_dt, window_end_dt):
                tz_and_window_ok = False
                break

        # Non-deadline events within availability
        availability_ok = True
        for ev in events:
            if ev["source"] == "deadline":
                continue
            if not _event_within_availability(ev["start"], ev["end"], availability_by_date, tz):
                availability_ok = False
                break

        # No overlaps across all scheduled items (treat as half-open)
        overlaps_ok = True
        for i in range(len(events)):
            for j in range(i + 1, len(events)):
                a = events[i]
                b = events[j]
                if _overlap(a["start"], a["end"], b["start"], b["end"]):
                    overlaps_ok = False
                    break
            if not overlaps_ok:
                break

        # Assignment blocks: one-hour and count >= ceil(estimate)
        assignment_blocks_ok = True
        assignment_last_block_ok = True
        deadlines_ok = True

        # Build index mappings
        assign_work_by_id: Dict[str, List[dict]] = {}
        deadline_by_id: Dict[str, List[dict]] = {}
        for ev in events:
            if ev["source"] == "assignment_work":
                assign_work_by_id.setdefault(ev["ref_id"], []).append(ev)
            elif ev["source"] == "deadline":
                deadline_by_id.setdefault(ev["ref_id"], []).append(ev)

        for a in assignments:
            aid = a["assignment_id"]
            due = a["due_at"]
            est = a["estimate_hours"]
            blocks = assign_work_by_id.get(aid, [])
            # Check count
            needed_blocks = ceil(est)
            if len(blocks) < needed_blocks:
                assignment_blocks_ok = False
            # Check each block duration is exactly 60 minutes
            for b in blocks:
                dur = (b["end"] - b["start"]).total_seconds()
                if not isclose(dur, 3600.0, rel_tol=0, abs_tol=0.5):
                    assignment_blocks_ok = False
                    break
            # Check last block end <= due_at - 120 minutes
            if blocks:
                last_end = max(b["end"] for b in blocks)
                if last_end > (due - timedelta(minutes=120)):
                    assignment_last_block_ok = False
            else:
                assignment_last_block_ok = False
            # Check deadline event present exact at due_at with zero duration
            dls = deadline_by_id.get(aid, [])
            # Must have at least one; require exactly one with start==end==due
            found_exact = False
            for dlev in dls:
                if dlev["start"] == due and dlev["end"] == due:
                    found_exact = True
                    break
            if not found_exact:
                deadlines_ok = False

        # Releases: exactly one 60-min watch block within 48h of release time, aligned if available
        releases_blocks_ok = True
        release_align_ok = True

        # Map release slug to release info for in-window releases
        in_window_releases = []
        if window_start_dt and window_end_dt:
            for r in releases:
                if _within_window(r["release_at"], window_start_dt, window_end_dt):
                    in_window_releases.append(r)

        watch_by_slug: Dict[str, List[dict]] = {}
        for ev in events:
            if ev["source"] == "release_watch":
                watch_by_slug.setdefault(ev["ref_id"], []).append(ev)

        for r in in_window_releases:
            slug = r["slug"]
            rel_t = r["release_at"]
            watches = watch_by_slug.get(slug, [])
            # Exactly one
            if len(watches) != 1:
                releases_blocks_ok = False
                continue
            w = watches[0]
            # Duration 60
            if not isclose((w["end"] - w["start"]).total_seconds(), 3600.0, rel_tol=0, abs_tol=0.5):
                releases_blocks_ok = False
            # Within 48 hours after release
            if w["start"] < rel_t or w["end"] > (rel_t + timedelta(hours=48)):
                releases_blocks_ok = False
            # Align if release time itself is within availability for a full hour
            align_needed = False
            local_rel = rel_t.astimezone(tz)
            rel_day_slots = availability_by_date.get(local_rel.date(), [])
            for s, e in rel_day_slots:
                if local_rel >= s and (local_rel + timedelta(hours=1)) <= e:
                    align_needed = True
                    break
            if align_needed:
                if w["start"] != rel_t:
                    release_align_ok = False

    # Set initial scores from above checks
    if merged_ok and schema_ok:
        scores["merged_schedule_exists_and_schema"] = 1.0
    if sources_ok and merged_ok and schema_ok:
        scores["sources_and_ref_ids_valid"] = 1.0
    if tz_and_window_ok and merged_ok and schema_ok and window_start_dt and window_end_dt:
        scores["times_timezone_aware_and_within_window"] = 1.0
    if availability_ok and merged_ok and schema_ok:
        scores["non_deadline_within_availability"] = 1.0
    if overlaps_ok and merged_ok and schema_ok:
        scores["no_overlaps_across_events"] = 1.0
    if assignment_blocks_ok and merged_ok and schema_ok and assignments:
        scores["assignment_blocks_one_hour_and_count"] = 1.0
    if assignment_last_block_ok and merged_ok and schema_ok and assignments:
        scores["assignment_last_block_before_due"] = 1.0
    if deadlines_ok and merged_ok and schema_ok and assignments:
        scores["deadlines_present_and_exact"] = 1.0
    if releases_blocks_ok and merged_ok and schema_ok and releases:
        scores["releases_watch_blocks_one_hour_and_within_48h"] = 1.0
    if release_align_ok and merged_ok and schema_ok and releases:
        scores["release_starts_align_when_available"] = 1.0

    # Summary JSON consistency
    summary_json = _safe_read_json(summary_path)
    if summary_json is not None and merged_ok and schema_ok:
        try:
            # Expected keys
            has_keys = all(k in summary_json for k in ["total_events", "total_hours", "hours_by_source", "events_by_day", "unmet_constraints"])
            if has_keys:
                # Recompute metrics from events
                total_events = len(events)
                total_hours = sum(max(0.0, (ev["end"] - ev["start"]).total_seconds() / 3600.0) for ev in events)
                hours_by_source = {"assignment_work": 0.0, "release_watch": 0.0, "deadline": 0.0}
                for ev in events:
                    dur = max(0.0, (ev["end"] - ev["start"]).total_seconds() / 3600.0)
                    if ev["source"] in hours_by_source:
                        hours_by_source[ev["source"]] += dur
                # events_by_day by local date from start
                events_by_day: Dict[str, int] = {}
                for ev in events:
                    dstr = ev["start"].astimezone(tz).date().isoformat()
                    events_by_day[dstr] = events_by_day.get(dstr, 0) + 1

                # Check unmet_constraints: if our critical checks all pass, expect empty; else expect non-empty
                our_constraints_pass = (scores["non_deadline_within_availability"] == 1.0 and
                                        scores["assignment_blocks_one_hour_and_count"] == 1.0 and
                                        scores["assignment_last_block_before_due"] == 1.0 and
                                        scores["releases_watch_blocks_one_hour_and_within_48h"] == 1.0 and
                                        scores["no_overlaps_across_events"] == 1.0)
                unmet_list = summary_json.get("unmet_constraints", [])
                unmet_ok = isinstance(unmet_list, list)
                if our_constraints_pass:
                    unmet_ok = unmet_ok and (len(unmet_list) == 0)
                else:
                    unmet_ok = unmet_ok and (len(unmet_list) >= 1)

                # Compare numbers with tolerance for floats
                numbers_ok = (
                    summary_json.get("total_events") == total_events and
                    isclose(float(summary_json.get("total_hours", -1.0)), total_hours, rel_tol=1e-6, abs_tol=1e-6)
                )
                hbs = summary_json.get("hours_by_source", {})
                hours_ok = all(
                    isclose(float(hbs.get(k, -1.0)), hours_by_source[k], rel_tol=1e-6, abs_tol=1e-6)
                    for k in ["assignment_work", "release_watch", "deadline"]
                )
                ebd = summary_json.get("events_by_day", {})
                ebd_ok = isinstance(ebd, dict) and all(ebd.get(k, 0) == v for k, v in events_by_day.items()) and all(
                    k in events_by_day for k in ebd.keys()
                )
                if numbers_ok and hours_ok and ebd_ok and unmet_ok:
                    summary_ok = True
        except Exception:
            summary_ok = False

    if summary_ok:
        scores["summary_json_consistency"] = 1.0

    # Validation report presence and consistency
    validation_json = _safe_read_json(validation_path)
    if validation_json is not None and merged_ok and schema_ok:
        try:
            # Accept either 'passed' bool or 'status' with 'pass'/'fail'; and 'issues' list
            issues = validation_json.get("issues")
            passed = None
            if isinstance(validation_json.get("passed"), bool):
                passed = validation_json.get("passed")
            elif isinstance(validation_json.get("status"), str):
                st = validation_json.get("status").lower().strip()
                if st in ("pass", "passed", "ok", "success"):
                    passed = True
                elif st in ("fail", "failed", "error"):
                    passed = False
            has_min_fields = isinstance(issues, list) and (passed is not None)
            if has_min_fields:
                # Our recomputed constraints pass/fail
                our_constraints_pass = (scores["non_deadline_within_availability"] == 1.0 and
                                        scores["assignment_blocks_one_hour_and_count"] == 1.0 and
                                        scores["assignment_last_block_before_due"] == 1.0 and
                                        scores["releases_watch_blocks_one_hour_and_within_48h"] == 1.0 and
                                        scores["no_overlaps_across_events"] == 1.0)
                if our_constraints_pass:
                    if passed is True and len(issues) == 0:
                        validation_ok = True
                else:
                    if passed is False or len(issues) > 0:
                        validation_ok = True
        except Exception:
            validation_ok = False

    if validation_ok:
        scores["validation_report_present_and_consistent"] = 1.0

    return scores


def main() -> None:
    workspace = "."
    if len(sys.argv) >= 2:
        workspace = sys.argv[1]
    result = grade([], workspace)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

import json
import csv
import math
import re
import sys
from pathlib import Path
from urllib.parse import urlparse
from html.parser import HTMLParser


def _read_csv_dicts(path: Path):
    try:
        with path.open(newline="", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            rows = list(reader)
            header = reader.fieldnames
        return header, rows
    except Exception:
        return None, None


def _read_csv_rows(path: Path):
    try:
        with path.open(newline="", encoding="utf-8") as f:
            reader = csv.reader(f)
            rows = list(reader)
        if not rows:
            return None
        return rows
    except Exception:
        return None


def _load_json(path: Path):
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _median(values):
    if not values:
        return None
    arr = sorted(values)
    n = len(arr)
    mid = n // 2
    if n % 2 == 1:
        return float(arr[mid])
    else:
        return float((arr[mid - 1] + arr[mid]) / 2.0)


def _isclose(a: float, b: float, rel_tol: float = 1e-6, abs_tol: float = 1e-9) -> bool:
    return math.isclose(a, b, rel_tol=rel_tol, abs_tol=abs_tol)


def _normalize_whitespace(text: str) -> str:
    return " ".join(text.split())


class ArticleAnalyzer(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.in_article = False
        self.in_script_style = 0
        self.text_parts = []
        self.images_count = 0
        self.total_links = 0
        self.outbound_domains = {}
        self.heading_counts = {1: 0, 2: 0, 3: 0}
        self.headings_extract = []
        self.heading_levels_seen = set()
        self.current_heading_level = None
        self.current_heading_text_parts = []

    def handle_starttag(self, tag, attrs):
        tag_l = tag.lower()
        if tag_l == "article":
            self.in_article = True
            return
        if not self.in_article:
            return

        if tag_l in ("script", "style"):
            self.in_script_style += 1
            return

        if tag_l == "img":
            self.images_count += 1

        if tag_l == "a":
            self.total_links += 1
            href = None
            for k, v in attrs:
                if k.lower() == "href":
                    href = v
                    break
            if href:
                parsed = urlparse(href)
                if parsed.scheme in ("http", "https") and parsed.netloc:
                    domain = parsed.netloc.lower()
                    self.outbound_domains[domain] = self.outbound_domains.get(domain, 0) + 1

        if tag_l in ("h1", "h2", "h3", "h4", "h5", "h6"):
            level = int(tag_l[1])
            self.current_heading_level = level
            self.current_heading_text_parts = []
            self.heading_levels_seen.add(level)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)

    def handle_endtag(self, tag):
        tag_l = tag.lower()
        if tag_l == "article":
            self.in_article = False
            return
        if not self.in_article:
            return

        if tag_l in ("script", "style"):
            if self.in_script_style > 0:
                self.in_script_style -= 1
            return

        if tag_l in ("h1", "h2", "h3", "h4", "h5", "h6"):
            if self.current_heading_level is not None:
                text = _normalize_whitespace("".join(self.current_heading_text_parts).strip())
                lvl = self.current_heading_level
                if lvl in (1, 2, 3):
                    self.heading_counts[lvl] = self.heading_counts.get(lvl, 0) + 1
                    self.headings_extract.append((lvl, text))
                self.current_heading_level = None
                self.current_heading_text_parts = []

    def handle_data(self, data):
        if self.in_article and self.in_script_style == 0:
            if data:
                self.text_parts.append(data)
                if self.current_heading_level is not None:
                    self.current_heading_text_parts.append(data)


def _compute_expected_tag_summary(posts_csv: Path):
    header, rows = _read_csv_dicts(posts_csv)
    if header is None or rows is None:
        return None

    required_cols = {"id", "title", "published_at", "tags", "words", "views", "likes", "comments", "shares"}
    if not required_cols.issubset(set(header or [])):
        return None

    posts = []
    for r in rows:
        try:
            views = int(r["views"])
            likes = int(r["likes"])
            comments = int(r["comments"])
            shares = int(r["shares"])
            words = int(r["words"])
            tags_str = r.get("tags", "")
            eng = (likes + comments + shares) / views if views > 0 else 0.0
            tag_list = [t.strip() for t in tags_str.split(";") if t.strip() != ""]
            posts.append({
                "views": views,
                "likes": likes,
                "comments": comments,
                "shares": shares,
                "words": words,
                "eng": float(eng),
                "tags": tag_list,
            })
        except Exception:
            return None

    if not posts:
        return None

    overall_median_eng = _median([p["eng"] for p in posts])
    if overall_median_eng is None:
        return None

    tag_groups = {}
    for p in posts:
        for tag in p["tags"]:
            tag_groups.setdefault(tag, []).append(p)

    result = []
    for tag, plist in tag_groups.items():
        if len(plist) >= 2:
            views_list = [p["views"] for p in plist]
            words_list = [p["words"] for p in plist]
            eng_list = [p["eng"] for p in plist]
            median_views = _median(views_list)
            median_words = _median(words_list)
            median_eng = _median(eng_list)
            count_above = sum(1 for e in eng_list if e >= overall_median_eng)
            pct_above = (count_above / len(plist)) * 100.0
            result.append({
                "tag": tag,
                "post_count": len(plist),
                "median_views": float(median_views),
                "median_engagement_rate": float(median_eng),
                "median_words": float(median_words),
                "pct_posts_above_overall_median_engagement": float(pct_above),
            })

    result.sort(key=lambda x: (-x["median_engagement_rate"], -x["median_views"]))
    return result


def _parse_student_tag_summary(path: Path):
    rows = _read_csv_rows(path)
    if rows is None:
        return None, None, False
    if not rows:
        return None, None, False
    header = rows[0]
    expected_header = ["tag", "post_count", "median_views", "median_engagement_rate", "median_words", "pct_posts_above_overall_median_engagement"]
    header_ok = header == expected_header
    if not header_ok:
        return header, rows[1:], False
    parsed = []
    for row in rows[1:]:
        if len(row) != len(expected_header):
            return header, None, True
        d = dict(zip(expected_header, row))
        parsed.append(d)
    return header, parsed, True


def _safe_int(x):
    try:
        return int(float(x))
    except Exception:
        return None


def _safe_float(x):
    try:
        return float(x)
    except Exception:
        return None


def _compute_expected_draft_metrics(draft_path: Path):
    try:
        html = draft_path.read_text(encoding="utf-8")
    except Exception:
        return None
    parser = ArticleAnalyzer()
    try:
        parser.feed(html)
    except Exception:
        return None

    text = " ".join(parser.text_parts)
    tokens = re.findall(r"\S+", text)
    word_count = sum(1 for tok in tokens if re.search(r"[A-Za-z0-9]", tok) is not None)
    total_words = int(word_count)
    reading_time = int(math.ceil(total_words / 220.0))

    heading_count_by_level = {
        "h1": parser.heading_counts.get(1, 0),
        "h2": parser.heading_counts.get(2, 0),
        "h3": parser.heading_counts.get(3, 0),
    }
    headings_extract = [{"level": lvl, "text": _normalize_whitespace(txt)} for (lvl, txt) in parser.headings_extract]

    max_depth = 0
    if parser.heading_levels_seen:
        max_depth = max(parser.heading_levels_seen)

    metrics = {
        "total_words": total_words,
        "estimated_reading_time_minutes": reading_time,
        "heading_count_by_level": heading_count_by_level,
        "headings_extract": headings_extract,
        "max_heading_depth": max_depth,
        "images_count": parser.images_count,
        "total_links": parser.total_links,
        "outbound_links_by_domain": parser.outbound_domains,
    }
    return metrics


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "tag_summary_file_and_header": 0.0,
        "tag_summary_rows_and_tags": 0.0,
        "tag_summary_values_match": 0.0,
        "tag_summary_sorting": 0.0,
        "draft_analysis_file_and_parseable": 0.0,
        "draft_analysis_word_and_time": 0.0,
        "draft_analysis_headings": 0.0,
        "draft_analysis_structure_counts": 0.0,
        "draft_analysis_outbound_domains": 0.0,
    }

    input_posts = workspace / "input" / "posts.csv"
    input_draft = workspace / "input" / "draft.html"
    out_dir = workspace / "outputs"
    tag_summary_path = out_dir / "tag_summary.csv"
    draft_analysis_path = out_dir / "draft_analysis.json"

    expected_tag_summary = None
    if input_posts.exists():
        expected_tag_summary = _compute_expected_tag_summary(input_posts)

    expected_draft = None
    if input_draft.exists():
        expected_draft = _compute_expected_draft_metrics(input_draft)

    header, parsed_rows, header_parseable = None, None, False
    if tag_summary_path.exists():
        header, parsed_rows, header_parseable = _parse_student_tag_summary(tag_summary_path)
        expected_header = ["tag", "post_count", "median_views", "median_engagement_rate", "median_words", "pct_posts_above_overall_median_engagement"]
        if header == expected_header:
            scores["tag_summary_file_and_header"] = 1.0
        else:
            scores["tag_summary_file_and_header"] = 0.0
    else:
        scores["tag_summary_file_and_header"] = 0.0

    if parsed_rows is not None and header_parseable and expected_tag_summary is not None:
        student_order = []
        student_by_tag = {}
        malformed = False
        for row in parsed_rows:
            tag = row.get("tag", "")
            if tag in student_by_tag:
                malformed = True
            student_order.append(tag)
            try:
                student_by_tag[tag] = {
                    "post_count": _safe_int(row.get("post_count")),
                    "median_views": _safe_float(row.get("median_views")),
                    "median_engagement_rate": _safe_float(row.get("median_engagement_rate")),
                    "median_words": _safe_float(row.get("median_words")),
                    "pct_posts_above_overall_median_engagement": _safe_float(row.get("pct_posts_above_overall_median_engagement")),
                }
            except Exception:
                malformed = True
        if not malformed:
            expected_tags = [r["tag"] for r in expected_tag_summary]
            expected_set = set(expected_tags)
            student_set = set(student_by_tag.keys())

            if student_set == expected_set and len(student_by_tag) == len(expected_set):
                scores["tag_summary_rows_and_tags"] = 1.0
            else:
                scores["tag_summary_rows_and_tags"] = 0.0

            if expected_tag_summary:
                total = len(expected_tag_summary)
                correct = 0
                for exp in expected_tag_summary:
                    tag = exp["tag"]
                    if tag not in student_by_tag:
                        continue
                    s = student_by_tag[tag]
                    if s["post_count"] is None or s["median_views"] is None or s["median_engagement_rate"] is None or s["median_words"] is None or s["pct_posts_above_overall_median_engagement"] is None:
                        continue
                    if s["post_count"] != exp["post_count"]:
                        continue
                    if not _isclose(s["median_views"], exp["median_views"]):
                        continue
                    if not _isclose(s["median_engagement_rate"], exp["median_engagement_rate"]):
                        continue
                    if not _isclose(s["median_words"], exp["median_words"]):
                        continue
                    if not _isclose(s["pct_posts_above_overall_median_engagement"], exp["pct_posts_above_overall_median_engagement"]):
                        continue
                    correct += 1
                if total > 0:
                    scores["tag_summary_values_match"] = correct / total
                else:
                    scores["tag_summary_values_match"] = 0.0

            if expected_tags and student_order:
                scores["tag_summary_sorting"] = 1.0 if student_order == expected_tags else 0.0

    student_json = None
    if draft_analysis_path.exists():
        student_json = _load_json(draft_analysis_path)
        if isinstance(student_json, dict):
            scores["draft_analysis_file_and_parseable"] = 1.0
        else:
            scores["draft_analysis_file_and_parseable"] = 0.0
    else:
        scores["draft_analysis_file_and_parseable"] = 0.0

    if expected_draft is not None and isinstance(student_json, dict):
        st_total_words = student_json.get("total_words")
        st_read_time = student_json.get("estimated_reading_time_minutes")
        if isinstance(st_total_words, int) and isinstance(st_read_time, int):
            if st_total_words == expected_draft["total_words"] and st_read_time == expected_draft["estimated_reading_time_minutes"]:
                scores["draft_analysis_word_and_time"] = 1.0

        heading_counts = student_json.get("heading_count_by_level")
        headings_extract = student_json.get("headings_extract")
        headings_ok = False
        if isinstance(heading_counts, dict) and isinstance(headings_extract, list):
            h1 = heading_counts.get("h1")
            h2 = heading_counts.get("h2")
            h3 = heading_counts.get("h3")
            counts_ok = isinstance(h1, int) and isinstance(h2, int) and isinstance(h3, int) and \
                        h1 == expected_draft["heading_count_by_level"]["h1"] and \
                        h2 == expected_draft["heading_count_by_level"]["h2"] and \
                        h3 == expected_draft["heading_count_by_level"]["h3"]
            student_hextract = []
            for item in headings_extract:
                if not isinstance(item, dict):
                    student_hextract = None
                    break
                lvl = item.get("level")
                text = item.get("text")
                if not isinstance(lvl, int) or not isinstance(text, str):
                    student_hextract = None
                    break
                if 1 <= lvl <= 3:
                    student_hextract.append({"level": lvl, "text": _normalize_whitespace(text)})
            if student_hextract is not None:
                headings_ok = counts_ok and (student_hextract == expected_draft["headings_extract"])
        scores["draft_analysis_headings"] = 1.0 if headings_ok else 0.0

        st_max_depth = student_json.get("max_heading_depth")
        st_images = student_json.get("images_count")
        st_links = student_json.get("total_links")
        if isinstance(st_max_depth, int) and isinstance(st_images, int) and isinstance(st_links, int):
            if st_max_depth == expected_draft["max_heading_depth"] and st_images == expected_draft["images_count"] and st_links == expected_draft["total_links"]:
                scores["draft_analysis_structure_counts"] = 1.0

        st_domains = student_json.get("outbound_links_by_domain")
        domains_ok = False
        if isinstance(st_domains, dict):
            try:
                normalized = {}
                for k, v in st_domains.items():
                    if not isinstance(k, str):
                        raise ValueError("Non-string domain")
                    vv = int(v)
                    normalized[k.lower()] = vv
                domains_ok = normalized == expected_draft["outbound_links_by_domain"]
            except Exception:
                domains_ok = False
        scores["draft_analysis_outbound_domains"] = 1.0 if domains_ok else 0.0

    return scores


def main() -> None:
    workspace_path = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace_path)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

import json
import csv
import re
import sys
from pathlib import Path
from typing import Any, Dict, List, Tuple, Optional


def _safe_read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _safe_load_json(path: Path) -> Optional[Any]:
    try:
        text = _safe_read_text(path)
        if text is None:
            return None
        return json.loads(text)
    except Exception:
        return None


def _parse_scalar(value: str) -> Any:
    v = value.strip()
    if len(v) >= 2 and ((v[0] == '"' and v[-1] == '"') or (v[0] == "'" and v[-1] == "'")):
        return v[1:-1]
    low = v.lower()
    if low == "true":
        return True
    if low == "false":
        return False
    if re.fullmatch(r"-?\d+", v):
        try:
            return int(v)
        except Exception:
            pass
    if re.fullmatch(r"-?\d+\.\d+", v):
        try:
            return float(v)
        except Exception:
            pass
    return v


def _parse_yaml_minimal(text: str) -> Optional[Dict[str, Any]]:
    lines = text.splitlines()
    root: Dict[str, Any] = {}
    stack: List[Tuple[int, Dict[str, Any]]] = [(-1, root)]
    for raw_line in lines:
        line = raw_line.split("#", 1)[0].rstrip()
        if not line.strip():
            continue
        indent = len(line) - len(line.lstrip(" "))
        if indent % 2 != 0:
            return None
        while stack and indent <= stack[-1][0]:
            stack.pop()
        if not stack:
            return None
        current = stack[-1][1]
        stripped = line.lstrip()
        if ":" not in stripped:
            return None
        key, _, rest = stripped.partition(":")
        key = key.strip()
        rest = rest.strip()
        if rest == "":
            if key in current and not isinstance(current[key], dict):
                return None
            new_dict: Dict[str, Any] = {}
            current[key] = new_dict
            stack.append((indent, new_dict))
        else:
            current[key] = _parse_scalar(rest)
    return root


def _parse_python_constants(text: str, names: List[str]) -> Dict[str, Any]:
    result: Dict[str, Any] = {}
    pattern = re.compile(r'^\s*([A-Z_][A-Z0-9_]*)\s*=\s*(.+?)\s*(#.*)?$')
    for line in text.splitlines():
        m = pattern.match(line)
        if not m:
            continue
        const, val_str, _ = m.groups()
        if const not in names:
            continue
        val = _parse_scalar(val_str)
        result[const] = val
    return result


def _safe_parse_csv_rows(path: Path) -> Optional[List[Dict[str, str]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            rows = [dict(r) for r in reader]
            return rows
    except Exception:
        return None


def _compute_expected_from_inputs(workspace: Path) -> Optional[Dict[str, Any]]:
    yaml_path = workspace / "config" / "study_space.yaml"
    code_path = workspace / "scripts" / "room_monitor.py"
    csv_path = workspace / "data" / "checkins.csv"
    yaml_text = _safe_read_text(yaml_path)
    code_text = _safe_read_text(code_path)
    rows = _safe_parse_csv_rows(csv_path)
    if yaml_text is None or code_text is None or rows is None:
        return None

    yaml_parsed = _parse_yaml_minimal(yaml_text)
    if yaml_parsed is None:
        return None

    def _get_nested(d: Dict[str, Any], keys: List[str]) -> Any:
        cur: Any = d
        for k in keys:
            if not isinstance(cur, dict) or k not in cur:
                return None
            cur = cur[k]
        return cur

    yaml_fields = {
        "quiet_hours.enabled": _get_nested(yaml_parsed, ["quiet_hours", "enabled"]),
        "quiet_hours.start": _get_nested(yaml_parsed, ["quiet_hours", "start"]),
        "quiet_hours.end": _get_nested(yaml_parsed, ["quiet_hours", "end"]),
        "noise_monitor.enabled": _get_nested(yaml_parsed, ["noise_monitor", "enabled"]),
        "noise_monitor.max_noise_db": _get_nested(yaml_parsed, ["noise_monitor", "max_noise_db"]),
        "break_policy.break_minutes": _get_nested(yaml_parsed, ["break_policy", "break_minutes"]),
    }

    const_names = [
        "QUIET_HOURS_ENABLED",
        "QUIET_HOURS_START",
        "QUIET_HOURS_END",
        "NOISE_MONITOR_ENABLED",
        "MAX_NOISE_DB",
    ]
    code_consts = _parse_python_constants(code_text, const_names)

    pairs = [
        ("quiet_hours.enabled", "QUIET_HOURS_ENABLED"),
        ("quiet_hours.start", "QUIET_HOURS_START"),
        ("quiet_hours.end", "QUIET_HOURS_END"),
        ("noise_monitor.enabled", "NOISE_MONITOR_ENABLED"),
        ("noise_monitor.max_noise_db", "MAX_NOISE_DB"),
    ]
    mismatches = []
    for yk, ck in pairs:
        yv = yaml_fields.get(yk, None)
        cv = code_consts.get(ck, None)
        if yv != cv:
            mismatches.append({
                "key": f"{yk}↔{ck}",
                "yaml_value": yv,
                "code_value": cv,
            })

    sessions: Dict[str, Dict[str, Any]] = {}
    unique_students: set = set()
    all_arrivals: List[float] = []
    dates_set: set = set()
    for r in rows:
        try:
            sid = r["session_id"]
            date = r["date"]
            student = r["student_id"]
            arr = float(r["arrived_minute"])
        except Exception:
            return None
        dates_set.add(date)
        unique_students.add(student)
        all_arrivals.append(arr)
        if sid not in sessions:
            sessions[sid] = {
                "date": date,
                "students": set(),
                "arrivals": [],
            }
        sessions[sid]["students"].add(student)
        sessions[sid]["arrivals"].append(arr)

    def _round2(x: float) -> float:
        return round(x, 2)

    expected_attendance_rows: Dict[str, Dict[str, Any]] = {}
    for sid, info in sessions.items():
        attendees = len(info["students"])
        avg_delay = _round2(sum(info["arrivals"]) / len(info["arrivals"])) if info["arrivals"] else 0.0
        expected_attendance_rows[sid] = {
            "session_id": sid,
            "date": info["date"],
            "attendees": attendees,
            "avg_arrival_delay_minutes": avg_delay,
        }

    total_sessions = len(expected_attendance_rows)
    total_unique_students = len(unique_students)
    overall_avg = _round2(sum(all_arrivals) / len(all_arrivals)) if all_arrivals else 0.0
    earliest = min(dates_set) if dates_set else None
    latest = max(dates_set) if dates_set else None

    return {
        "yaml_fields": yaml_fields,
        "code_consts": code_consts,
        "mismatches": mismatches,
        "expected_attendance_rows": expected_attendance_rows,
        "total_sessions": total_sessions,
        "total_unique_students": total_unique_students,
        "overall_avg": overall_avg,
        "earliest_date": earliest,
        "latest_date": latest,
    }


def _load_artifacts(workspace: Path) -> Dict[str, Any]:
    artifacts: Dict[str, Any] = {}
    artifacts["config_consistency"] = _safe_load_json(workspace / "output" / "config_consistency.json")
    artifacts["attendance_stats_rows"] = _safe_parse_csv_rows(workspace / "output" / "attendance_stats.csv")
    artifacts["overall_stats"] = _safe_load_json(workspace / "output" / "overall_stats.json")
    artifacts["meeting_notes"] = _safe_read_text(workspace / "output" / "meeting_notes.md")
    return artifacts


def _compare_dicts_exact(d1: Dict[str, Any], d2: Dict[str, Any]) -> bool:
    if set(d1.keys()) != set(d2.keys()):
        return False
    for k in d1:
        if d1[k] != d2[k]:
            return False
    return True


def _mismatches_equal(m1: List[Dict[str, Any]], m2: List[Dict[str, Any]]) -> bool:
    def norm_list(lst: List[Dict[str, Any]]) -> List[Tuple[str, Any, Any]]:
        res = []
        for d in lst:
            key = d.get("key")
            yv = d.get("yaml_value")
            cv = d.get("code_value")
            res.append((key, yv, cv))
        return sorted(res, key=lambda x: x[0])
    return norm_list(m1) == norm_list(m2)


def _rows_to_attendance_map(rows: List[Dict[str, str]]) -> Optional[Dict[str, Dict[str, Any]]]:
    required_headers = ["session_id", "date", "attendees", "avg_arrival_delay_minutes"]
    if not rows:
        return None
    first_row = rows[0]
    if list(first_row.keys()) != required_headers:
        return None
    result: Dict[str, Dict[str, Any]] = {}
    for r in rows:
        try:
            sid = r["session_id"]
            date = r["date"]
            attendees = int(r["attendees"])
            avg = float(r["avg_arrival_delay_minutes"])
        except Exception:
            return None
        result[sid] = {
            "session_id": sid,
            "date": date,
            "attendees": attendees,
            "avg_arrival_delay_minutes": round(avg, 2),
        }
    return result


def _find_section_indices(lines: List[str], titles: List[str]) -> Optional[Dict[str, Tuple[int, int]]]:
    indices: Dict[str, Tuple[int, int]] = {}
    last_idx = -1
    found_positions: List[int] = []
    for title in titles:
        found = -1
        for i in range(last_idx + 1, len(lines)):
            s = lines[i].strip()
            s = s.lstrip('#').strip()
            if s.lower() == title.lower():
                found = i
                break
        if found == -1:
            return None
        found_positions.append(found)
        last_idx = found
    for idx, start in enumerate(found_positions):
        if idx < len(found_positions) - 1:
            end = found_positions[idx + 1]
        else:
            end = len(lines)
        indices[titles[idx]] = (start, end)
    return indices


def _section_text(lines: List[str], start: int, end: int) -> str:
    return "\n".join(lines[start + 1:end]).strip()


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores: Dict[str, float] = {
        "config_consistency_json_exists_and_valid": 0.0,
        "config_yaml_fields_match_expected": 0.0,
        "config_code_constants_match_expected": 0.0,
        "config_mismatches_match_expected": 0.0,
        "attendance_stats_csv_correct_header_and_rows": 0.0,
        "overall_stats_json_correct_values": 0.0,
        "meeting_notes_sections_order": 0.0,
        "meeting_notes_context_includes_files_and_dates": 0.0,
        "meeting_notes_findings_section_mentions_mismatches": 0.0,
        "meeting_notes_attendance_summary_matches_artifacts": 0.0,
        "meeting_notes_action_items_follow_rules": 0.0,
    }

    expected = _compute_expected_from_inputs(workspace)
    artifacts = _load_artifacts(workspace)

    cc = artifacts["config_consistency"]
    if isinstance(cc, dict) and "yaml" in cc and "code" in cc and "mismatches" in cc and isinstance(cc["yaml"], dict) and isinstance(cc["code"], dict) and isinstance(cc["mismatches"], list):
        scores["config_consistency_json_exists_and_valid"] = 1.0

    if expected is not None and isinstance(cc, dict):
        exp_yaml = expected["yaml_fields"]
        if isinstance(cc.get("yaml"), dict) and _compare_dicts_exact(cc["yaml"], exp_yaml):
            scores["config_yaml_fields_match_expected"] = 1.0
        exp_code = expected["code_consts"]
        if isinstance(cc.get("code"), dict) and _compare_dicts_exact(cc["code"], exp_code):
            scores["config_code_constants_match_expected"] = 1.0
        if isinstance(cc.get("mismatches"), list) and _mismatches_equal(cc["mismatches"], expected["mismatches"]):
            scores["config_mismatches_match_expected"] = 1.0

    attendance_rows = artifacts["attendance_stats_rows"]
    attendance_ok = False
    if isinstance(attendance_rows, list) and len(attendance_rows) > 0:
        att_map = _rows_to_attendance_map(attendance_rows)
        if att_map is not None and expected is not None:
            exp_rows = expected["expected_attendance_rows"]
            if set(att_map.keys()) == set(exp_rows.keys()):
                same = True
                for sid, exp in exp_rows.items():
                    got = att_map[sid]
                    if got["date"] != exp["date"]:
                        same = False
                        break
                    if int(got["attendees"]) != int(exp["attendees"]):
                        same = False
                        break
                    if float(got["avg_arrival_delay_minutes"]) != float(exp["avg_arrival_delay_minutes"]):
                        same = False
                        break
                if same:
                    attendance_ok = True
    scores["attendance_stats_csv_correct_header_and_rows"] = 1.0 if attendance_ok else 0.0

    overall = artifacts["overall_stats"]
    overall_ok = False
    if expected is not None and isinstance(overall, dict):
        if (
            overall.get("total_sessions") == expected["total_sessions"]
            and overall.get("total_unique_students") == expected["total_unique_students"]
            and isinstance(overall.get("overall_avg_arrival_delay_minutes"), (int, float))
            and round(float(overall.get("overall_avg_arrival_delay_minutes")), 2) == float(expected["overall_avg"])
        ):
            overall_ok = True
    scores["overall_stats_json_correct_values"] = 1.0 if overall_ok else 0.0

    notes_text = artifacts["meeting_notes"]
    notes_lines = notes_text.splitlines() if isinstance(notes_text, str) else []
    titles = ["Context", "Config Consistency Findings", "Attendance Statistics Summary", "Action Items"]
    sections = _find_section_indices(notes_lines, titles) if notes_lines else None
    if sections is not None:
        scores["meeting_notes_sections_order"] = 1.0

    context_ok = False
    if sections is not None:
        ctx_start, ctx_end = sections["Context"]
        ctx_text = _section_text(notes_lines, ctx_start, ctx_end)
        if expected is not None:
            earliest = expected["earliest_date"]
            latest = expected["latest_date"]
        else:
            checkins = _safe_parse_csv_rows(workspace / "data" / "checkins.csv")
            if checkins:
                try:
                    dates = {r["date"] for r in checkins if "date" in r}
                    earliest = min(dates) if dates else None
                    latest = max(dates) if dates else None
                except Exception:
                    earliest = None
                    latest = None
            else:
                earliest = None
                latest = None
        if earliest and latest:
            mentions_dates = (earliest in ctx_text) and (latest in ctx_text)
        else:
            mentions_dates = False
        mentions_audit = "audit" in ctx_text.lower()
        mentions_files = all(p in ctx_text for p in ["config/study_space.yaml", "scripts/room_monitor.py", "data/checkins.csv"])
        if mentions_dates and mentions_audit and mentions_files:
            context_ok = True
    scores["meeting_notes_context_includes_files_and_dates"] = 1.0 if context_ok else 0.0

    findings_ok = False
    if sections is not None:
        f_start, f_end = sections["Config Consistency Findings"]
        f_text = _section_text(notes_lines, f_start, f_end)
        f_bullets = [ln.strip() for ln in f_text.splitlines() if ln.strip().startswith(("-", "*"))]
        if isinstance(cc, dict) and isinstance(cc.get("mismatches"), list):
            mismatches = cc["mismatches"]
            if mismatches:
                ok_count = 0
                for m in mismatches:
                    key = m.get("key", "")
                    parts = key.split("↔")
                    if len(parts) == 2:
                        yk, ck = parts[0], parts[1]
                        found = False
                        for bl in f_bullets:
                            if yk in bl and ck in bl:
                                found = True
                                break
                        if found:
                            ok_count += 1
                findings_ok = (ok_count == len(mismatches))
            else:
                findings_ok = ("none" in f_text.lower()) or ("no mismatch" in f_text.lower())
    scores["meeting_notes_findings_section_mentions_mismatches"] = 1.0 if findings_ok else 0.0

    attendance_summary_ok = False
    if sections is not None and isinstance(artifacts.get("overall_stats"), dict) and isinstance(artifacts.get("attendance_stats_rows"), list):
        a_start, a_end = sections["Attendance Statistics Summary"]
        a_text = _section_text(notes_lines, a_start, a_end)
        o = artifacts["overall_stats"]
        att_rows = artifacts["attendance_stats_rows"]
        att_map = _rows_to_attendance_map(att_rows) if isinstance(att_rows, list) else None
        if isinstance(o, dict) and att_map is not None:
            total_sessions_str = str(o.get("total_sessions"))
            total_unique_str = str(o.get("total_unique_students"))
            overall_avg_val = o.get("overall_avg_arrival_delay_minutes")
            try:
                overall_avg_str = f"{float(overall_avg_val):.2f}"
            except Exception:
                overall_avg_str = None
            low_sessions = sorted([sid for sid, rec in att_map.items() if int(rec["attendees"]) < 3])
            lows_present = all(ls in a_text for ls in low_sessions) if low_sessions else True
            nums_present = (total_sessions_str in a_text) and (total_unique_str in a_text) and (overall_avg_str in a_text if overall_avg_str else False)
            attendance_summary_ok = nums_present and lows_present
    scores["meeting_notes_attendance_summary_matches_artifacts"] = 1.0 if attendance_summary_ok else 0.0

    actions_ok = False
    if sections is not None:
        ai_start, ai_end = sections["Action Items"]
        ai_text = _section_text(notes_lines, ai_start, ai_end)
        ai_bullets = [ln.strip()[1:].strip() for ln in ai_text.splitlines() if ln.strip().startswith(("-", "*"))]

        expected_actions: List[str] = []

        if isinstance(cc, dict) and isinstance(cc.get("mismatches"), list):
            for m in cc["mismatches"]:
                key = m.get("key", "")
                parts = key.split("↔")
                if len(parts) == 2:
                    const = parts[1]
                    code_val = m.get("code_value")
                    yaml_val = m.get("yaml_value")
                    expected_actions.append(f"Update scripts/room_monitor.py {const} from {code_val} to {yaml_val} to match config.")

        try:
            yaml_block = cc.get("yaml") if isinstance(cc, dict) else None
            if isinstance(yaml_block, dict):
                bpm = yaml_block.get("break_policy.break_minutes")
                if isinstance(bpm, (int, float)) and bpm < 5:
                    expected_actions.append("Update config/study_space.yaml break_policy.break_minutes to 5 to ensure sufficient breaks.")
        except Exception:
            pass

        try:
            if isinstance(yaml_block, dict):
                qh_enabled = yaml_block.get("quiet_hours.enabled")
                max_db = yaml_block.get("noise_monitor.max_noise_db")
                if bool(qh_enabled) and isinstance(max_db, (int, float)) and max_db > 45:
                    expected_actions.append("Reduce config/study_space.yaml noise_monitor.max_noise_db to 45 for quieter study hours.")
        except Exception:
            pass

        low_list: List[str] = []
        if isinstance(artifacts.get("attendance_stats_rows"), list):
            att_map2 = _rows_to_attendance_map(artifacts["attendance_stats_rows"])  # type: ignore
            if att_map2 is not None:
                low_list = sorted([sid for sid, rec in att_map2.items() if int(rec["attendees"]) < 3])
                if len(low_list) > 0:
                    expected_actions.append(f"Consider consolidating low-attendance sessions: {','.join(low_list)}.")

        if isinstance(artifacts.get("overall_stats"), dict):
            try:
                avg_val = float(artifacts["overall_stats"].get("overall_avg_arrival_delay_minutes"))  # type: ignore
                if avg_val > 5.00:
                    expected_actions.append("Send a reminder encouraging on-time arrivals (aim for ≤5 minutes average delay).")
            except Exception:
                pass

        def normalize(s: str) -> str:
            return " ".join(s.strip().split())

        ai_norm = [normalize(s) for s in ai_bullets]
        exp_norm = [normalize(s) for s in expected_actions]

        def bullet_matches_expected(bullet: str, expected_str: str) -> bool:
            if expected_str.startswith("Update scripts/room_monitor.py "):
                m = re.match(r"Update scripts/room_monitor.py ([A-Z0-9_]+) from (.+) to (.+) to match config\.", expected_str)
                if m:
                    const, code_v, yaml_v = m.groups()
                    return ("Update scripts/room_monitor.py" in bullet
                            and const in bullet
                            and "from" in bullet
                            and str(code_v).strip().strip('"').strip("'") in bullet.replace('"', '').replace("'", "")
                            and "to" in bullet
                            and str(yaml_v).strip().strip('"').strip("'") in bullet.replace('"', '').replace("'", "")
                            and "match config" in bullet)
            return normalize(bullet) == normalize(expected_str)

        if len(ai_norm) == len(exp_norm) and all(any(bullet_matches_expected(b, e) for b in ai_bullets) for e in expected_actions):
            unmatched_indices = set(range(len(ai_bullets)))
            for e in expected_actions:
                found_idx = None
                for idx in list(unmatched_indices):
                    if bullet_matches_expected(ai_bullets[idx], e):
                        found_idx = idx
                        break
                if found_idx is not None:
                    unmatched_indices.discard(found_idx)
            actions_ok = (len(unmatched_indices) == 0)
    scores["meeting_notes_action_items_follow_rules"] = 1.0 if actions_ok else 0.0

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

import csv
import json
import math
import sys
from pathlib import Path
from datetime import datetime
from statistics import median


def _read_csv_dicts(path: Path):
    try:
        with path.open(newline="", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            rows = [dict(r) for r in reader]
            return rows, reader.fieldnames
    except Exception:
        return None, None


def _parse_date_ymd(s: str):
    try:
        return datetime.strptime(s, "%Y-%m-%d").date()
    except Exception:
        return None


def _month_from_date_str(s: str):
    d = _parse_date_ymd(s)
    if d is None:
        return None
    return f"{d.year:04d}-{d.month:02d}"


def _format_money(amount: float) -> str:
    return f"{amount:.2f}"


def _format_pct_one_decimal(p: float) -> str:
    # Standard rounding to one decimal
    return f"{round(p, 1):.1f}"


def _is_two_decimals(s: str) -> bool:
    if not isinstance(s, str):
        return False
    parts = s.split(".")
    if len(parts) != 2:
        return False
    if not parts[0].lstrip("-").isdigit():
        return False
    return len(parts[1]) == 2 and parts[1].isdigit()


def _safe_float(s):
    try:
        return float(s)
    except Exception:
        return None


def _sum_by_date(rows, date_key: str, value_key: str):
    sums = {}
    for r in rows:
        date = r.get(date_key, "")
        try:
            val = float(r.get(value_key, 0))
        except Exception:
            return None
        if date not in sums:
            sums[date] = 0.0
        sums[date] += val
    return sums


def _compute_expected_per_match(match_rows, travel_rows):
    # travel: sum cost for same date
    travel_map = _sum_by_date(travel_rows, "date", "cost_chf") if travel_rows is not None else {}
    if travel_map is None:
        return None
    expected = []
    for r in match_rows:
        date = r.get("date", "")
        op = r.get("opponent", "")
        ha = r.get("home_away", "")
        ticket_str = r.get("ticket_chf", "")
        t_val = _safe_float(ticket_str)
        if date == "" or op == "" or ha == "" or t_val is None:
            return None
        travel_cost = travel_map.get(date, 0.0)
        per_total = t_val + travel_cost
        expected.append({
            "date": date,
            "opponent": op,
            "home_away": ha,
            "ticket_chf": _format_money(t_val),
            "travel_same_day_chf": _format_money(travel_cost),
            "per_match_total_chf": _format_money(per_total),
        })
    # sort ascending by date
    expected.sort(key=lambda x: x["date"])
    return expected


def _compute_expected_monthly(match_rows, travel_rows, merch_rows):
    # tickets by month
    tickets_by_month = {}
    for r in match_rows or []:
        m = _month_from_date_str(r.get("date", ""))
        v = _safe_float(r.get("ticket_chf", ""))
        if m is None or v is None:
            return None
        tickets_by_month[m] = tickets_by_month.get(m, 0.0) + v
    # travel by month
    travel_by_month = {}
    for r in travel_rows or []:
        m = _month_from_date_str(r.get("date", ""))
        v = _safe_float(r.get("cost_chf", ""))
        if m is None or v is None:
            return None
        travel_by_month[m] = travel_by_month.get(m, 0.0) + v
    # merch by month
    merch_by_month = {}
    for r in merch_rows or []:
        m = _month_from_date_str(r.get("date", ""))
        v = _safe_float(r.get("price_chf", ""))
        if m is None or v is None:
            return None
        merch_by_month[m] = merch_by_month.get(m, 0.0) + v
    all_months = sorted(set(list(tickets_by_month.keys()) + list(travel_by_month.keys()) + list(merch_by_month.keys())))
    expected = []
    for m in all_months:
        t = tickets_by_month.get(m, 0.0)
        tr = travel_by_month.get(m, 0.0)
        me = merch_by_month.get(m, 0.0)
        total = t + tr + me
        expected.append({
            "month": m,
            "tickets_chf": _format_money(t),
            "travel_chf": _format_money(tr),
            "merch_chf": _format_money(me),
            "total_chf": _format_money(total),
        })
    return expected


def _compute_expected_season(match_rows, travel_rows, merch_rows, expected_per_match, expected_monthly):
    if match_rows is None or travel_rows is None or merch_rows is None or expected_per_match is None or expected_monthly is None:
        return None
    # totals
    total_tickets = 0.0
    tickets_list = []
    for r in match_rows:
        v = _safe_float(r.get("ticket_chf", ""))
        if v is None:
            return None
        total_tickets += v
        tickets_list.append(v)
    total_travel = 0.0
    for r in travel_rows:
        v = _safe_float(r.get("cost_chf", ""))
        if v is None:
            return None
        total_travel += v
    total_merch = 0.0
    for r in merch_rows:
        v = _safe_float(r.get("price_chf", ""))
        if v is None:
            return None
        total_merch += v
    overall_total = total_tickets + total_travel + total_merch
    matches_attended = len(match_rows)
    # average per match from expected per match totals
    per_totals = []
    for r in expected_per_match:
        v = _safe_float(r.get("per_match_total_chf", ""))
        if v is None:
            return None
        per_totals.append(v)
    avg_per_match = sum(per_totals) / len(per_totals) if per_totals else 0.0
    # median ticket
    med_ticket = float(median(tickets_list)) if tickets_list else 0.0
    # top months (by total_chf descending, then month ascending for determinism)
    monthly_totals = [(r["month"], _safe_float(r["total_chf"])) for r in expected_monthly]
    if any(v is None for _, v in monthly_totals):
        return None
    monthly_totals.sort(key=lambda x: (-x[1], x[0]))
    top1 = monthly_totals[0][0] if monthly_totals else ""
    top2 = monthly_totals[1][0] if len(monthly_totals) > 1 else ""
    # shares
    if overall_total > 0:
        tickets_share = total_tickets / overall_total * 100.0
        travel_share = total_travel / overall_total * 100.0
        merch_share = total_merch / overall_total * 100.0
    else:
        tickets_share = travel_share = merch_share = 0.0
    # top home opponents by ticket
    home_rows = [r for r in match_rows if r.get("home_away", "") == "home"]
    # sort by ticket desc then opponent asc
    home_sorted = sorted(
        home_rows,
        key=lambda r: (-_safe_float(r.get("ticket_chf", "0")) if _safe_float(r.get("ticket_chf", "0")) is not None else 0.0,
                       r.get("opponent", ""))
    )
    top_home = [r.get("opponent", "") for r in home_sorted[:2]]
    top_home_str = ";".join(top_home)

    expected = {
        "total_tickets_chf": _format_money(total_tickets),
        "total_travel_chf": _format_money(total_travel),
        "total_merch_chf": _format_money(total_merch),
        "overall_total_chf": _format_money(overall_total),
        "matches_attended": str(matches_attended),
        "average_per_match_chf": _format_money(avg_per_match),
        "median_ticket_chf": _format_money(med_ticket),
        "top_month_1": top1,
        "top_month_2": top2,
        "tickets_share_pct": _format_pct_one_decimal(tickets_share),
        "travel_share_pct": _format_pct_one_decimal(travel_share),
        "merch_share_pct": _format_pct_one_decimal(merch_share),
        "top_home_opponents_by_ticket": top_home_str,
    }
    return expected


def _read_output_csv_rows(path: Path):
    try:
        with path.open(newline="", encoding="utf-8") as f:
            reader = csv.reader(f)
            rows = [row for row in reader]
        return rows
    except Exception:
        return None


def _round_to_nearest_10_half_up(x: float) -> int:
    # For positive numbers, half-up rounding to nearest 10
    return int(math.floor((x + 5) / 10.0) * 10)


def _ceil_to_next_multiple(x: float, base: int) -> int:
    return int(math.ceil(x / base) * base)


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "per_match_costs_exists_and_structure": 0.0,
        "per_match_costs_values_and_sort": 0.0,
        "monthly_breakdown_correct": 0.0,
        "season_summary_metrics_complete": 0.0,
        "season_summary_values_correct": 0.0,
        "fan_budget_report_placeholders_and_values": 0.0,
        "fan_budget_recommendations": 0.0,
    }

    # Load inputs
    match_path = workspace / "input" / "match_attendance.csv"
    travel_path = workspace / "input" / "travel.csv"
    merch_path = workspace / "input" / "merch.csv"
    draft_path = workspace / "input" / "draft_budget.md"

    match_rows, match_fields = _read_csv_dicts(match_path) if match_path.exists() else (None, None)
    travel_rows, travel_fields = _read_csv_dicts(travel_path) if travel_path.exists() else (None, None)
    merch_rows, merch_fields = _read_csv_dicts(merch_path) if merch_path.exists() else (None, None)

    # Compute expected structures only if inputs are present and parseable
    expected_per_match = None
    expected_monthly = None
    expected_season = None
    if match_rows is not None and travel_rows is not None and merch_rows is not None:
        expected_per_match = _compute_expected_per_match(match_rows, travel_rows)
        expected_monthly = _compute_expected_monthly(match_rows, travel_rows, merch_rows)
        if expected_per_match is not None and expected_monthly is not None:
            expected_season = _compute_expected_season(match_rows, travel_rows, merch_rows, expected_per_match, expected_monthly)

    # 1) per_match_costs.csv checks
    per_match_out = workspace / "output" / "per_match_costs.csv"
    per_rows = _read_output_csv_rows(per_match_out) if per_match_out.exists() else None
    expected_header_per = ["date", "opponent", "home_away", "ticket_chf", "travel_same_day_chf", "per_match_total_chf"]
    if per_rows is not None and len(per_rows) >= 1:
        header = per_rows[0]
        structure_ok = header == expected_header_per
        values_ok = False
        if structure_ok and expected_per_match is not None:
            # Compare row counts and values
            data_rows = per_rows[1:]
            if len(data_rows) == len(expected_per_match):
                # Build parsed rows as dicts
                rows_ok = True
                # Check order by date ascending
                dates_in_file = [r[0] if len(r) >= 1 else "" for r in data_rows]
                if dates_in_file != sorted(dates_in_file):
                    rows_ok = False
                # Compare each row with expected
                for i, exp in enumerate(expected_per_match):
                    row = data_rows[i] if i < len(data_rows) else None
                    if row is None or len(row) != 6:
                        rows_ok = False
                        break
                    comp = {
                        "date": row[0],
                        "opponent": row[1],
                        "home_away": row[2],
                        "ticket_chf": row[3],
                        "travel_same_day_chf": row[4],
                        "per_match_total_chf": row[5],
                    }
                    if comp != exp:
                        rows_ok = False
                        break
                    # Check numeric format for numeric columns
                    if not (_is_two_decimals(comp["ticket_chf"]) and _is_two_decimals(comp["travel_same_day_chf"]) and _is_two_decimals(comp["per_match_total_chf"])):
                        rows_ok = False
                        break
                values_ok = rows_ok
        if structure_ok:
            scores["per_match_costs_exists_and_structure"] = 1.0
        if values_ok:
            scores["per_match_costs_values_and_sort"] = 1.0

    # 2) monthly_breakdown.csv
    monthly_out = workspace / "output" / "monthly_breakdown.csv"
    mon_rows = _read_output_csv_rows(monthly_out) if monthly_out.exists() else None
    expected_header_monthly = ["month", "tickets_chf", "travel_chf", "merch_chf", "total_chf"]
    if mon_rows is not None and len(mon_rows) >= 1:
        header = mon_rows[0]
