import json
import os
import sys
from datetime import datetime

def nearly_equal(a, b, tol=1e-2):
    try:
        return abs(float(a) - float(b)) <= tol
    except Exception:
        return False

def read_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

def safe_get(d, keys, default=None):
    for k in keys:
        if k in d and d[k] is not None:
            return d[k]
    return default

def parse_leaderboard(lb):
    # Accept list or dict with "data"
    rows = lb
    if isinstance(lb, dict):
        rows = lb.get("data") or lb.get("rows") or lb.get("leaders") or []
    if not isinstance(rows, list):
        rows = []
    result = []
    for w in rows:
        name = safe_get(w, ["name", "userName", "pseudonym"], "")
        address = safe_get(w, ["address", "proxyWallet"], "")
        pnl = safe_get(w, ["pnl", "profit"], 0.0)
        vol = safe_get(w, ["vol", "volume"], 0.0)
        if address:
            result.append({
                "name": str(name),
                "address": str(address),
                "pnl": float(pnl) if isinstance(pnl, (int, float, str)) and str(pnl).strip() != "" else 0.0,
                "vol": float(vol) if isinstance(vol, (int, float, str)) and str(vol).strip() != "" else 0.0,
            })
    return result

def parse_positions_list(data):
    # positions may be a list at top-level or under a key
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ["positions", "data", "items"]:
            if key in data and isinstance(data[key], list):
                return data[key]
    return []

def normalize_position(p, markets_map):
    # Extract fields with flexible keys
    condition_id = safe_get(p, ["conditionId", "condition_id", "marketId", "conditionID", "id"])
    if condition_id is None:
        return None
    condition_id = str(condition_id)

    outcome_raw = safe_get(p, ["outcome", "side"])
    outcome = str(outcome_raw).strip().upper() if outcome_raw is not None else None
    if outcome not in ("YES", "NO"):
        # try normalizing truthy/falsey
        if str(outcome_raw).lower() in ("y", "true", "1"):
            outcome = "YES"
        elif str(outcome_raw).lower() in ("n", "false", "0"):
            outcome = "NO"
        else:
            # leave as-is uppercase token
            outcome = str(outcome_raw).strip().upper() if outcome_raw is not None else ""

    shares = safe_get(p, ["shares", "size", "quantity", "qty", "currentValue"])
    try:
        shares = float(shares)
    except Exception:
        return None

    avg_price = safe_get(p, ["avg_price", "avgPrice", "averagePrice"])
    curr_price = safe_get(p, ["curr_price", "curPrice", "currentPrice", "price"])

    try:
        avg_price = float(avg_price)
    except Exception:
        avg_price = None
    try:
        curr_price = float(curr_price)
    except Exception:
        curr_price = None

    # Require prices to compute results
    if avg_price is None or curr_price is None:
        return None

    # Title resolution
    title = safe_get(p, ["market_title", "title", "market", "question"])
    market_title = str(title) if title else markets_map.get(condition_id) or condition_id

    position_usd = curr_price * shares
    pnl_usd = (curr_price - avg_price) * shares

    return {
        "conditionId": condition_id,
        "market_title": market_title,
        "outcome": outcome,
        "shares": shares,
        "avg_price": avg_price,
        "curr_price": curr_price,
        "position_usd": position_usd,
        "pnl_usd": pnl_usd,
    }

def compute_expected(workspace_root, min_threshold=10.0):
    input_dir = os.path.join(workspace_root, "input")
    # Load leaderboard and markets
    lb_path = os.path.join(input_dir, "leaderboard.json")
    mk_path = os.path.join(input_dir, "markets.json")
    positions_dir = os.path.join(input_dir, "positions")

    lb = read_json(lb_path)
    markets = read_json(mk_path)
    # markets.json assumed mapping of conditionId to question string
    if isinstance(markets, dict):
        markets_map = {str(k): str(v) for k, v in markets.items()}
    else:
        # fallback if provided as list of {conditionId, question}
        markets_map = {}
        if isinstance(markets, list):
            for m in markets:
                cid = safe_get(m, ["conditionId", "id"])
                q = safe_get(m, ["question", "title"])
                if cid and q:
                    markets_map[str(cid)] = str(q)

    whales_lb = parse_leaderboard(lb)
    # Intersect with positions files present
    available_files = set()
    if os.path.isdir(positions_dir):
        for fn in os.listdir(positions_dir):
            if fn.lower().endswith(".json"):
                available_files.add(fn[:-5])  # strip .json

    whales = []
    for w in whales_lb:
        if w["address"] in available_files:
            whales.append(w)

    # Ensure deterministic set (expected exactly three)
    whales_by_addr = {w["address"]: w for w in whales}

    # Build expected positions per whale
    expected_whale_positions = {}
    for addr, whale in whales_by_addr.items():
        path = os.path.join(positions_dir, f"{addr}.json")
        try:
            pdata = read_json(path)
        except Exception:
            pdata = []
        plist = parse_positions_list(pdata)
        normalized = []
        for p in plist:
            norm = normalize_position(p, markets_map)
            if norm is None:
                continue
            if norm["position_usd"] >= min_threshold:
                # Ensure market_title resolution uses markets mapping if available
                resolved_title = markets_map.get(norm["conditionId"], norm["market_title"])
                norm["market_title"] = resolved_title
                normalized.append(norm)
        expected_whale_positions[addr] = normalized

    # Compute signals
    # group key: (conditionId, outcome)
    groups = {}
    for addr, positions in expected_whale_positions.items():
        name = whales_by_addr.get(addr, {}).get("name", "")
        for p in positions:
            key = (p["conditionId"], p["outcome"])
            g = groups.setdefault(key, {"conditionId": p["conditionId"], "outcome": p["outcome"], "market_title": p["market_title"], "whales": []})
            g["whales"].append({
                "address": addr,
                "name": name,
                "position_usd": p["position_usd"],
            })

    expected_signals = []
    for key, g in groups.items():
        whales_list = g["whales"]
        num_whales = len(whales_list)
        total_position_usd = sum(w["position_usd"] for w in whales_list)
        conviction = None
        if num_whales >= 2:
            conviction = "high"
        elif num_whales == 1 and total_position_usd >= 50000:
            conviction = "medium"
        if conviction:
            expected_signals.append({
                "conditionId": g["conditionId"],
                "market_title": g["market_title"],
                "outcome": g["outcome"],
                "conviction": conviction,
                "num_whales": num_whales,
                "total_position_usd": total_position_usd,
                "whales": whales_list,
            })

    return whales_by_addr, expected_whale_positions, expected_signals, markets_map

def validate_whale_positions(out_path, whales_by_addr, expected_whale_positions, markets_map, min_threshold=10.0):
    checks = {
        "whale_positions_exists": False,
        "whale_positions_json_valid": False,
        "whale_positions_min_threshold": False,
        "whales_count_and_identity": False,
        "whales_have_pnl_vol_numeric": False,
        "positions_titles_resolved": False,
        "positions_values_correct": False,
        "positions_filter_applied": False,
        "positions_counts_match": False,
    }
    if not os.path.isfile(out_path):
        return checks

    checks["whale_positions_exists"] = True

    try:
        data = read_json(out_path)
        checks["whale_positions_json_valid"] = isinstance(data, dict)
    except Exception:
        return checks

    if not isinstance(data, dict):
        return checks

    # min_position_usd
    if "min_position_usd" in data and data["min_position_usd"] == 10:
        checks["whale_positions_min_threshold"] = True

    whales = data.get("whales")
    if not isinstance(whales, list):
        return checks

    # Check count and identity (addresses and names)
    expected_addresses = set(whales_by_addr.keys())
    out_addresses = set()
    name_match = True
    for w in whales:
        addr = w.get("address")
        name = w.get("name")
        if isinstance(addr, str):
            out_addresses.add(addr)
            exp = whales_by_addr.get(addr)
            if exp:
                if str(name) != str(exp["name"]):
                    name_match = False
    if out_addresses == expected_addresses and name_match and len(whales) == len(expected_addresses):
        checks["whales_count_and_identity"] = True

    # Check pnl and vol numeric
    pnl_vol_ok = True
    for w in whales:
        pnl = w.get("pnl")
        vol = w.get("vol")
        try:
            _ = float(pnl)
            _ = float(vol)
        except Exception:
            pnl_vol_ok = False
            break
    checks["whales_have_pnl_vol_numeric"] = pnl_vol_ok

    # Positions per whale
    titles_ok = True
    values_ok = True
    filter_ok = True
    counts_ok = True

    # Build mapping from out whales by address
    whales_by_addr_out = {w.get("address"): w for w in whales if isinstance(w, dict) and "address" in w}

    for addr, expected_positions in expected_whale_positions.items():
        out_w = whales_by_addr_out.get(addr)
        out_positions = out_w.get("positions") if isinstance(out_w, dict) else None
        if not isinstance(out_positions, list):
            counts_ok = False
            values_ok = False
            titles_ok = False
            filter_ok = False
            continue

        # Check filter: no positions under threshold
        for p in out_positions:
            pos_usd = p.get("position_usd")
            try:
                if float(pos_usd) < min_threshold:
                    filter_ok = False
                    break
            except Exception:
                filter_ok = False
                break

        # Compare counts
        if len(out_positions) != len(expected_positions):
            counts_ok = False

        # Build index by (conditionId, outcome)
        out_index = {}
        for p in out_positions:
            cid = str(p.get("conditionId"))
            outcome = str(p.get("outcome")).upper() if p.get("outcome") else ""
            out_index[(cid, outcome)] = p

        for ep in expected_positions:
            key = (ep["conditionId"], ep["outcome"])
            op = out_index.get(key)
            if not op:
                values_ok = False
                titles_ok = False
                continue
            # Title
            exp_title = markets_map.get(ep["conditionId"], ep["market_title"])
            if str(op.get("market_title")) != str(exp_title):
                titles_ok = False
            # Numeric fields
            try:
                shares_ok = nearly_equal(op.get("shares"), ep["shares"], tol=1e-4)
                avg_ok = nearly_equal(op.get("avg_price"), ep["avg_price"], tol=1e-4)
                curr_ok = nearly_equal(op.get("curr_price"), ep["curr_price"], tol=1e-4)
                pos_ok = nearly_equal(op.get("position_usd"), ep["position_usd"], tol=1e-2)
                pnl_ok = nearly_equal(op.get("pnl_usd"), ep["pnl_usd"], tol=1e-2)
                if not (shares_ok and avg_ok and curr_ok and pos_ok and pnl_ok):
                    values_ok = False
            except Exception:
                values_ok = False

    checks["positions_titles_resolved"] = titles_ok
    checks["positions_values_correct"] = values_ok
    checks["positions_filter_applied"] = filter_ok
    checks["positions_counts_match"] = counts_ok

    return checks

def validate_signals(out_path, expected_signals, markets_map, min_threshold=10.0):
    checks = {
        "signals_exists": False,
        "signals_json_valid": False,
        "signals_min_threshold": False,
        "signals_count_correct": False,
        "signals_groups_correct": False,
        "signals_values_correct": False,
        "signals_no_extras": False,
    }
    if not os.path.isfile(out_path):
        return checks

    checks["signals_exists"] = True

    try:
        data = read_json(out_path)
        checks["signals_json_valid"] = isinstance(data, dict)
    except Exception:
        return checks

    if not isinstance(data, dict):
        return checks

    if "min_position_usd" in data and data["min_position_usd"] == 10:
        checks["signals_min_threshold"] = True

    out_signals = data.get("signals")
    if not isinstance(out_signals, list):
        return checks

    # Count check
    if len(out_signals) == len(expected_signals):
        checks["signals_count_correct"] = True

    # Build index for comparison: (conditionId, outcome)
    def key_sig(s):
        return (str(s.get("conditionId")), str(s.get("outcome")).upper() if s.get("outcome") else "")

    out_index = {key_sig(s): s for s in out_signals}

    groups_ok = True
    values_ok = True

    for es in expected_signals:
        key = (es["conditionId"], es["outcome"])
        osig = out_index.get(key)
        if not osig:
            groups_ok = False
            values_ok = False
            continue
        # Title
        exp_title = markets_map.get(es["conditionId"], es["market_title"])
        if str(osig.get("market_title")) != str(exp_title):
            groups_ok = False
        # Conviction and counts
        if osig.get("conviction") != es["conviction"]:
            values_ok = False
        if int(osig.get("num_whales") or -1) != int(es["num_whales"]):
            values_ok = False
        # Total
        if not nearly_equal(osig.get("total_position_usd"), es["total_position_usd"], tol=1e-2):
            values_ok = False
        # Whales list contents (addresses and per-position_usd)
        ow = osig.get("whales")
        if not isinstance(ow, list):
            values_ok = False
            continue
        exp_addr_map = {w["address"]: w for w in es["whales"]}
        out_addr_map = {w.get("address"): w for w in ow if isinstance(w, dict) and w.get("address")}
        if set(exp_addr_map.keys()) != set(out_addr_map.keys()):
            values_ok = False
        else:
            for addr, ew in exp_addr_map.items():
                ow_entry = out_addr_map.get(addr)
                if not ow_entry:
                    values_ok = False
                    continue
                # Check position_usd per whale
                if not nearly_equal(ow_entry.get("position_usd"), ew["position_usd"], tol=1e-2):
                    values_ok = False
                # Name is optional in spec but we verify if present
                if "name" in ow_entry:
                    if str(ow_entry["name"]) != str(ew["name"]):
                        values_ok = False

    checks["signals_groups_correct"] = groups_ok
    checks["signals_values_correct"] = values_ok

    # No extras: ensure that every out signal is expected
    expected_keys = {(es["conditionId"], es["outcome"]) for es in expected_signals}
    out_keys = set(out_index.keys())
    if out_keys == expected_keys:
        checks["signals_no_extras"] = True

    return checks

def main():
    workspace_root = sys.argv[1] if len(sys.argv) > 1 else "/root/.openclaw/workspace"
    input_dir = os.path.join(workspace_root, "input")
    output_dir = os.path.join(workspace_root, "output")

    # Compute expected from inputs
    try:
        whales_by_addr, expected_whale_positions, expected_signals, markets_map = compute_expected(workspace_root, min_threshold=10.0)
    except Exception:
        # If inputs missing or malformed, we cannot grant reward, but we should still output JSON
        whales_by_addr, expected_whale_positions, expected_signals, markets_map = {}, {}, [], {}

    # Validate outputs
    whale_positions_path = os.path.join(output_dir, "whale_positions.json")
    signals_path = os.path.join(output_dir, "signals.json")

    checks_wp = validate_whale_positions(whale_positions_path, whales_by_addr, expected_whale_positions, markets_map, min_threshold=10.0)
    checks_sig = validate_signals(signals_path, expected_signals, markets_map, min_threshold=10.0)

    checks = {}
    checks.update(checks_wp)
    checks.update(checks_sig)

    # Compute reward: proportion of passed checks; baseline 0.0 if outputs missing or empty
    total_checks = len(checks)
    passed_checks = sum(1 for v in checks.values() if v)
    # Ensure baseline no-op yields 0.0
    if not checks.get("whale_positions_exists") and not checks.get("signals_exists"):
        reward = 0.0
    else:
        reward = passed_checks / total_checks if total_checks > 0 else 0.0

    # Clamp reward between 0 and 1
    if reward < 0:
        reward = 0.0
    if reward > 1:
        reward = 1.0

    result = {"reward": float(reward)}
    result.update(checks)

    # Print exactly one JSON object on the last non-empty line
    print(json.dumps(result))

if __name__ == "__main__":
    main()

import csv
import json
import re
import sys
from datetime import date, datetime
from pathlib import Path
from statistics import mean
from typing import Dict, List, Optional, Tuple


def safe_read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def safe_load_csv(path: Path) -> Optional[List[Dict[str, str]]]:
    try:
        with path.open(newline="", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            return list(reader)
    except Exception:
        return None


def parse_iso_date(s: str) -> Optional[date]:
    try:
        y, m, d = s.split("-")
        return date(int(y), int(m), int(d))
    except Exception:
        return None


def parse_yaml_trip_config(text: str) -> Optional[Dict]:
    """
    Minimal YAML parser for the expected structure:
    destination: str
    start_date: YYYY-MM-DD
    end_date: YYYY-MM-DD
    comfort:
      min_c: number
      max_c: number
    """
    try:
        conf: Dict = {}
        lines = text.splitlines()
        i = 0
        current_section = None
        base_indent = 0
        while i < len(lines):
            raw = lines[i]
            line = raw.split("#", 1)[0].rstrip("\n")
            if not line.strip():
                i += 1
                continue
            if ":" in line:
                # measure indent
                indent = len(line) - len(line.lstrip(" "))
                key, val = line.split(":", 1)
                key = key.strip()
                val = val.strip()
                if key == "comfort":
                    current_section = "comfort"
                    conf[current_section] = {}
                    base_indent = indent
                else:
                    current_section = None
                    if val == "":
                        conf[key] = None
                    else:
                        conf[key] = val
            else:
                # ignore lines we can't parse
                pass
            # handle nested comfort
            if current_section == "comfort":
                # consume subsequent indented lines
                j = i + 1
                while j < len(lines):
                    sub_raw = lines[j]
                    sub = sub_raw.split("#", 1)[0].rstrip("\n")
                    if not sub.strip():
                        j += 1
                        continue
                    sub_indent = len(sub) - len(sub.lstrip(" "))
                    if sub_indent <= base_indent:
                        break
                    if ":" in sub:
                        skey, sval = sub.split(":", 1)
                        skey = skey.strip()
                        sval = sval.strip()
                        # try numeric convert
                        if sval != "":
                            try:
                                if "." in sval:
                                    conv = float(sval)
                                else:
                                    conv = int(sval)
                            except Exception:
                                conv = sval
                            conf[current_section][skey] = conv
                    j += 1
                i = j - 1
            i += 1
        return conf
    except Exception:
        return None


def get_windy_threshold_from_script(script_text: Optional[str]) -> int:
    default_threshold = 20
    if not script_text:
        return default_threshold
    # Look for WINDY_THRESHOLD_KPH = <int>
    m = re.search(r"WINDY_THRESHOLD_KPH\s*=\s*(\d+)", script_text)
    if m:
        try:
            return int(m.group(1))
        except Exception:
            return default_threshold
    return default_threshold


def compute_expected_metrics(csv_rows: List[Dict[str, str]], city: str, start: date, end: date, comfort_min: float, comfort_max: float, windy_threshold: int) -> Optional[Dict[str, float]]:
    try:
        filtered = []
        for r in csv_rows:
            if r.get("city") != city:
                continue
            d = parse_iso_date(r.get("date", ""))
            if d is None:
                return None
            if start <= d <= end:
                filtered.append(r)
        if not filtered:
            return None
        tavgs = []
        ranges = []
        gaps = []
        rain_days = 0
        windy_days = 0
        for r in filtered:
            tmin = float(r["tmin_c"])
            tmax = float(r["tmax_c"])
            precip = float(r["precip_mm"])
            wind = float(r["wind_kph"])
            tavgs.append((tmin + tmax) / 2.0)
            ranges.append(tmax - tmin)
            if precip > 0:
                rain_days += 1
            if wind >= windy_threshold:
                windy_days += 1
            gap = max(0.0, comfort_min - tmin) + max(0.0, tmax - comfort_max)
            gaps.append(gap)
        m_temp = round(mean(tavgs), 1)
        m_range = round(mean(ranges), 1)
        m_gap = round(mean(gaps), 1)
        days_rain = int(rain_days)
        days_windy = int(windy_days)
        pack_idx = round(m_gap + m_range / 10.0 + days_rain * 0.5 + days_windy * 0.2, 1)
        return {
            "mean_daily_temp_c": m_temp,
            "mean_daily_temp_range_c": m_range,
            "days_with_rain": days_rain,
            "days_windy": days_windy,
            "comfort_gap_mean_c": m_gap,
            "pack_layers_index": pack_idx,
        }
    except Exception:
        return None


def first_nonempty_header_line(lines: List[str]) -> Optional[str]:
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith("#"):
            return s
        # If no header, return first non-empty anyway
        return s
    return None


def find_section_bounds(lines: List[str], title_exact: Optional[str] = None, title_contains: Optional[str] = None) -> Optional[Tuple[int, int]]:
    """
    Returns (content_start_idx, content_end_idx) where start is the line after the header,
    and end is the index of the line just before the next header or EOF.
    The header is identified by a line that starts with '#' and matches the title condition.
    """
    header_idx = None
    for idx, ln in enumerate(lines):
        s = ln.strip()
        if s.startswith("#"):
            # Extract header text (strip leading #'s and whitespace)
            text = s.lstrip("#").strip()
            if title_exact is not None:
                if text == title_exact:
                    header_idx = idx
                    break
            elif title_contains is not None:
                if title_contains.lower() in text.lower():
                    header_idx = idx
                    break
    if header_idx is None:
        return None
    # Find next header
    next_header = None
    for j in range(header_idx + 1, len(lines)):
        if lines[j].strip().startswith("#"):
            next_header = j
            break
    start = header_idx + 1
    end = next_header - 1 if next_header is not None else len(lines) - 1
    if start > end + 1:
        start = end + 1
    return (start, end)


def extract_metric_line_value(line: str) -> Optional[Tuple[str, float]]:
    """
    Extracts the first numeric token and returns both the raw token and its float value.
    """
    m = re.search(r"([-+]?\d+(?:\.\d+)?)", line)
    if not m:
        return None
    raw = m.group(1)
    try:
        return (raw, float(raw))
    except Exception:
        return None


def parse_report_metrics(report_text: str, metric_keys: List[str]) -> Tuple[Dict[str, float], Dict[str, str]]:
    """
    Returns:
      values: dict of metric -> numeric value (float for all, even integers)
      raw_tokens: dict of metric -> raw numeric token string as appeared
    """
    values: Dict[str, float] = {}
    raw_tokens: Dict[str, str] = {}
    lines = report_text.splitlines()
    for key in metric_keys:
        found = False
        for ln in lines:
            if key in ln:
                res = extract_metric_line_value(ln)
                if res is not None:
                    raw, val = res
                    values[key] = val
                    raw_tokens[key] = raw
                    found = True
                    break
        if not found:
            # Leave missing
            pass
    return values, raw_tokens


def count_sentences(text: str) -> int:
    # Split on ., !, ? while handling abbreviations minimally
    # Consider sentences as sequences ending with punctuation.
    parts = re.split(r"[.!?]+", text)
    return sum(1 for p in parts if p.strip())


def guidance_section_after_metrics(report_text: str) -> str:
    """
    Attempts to extract the narrative guidance text after the Metrics section.
    """
    lines = report_text.splitlines()
    bounds = find_section_bounds(lines, title_contains="Metrics")
    if not bounds:
        # return all non-header lines as fallback
        non_header_lines = [ln for ln in lines if not ln.strip().startswith("#")]
        return "\n".join(non_header_lines).strip()
    start, end = bounds
    # Take lines after metrics section header up to next header
    content_lines = lines[start : end + 1]
    # Remove lines that clearly list metrics (contain metric keys or look like bullets with underscores)
    metric_like = (
        "mean_daily_temp_c",
        "mean_daily_temp_range_c",
        "days_with_rain",
        "days_windy",
        "comfort_gap_mean_c",
        "pack_layers_index",
    )
    filtered = []
    for ln in content_lines:
        if any(k in ln for k in metric_like):
            continue
        if ln.strip().startswith(("-", "*")) and "_" in ln:
            continue
        filtered.append(ln)
    return "\n".join(filtered).strip()


def check_guidance_content(guidance_text: str) -> bool:
    """
    Checks for 2–4 sentences and references to at least two categories among rain, wind, temperature/layers.
    """
    if not guidance_text:
        return False
    n_sent = count_sentences(guidance_text)
    if n_sent < 2 or n_sent > 4:
        return False
    lower = guidance_text.lower()
    rain_words = ["rain", "precip"]
    wind_words = ["wind", "windy", "breeze"]
    temp_words = ["cool", "cold", "warm", "chilly", "temperature", "comfort", "layer", "layers", "morning", "evening", "range", "thermal", "socks", "hoodie", "jacket"]
    categories = 0
    if any(w in lower for w in rain_words):
        categories += 1
    if any(w in lower for w in wind_words):
        categories += 1
    if any(w in lower for w in temp_words):
        categories += 1
    return categories >= 2


def extract_section_lines(lines: List[str], section_title_exact: str) -> Optional[List[str]]:
    bounds = find_section_bounds(lines, title_exact=section_title_exact)
    if not bounds:
        return None
    start, end = bounds
    return lines[start : end + 1]


def count_occurrences(lines: List[str], phrase: str) -> int:
    cnt = 0
    for ln in lines:
        if phrase in ln:
            cnt += 1
    return cnt


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores: Dict[str, float] = {
        "config_destination_correct": 0.0,
        "config_dates_correct": 0.0,
        "config_comfort_correct": 0.0,
        "report_title_ok": 0.0,
        "report_config_section_ok": 0.0,
        "report_metrics_values_correct": 0.0,
        "report_float_metrics_one_decimal_format": 0.0,
        "report_days_metrics_integer_format": 0.0,
        "report_guidance_references_and_length": 0.0,
        "packing_section_title_present": 0.0,
        "packing_required_items_present": 0.0,
        "packing_no_duplicate_added_items": 0.0,
    }

    # Constants per task
    expected_destination = "MountainVille"
    expected_start = date(2024, 8, 12)
    expected_end = date(2024, 8, 16)
    expected_comfort_min = 18.0
    expected_comfort_max = 26.0
    expected_section_title = "Weather-based additions (MountainVille, 2024-08-12 to 2024-08-16)"

    # Load analyze script to extract threshold (authoritative)
    script_path = workspace / "scripts" / "analyze_trip.py"
    script_text = safe_read_text(script_path)
    windy_threshold = get_windy_threshold_from_script(script_text)

    # Load CSV
    csv_path = workspace / "data" / "historical_weather.csv"
    csv_rows = safe_load_csv(csv_path)

    # Compute expected metrics
    expected_metrics: Optional[Dict[str, float]] = None
    if csv_rows is not None:
        expected_metrics = compute_expected_metrics(
            csv_rows,
            expected_destination,
            expected_start,
            expected_end,
            expected_comfort_min,
            expected_comfort_max,
            windy_threshold,
        )

    # 1) Check config/trip.yaml
    config_path = workspace / "config" / "trip.yaml"
    cfg_text = safe_read_text(config_path)
    if cfg_text is not None:
        cfg = parse_yaml_trip_config(cfg_text)
        if isinstance(cfg, dict):
            # Destination
            if str(cfg.get("destination", "")).strip() == expected_destination:
                scores["config_destination_correct"] = 1.0
            # Dates
            start_ok = False
            end_ok = False
            try:
                sd = cfg.get("start_date", "")
                ed = cfg.get("end_date", "")
                sd_date = parse_iso_date(str(sd)) if sd else None
                ed_date = parse_iso_date(str(ed)) if ed else None
                if sd_date == expected_start:
                    start_ok = True
                if ed_date == expected_end:
                    end_ok = True
            except Exception:
                start_ok = False
                end_ok = False
            if start_ok and end_ok:
                scores["config_dates_correct"] = 1.0
            # Comfort
            comfort = cfg.get("comfort", {}) if isinstance(cfg.get("comfort"), dict) else {}
            min_ok = False
            max_ok = False
            try:
                min_val = float(comfort.get("min_c", "nan"))
                max_val = float(comfort.get("max_c", "nan"))
                if min_val == expected_comfort_min:
                    min_ok = True
                if max_val == expected_comfort_max:
                    max_ok = True
            except Exception:
                min_ok = False
                max_ok = False
            if min_ok and max_ok:
                scores["config_comfort_correct"] = 1.0

    # 2) Report checks
    report_path = workspace / "reports" / "trip_weather_summary.md"
    report_text = safe_read_text(report_path)
    metric_keys = [
        "mean_daily_temp_c",
        "mean_daily_temp_range_c",
        "days_with_rain",
        "days_windy",
        "comfort_gap_mean_c",
        "pack_layers_index",
    ]
    float_metric_keys = [
        "mean_daily_temp_c",
        "mean_daily_temp_range_c",
        "comfort_gap_mean_c",
        "pack_layers_index",
    ]
    int_metric_keys = [
        "days_with_rain",
        "days_windy",
    ]

    if report_text is not None and expected_metrics is not None:
        lines = report_text.splitlines()
        # Title check: first header contains destination and dates
        first_header = first_nonempty_header_line(lines)
        if first_header:
            text = first_header.lstrip("#").strip()
            if (
                "MountainVille" in text
                and "2024-08-12" in text
                and "2024-08-16" in text
                and first_header.strip().startswith("#")
            ):
                scores["report_title_ok"] = 1.0

        # Config used section
        bounds = find_section_bounds(lines, title_contains="Config used")
        if bounds:
            start, end = bounds
            section_text = "\n".join(lines[start : end + 1])
            if (
                "MountainVille" in section_text
                and "2024-08-12" in section_text
                and "2024-08-16" in section_text
                and ("comfort" in section_text.lower())
                and ("18" in section_text)
                and ("26" in section_text)
            ):
                scores["report_config_section_ok"] = 1.0

        # Metrics values presence and correctness
        parsed_values, raw_tokens = parse_report_metrics(report_text, metric_keys)
        correct_count = 0
        for k in metric_keys:
            if k not in parsed_values:
                continue
            val = parsed_values[k]
            exp = expected_metrics.get(k)
            if exp is None:
                continue
            # For integer metrics, require exact integer match
            if k in int_metric_keys:
                try:
                    if int(round(val)) == int(exp) and abs(val - int(exp)) < 1e-9:
                        correct_count += 1
                except Exception:
                    pass
            else:
                if abs(val - float(exp)) < 1e-9:
                    correct_count += 1
        scores["report_metrics_values_correct"] = correct_count / len(metric_keys)

        # Formatting checks: floats must have exactly one decimal, ints must be integers (no decimal point)
        float_fmt_ok = 0
        for k in float_metric_keys:
            tok = raw_tokens.get(k)
            if tok is None:
                continue
            if re.fullmatch(r"-?\d+\.\d", tok) is not None:
                float_fmt_ok += 1
        scores["report_float_metrics_one_decimal_format"] = float_fmt_ok / len(float_metric_keys)

        int_fmt_ok = 0
        for k in int_metric_keys:
            tok = raw_tokens.get(k)
            if tok is None:
                continue
            if re.fullmatch(r"-?\d+", tok) is not None:
                int_fmt_ok += 1
        scores["report_days_metrics_integer_format"] = int_fmt_ok / len(int_metric_keys)

        # Guidance after metrics
        guidance_text = guidance_section_after_metrics(report_text)
        if check_guidance_content(guidance_text):
            scores["report_guidance_references_and_length"] = 1.0

    # 3) Packing checklist checks
    packing_path = workspace / "docs" / "packing_checklist.md"
    packing_text = safe_read_text(packing_path)
    # Determine required items based on expected metrics and rules
    required_items: List[str] = []
    if expected_metrics is not None:
        if expected_metrics["comfort_gap_mean_c"] >= 5.0:
            required_items.append("Light insulating layers (sweater or hoodie)")
            required_items.append("Packable rain jacket")
        if expected_metrics["days_with_rain"] >= 2:
            required_items.append("Compact umbrella")
        if expected_metrics["days_windy"] >= 3:
            required_items.append("Windproof jacket or shell")
        if expected_metrics["mean_daily_temp_c"] < 18.0:
            required_items.append("Warm socks")
            required_items.append("Thermal base layer top")

    if packing_text is not None and required_items:
        lines = packing_text.splitlines()
        # Section title present
        # Accept any heading level but exact text after '#'
        found_section = False
        for ln in lines:
            s = ln.strip()
            if s.startswith("#"):
                text = s.lstrip("#").strip()
                if text == expected_section_title:
                    found_section = True
                    break
        if found_section:
            scores["packing_section_title_present"] = 1.0

        # Extract section lines
        section_lines = extract_section_lines(lines, expected_section_title)
        if section_lines is not None:
            present = 0
            for item in required_items:
                found_item = any(item in ln for ln in section_lines)
                if found_item:
                    present += 1
            scores["packing_required_items_present"] = present / len(required_items)

            # No duplicates anywhere in the file for the added items
            dup_free = True
            for item in required_items:
                occ = count_occurrences(lines, item)
                if occ != 1:
                    dup_free = False
                    break
            scores["packing_no_duplicate_added_items"] = 1.0 if dup_free else 0.0

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

import json
import csv
import sys
from pathlib import Path
from typing import List, Dict, Tuple, Optional
import math

def _safe_read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None

def _safe_load_json(path: Path) -> Optional[dict]:
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None

def _safe_read_csv_dicts(path: Path) -> Tuple[Optional[List[Dict[str, str]]], Optional[List[str]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            rows = [dict(row) for row in reader]
            header = reader.fieldnames if reader.fieldnames is not None else []
            return rows, header
    except Exception:
        return None, None

def _parse_float_maybe(value: str) -> Optional[float]:
    if value is None:
        return None
    s = str(value).strip()
    if s == "":
        return None
    try:
        s2 = s.replace(",", "")
        return float(s2)
    except Exception:
        return None

def _median(values: List[float]) -> float:
    n = len(values)
    if n == 0:
        return float("nan")
    vals = sorted(values)
    mid = n // 2
    if n % 2 == 1:
        return float(vals[mid])
    else:
        return (vals[mid - 1] + vals[mid]) / 2.0

def _float_close(a: float, b: float, tol: float = 1e-6, rel: float = 0.0) -> bool:
    if a is None or b is None:
        return False
    if math.isfinite(a) and math.isfinite(b):
        return abs(a - b) <= max(tol, rel * max(abs(a), abs(b)))
    return False

def _extract_headings(lines: List[str]) -> Dict[str, int]:
    # Return mapping from heading name to its line index
    headings = {}
    for idx, line in enumerate(lines):
        s = line.strip()
        if s.startswith("#"):
            # strip leading #'s and spaces and trailing ':' if present
            name = s.lstrip("#").strip()
            if name.endswith(":"):
                name = name[:-1].strip()
            headings[name] = idx
    return headings

def _section_content(lines: List[str], headings_map: Dict[str, int], section_name: str) -> Optional[str]:
    if section_name not in headings_map:
        return None
    start = headings_map[section_name] + 1
    # end at next heading or end
    indices = sorted(idx for name, idx in headings_map.items() if idx > headings_map[section_name])
    end = indices[0] if indices else len(lines)
    return "\n".join(lines[start:end])

def _numbers_in_text_with_percents(s: str) -> Tuple[List[float], List[float]]:
    # returns (plain_numbers, percent_numbers)
    import re
    plain = []
    perc = []
    # Percent numbers e.g., -12.3%
    for m in re.finditer(r'([-+]?\d+(?:,\d{3})*(?:\.\d+)?)[ ]*%', s):
        num = _parse_float_maybe(m.group(1))
        if num is not None:
            perc.append(num)
    # Plain numbers (avoid double-counting percents)
    # Remove percent patterns first
    s2 = re.sub(r'([-+]?\d+(?:,\d{3})*(?:\.\d+)?)[ ]*%', ' ', s)
    for m in re.finditer(r'([-+]?\d+(?:,\d{3})*(?:\.\d+)?)', s2):
        num = _parse_float_maybe(m.group(1))
        if num is not None:
            plain.append(num)
    return plain, perc

def _format_variants(n: float) -> List[str]:
    # produce potential string representations to match within memo text
    # include integer, comma-separated, with/without .0 for integers, fixed 1-2 decimals
    res = set()
    if n is None or not math.isfinite(n):
        return []
    # base float
    # integerness
    if abs(n - round(n)) < 1e-9:
        i = int(round(n))
        res.add(str(i))
        res.add(f"{i:,}")
        res.add(f"{i}.0")
        res.add(f"{i:,}.0")
    # general with 1-3 decimals
    for dp in [0, 1, 2]:
        s = f"{n:,.{dp}f}"
        res.add(s)
        res.add(s.replace(",", ""))
    return list(res)

def _compute_expected_cleaned_rows(workspace: Path) -> Optional[Dict[str, Dict[str, str]]]:
    # Returns map id -> row dict of expected cleaned dataset
    in2021 = workspace / "input" / "contracts_2021.csv"
    in2022 = workspace / "input" / "contracts_2022.csv"
    normp = workspace / "input" / "agency_normalization.json"
    rows21, _ = _safe_read_csv_dicts(in2021)
    rows22, _ = _safe_read_csv_dicts(in2022)
    norm = _safe_load_json(normp)
    if rows21 is None or rows22 is None or norm is None:
        return None
    expected = {}
    for row in (rows21 + rows22):
        if (row.get("status") or "").strip() != "awarded":
            continue
        rid = (row.get("id") or "").strip()
        agency_raw = (row.get("agency") or "").strip()
        canonical = norm.get(agency_raw)
        # If missing mapping, treat canonical as None (this will fail downstream checks)
        vendor = (row.get("vendor") or "").strip()
        value_str = (row.get("value_usd") or "").strip()
        value = _parse_float_maybe(value_str)
        date = (row.get("date") or "").strip()
        # derive year from date
        year = ""
        if len(date) >= 4 and date[0:4].isdigit():
            year = date[0:4]
        expected[rid] = {
            "id": rid,
            "year": year,
            "agency_raw": agency_raw,
            "agency": canonical if canonical is not None else "",
            "vendor": vendor,
            "value_usd": f"{value:.10g}" if value is not None else "",
            "date": date,
            "status": "awarded",
        }
    return expected

def _read_cleaned_csv(workspace: Path) -> Tuple[Optional[List[Dict[str, str]]], Optional[List[str]]]:
    path = workspace / "outputs" / "clean" / "contracts_all_awarded.csv"
    return _safe_read_csv_dicts(path)

def _compute_expected_summary(expected_cleaned: Dict[str, Dict[str, str]]) -> Optional[Dict[Tuple[str, str], Dict[str, Optional[float]]]]:
    if expected_cleaned is None:
        return None
    # group by (agency, year)
    groups: Dict[Tuple[str, str], List[float]] = {}
    for rid, row in expected_cleaned.items():
        agency = row.get("agency", "")
        year = row.get("year", "")
        val = _parse_float_maybe(row.get("value_usd", ""))
        if agency == "" or year == "" or val is None:
            return None
        key = (agency, year)
        groups.setdefault(key, []).append(val)
    # compute stats
    summary: Dict[Tuple[str, str], Dict[str, Optional[float]]] = {}
    for key, vals in groups.items():
        agency, year = key
        count = len(vals)
        total = sum(vals)
        med = _median(vals)
        pct_change = None  # to be computed for 2022
        summary[(agency, year)] = {
            "contract_count": float(count),
            "total_value_usd": float(total),
            "median_value_usd": float(med),
            "pct_change_total_vs_prev_year": None
        }
    # compute pct change for 2022
    for (agency, year), stats in list(summary.items()):
        if year == "2022":
            prev = summary.get((agency, "2021"))
            if prev is None:
                stats["pct_change_total_vs_prev_year"] = None
            else:
                prev_total = prev["total_value_usd"]
                if prev_total is None or prev_total == 0:
                    stats["pct_change_total_vs_prev_year"] = None
                else:
                    stats["pct_change_total_vs_prev_year"] = ((stats["total_value_usd"] - prev_total) / prev_total) * 100.0
    return summary

def _read_summary_csv(workspace: Path) -> Tuple[Optional[List[Dict[str, str]]], Optional[List[str]]]:
    path = workspace / "outputs" / "summary_stats.csv"
    return _safe_read_csv_dicts(path)

def _parse_summary_rows(rows: List[Dict[str, str]]) -> Optional[Dict[Tuple[str, str], Dict[str, Optional[float]]]]:
    parsed: Dict[Tuple[str, str], Dict[str, Optional[float]]] = {}
    for r in rows:
        agency = (r.get("agency") or "").strip()
        year = (r.get("year") or "").strip()
        if agency == "" or year == "":
            return None
        cc = _parse_float_maybe((r.get("contract_count") or "").strip())
        tv = _parse_float_maybe((r.get("total_value_usd") or "").strip())
        med = _parse_float_maybe((r.get("median_value_usd") or "").strip())
        pct_str = (r.get("pct_change_total_vs_prev_year") or "").strip()
        pct = None if pct_str == "" else _parse_float_maybe(pct_str)
        parsed[(agency, year)] = {
            "contract_count": cc,
            "total_value_usd": tv,
            "median_value_usd": med,
            "pct_change_total_vs_prev_year": pct,
            "_raw_pct_str": pct_str
        }
    return parsed

def _sum_by_year(summary_parsed: Dict[Tuple[str, str], Dict[str, Optional[float]]], year: str) -> Optional[float]:
    s = 0.0
    found = False
    for (agency, y), stats in summary_parsed.items():
        if y == year:
            tv = stats.get("total_value_usd")
            if tv is None:
                return None
            s += tv
            found = True
    return s if found else None

def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "cleaned_csv_present_and_schema": 0.0,
        "cleaned_csv_content_consistency_with_inputs": 0.0,
        "summary_stats_present_and_schema": 0.0,
        "summary_stats_values_correct": 0.0,
        "memo_sections_and_rowcount": 0.0,
        "memo_key_findings_consistency": 0.0,
        "email_subject_bullets_and_paths": 0.0,
        "email_figures_consistency_with_summary": 0.0,
    }

    # Expected from inputs
    expected_cleaned = _compute_expected_cleaned_rows(workspace)
    expected_summary = _compute_expected_summary(expected_cleaned) if expected_cleaned is not None else None

    # 1) Cleaned CSV schema check
    cleaned_rows, cleaned_header = _read_cleaned_csv(workspace)
    expected_cols = ["id", "year", "agency_raw", "agency", "vendor", "value_usd", "date", "status"]
    if cleaned_rows is not None and cleaned_header is not None:
        if cleaned_header == expected_cols:
            scores["cleaned_csv_present_and_schema"] = 1.0
        else:
            scores["cleaned_csv_present_and_schema"] = 0.0
    else:
        scores["cleaned_csv_present_and_schema"] = 0.0

    # 2) Cleaned CSV content consistency
    if cleaned_rows is not None and expected_cleaned is not None:
        # Build map by id
        cleaned_map: Dict[str, Dict[str, str]] = {}
        ok = True
        for r in cleaned_rows:
            rid = (r.get("id") or "").strip()
            if rid in cleaned_map:
                ok = False
                break
            cleaned_map[rid] = r
        if ok and set(cleaned_map.keys()) == set(expected_cleaned.keys()):
            for rid, exp in expected_cleaned.items():
                row = cleaned_map.get(rid)
                if row is None:
                    ok = False
                    break
                # Check fields
                # year equals date year
                date = (row.get("date") or "").strip()
                year = (row.get("year") or "").strip()
                if len(date) < 10 or date[4] != "-" or date[7] != "-":
                    ok = False
                    break
                if year != date[0:4]:
                    ok = False
                if (row.get("status") or "").strip() != "awarded":
                    ok = False
                if (row.get("agency_raw") or "").strip() != exp["agency_raw"]:
                    ok = False
                if (row.get("agency") or "").strip() != exp["agency"]:
                    ok = False
                if (row.get("vendor") or "").strip() != exp["vendor"]:
                    ok = False
                # value numeric equality
                v_row = _parse_float_maybe((row.get("value_usd") or "").strip())
                v_exp = _parse_float_maybe(exp["value_usd"])
                if v_row is None or v_exp is None or not _float_close(v_row, v_exp, tol=0.01):
                    ok = False
                # id and date match
                if (row.get("id") or "").strip() != exp["id"]:
                    ok = False
                if (row.get("date") or "").strip() != exp["date"]:
                    ok = False
                if not ok:
                    break
        else:
            ok = False
        scores["cleaned_csv_content_consistency_with_inputs"] = 1.0 if ok else 0.0
    else:
        scores["cleaned_csv_content_consistency_with_inputs"] = 0.0

    # 3) Summary stats schema
    summary_rows, summary_header = _read_summary_csv(workspace)
    expected_summary_cols = ["agency", "year", "contract_count", "total_value_usd", "median_value_usd", "pct_change_total_vs_prev_year"]
    if summary_rows is not None and summary_header is not None and summary_header == expected_summary_cols:
        scores["summary_stats_present_and_schema"] = 1.0
    else:
        scores["summary_stats_present_and_schema"] = 0.0

    # 4) Summary stats values correct
    if summary_rows is not None and expected_summary is not None:
        parsed_summary = _parse_summary_rows(summary_rows)
        if parsed_summary is None:
            scores["summary_stats_values_correct"] = 0.0
        else:
            ok = True
            # Compare sets of keys
            if set(parsed_summary.keys()) != set(expected_summary.keys()):
                ok = False
            else:
                for key in expected_summary.keys():
                    exp_stats = expected_summary[key]
                    got_stats = parsed_summary[key]
                    # contract_count must match exactly as integer
                    exp_cc = exp_stats["contract_count"]
                    got_cc = got_stats["contract_count"]
                    if exp_cc is None or got_cc is None or not _float_close(exp_cc, got_cc, tol=0.0):
                        ok = False
                        break
                    # total_value_usd
                    if not _float_close(exp_stats["total_value_usd"], got_stats["total_value_usd"], tol=0.5):
                        ok = False
                        break
                    # median_value_usd within 0.5
                    if not _float_close(exp_stats["median_value_usd"], got_stats["median_value_usd"], tol=0.5):
                        ok = False
                        break
                    # pct change: for 2021 must be empty in CSV; for 2022 close within 0.01
                    agency, year = key
                    raw_pct_str = got_stats.get("_raw_pct_str", "")
                    if year == "2021":
                        if raw_pct_str != "":
                            ok = False
                            break
                    elif year == "2022":
                        exp_pct = exp_stats["pct_change_total_vs_prev_year"]
                        got_pct = got_stats["pct_change_total_vs_prev_year"]
                        if exp_pct is None or got_pct is None or not _float_close(exp_pct, got_pct, tol=0.01):
                            ok = False
                            break
                    else:
                        # only years 2021 and 2022 expected
                        ok = False
                        break
            scores["summary_stats_values_correct"] = 1.0 if ok else 0.0
    else:
        scores["summary_stats_values_correct"] = 0.0

    # 5) Memo sections and rowcount line
    memo_path = workspace / "outputs" / "status_memo.md"
    memo_text = _safe_read_text(memo_path)
    if memo_text is not None and cleaned_rows is not None:
        lines = memo_text.splitlines()
        headings = _extract_headings(lines)
        required_sections = ["Overview", "Method", "Key Findings", "Data Checks", "Next Steps"]
        sections_present = all(name in headings for name in required_sections)
        # Check last non-empty line is "Data source rows counted: N"
        # N equals number of rows in cleaned CSV
        last_nonempty = ""
        for l in reversed(lines):
            if l.strip() != "":
                last_nonempty = l.strip()
                break
        n_rows = len(cleaned_rows)
        expected_tail = f"Data source rows counted: {n_rows}"
        tail_ok = (last_nonempty == expected_tail)
        scores["memo_sections_and_rowcount"] = 1.0 if (sections_present and tail_ok) else 0.0
    else:
        scores["memo_sections_and_rowcount"] = 0.0

    # 6) Memo key findings consistency
    memo_ok = False
    if memo_text is not None and summary_rows is not None:
        lines = memo_text.splitlines()
        headings = _extract_headings(lines)
        key_findings_text = _section_content(lines, headings, "Key Findings")
        parsed_summary = _parse_summary_rows(summary_rows) if summary_rows is not None else None
        if key_findings_text is not None and parsed_summary is not None:
            # Compute top3 by 2022 total_value_usd
            # Build list of (agency, total2022, pct2022)
            totals_2022 = []
            for (agency, year), stats in parsed_summary.items():
                if year == "2022":
                    tv = stats.get("total_value_usd")
                    pct = stats.get("pct_change_total_vs_prev_year")
                    if tv is not None and pct is not None:
                        totals_2022.append((agency, tv, pct))
            totals_2022.sort(key=lambda x: (-x[1], x[0]))
            top3 = totals_2022[:3]
            # Verify each top3 agency appears with its 2022 total and pct in the Key Findings section
            key_lines = key_findings_text.splitlines()
            top3_ok = True
            for agency, tv, pct in top3:
                found_line = False
                for kl in key_lines:
                    if agency in kl:
                        plain_nums, perc_nums = _numbers_in_text_with_percents(kl)
                        # Check if includes a pct close to pct and a plain number close to total
                        has_pct = any(abs(p - pct) <= 0.01 for p in perc_nums)
                        has_total = any(abs(v - tv) <= 0.5 for v in plain_nums)
                        if has_pct and has_total:
                            found_line = True
                            break
                if not found_line:
                    top3_ok = False
                    break
            # Verify overall totals 2021 and 2022 appear as numbers in Key Findings
            total_2021 = _sum_by_year(parsed_summary, "2021")
            total_2022 = _sum_by_year(parsed_summary, "2022")
            totals_ok = False
            if total_2021 is not None and total_2022 is not None:
                # Check presence of both numbers in section text (allow comma/decimal variants)
                variants_2021 = _format_variants(total_2021)
                variants_2022 = _format_variants(total_2022)
                text = key_findings_text
                has_2021 = any(v in text for v in variants_2021)
                has_2022 = any(v in text for v in variants_2022)
                totals_ok = has_2021 and has_2022
            memo_ok = top3_ok and totals_ok
    scores["memo_key_findings_consistency"] = 1.0 if memo_ok else 0.0

    # 7) Email subject, bullets, and paths
    email_path = workspace / "outputs" / "editor_email.txt"
    email_text = _safe_read_text(email_path)
    email_presence_ok = False
    bullets_ok = False
    paths_ok = False
    if email_text is not None:
        lines = [l.rstrip("\n") for l in email_text.splitlines()]
        # Subject line present
        subject_present = any(l.strip().startswith("Subject:") for l in lines)
        # Bullet lines: start with '-' or '*'
        bullet_lines = [l for l in lines if l.strip().startswith("-") or l.strip().startswith("*")]
        bullets_ok = 2 <= len(bullet_lines) <= 3
        # Paths presence
        paths_ok = ("outputs/status_memo.md" in email_text and
                    "outputs/summary_stats.csv" in email_text and
                    "outputs/clean/contracts_all_awarded.csv" in email_text)
        email_presence_ok = subject_present and bullets_ok and paths_ok
    scores["email_subject_bullets_and_paths"] = 1.0 if email_presence_ok else 0.0

    # 8) Email figures consistency with summary
    email_figures_ok = False
    if email_text is not None and summary_rows is not None:
        parsed_summary = _parse_summary_rows(summary_rows)
        if parsed_summary is not None:
            # overall change
            total_2021 = _sum_by_year(parsed_summary, "2021")
            total_2022 = _sum_by_year(parsed_summary, "2022")
            if total_2021 is not None and total_2022 is not None and total_2021 != 0:
                delta = total_2022 - total_2021
                pct = (delta / total_2021) * 100.0
                # top agency
                best_agency = None
                best_total = None
                best_pct = None
                for (agency, year), stats in parsed_summary.items():
                    if year == "2022" and stats.get("total_value_usd") is not None:
                        if best_total is None or stats["total_value_usd"] > best_total:
                            best_agency = agency
                            best_total = stats["total_value_usd"]
                            best_pct = stats.get("pct_change_total_vs_prev_year")
                lines = [l.rstrip("\n") for l in email_text.splitlines()]
                bullet_lines = [l for l in lines if l.strip().startswith("-") or l.strip().startswith("*")]
                # Find a bullet with overall change (absolute and percent)
                overall_ok = False
                for bl in bullet_lines:
                    plain_nums, perc_nums = _numbers_in_text_with_percents(bl)
                    has_pct = any(abs(p - pct) <= 0.1 for p in perc_nums)
                    has_delta = any(abs(v - delta) <= 0.5 for v in plain_nums)
                    if has_pct and has_delta:
                        overall_ok = True
                        break
                # Find a bullet with top agency info (agency name, total, yoy percent)
                top_ok = False
                if best_agency is not None and best_total is not None and best_pct is not None:
                    for bl in bullet_lines:
                        if best_agency in bl:
                            plain_nums, perc_nums = _numbers_in_text_with_percents(bl)
                            has_total = any(abs(v - best_total) <= 0.5 for v in plain_nums)
                            has_pct = any(abs(p - best_pct) <= 0.1 for p in perc_nums)
                            if has_total and has_pct:
                                top_ok = True
                                break
                email_figures_ok = overall_ok and top_ok
    scores["email_figures_consistency_with_summary"] = 1.0 if email_figures_ok else 0.0

    return scores

def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, ensure_ascii=False))

if __name__ == "__main__":
    main()

