import json
import csv
import sys
import re
from pathlib import Path
from datetime import datetime, timedelta


def _read_text(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return ""


def _load_json_list(path: Path):
    try:
        data = json.loads(_read_text(path))
        if isinstance(data, list):
            return data
    except Exception:
        pass
    return None


def _save_json_list(path: Path, data):
    try:
        path.write_text(json.dumps(data, indent=2), encoding="utf-8")
        return True
    except Exception:
        return False


def _read_csv_dicts(path: Path):
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            rows = list(reader)
            return rows, reader.fieldnames if reader.fieldnames else []
    except Exception:
        return None, None


def _parse_schedule_yaml(path: Path) -> dict:
    # Minimal YAML parser for simple key: "value" pairs
    config = {}
    try:
        text = _read_text(path)
        for line in text.splitlines():
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if ":" not in line:
                continue
            key, val = line.split(":", 1)
            key = key.strip()
            val = val.strip()
            # remove inline comments
            if "#" in val:
                val = val.split("#", 1)[0].strip()
            # strip surrounding quotes
            if (val.startswith('"') and val.endswith('"')) or (val.startswith("'") and val.endswith("'")):
                val = val[1:-1]
            config[key] = val
    except Exception:
        pass
    return config


def _parse_case_html(text: str) -> dict:
    # Extract key-value pairs from simple <tr><th>Key</th><td>Value</td></tr> structure
    result = {}
    try:
        pattern = re.compile(
            r"<tr>\s*<th>\s*([^<]+)\s*</th>\s*<td>\s*([^<]+)\s*</td>\s*</tr>",
            re.IGNORECASE | re.DOTALL,
        )
        for m in pattern.finditer(text):
            key = m.group(1).strip().lower()
            val = m.group(2).strip()
            if key == "case id":
                result["case_id"] = val
            elif key == "officer":
                result["officer"] = val
            elif key == "agency":
                result["agency"] = val
            elif key == "allegation":
                result["allegation"] = val
            elif key == "status":
                result["status"] = val
            elif key == "last updated":
                result["last_updated"] = val
    except Exception:
        return {}
    return result


def _load_cases_from_html(dir_path: Path) -> dict:
    cases = {}
    if not dir_path.exists():
        return cases
    for p in sorted(dir_path.glob("*.html")):
        text = _read_text(p)
        if not text:
            continue
        parsed = _parse_case_html(text)
        cid = parsed.get("case_id")
        if cid:
            cases[cid] = parsed
    return cases


def _parse_date(d: str):
    try:
        return datetime.strptime(d, "%Y-%m-%d").date()
    except Exception:
        return None


def _lower_or_blank(s):
    return (s or "").strip().lower()


def _extract_t_ids(s: str):
    # Extract tip IDs like T-0001 using regex to robustly compare sets
    if not s:
        return set()
    return set(re.findall(r"T-\d{4}", s))


def _find_line_with_tokens(lines, tokens):
    for line in lines:
        ok = True
        for tok in tokens:
            if tok not in line:
                ok = False
                break
        if ok:
            return True
    return False


def _compute_expected(workspace: Path, run_date_str: str):
    # Read configuration with fallbacks to explicit required paths
    schedule_path = workspace / "input" / "config" / "schedule.yaml"
    cfg = _parse_schedule_yaml(schedule_path) if schedule_path.exists() else {}
    output_dir_cfg = cfg.get("output_dir", "output/run")
    tips_glob = cfg.get("source_tip_glob", "input/tips/*.csv")
    html_dir_cfg = cfg.get("source_html_dir", "input/discipline_snapshots")
    state_file_cfg = cfg.get("state_file", "state/processed_tip_ids.json")
    daily_time = cfg.get("daily_time", "06:00")
    try:
        top_n = int(cfg.get("top_n", "5"))
    except Exception:
        top_n = 5

    run_date = _parse_date(run_date_str)
    # Load state
    state_file = workspace / state_file_cfg
    processed_ids = _load_json_list(state_file)
    if processed_ids is None:
        processed_ids = []

    # Load watchlist
    watchlist_path = workspace / "input" / "config" / "watchlist.csv"
    watch_agencies = set()
    watch_officers = set()
    wl_rows, wl_fields = _read_csv_dicts(watchlist_path)
    if wl_rows is not None:
        for row in wl_rows:
            t = (row.get("type") or "").strip().lower()
            flag = (row.get("flag") or "").strip().lower()
            if flag != "watch":
                continue
            if t == "agency":
                name = (row.get("name") or "").strip()
                if name:
                    watch_agencies.add(name)
            elif t == "officer":
                name = (row.get("name") or "").strip()
                if name:
                    watch_officers.add(name)

    # Load cases from HTML
    html_dir = workspace / html_dir_cfg
    cases = _load_cases_from_html(html_dir)

    # Load tips
    # Resolve glob relative to workspace
    tips_files = sorted(workspace.glob(tips_glob))
    tips = []
    for tf in tips_files:
        rows, fields = _read_csv_dicts(tf)
        if rows is None:
            continue
        for r in rows:
            tip_id = (r.get("tip_id") or "").strip()
            date_received = (r.get("date_received") or "").strip()
            d = _parse_date(date_received)
            if not tip_id or d is None:
                continue
            if d <= run_date and tip_id not in processed_ids:
                tips.append({
                    "tip_id": tip_id,
                    "date_received": d,
                    "agency": (r.get("agency") or "").strip(),
                    "allegation_type": (r.get("allegation_type") or "").strip(),
                    "severity": (r.get("severity") or "").strip(),
                    "description": (r.get("description") or "").strip(),
                    "officer_names": (r.get("officer_names") or "").strip(),
                    "source": (r.get("source") or "").strip(),
                    "prior_internal_affairs_flag": (r.get("prior_internal_affairs_flag") or "").strip(),
                    "related_case_id": (r.get("related_case_id") or "").strip(),
                })

    # Cluster tips
    clusters = {}
    for t in tips:
        if t.get("related_case_id"):
            key = t["related_case_id"]
        else:
            key = _lower_or_blank(t["agency"]) + "|" + _lower_or_blank(t["officer_names"]) + "|" + _lower_or_blank(t["allegation_type"])
        if key not in clusters:
            clusters[key] = {
                "cluster_key": key,
                "tips": [],
            }
        clusters[key]["tips"].append(t)

    severity_map = {"low": 1, "medium": 2, "high": 3}
    keyword_list = ["Bribery", "Record tampering", "Retaliation"]

    expected_clusters = []
    for key, data in clusters.items():
        tips_list = data["tips"]
        tip_ids = [x["tip_id"] for x in tips_list]
        most_recent_date = max(x["date_received"] for x in tips_list) if tips_list else None
        smallest_tip_id = min(tip_ids) if tip_ids else ""
        # Choose representative agency and allegation_type from first tip
        agency = tips_list[0]["agency"] if tips_list else ""
        allegation_type = tips_list[0]["allegation_type"] if tips_list else ""
        # Determine severity (highest)
        sev_strs = [(_lower_or_blank(x["severity"])) for x in tips_list]
        sev_num = max([severity_map.get(s, 0) for s in sev_strs]) if sev_strs else 0
        sev_label = ""
        for k, v in severity_map.items():
            if v == sev_num:
                sev_label = k.capitalize()
        # Link to case if key is related_case_id and exists in cases
        case_id = ""
        linked_status = ""
        source = "tips"
        if key in cases:
            case_id = key
            linked_status = cases[key].get("status", "")
            source = "tips+case"
        # Watchlist boost: if cluster’s agency OR any officer appears on watchlist
        officers = set([x["officer_names"].strip() for x in tips_list if x.get("officer_names")])
        watch_boost = 1 if (agency in watch_agencies or any(o in watch_officers for o in officers)) else 0
        # Keyword boost
        kw_boost = 1 if any(kw.lower() in allegation_type.lower() for kw in keyword_list) else 0
        # Linked status boost
        status_boost = 1 if linked_status in {"Pending Hearing", "Sustained"} else 0
        priority_score = sev_num + watch_boost + kw_boost + status_boost
        expected_clusters.append({
            "cluster_key": key,
            "tip_ids": tip_ids,
            "case_id": case_id,
            "agency": agency,
            "allegation_type": allegation_type,
            "severity": sev_label,
            "linked_status": linked_status,
            "priority_score": priority_score,
            "tips_count": len(tip_ids),
            "most_recent_date": most_recent_date,
            "smallest_tip_id": smallest_tip_id,
            "source": source,
        })

    # Sort by priority_score desc, most_recent_date desc, smallest_tip_id asc
    expected_clusters.sort(key=lambda x: (-x["priority_score"], -(x["most_recent_date"].toordinal() if x["most_recent_date"] else -10**9), x["smallest_tip_id"]))

    # Compute expected agency counts for processed tips this run
    agency_counts = {}
    for t in tips:
        ag = t["agency"]
        agency_counts[ag] = agency_counts.get(ag, 0) + 1

    # Determine output run dir
    base_output_dir = output_dir_cfg if output_dir_cfg else "output/run"
    run_dir = workspace / base_output_dir / run_date_str

    # Determine expected next_run string
    try:
        hour, minute = daily_time.split(":")
        hour = int(hour)
        minute = int(minute)
        next_dt = datetime(run_date.year, run_date.month, run_date.day, hour, minute) + timedelta(days=1)
        expected_next_run_str = next_dt.strftime("%Y-%m-%d %H:%M")
    except Exception:
        # Fallback to next day 00:00
        next_dt = datetime(run_date.year, run_date.month, run_date.day, 0, 0) + timedelta(days=1)
        expected_next_run_str = next_dt.strftime("%Y-%m-%d %H:%M")

    return {
        "expected_clusters": expected_clusters,
        "agency_counts": agency_counts,
        "run_dir": run_dir,
        "expected_next_run_str": expected_next_run_str,
        "processed_tip_ids": [t["tip_id"] for t in tips],
        "top_n": top_n,
    }


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    run_date = "2025-01-11"
    expected = _compute_expected(workspace, run_date)
    run_dir = expected["run_dir"]

    scores = {
        "prioritized_csv_exists": 0.0,
        "prioritized_csv_schema": 0.0,
        "prioritized_csv_content": 0.0,
        "daily_report_exists": 0.0,
        "daily_report_no_officer_names": 0.0,
        "daily_report_agency_counts": 0.0,
        "daily_report_top_section": 0.0,
        "next_run_correct": 0.0,
        "state_updated": 0.0,
        "run_script_supports_run_on": 0.0,
    }

    # Check prioritized_cases.csv
    prioritized_path = run_dir / "prioritized_cases.csv"
    if prioritized_path.exists():
        scores["prioritized_csv_exists"] = 1.0
        rows, headers = _read_csv_dicts(prioritized_path)
        if rows is not None and headers is not None:
            expected_headers = [
                "rank",
                "cluster_key",
                "source",
                "tip_ids",
                "case_id",
                "agency",
                "allegation_type",
                "severity",
                "linked_status",
                "priority_score",
                "tips_count",
            ]
            if headers == expected_headers:
                scores["prioritized_csv_schema"] = 1.0
            # Content checks
            try:
                exp_clusters = expected["expected_clusters"]
                if rows is not None and isinstance(rows, list) and len(rows) == len(exp_clusters) and len(exp_clusters) > 0:
                    ok_all = True
                    # Verify ranks continuous starting at 1 and order matches expected
                    for idx, row in enumerate(rows):
                        # rank check
                        try:
                            rank_val = int(row.get("rank", ""))
                        except Exception:
                            ok_all = False
                            break
                        if rank_val != idx + 1:
                            ok_all = False
                            break
                        exp = exp_clusters[idx]
                        # cluster_key
                        if row.get("cluster_key") != exp["cluster_key"]:
                            ok_all = False
                            break
                        # source
                        if row.get("source") != exp["source"]:
                            ok_all = False
                            break
                        # case_id
                        if (row.get("case_id") or "") != (exp["case_id"] or ""):
                            ok_all = False
                            break
                        # agency
                        if (row.get("agency") or "") != (exp["agency"] or ""):
                            ok_all = False
                            break
                        # allegation_type
                        if (row.get("allegation_type") or "") != (exp["allegation_type"] or ""):
                            ok_all = False
                            break
                        # severity
                        if (row.get("severity") or "") != (exp["severity"] or ""):
                            ok_all = False
                            break
                        # linked_status
                        if (row.get("linked_status") or "") != (exp["linked_status"] or ""):
                            ok_all = False
                            break
                        # priority_score
                        try:
                            ps = int(row.get("priority_score", ""))
                        except Exception:
                            ok_all = False
                            break
                        if ps != exp["priority_score"]:
                            ok_all = False
                            break
                        # tips_count
                        try:
                            tc = int(row.get("tips_count", ""))
                        except Exception:
                            ok_all = False
                            break
                        if tc != exp["tips_count"]:
                            ok_all = False
                            break
                        # tip_ids contain correct set
                        tip_ids_str = row.get("tip_ids", "")
                        found_ids = _extract_t_ids(tip_ids_str)
                        if set(exp["tip_ids"]) != found_ids:
                            ok_all = False
                            break
                    if ok_all:
                        scores["prioritized_csv_content"] = 1.0
            except Exception:
                pass
    # Check daily_report.txt
    daily_report_path = run_dir / "daily_report.txt"
    if daily_report_path.exists():
        scores["daily_report_exists"] = 1.0
        text = _read_text(daily_report_path)
        if text:
            # No officer names leakage
            if ("John Doe" not in text) and ("Jane Smith" not in text):
                scores["daily_report_no_officer_names"] = 1.0
            lines = text.splitlines()
            # Agency counts
            agency_counts = expected["agency_counts"]
            agency_ok = True
            for agency, count in agency_counts.items():
                # look for a line containing both agency and count
                if not _find_line_with_tokens(lines, [agency, str(count)]):
                    agency_ok = False
                    break
            if agency_counts and agency_ok:
                scores["daily_report_agency_counts"] = 1.0
            # Top N section entries for each expected cluster
            top_ok = True
            exp_clusters = expected["expected_clusters"]
            # Only check up to N or number of clusters
            max_check = min(len(exp_clusters), expected.get("top_n", 5))
            for idx in range(max_check):
                rank = idx + 1
                exp = exp_clusters[idx]
                if exp["case_id"]:
                    key_display = exp["case_id"]
                else:
                    # first tip id if no case
                    key_display = sorted(exp["tip_ids"])[0] if exp["tip_ids"] else ""
                tokens = [
                    str(rank),
                    key_display,
                    exp["agency"],
                    exp["allegation_type"],
                    str(exp["priority_score"]),
                    str(exp["tips_count"]),
                ]
                if not _find_line_with_tokens(lines, tokens):
                    top_ok = False
                    break
            if (len(exp_clusters) > 0) and top_ok:
                scores["daily_report_top_section"] = 1.0

    # Check next_run.txt
    next_run_path = run_dir / "next_run.txt"
    if next_run_path.exists():
        next_text = _read_text(next_run_path).strip()
        if next_text == expected["expected_next_run_str"]:
            scores["next_run_correct"] = 1.0

    # Check state updated
    state_path = workspace / "state" / "processed_tip_ids.json"
    state_list = _load_json_list(state_path)
    if isinstance(state_list, list):
        expected_new = set(expected["processed_tip_ids"])
        # ensure all expected new tips are present
        if expected_new and expected_new.issubset(set(state_list)):
            scores["state_updated"] = 1.0

    # Check for a user-created runnable script that supports --run-on.
    # Skip reward/test.py so the checker cannot satisfy this item by reading itself.
    run_on_found = False
    script_exts = {".py", ".sh", ".bat", ".ps1", ".rb", ".pl", ".js"}
    try:
        checker_path = (workspace / "reward" / "test.py").resolve()
        for p in workspace.rglob("*"):
            if not p.is_file() or p.suffix.lower() not in script_exts:
                continue
            try:
                if p.resolve() == checker_path:
                    continue
                text = p.read_text(encoding="utf-8", errors="ignore")
                if "--run-on" in text:
                    run_on_found = True
                    break
            except Exception:
                continue
    except Exception:
        run_on_found = False
    if run_on_found:
        scores["run_script_supports_run_on"] = 1.0

    return scores


def main() -> None:
    workspace_path = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace_path)
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

import sys
import json
import csv
from decimal import Decimal, ROUND_HALF_UP, InvalidOperation
from pathlib import Path
from typing import List, Dict, Optional


CURRENCY_Q = Decimal("0.01")


def _quantize_money(val: Decimal) -> Decimal:
    return val.quantize(CURRENCY_Q, rounding=ROUND_HALF_UP)


def _parse_decimal(val) -> Optional[Decimal]:
    if val is None:
        return None
    try:
        if isinstance(val, (int, float, Decimal)):
            return Decimal(str(val))
        s = str(val).strip()
        if s == "":
            return None
        return Decimal(s)
    except (InvalidOperation, ValueError):
        return None


def _read_csv_dicts(path: Path) -> Optional[List[Dict[str, str]]]:
    try:
        with path.open("r", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            rows = []
            for row in reader:
                rows.append({k: v.strip() if isinstance(v, str) else v for k, v in row.items()})
            return rows
    except Exception:
        return None


def _read_csv_header(path: Path) -> Optional[List[str]]:
    try:
        with path.open("r", encoding="utf-8") as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                return None
            return [h.strip() for h in header]
    except Exception:
        return None


def _safe_load_json(path: Path) -> Optional[dict]:
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _compute_payments_by_stay(payments_rows: List[Dict[str, str]]) -> Dict[str, Decimal]:
    totals: Dict[str, Decimal] = {}
    for row in payments_rows:
        stay_id = row.get("stay_id", "").strip()
        amt = _parse_decimal(row.get("amount_usd"))
        if stay_id and amt is not None:
            totals[stay_id] = totals.get(stay_id, Decimal("0")) + amt
    return {k: _quantize_money(v) for k, v in totals.items()}


def _compute_expected_ledger(stays_rows: List[Dict[str, str]], payments_by_stay: Dict[str, Decimal]) -> Dict[str, Dict[str, Decimal]]:
    expected: Dict[str, Dict[str, Decimal]] = {}
    for row in stays_rows:
        stay_id = row.get("stay_id", "").strip()
        if not stay_id:
            continue
        nights = _parse_decimal(row.get("nights")) or Decimal("0")
        nightly = _parse_decimal(row.get("nightly_rate_usd")) or Decimal("0")
        discount = _parse_decimal(row.get("discount_usd")) or Decimal("0")
        tax_rate = _parse_decimal(row.get("tax_rate")) or Decimal("0")
        referral_applied = _parse_decimal(row.get("referral_credit_applied_usd")) or Decimal("0")

        taxable = _quantize_money(nights * nightly - discount)
        tax = _quantize_money(tax_rate * taxable)
        total_due = _quantize_money(taxable + tax - referral_applied)
        payment_received = _quantize_money(payments_by_stay.get(stay_id, Decimal("0")))
        balance = _quantize_money(total_due - payment_received)

        expected[stay_id] = {
            "taxable_subtotal_usd": taxable,
            "tax_usd": tax,
            "total_due_usd": total_due,
            "payment_received_usd": payment_received,
            "balance_usd": balance,
            "nights": _quantize_money(nights),
            "nightly_rate_usd": _quantize_money(nightly),
            "discount_usd": _quantize_money(discount),
            "referral_credit_applied_usd": _quantize_money(referral_applied),
        }
    return expected


def _parse_ledger(ledger_rows: List[Dict[str, str]]) -> Dict[str, Dict[str, Decimal]]:
    parsed: Dict[str, Dict[str, Decimal]] = {}
    for row in ledger_rows:
        stay_id = row.get("stay_id", "").strip()
        if not stay_id:
            continue
        entry: Dict[str, Decimal] = {}
        for k in [
            "nights",
            "nightly_rate_usd",
            "discount_usd",
            "taxable_subtotal_usd",
            "tax_usd",
            "total_due_usd",
            "referral_credit_applied_usd",
            "payment_received_usd",
            "balance_usd",
        ]:
            entry[k] = _parse_decimal(row.get(k)) if row.get(k) is not None else None
            if entry[k] is not None:
                entry[k] = _quantize_money(entry[k])
        parsed[stay_id] = entry
    return parsed


def _compute_aggregates(ledger_rows: List[Dict[str, str]], referrals_rows: Optional[List[Dict[str, str]]], payments_rows: Optional[List[Dict[str, str]]]) -> Optional[Dict[str, Decimal]]:
    try:
        total_taxable = Decimal("0")
        total_tax = Decimal("0")
        total_due_before_credits = Decimal("0")
        total_due_after_credits = Decimal("0")
        payments_received = Decimal("0")
        referral_credits_applied = Decimal("0")
        outstanding_balance = Decimal("0")
        for row in ledger_rows:
            taxable = _parse_decimal(row.get("taxable_subtotal_usd")) or Decimal("0")
            tax = _parse_decimal(row.get("tax_usd")) or Decimal("0")
            total_due = _parse_decimal(row.get("total_due_usd")) or Decimal("0")
            paid = _parse_decimal(row.get("payment_received_usd")) or Decimal("0")
            applied = _parse_decimal(row.get("referral_credit_applied_usd")) or Decimal("0")
            balance = _parse_decimal(row.get("balance_usd")) or Decimal("0")
            total_taxable += taxable
            total_tax += tax
            total_due_after_credits += total_due
            total_due_before_credits += (taxable + tax)
            payments_received += paid
            referral_credits_applied += applied
            outstanding_balance += balance

        total_taxable = _quantize_money(total_taxable)
        total_tax = _quantize_money(total_tax)
        total_due_after_credits = _quantize_money(total_due_after_credits)
        total_due_before_credits = _quantize_money(total_due_before_credits)
        payments_received = _quantize_money(payments_received)
        referral_credits_applied = _quantize_money(referral_credits_applied)
        outstanding_balance = _quantize_money(outstanding_balance)

        referral_credits_earned = Decimal("0")
        if referrals_rows is not None:
            for r in referrals_rows:
                c = _parse_decimal(r.get("credit_usd")) or Decimal("0")
                referral_credits_earned += c
        referral_credits_earned = _quantize_money(referral_credits_earned)
        unredeemed = _quantize_money(referral_credits_earned - referral_credits_applied)

        number_of_stays = len(ledger_rows)
        number_of_payments = len(payments_rows) if payments_rows is not None else 0

        return {
            "number_of_stays": Decimal(number_of_stays),
            "number_of_payments": Decimal(number_of_payments),
            "referral_credits_earned_usd": referral_credits_earned,
            "referral_credits_applied_usd": referral_credits_applied,
            "unredeemed_referral_credits_usd": unredeemed,
            "total_taxable_subtotal_usd": total_taxable,
            "total_tax_usd": total_tax,
            "total_due_before_credits_usd": total_due_before_credits,
            "total_due_after_credits_usd": total_due_after_credits,
            "payments_received_usd": payments_received,
            "outstanding_balance_usd": outstanding_balance,
        }
    except Exception:
        return None


def _decimal_equal(a: Optional[Decimal], b: Optional[Decimal]) -> bool:
    if a is None or b is None:
        return False
    return _quantize_money(a) == _quantize_money(b)


def _value_in_text(text: str, value: Decimal) -> bool:
    s = f"{_quantize_money(value):.2f}"
    return s in text


def _find_section(text: str, section_name: str) -> Optional[str]:
    lines = text.splitlines()
    indices = []
    for i, line in enumerate(lines):
        if section_name.lower() in line.lower():
            indices.append(i)
    if not indices:
        return None
    start = indices[0]
    known_sections = ["Summary", "Discrepancies", "Credits & Outstanding"]
    end = len(lines)
    for i in range(start + 1, len(lines)):
        for s in known_sections:
            if s.lower() in lines[i].lower():
                end = i
                break
        if end != len(lines):
            break
    return "\n".join(lines[start:end]).strip()


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "ledger_file_exists_and_columns": 0.0,
        "ledger_rows_match_inputs_and_calculations": 0.0,
        "aggregated_totals_match_expected": 0.0,
        "validation_results_present_and_structure": 0.0,
        "validation_results_values_correct": 0.0,
        "reconciliation_report_has_required_sections_and_content": 0.0,
        "meeting_notes_include_figures_and_actions": 0.0,
    }

    stays_path = workspace / "input" / "stays.csv"
    payments_path = workspace / "input" / "payments.csv"
    referrals_path = workspace / "input" / "referrals.csv"
    expected_totals_path = workspace / "tests" / "expected_totals.json"

    ledger_path = workspace / "outputs" / "ledger.csv"
    report_path = workspace / "outputs" / "reconciliation_report.md"
    validation_path = workspace / "outputs" / "validation_results.json"
    notes_path = workspace / "outputs" / "meeting_notes.md"

    stays_rows = _read_csv_dicts(stays_path) or []
    payments_rows = _read_csv_dicts(payments_path) or []
    referrals_rows = _read_csv_dicts(referrals_path) or []
    expected_totals = _safe_load_json(expected_totals_path) or {}

    required_ledger_columns = [
        "stay_id",
        "check_in",
        "check_out",
        "nights",
        "nightly_rate_usd",
        "discount_usd",
        "taxable_subtotal_usd",
        "tax_usd",
        "total_due_usd",
        "referral_credit_applied_usd",
        "payment_received_usd",
        "balance_usd",
    ]
    header = _read_csv_header(ledger_path) if ledger_path.exists() else None
    if header is not None and header == required_ledger_columns:
        scores["ledger_file_exists_and_columns"] = 1.0
    else:
        scores["ledger_file_exists_and_columns"] = 0.0

    ledger_rows = _read_csv_dicts(ledger_path) or []

    if stays_rows and ledger_rows:
        payments_by_stay = _compute_payments_by_stay(payments_rows)
        expected_ledger = _compute_expected_ledger(stays_rows, payments_by_stay)
        parsed_ledger = _parse_ledger(ledger_rows)

        all_ok = True
        input_stay_ids = {row.get("stay_id", "").strip() for row in stays_rows if row.get("stay_id")}
        ledger_stay_ids = {row.get("stay_id", "").strip() for row in ledger_rows if row.get("stay_id")}
        if input_stay_ids != ledger_stay_ids:
            all_ok = False
        else:
            for s in input_stay_ids:
                exp = expected_ledger.get(s)
                got = parsed_ledger.get(s)
                if exp is None or got is None:
                    all_ok = False
                    break
                for field in [
                    "taxable_subtotal_usd",
                    "tax_usd",
                    "total_due_usd",
                    "payment_received_usd",
                    "balance_usd",
                    "nights",
                    "nightly_rate_usd",
                    "discount_usd",
                    "referral_credit_applied_usd",
                ]:
                    if not _decimal_equal(exp.get(field), got.get(field)):
                        all_ok = False
                        break
                src = next((r for r in stays_rows if r.get("stay_id", "").strip() == s), None)
                if src:
                    ledger_src = next((r for r in ledger_rows if r.get("stay_id", "").strip() == s), {})
                    if src.get("check_in", "").strip() != ledger_src.get("check_in", "").strip():
                        all_ok = False
                    if src.get("check_out", "").strip() != ledger_src.get("check_out", "").strip():
                        all_ok = False
                if not all_ok:
                    break
        scores["ledger_rows_match_inputs_and_calculations"] = 1.0 if all_ok else 0.0
    else:
        scores["ledger_rows_match_inputs_and_calculations"] = 0.0

    if ledger_rows and expected_totals:
        aggs = _compute_aggregates(ledger_rows, referrals_rows, payments_rows)
        expected_fields = expected_totals.get("expected", {})
        if aggs is not None and expected_fields:
            comparisons = {
                "number_of_stays": int(aggs["number_of_stays"]) == int(expected_fields.get("number_of_stays", -1)),
                "number_of_payments": int(aggs["number_of_payments"]) == int(expected_fields.get("number_of_payments", -1)),
                "referral_credits_earned_usd": _decimal_equal(aggs["referral_credits_earned_usd"], _parse_decimal(expected_fields.get("referral_credits_earned_usd"))),
                "referral_credits_applied_usd": _decimal_equal(aggs["referral_credits_applied_usd"], _parse_decimal(expected_fields.get("referral_credits_applied_usd"))),
                "unredeemed_referral_credits_usd": _decimal_equal(aggs["unredeemed_referral_credits_usd"], _parse_decimal(expected_fields.get("unredeemed_referral_credits_usd"))),
                "total_taxable_subtotal_usd": _decimal_equal(aggs["total_taxable_subtotal_usd"], _parse_decimal(expected_fields.get("total_taxable_subtotal_usd"))),
                "total_tax_usd": _decimal_equal(aggs["total_tax_usd"], _parse_decimal(expected_fields.get("total_tax_usd"))),
                "total_due_before_credits_usd": _decimal_equal(aggs["total_due_before_credits_usd"], _parse_decimal(expected_fields.get("total_due_before_credits_usd"))),
                "total_due_after_credits_usd": _decimal_equal(aggs["total_due_after_credits_usd"], _parse_decimal(expected_fields.get("total_due_after_credits_usd"))),
                "payments_received_usd": _decimal_equal(aggs["payments_received_usd"], _parse_decimal(expected_fields.get("payments_received_usd"))),
                "outstanding_balance_usd": _decimal_equal(aggs["outstanding_balance_usd"], _parse_decimal(expected_fields.get("outstanding_balance_usd"))),
            }
            scores["aggregated_totals_match_expected"] = 1.0 if all(comparisons.values()) else 0.0
        else:
            scores["aggregated_totals_match_expected"] = 0.0
    else:
        scores["aggregated_totals_match_expected"] = 0.0

    validation_json = _safe_load_json(validation_path) if validation_path.exists() else None
    if validation_json is not None:
        checks_map = validation_json.get("checks")
        computed_map = validation_json.get("computed")
        expected_map = validation_json.get("expected")
        overall_status = validation_json.get("overall_status", validation_json.get("status"))
        needed_checks = [
            "total_due_after_credits_usd == total_taxable_subtotal_usd + total_tax_usd - referral_credits_applied_usd",
            "outstanding_balance_usd == total_due_after_credits_usd - payments_received_usd",
            "unredeemed_referral_credits_usd == referral_credits_earned_usd - referral_credits_applied_usd",
            "outstanding_balance_usd == unredeemed_referral_credits_usd",
        ]
        structure_ok = True
        if not isinstance(checks_map, dict):
            structure_ok = False
        else:
            for k in needed_checks:
                if k not in checks_map or not isinstance(checks_map[k], bool):
                    structure_ok = False
                    break
        if not isinstance(computed_map, dict) or not isinstance(expected_map, dict):
            structure_ok = False
        if overall_status is None:
            structure_ok = False
        scores["validation_results_present_and_structure"] = 1.0 if structure_ok else 0.0
    else:
        scores["validation_results_present_and_structure"] = 0.0

    if validation_json is not None and ledger_rows and referrals_rows is not None:
        computed = validation_json.get("computed", {})
        expected = validation_json.get("expected", {})
        checks_map = validation_json.get("checks", {})
        overall_status = validation_json.get("overall_status", validation_json.get("status"))

        aggs = _compute_aggregates(ledger_rows, referrals_rows, payments_rows)
        expected_totals_expected = (expected_totals.get("expected") if isinstance(expected_totals, dict) else None) or {}

        values_ok = True
        if aggs is None:
            values_ok = False
        else:
            def cmp_field(name: str, allow_int: bool = False) -> bool:
                comp_val = _parse_decimal(computed.get(name))
                if comp_val is None and allow_int:
                    try:
                        comp_val = Decimal(int(computed.get(name)))
                    except Exception:
                        comp_val = None
                if name in ("number_of_stays", "number_of_payments"):
                    try:
                        return int(aggs[name]) == int(computed.get(name)) if computed.get(name) is not None else False
                    except Exception:
                        return False
                return _decimal_equal(aggs[name], comp_val)

            fields = [
                "referral_credits_earned_usd",
                "referral_credits_applied_usd",
                "unredeemed_referral_credits_usd",
                "total_taxable_subtotal_usd",
                "total_tax_usd",
                "total_due_before_credits_usd",
                "total_due_after_credits_usd",
                "payments_received_usd",
                "outstanding_balance_usd",
            ]
            for f in fields:
                if not cmp_field(f):
                    values_ok = False
                    break
            if values_ok:
                if not cmp_field("number_of_stays", allow_int=True):
                    values_ok = False
                if not cmp_field("number_of_payments", allow_int=True):
                    values_ok = False

            if values_ok:
                for key, exp_val in expected_totals_expected.items():
                    if key in ("number_of_stays", "number_of_payments"):
                        try:
                            if int(expected.get(key)) != int(exp_val):
                                values_ok = False
                                break
                        except Exception:
                            values_ok = False
                            break
                    else:
                        if not _decimal_equal(_parse_decimal(expected.get(key)), _parse_decimal(exp_val)):
                            values_ok = False
                            break

            if values_ok:
                cm = {k: _parse_decimal(computed.get(k)) for k in computed}
                try:
                    c1 = _decimal_equal(
                        cm.get("total_due_after_credits_usd"),
                        _quantize_money((cm.get("total_taxable_subtotal_usd") or Decimal("0")) + (cm.get("total_tax_usd") or Decimal("0")) - (cm.get("referral_credits_applied_usd") or Decimal("0")))
                    )
                    c2 = _decimal_equal(
                        cm.get("outstanding_balance_usd"),
                        _quantize_money((cm.get("total_due_after_credits_usd") or Decimal("0")) - (cm.get("payments_received_usd") or Decimal("0")))
                    )
                    c3 = _decimal_equal(
                        cm.get("unredeemed_referral_credits_usd"),
                        _quantize_money((cm.get("referral_credits_earned_usd") or Decimal("0")) - (cm.get("referral_credits_applied_usd") or Decimal("0")))
                    )
                    c4 = _decimal_equal(
                        cm.get("outstanding_balance_usd"),
                        cm.get("unredeemed_referral_credits_usd")
                    )
                    evals_ok = c1 and c2 and c3 and c4
                except Exception:
                    evals_ok = False

                if not isinstance(checks_map, dict):
                    values_ok = False
                else:
                    needed_checks = {
                        "total_due_after_credits_usd == total_taxable_subtotal_usd + total_tax_usd - referral_credits_applied_usd": c1,
                        "outstanding_balance_usd == total_due_after_credits_usd - payments_received_usd": c2,
                        "unredeemed_referral_credits_usd == referral_credits_earned_usd - referral_credits_applied_usd": c3,
                        "outstanding_balance_usd == unredeemed_referral_credits_usd": c4,
                    }
                    for k, truth in needed_checks.items():
                        if checks_map.get(k) is not True or not truth:
                            values_ok = False
                            break
                if values_ok:
                    if isinstance(overall_status, bool):
                        if not overall_status:
                            values_ok = False
                    elif isinstance(overall_status, str):
                        if overall_status.strip().lower() not in ("pass", "passed", "ok", "true", "success"):
                            values_ok = False
                    else:
                        values_ok = False

        scores["validation_results_values_correct"] = 1.0 if values_ok else 0.0
    else:
        scores["validation_results_values_correct"] = 0.0

    if (workspace / "outputs" / "reconciliation_report.md").exists():
        try:
            report_text = (workspace / "outputs" / "reconciliation_report.md").read_text(encoding="utf-8")
        except Exception:
            report_text = ""
        has_summary = "summary" in report_text.lower()
        has_discrepancies = "discrepancies" in report_text.lower()
        has_credits_section = "credits & outstanding".lower() in report_text.lower()
        sections_ok = has_summary and has_discrepancies and has_credits_section

        content_ok = False
        if sections_ok and ledger_rows:
            disc_text = _find_section(report_text, "Discrepancies") or ""
            parsed_ledger = _parse_ledger(ledger_rows)
            all_listed = True
            for stay_id, vals in parsed_ledger.items():
                bal = vals.get("balance_usd") or Decimal("0")
                if _quantize_money(bal) != Decimal("0.00"):
                    amount_str = f"{_quantize_money(bal):.2f}"
                    if (stay_id not in disc_text) or (amount_str not in disc_text):
                        all_listed = False
                        break
            credits_text = _find_section(report_text, "Credits & Outstanding") or ""
            aggs = _compute_aggregates(ledger_rows, referrals_rows, payments_rows)
            if aggs is not None:
                earned = aggs["referral_credits_earned_usd"]
                applied = aggs["referral_credits_applied_usd"]
                unredeemed = aggs["unredeemed_referral_credits_usd"]
                credits_numbers_present = (
                    _value_in_text(credits_text, earned)
                    and _value_in_text(credits_text, applied)
                    and _value_in_text(credits_text, unredeemed)
                )
            else:
                credits_numbers_present = False
            content_ok = all_listed and credits_numbers_present

        scores["reconciliation_report_has_required_sections_and_content"] = 1.0 if (sections_ok and content_ok) else 0.0
    else:
        scores["reconciliation_report_has_required_sections_and_content"] = 0.0

    if (workspace / "outputs" / "meeting_notes.md").exists():
        try:
            notes_text = (workspace / "outputs" / "meeting_notes.md").read_text(encoding="utf-8")
        except Exception:
            notes_text = ""
        has_bullets = any(line.strip().startswith(("-", "*")) for line in notes_text.splitlines())

        if ledger_rows:
            aggs = _compute_aggregates(ledger_rows, referrals_rows, payments_rows)
        else:
            aggs = None
        figures_ok = False
        actions_ok = False
        discrepancies_ok = False
        if aggs is not None:
            total_spend = aggs["total_due_after_credits_usd"]
            total_taxes = aggs["total_tax_usd"]
            payments_recv = aggs["payments_received_usd"]
            unredeemed = aggs["unredeemed_referral_credits_usd"]
            figures_ok = (
                _value_in_text(notes_text, total_spend)
                and _value_in_text(notes_text, total_taxes)
                and _value_in_text(notes_text, payments_recv)
                and _value_in_text(notes_text, unredeemed)
            )

            parsed_ledger = _parse_ledger(ledger_rows)
            nonzero_stays = [
                (sid, vals.get("balance_usd") or Decimal("0"))
                for sid, vals in parsed_ledger.items()
                if _quantize_money(vals.get("balance_usd") or Decimal("0")) != Decimal("0.00")
            ]
            if nonzero_stays:
                discrepancies_ok = True
                for sid, bal in nonzero_stays:
                    if sid not in notes_text or f"{_quantize_money(bal):.2f}" not in notes_text:
                        discrepancies_ok = False
                        break
            else:
                discrepancies_ok = True

            lower_text = notes_text.lower()
            actions_ok = ("apply" in lower_text and "credit" in lower_text and ("stay" in lower_text or "s00" in lower_text))
        scores["meeting_notes_include_figures_and_actions"] = 1.0 if (has_bullets and figures_ok and discrepancies_ok and actions_ok) else 0.0
    else:
        scores["meeting_notes_include_figures_and_actions"] = 0.0

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

import json
import sys
import subprocess
import csv
import re
from pathlib import Path
from typing import Optional, Tuple, Dict, List, Any


def _read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return None


def _load_csv_dicts(path: Path) -> Tuple[Optional[List[str]], Optional[List[Dict[str, str]]]]:
    try:
        with path.open(newline="", encoding="utf-8", errors="replace") as f:
            rdr = csv.DictReader(f)
            header = rdr.fieldnames
            if header is None:
                return None, None
            rows = [dict(row) for row in rdr]
            return header, rows
    except Exception:
        return None, None


def _safe_float(s: Any) -> Optional[float]:
    try:
        return float(s)
    except Exception:
        return None


def _safe_int(s: Any) -> Optional[int]:
    try:
        # Allow float strings that are whole numbers
        if isinstance(s, float):
            return int(s) if s.is_integer() else None
        s_str = str(s).strip()
        if s_str == "":
            return None
        if re.fullmatch(r"-?\d+", s_str):
            return int(s_str)
        # check if it's something like "3.0"
        f = float(s_str)
        if f.is_integer():
            return int(f)
        return None
    except Exception:
        return None


def _compare_float(a: float, b: float, tol: float = 1e-6) -> bool:
    return abs(a - b) <= tol


def _run_checker(workspace: Path) -> Optional[Dict[str, Any]]:
    check_script = workspace / "input" / "check_data.py"
    readings_csv = workspace / "input" / "readings.csv"
    if not check_script.exists() or not readings_csv.exists():
        return None
    try:
        proc = subprocess.run(
            [sys.executable, str(check_script), str(readings_csv)],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            cwd=str(workspace),
            text=True,
            encoding="utf-8",
        )
        stdout = proc.stdout
        stderr = proc.stderr
        rc = proc.returncode
        parsed = _parse_checker_output(stdout=stdout, stderr=stderr)
        parsed["returncode"] = rc
        parsed["stdout"] = stdout
        parsed["stderr"] = stderr
        return parsed
    except Exception:
        return None


def _parse_checker_output(stdout: str, stderr: str) -> Dict[str, Any]:
    # Parse ERROR lines from stderr and WARNING + SUMMARY from stdout
    error_re = re.compile(r"^ERROR\s+unit=(?P<unit>[^ ]+)\s+timestamp=(?P<ts>[^ ]+)\s+reason=(?P<reason>.+)$")
    warn_re = re.compile(r"^WARNING\s+unit=(?P<unit>[^ ]+)\s+timestamp=(?P<ts>[^ ]+)\s+reason=(?P<reason>.+)$")
    summary_re = re.compile(r"^SUMMARY\s+errors=(?P<errors>\d+)\s+warnings=(?P<warnings>\d+)$")

    errors_by_pair = set()
    warnings_by_pair = set()
    errors_by_unit: Dict[str, int] = {}
    warnings_by_unit: Dict[str, int] = {}
    summary_counts = {"errors": None, "warnings": None}

    for line in stderr.splitlines():
        m = error_re.match(line.strip())
        if m:
            unit = m.group("unit")
            ts = m.group("ts")
            errors_by_pair.add((unit, ts))
            errors_by_unit[unit] = errors_by_unit.get(unit, 0) + 1
    for line in stdout.splitlines():
        sline = line.strip()
        m_w = warn_re.match(sline)
        if m_w:
            unit = m_w.group("unit")
            ts = m_w.group("ts")
            warnings_by_pair.add((unit, ts))
            warnings_by_unit[unit] = warnings_by_unit.get(unit, 0) + 1
            continue
        m_s = summary_re.match(sline)
        if m_s:
            summary_counts["errors"] = int(m_s.group("errors"))
            summary_counts["warnings"] = int(m_s.group("warnings"))

    return {
        "errors_by_pair": errors_by_pair,
        "warnings_by_pair": warnings_by_pair,
        "errors_by_unit": errors_by_unit,
        "warnings_by_unit": warnings_by_unit,
        "summary": summary_counts,
    }


def _parse_checker_log_content(content: str) -> Dict[str, Any]:
    # Log may contain both stdout and stderr mixed. Extract ERROR/WARNING/SUMMARY regardless of stream.
    error_re = re.compile(r"^ERROR\s+unit=(?P<unit>[^ ]+)\s+timestamp=(?P<ts>[^ ]+)\s+reason=(?P<reason>.+)$")
    warn_re = re.compile(r"^WARNING\s+unit=(?P<unit>[^ ]+)\s+timestamp=(?P<ts>[^ ]+)\s+reason=(?P<reason>.+)$")
    summary_re = re.compile(r"^SUMMARY\s+errors=(?P<errors>\d+)\s+warnings=(?P<warnings>\d+)$")

    errors_by_pair = set()
    warnings_by_pair = set()
    errors_by_unit: Dict[str, int] = {}
    warnings_by_unit: Dict[str, int] = {}
    summary_counts = {"errors": None, "warnings": None}
    for raw in content.splitlines():
        line = raw.strip()
        m_e = error_re.match(line)
        if m_e:
            unit = m_e.group("unit")
            ts = m_e.group("ts")
            errors_by_pair.add((unit, ts))
            errors_by_unit[unit] = errors_by_unit.get(unit, 0) + 1
            continue
        m_w = warn_re.match(line)
        if m_w:
            unit = m_w.group("unit")
            ts = m_w.group("ts")
            warnings_by_pair.add((unit, ts))
            warnings_by_unit[unit] = warnings_by_unit.get(unit, 0) + 1
            continue
        m_s = summary_re.match(line)
        if m_s:
            summary_counts["errors"] = int(m_s.group("errors"))
            summary_counts["warnings"] = int(m_s.group("warnings"))
            continue
    return {
        "errors_by_pair": errors_by_pair,
        "warnings_by_pair": warnings_by_pair,
        "errors_by_unit": errors_by_unit,
        "warnings_by_unit": warnings_by_unit,
        "summary": summary_counts,
    }


def _detect_exit_code_in_log(content: str, expected_rc: int) -> bool:
    # Accept several formats:
    # - A line that is exactly the integer exit code
    # - Lines containing 'exit code: N', 'exit_code=N', 'returncode: N', etc.
    patterns = [
        re.compile(r"(?i)\bexit\s*code\b\s*[:=]\s*(\d+)\b"),
        re.compile(r"(?i)\breturn\s*code\b\s*[:=]\s*(\d+)\b"),
        re.compile(r"(?i)\b(exitcode|returncode)\b\s*[:=]?\s*(\d+)\b"),
    ]
    lines = content.splitlines()
    for line in lines:
        stripped = line.strip()
        # exact integer line
        if re.fullmatch(r"-?\d+", stripped):
            try:
                val = int(stripped)
                if val == expected_rc:
                    return True
            except Exception:
                pass
        # pattern match
        for pat in patterns:
            m = pat.search(stripped)
            if m:
                g = m.groups()
                num = None
                for token in g[::-1]:
                    if token is None:
                        continue
                    if re.fullmatch(r"\d+", str(token)):
                        num = int(token)
                        break
                if num is not None and num == expected_rc:
                    return True
    return False


def _load_readings(workspace: Path) -> Optional[List[Dict[str, str]]]:
    path = workspace / "input" / "readings.csv"
    header, rows = _load_csv_dicts(path)
    if header is None or rows is None:
        return None
    # Verify required columns exist
    required = ["unit_id", "site", "region", "timestamp", "energy_kwh", "runtime_hours"]
    for col in required:
        if col not in header:
            return None
    return rows


def _compute_expected_metrics(workspace: Path, error_pairs: set) -> Optional[Dict[str, Any]]:
    rows = _load_readings(workspace)
    if rows is None:
        return None
    units = {}
    for row in rows:
        unit = (row.get("unit_id") or "").strip()
        site = (row.get("site") or "").strip()
        region = (row.get("region") or "").strip()
        ts = (row.get("timestamp") or "").strip()
        e_s = row.get("energy_kwh")
        r_s = row.get("runtime_hours")
        if unit == "" or ts == "":
            continue
        # skip if (unit, ts) flagged as error
        if (unit, ts) in error_pairs:
            continue
        e_v = _safe_float(e_s)
        r_v = _safe_float(r_s)
        if unit not in units:
            units[unit] = {
                "site": site,
                "region": region,
                "valid_readings": 0,
                "total_energy_kwh": 0.0,
                "total_runtime_hours": 0.0,
            }
        units[unit]["valid_readings"] += 1
        units[unit]["total_energy_kwh"] += (e_v if e_v is not None else 0.0)
        units[unit]["total_runtime_hours"] += (r_v if r_v is not None else 0.0)

    # Ensure each unit in readings appears in summary even if zero valid rows
    unit_ids_in_readings = set([(row.get("unit_id") or "").strip() for row in rows if (row.get("unit_id") or "").strip() != ""])
    for uid in unit_ids_in_readings:
        if uid not in units:
            site = ""
            region = ""
            for row in rows:
                if (row.get("unit_id") or "").strip() == uid:
                    site = (row.get("site") or "").strip()
                    region = (row.get("region") or "").strip()
                    break
            units[uid] = {
                "site": site,
                "region": region,
                "valid_readings": 0,
                "total_energy_kwh": 0.0,
                "total_runtime_hours": 0.0,
                "avg_kwh_per_hour": 0.0,
            }

    # Compute avg
    for uid, rec in units.items():
        runtime = rec.get("total_runtime_hours", 0.0)
        if runtime > 0:
            rec["avg_kwh_per_hour"] = rec.get("total_energy_kwh", 0.0) / runtime
        else:
            rec["avg_kwh_per_hour"] = 0.0

    return {
        "units": units,
        "unit_ids": sorted(units.keys()),
    }


def _expected_least_efficient_top5(expected_metrics: Dict[str, Any]) -> List[Tuple[str, float, float, int]]:
    # Filter: valid_readings >= 3 and total_runtime_hours >= 10
    rows = []
    for uid, rec in expected_metrics["units"].items():
        vr = rec.get("valid_readings", 0)
        tr = rec.get("total_runtime_hours", 0.0)
        if vr >= 3 and tr >= 10:
            rows.append((uid, rec.get("avg_kwh_per_hour", 0.0), tr, vr))
    # Sort ascending by avg_kwh_per_hour, then unit_id ascending
    rows.sort(key=lambda x: (x[1], x[0]))
    return rows[:5]


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "data_check_log_messages": 0.0,
        "data_check_log_exit_code_recorded": 0.0,
        "issues_by_unit_counts_correct": 0.0,
        "efficiency_summary_correct_values": 0.0,
        "least_efficient_top5_correct_order_and_values": 0.0,
    }

    # Paths to expected outputs
    out_dir = workspace / "output"
    data_check_log_path = out_dir / "data_check.log"
    issues_by_unit_path = out_dir / "issues_by_unit.csv"
    efficiency_summary_path = out_dir / "efficiency_summary.csv"
    least_efficient_path = out_dir / "least_efficient_top5.csv"

    # Run checker to compute expected
    checker_result = _run_checker(workspace)
    # Prepare expected structures
    expected_error_pairs = set()
    expected_warning_pairs = set()
    expected_errors_by_unit: Dict[str, int] = {}
    expected_warnings_by_unit: Dict[str, int] = {}
    expected_summary_err = None
    expected_summary_warn = None
    expected_rc = None
    if checker_result is not None:
        expected_error_pairs = checker_result.get("errors_by_pair", set())
        expected_warning_pairs = checker_result.get("warnings_by_pair", set())
        expected_errors_by_unit = checker_result.get("errors_by_unit", {})
        expected_warnings_by_unit = checker_result.get("warnings_by_unit", {})
        summary = checker_result.get("summary", {})
        expected_summary_err = summary.get("errors")
        expected_summary_warn = summary.get("warnings")
        expected_rc = checker_result.get("returncode")

    # 1) Validate data_check.log content (messages and summary)
    log_content = _read_text(data_check_log_path)
    if log_content is not None and checker_result is not None:
        parsed_log = _parse_checker_log_content(log_content)
        # Check that sets of error pairs and warning pairs match expected (exact)
        log_error_pairs = parsed_log.get("errors_by_pair", set())
        log_warning_pairs = parsed_log.get("warnings_by_pair", set())
        log_summary = parsed_log.get("summary", {})
        log_sum_err = log_summary.get("errors")
        log_sum_warn = log_summary.get("warnings")

        if (
            log_error_pairs == expected_error_pairs
            and log_warning_pairs == expected_warning_pairs
            and log_sum_err == expected_summary_err
            and log_sum_warn == expected_summary_warn
        ):
            scores["data_check_log_messages"] = 1.0
        else:
            scores["data_check_log_messages"] = 0.0
    else:
        scores["data_check_log_messages"] = 0.0

    # 1b) Check that exit code is recorded in the log in some recognizable form
    if log_content is not None and expected_rc is not None:
        if _detect_exit_code_in_log(log_content, expected_rc):
            scores["data_check_log_exit_code_recorded"] = 1.0
        else:
            scores["data_check_log_exit_code_recorded"] = 0.0
    else:
        scores["data_check_log_exit_code_recorded"] = 0.0

    # 2) Validate issues_by_unit.csv
    header, rows = _load_csv_dicts(issues_by_unit_path)
    if header is not None and rows is not None and checker_result is not None:
        # Require exact header order
        required_header = ["unit_id", "errors", "warnings"]
        if header == required_header:
            # Build mapping from file
            file_map: Dict[str, Tuple[int, int]] = {}
            valid = True
            for row in rows:
                uid = (row.get("unit_id") or "").strip()
                if uid == "":
                    valid = False
                    break
                e = _safe_int(row.get("errors"))
                w = _safe_int(row.get("warnings"))
                if e is None or w is None:
                    valid = False
                    break
                if uid in file_map:
                    valid = False
                    break
                file_map[uid] = (e, w)
            if valid:
                # Expected counts by unit
                expected_counts = {}
                readings_rows = _load_readings(workspace)
                units_in_readings = set()
                if readings_rows is not None:
                    units_in_readings = set([(r.get("unit_id") or "").strip() for r in readings_rows if (r.get("unit_id") or "").strip() != ""])
                # Combine units set: any unit that appears in readings or messages
                combined_units = set(units_in_readings) | set(expected_errors_by_unit.keys()) | set(expected_warnings_by_unit.keys())
                for uid in combined_units:
                    e = expected_errors_by_unit.get(uid, 0)
                    w = expected_warnings_by_unit.get(uid, 0)
                    expected_counts[uid] = (e, w)
                ok = True
                for uid, (e_exp, w_exp) in expected_counts.items():
                    if e_exp != 0 or w_exp != 0:
                        if uid not in file_map:
                            ok = False
                            break
                        e_got, w_got = file_map[uid]
                        if e_got != e_exp or w_got != w_exp:
                            ok = False
                            break
                if ok:
                    for uid, (e_got, w_got) in file_map.items():
                        if uid in expected_counts:
                            e_exp, w_exp = expected_counts[uid]
                            if e_got != e_exp or w_got != w_exp:
                                ok = False
                                break
                if ok:
                    scores["issues_by_unit_counts_correct"] = 1.0
                else:
                    scores["issues_by_unit_counts_correct"] = 0.0
            else:
                scores["issues_by_unit_counts_correct"] = 0.0
        else:
            scores["issues_by_unit_counts_correct"] = 0.0
    else:
        scores["issues_by_unit_counts_correct"] = 0.0

    # 3) Validate efficiency_summary.csv
    expected_metrics = None
    if checker_result is not None:
        expected_metrics = _compute_expected_metrics(workspace, checker_result.get("errors_by_pair", set()))
    if expected_metrics is not None:
        header_s, rows_s = _load_csv_dicts(efficiency_summary_path)
        if header_s is not None and rows_s is not None:
            req_header_s = ["unit_id", "site", "region", "valid_readings", "total_energy_kwh", "total_runtime_hours", "avg_kwh_per_hour"]
            if header_s == req_header_s:
                # Build file mapping by unit
                file_units: Dict[str, Dict[str, Any]] = {}
                valid = True
                for row in rows_s:
                    uid = (row.get("unit_id") or "").strip()
                    if uid == "":
                        valid = False
                        break
                    if uid in file_units:
                        valid = False
                        break
                    site = (row.get("site") or "").strip()
                    region = (row.get("region") or "").strip()
                    vr = _safe_int(row.get("valid_readings"))
                    te = _safe_float(row.get("total_energy_kwh"))
                    tr = _safe_float(row.get("total_runtime_hours"))
                    avg = _safe_float(row.get("avg_kwh_per_hour"))
                    if vr is None or te is None or tr is None or avg is None:
                        valid = False
                        break
                    file_units[uid] = {
                        "site": site,
                        "region": region,
                        "valid_readings": vr,
                        "total_energy_kwh": te,
                        "total_runtime_hours": tr,
                        "avg_kwh_per_hour": avg,
                    }
                if valid:
                    readings_rows = _load_readings(workspace)
                    units_in_readings = set()
                    if readings_rows is not None:
                        units_in_readings = set([(r.get("unit_id") or "").strip() for r in readings_rows if (r.get("unit_id") or "").strip() != ""])
                    if set(file_units.keys()) == units_in_readings:
                        ok = True
                        for uid in units_in_readings:
                            exp = expected_metrics["units"].get(uid)
                            if exp is None:
                                ok = False
                                break
                            got = file_units.get(uid)
                            if got is None:
                                ok = False
                                break
                            if got["site"] != exp["site"] or got["region"] != exp["region"]:
                                ok = False
                                break
                            if got["valid_readings"] != exp["valid_readings"]:
                                ok = False
                                break
                            if not _compare_float(got["total_energy_kwh"], exp["total_energy_kwh"]):
                                ok = False
                                break
                            if not _compare_float(got["total_runtime_hours"], exp["total_runtime_hours"]):
                                ok = False
                                break
                            if not _compare_float(got["avg_kwh_per_hour"], exp["avg_kwh_per_hour"]):
                                ok = False
                                break
                        if ok:
                            scores["efficiency_summary_correct_values"] = 1.0
                        else:
                            scores["efficiency_summary_correct_values"] = 0.0
                    else:
                        scores["efficiency_summary_correct_values"] = 0.0
                else:
                    scores["efficiency_summary_correct_values"] = 0.0
            else:
                scores["efficiency_summary_correct_values"] = 0.0
        else:
            scores["efficiency_summary_correct_values"] = 0.0
    else:
        scores["efficiency_summary_correct_values"] = 0.0

    # 4) Validate least_efficient_top5.csv
    if expected_metrics is not None:
        expected_top5 = _expected_least_efficient_top5(expected_metrics)
        header_t, rows_t = _load_csv_dicts(least_efficient_path)
        if header_t is not None and rows_t is not None:
            req_header_t = ["unit_id", "avg_kwh_per_hour", "total_runtime_hours", "valid_readings"]
            if header_t == req_header_t:
                # Parse rows preserving order
                valid = True
                file_top: List[Tuple[str, float, float, int]] = []
                for row in rows_t:
                    uid = (row.get("unit_id") or "").strip()
                    avg = _safe_float(row.get("avg_kwh_per_hour"))
                    tr = _safe_float(row.get("total_runtime_hours"))
                    vr = _safe_int(row.get("valid_readings"))
                    if uid == "" or avg is None or tr is None or vr is None:
                        valid = False
                        break
                    file_top.append((uid, avg, tr, vr))
                if valid:
                    if len(file_top) == len(expected_top5):
                        ok = True
                        for (uid_g, avg_g, tr_g, vr_g), (uid_e, avg_e, tr_e, vr_e) in zip(file_top, expected_top5):
                            if uid_g != uid_e:
                                ok = False
                                break
                            if vr_g != vr_e:
                                ok = False
                                break
                            if not _compare_float(avg_g, avg_e):
                                ok = False
                                break
                            if not _compare_float(tr_g, tr_e):
                                ok = False
                                break
                        if ok:
                            scores["least_efficient_top5_correct_order_and_values"] = 1.0
                        else:
                            scores["least_efficient_top5_correct_order_and_values"] = 0.0
                    else:
                        scores["least_efficient_top5_correct_order_and_values"] = 0.0
                else:
                    scores["least_efficient_top5_correct_order_and_values"] = 0.0
            else:
                scores["least_efficient_top5_correct_order_and_values"] = 0.0
        else:
            scores["least_efficient_top5_correct_order_and_values"] = 0.0
    else:
        scores["least_efficient_top5_correct_order_and_values"] = 0.0

    return scores


