def _read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        try:
            return path.read_text()
        except Exception:
            return None


def _load_json(path: Path) -> Optional[Any]:
    text = _read_text(path)
    if text is None:
        return None
    try:
        return json.loads(text)
    except Exception:
        return None


def _round2(value: float) -> float:
    return round(value + 1e-12, 2)


def _parse_python_pricing_constants(path: Path) -> Tuple[Optional[float], Optional[Dict[str, float]]]:
    text = _read_text(path)
    if text is None:
        return None, None
    try:
        module = ast.parse(text, filename=str(path))
    except Exception:
        return None, None
    tax_rate: Optional[float] = None
    bundle_discount: Optional[Dict[str, float]] = None
    for node in module.body:
        if isinstance(node, ast.Assign):
            for target in node.targets:
                # TAX_RATE
                if isinstance(target, ast.Name) and target.id == "TAX_RATE":
                    try:
                        if isinstance(node.value, ast.Num):
                            tax_rate = float(node.value.n)
                        elif isinstance(node.value, ast.Constant):
                            tax_rate = float(node.value.value)
                    except Exception:
                        tax_rate = None
                # BUNDLE_DISCOUNT
                if isinstance(target, ast.Name) and target.id == "BUNDLE_DISCOUNT":
                    try:
                        if isinstance(node.value, ast.Dict):
                            d: Dict[str, float] = {}
                            for k_node, v_node in zip(node.value.keys, node.value.values):
                                key: Optional[str] = None
                                if isinstance(k_node, ast.Str):
                                    key = k_node.s
                                elif isinstance(k_node, ast.Constant) and isinstance(k_node.value, str):
                                    key = k_node.value
                                if key is None:
                                    continue
                                if isinstance(v_node, ast.Num):
                                    val = float(v_node.n)
                                elif isinstance(v_node, ast.Constant) and isinstance(v_node.value, (int, float)):
                                    val = float(v_node.value)
                                else:
                                    continue
                                d[key] = val
                            bundle_discount = d
                    except Exception:
                        bundle_discount = None
    return tax_rate, bundle_discount


def _parse_value_scalar(val: str) -> Any:
    v = val.strip()
    if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
        v = v[1:-1]
    lower = v.lower()
    if lower == "true":
        return True
    if lower == "false":
        return False
    try:
        if v.isdigit() or (v.startswith('-') and v[1:].isdigit()):
            return int(v)
        return float(v)
    except Exception:
        return v


def _parse_packages_yaml(path: Path) -> Optional[Dict[str, Any]]:
    text = _read_text(path)
    if text is None:
        return None
    lines = text.splitlines()
    add_ons_pricing: Dict[str, int] = {}
    packages: List[Dict[str, Any]] = []
    state: Optional[str] = None
    current_pkg: Optional[Dict[str, Any]] = None

    for raw_line in lines:
        line = raw_line.rstrip('\n')
        stripped = line.strip()
        if stripped == "" or stripped.startswith("#"):
            continue
        if not line.startswith(" "):
            if stripped.startswith("add_ons_pricing:"):
                state = "add_ons_pricing"
                continue
            if stripped.startswith("packages:"):
                state = "packages"
                continue
            state = None
            continue

        if state == "add_ons_pricing":
            if line.startswith("  ") and ":" in line:
                try:
                    key, val = line.strip().split(":", 1)
                    key = key.strip()
                    val = val.strip()
                    if val == "":
                        continue
                    add_ons_pricing[key] = int(val)
                except Exception:
                    return None
            else:
                state = None
            continue

        if state == "packages":
            if line.startswith("  - "):
                current_pkg = {}
                packages.append(current_pkg)
                rest = line[4:].strip()
                if rest:
                    if ":" in rest:
                        k, v = rest.split(":", 1)
                        current_pkg[k.strip()] = _parse_value_scalar(v.strip())
                continue
            if line.startswith("    "):
                if current_pkg is None:
                    return None
                l = line.strip()
                if l.startswith("included_add_ons:"):
                    if l.endswith("[]"):
                        current_pkg["included_add_ons"] = []
                    else:
                        current_pkg["included_add_ons"] = current_pkg.get("included_add_ons", [])
                    continue
                if line.startswith("      - "):
                    item = line[8:].strip()
                    current_pkg.setdefault("included_add_ons", [])
                    current_pkg["included_add_ons"].append(item)
                    continue
                if ":" in l:
                    k, v = l.split(":", 1)
                    current_pkg[k.strip()] = _parse_value_scalar(v.strip())
                continue
            continue

    return {"add_ons_pricing": add_ons_pricing, "packages": packages}


def _compute_expected_catalog(yaml_data: Dict[str, Any], tax_rate: float, bundle_discount: Dict[str, float], bookings_counts: Dict[str, int]) -> List[Dict[str, Any]]:
    catalog = []
    add_on_prices: Dict[str, float] = yaml_data.get("add_ons_pricing", {})
    for pkg in yaml_data.get("packages", []):
        package_id = str(pkg.get("id"))
        name = pkg.get("name")
        active = bool(pkg.get("active"))
        ys = int(pkg.get("yoga_sessions"))
        ym = int(pkg.get("yoga_minutes"))
        ms = int(pkg.get("massage_sessions"))
        mm = int(pkg.get("massage_minutes"))
        base_price = float(pkg.get("base_price"))
        included = list(pkg.get("included_add_ons", []))
        add_ons_cost = sum(float(add_on_prices.get(a, 0)) for a in included)
        subtotal = base_price + add_ons_cost
        discount_pct = float(bundle_discount.get(package_id, 0.0))
        after_discount = subtotal * (1.0 - discount_pct)
        final_with_tax = _round2(after_discount * (1.0 + tax_rate))
        booking_count = int(bookings_counts.get(package_id, 0))
        obj = {
            "package_id": package_id,
            "name": name,
            "active": active,
            "yoga_sessions": ys,
            "yoga_minutes": ym,
            "massage_sessions": ms,
            "massage_minutes": mm,
            "included_add_ons": included,
            "base_price": base_price,
            "discount_pct": discount_pct,
            "tax_rate": tax_rate,
            "subtotal_before_discount": subtotal,
            "total_after_discount": after_discount,
            "final_price_with_tax": final_with_tax,
            "booking_count": booking_count,
        }
        catalog.append(obj)
    return catalog


def _load_bookings_counts(path: Path) -> Optional[Dict[str, int]]:
    try:
        with path.open("r", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            if not reader.fieldnames or "package_id" not in reader.fieldnames:
                return None
            counts: Dict[str, int] = {}
            for row in reader:
                pid = (row.get("package_id") or "").strip()
                if pid == "":
                    continue
                counts[pid] = counts.get(pid, 0) + 1
            return counts
    except Exception:
        return None


def _split_current_packages_section(doc_text: str) -> Tuple[Optional[str], Optional[str], Optional[str]]:
    text = doc_text.replace("\r\n", "\n")
    header = "## Current Packages"
    idx = text.find(header)
    if idx == -1:
        return None, None, None
    line_end = text.find("\n", idx)
    if line_end == -1:
        pre = text
        return pre, "", ""
    pre = text[:line_end + 1]
    next_idx = text.find("\n## ", line_end + 1)
    if next_idx == -1:
        section = text[line_end + 1:]
        post = ""
    else:
        section = text[line_end + 1: next_idx + 1]
        post = text[next_idx + 1:]
    return pre, section, post


def _extract_bullet_lines(section_text: str) -> List[str]:
    lines = [ln.strip() for ln in section_text.splitlines()]
    bullets = [ln for ln in lines if ln.startswith("- ")]
    return bullets


def _extract_names_from_doc_bullets(section_text: str) -> List[str]:
    names: List[str] = []
    bullets = _extract_bullet_lines(section_text)
    for b in bullets:
        content = b[2:].strip()
        # Try em dash first, then hyphen
        sep_pos = content.find("—")
        if sep_pos == -1:
            sep_pos = content.find("-")
        if sep_pos != -1:
            name = content[:sep_pos].strip()
        else:
            # whole line if no dash found
            name = content.strip()
        if name:
            names.append(name)
    return names


def _compute_discrepancies_expected(config_yaml: Dict[str, Any], original_doc_text: str) -> Tuple[List[Tuple[str, str]], List[Tuple[str, str]]]:
    # Returns (config_only_rows, doc_only_rows)
    yaml_names = [pkg.get("name") for pkg in config_yaml.get("packages", []) if "name" in pkg]
    yaml_names_ci_map = {n.lower(): n for n in yaml_names if isinstance(n, str)}
    pre_o, section_o, post_o = _split_current_packages_section(original_doc_text.replace("\r\n", "\n"))
    doc_names = _extract_names_from_doc_bullets(section_o or "")
    doc_names_ci_map = {n.lower(): n for n in doc_names}

    yaml_set_ci = set(yaml_names_ci_map.keys())
    doc_set_ci = set(doc_names_ci_map.keys())

    config_only_ci = sorted(yaml_set_ci - doc_set_ci)
    doc_only_ci = sorted(doc_set_ci - yaml_set_ci)

    config_only_rows = [("config_only", yaml_names_ci_map[n_ci]) for n_ci in config_only_ci]
    doc_only_rows = [("doc_only", doc_names_ci_map[n_ci]) for n_ci in doc_only_ci]
    return config_only_rows, doc_only_rows


def _compare_float(a: Any, b: Any, tol: float = 1e-6) -> bool:
    try:
        return abs(float(a) - float(b)) <= tol
    except Exception:
        return False


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores: Dict[str, float] = {
        "catalog_json_valid": 0.0,
        "catalog_includes_all_packages": 0.0,
        "catalog_field_values_correct": 0.0,
        "discrepancies_csv_valid": 0.0,
        "discrepancies_rows_correct": 0.0,
        "doc_sections_intact": 0.0,
        "doc_current_packages_active_only": 0.0,
        "doc_package_lines_prices_and_descriptions_correct": 0.0,
    }

    yaml_path = workspace / "config" / "packages.yaml"
    pricing_py_path = workspace / "scripts" / "pricing.py"
    bookings_csv_path = workspace / "data" / "bookings.csv"
    catalog_json_path = workspace / "out" / "packages_catalog.json"
    discrepancies_csv_path = workspace / "out" / "discrepancies.csv"
    doc_path = workspace / "docs" / "offerings.md"

    yaml_data = _parse_packages_yaml(yaml_path) if yaml_path.exists() else None
    tax_rate, bundle_discount = _parse_python_pricing_constants(pricing_py_path) if pricing_py_path.exists() else (None, None)
    bookings_counts = _load_bookings_counts(bookings_csv_path) if bookings_csv_path.exists() else None

    expected_catalog: Optional[List[Dict[str, Any]]] = None
    if yaml_data is not None and tax_rate is not None and bundle_discount is not None and bookings_counts is not None:
        expected_catalog = _compute_expected_catalog(yaml_data, tax_rate, bundle_discount, bookings_counts)

    # Validate out/packages_catalog.json
    catalog_json = _load_json(catalog_json_path)
    if isinstance(catalog_json, list):
        scores["catalog_json_valid"] = 1.0

    if isinstance(catalog_json, list) and yaml_data is not None:
        try:
            expected_pkg_ids = [str(p.get("id")) for p in yaml_data.get("packages", [])]
            actual_pkg_ids = [str(obj.get("package_id")) for obj in catalog_json]
            if len(actual_pkg_ids) == len(expected_pkg_ids) and set(actual_pkg_ids) == set(expected_pkg_ids):
                scores["catalog_includes_all_packages"] = 1.0
        except Exception:
            scores["catalog_includes_all_packages"] = 0.0

    if isinstance(catalog_json, list) and expected_catalog is not None:
        expected_by_id = {obj["package_id"]: obj for obj in expected_catalog}
        ok = True
        try:
            for obj in catalog_json:
                pid = obj.get("package_id")
                if pid not in expected_by_id:
                    ok = False
                    break
                exp = expected_by_id[pid]
                required_keys = [
                    "package_id", "name", "active",
                    "yoga_sessions", "yoga_minutes", "massage_sessions", "massage_minutes",
                    "included_add_ons", "base_price",
                    "discount_pct", "tax_rate",
                    "subtotal_before_discount", "total_after_discount", "final_price_with_tax",
                    "booking_count",
                ]
                if not all(k in obj for k in required_keys):
                    ok = False
                    break
                if obj.get("name") != exp.get("name"):
                    ok = False
                    break
                if bool(obj.get("active")) != bool(exp.get("active")):
                    ok = False
                    break
                if int(obj.get("yoga_sessions")) != int(exp.get("yoga_sessions")):
                    ok = False
                    break
                if int(obj.get("yoga_minutes")) != int(exp.get("yoga_minutes")):
                    ok = False
                    break
                if int(obj.get("massage_sessions")) != int(exp.get("massage_sessions")):
                    ok = False
                    break
                if int(obj.get("massage_minutes")) != int(exp.get("massage_minutes")):
                    ok = False
                    break
                try:
                    inc_actual = list(obj.get("included_add_ons", []))
                except Exception:
                    ok = False
                    break
                inc_expected = list(exp.get("included_add_ons", []))
                if inc_actual != inc_expected:
                    ok = False
                    break
                if not _compare_float(obj.get("base_price"), exp.get("base_price")):
                    ok = False
                    break
                if not _compare_float(obj.get("discount_pct"), exp.get("discount_pct")):
                    ok = False
                    break
                if not _compare_float(obj.get("tax_rate"), exp.get("tax_rate")):
                    ok = False
                    break
                if not _compare_float(obj.get("subtotal_before_discount"), exp.get("subtotal_before_discount")):
                    ok = False
                    break
                if not _compare_float(obj.get("total_after_discount"), exp.get("total_after_discount")):
                    ok = False
                    break
                try:
                    final_actual = float(obj.get("final_price_with_tax"))
                except Exception:
                    ok = False
                    break
                if _round2(final_actual) != exp.get("final_price_with_tax"):
                    ok = False
                    break
                if int(obj.get("booking_count")) != int(exp.get("booking_count")):
                    ok = False
                    break
        except Exception:
            ok = False
        scores["catalog_field_values_correct"] = 1.0 if ok else 0.0

    # Validate out/discrepancies.csv
    # Compute expected from ORIGINAL_DOC_TEXT and YAML
    if yaml_data is not None:
        cfg_only_exp, doc_only_exp = _compute_discrepancies_expected(yaml_data, ORIGINAL_DOC_TEXT)
        expected_rows_set = set(cfg_only_exp + doc_only_exp)
    else:
        expected_rows_set = set()

    try:
        with discrepancies_csv_path.open("r", encoding="utf-8") as f:
            reader = csv.reader(f)
            rows = list(reader)
        if rows and rows[0] == ["type", "package_name"]:
            scores["discrepancies_csv_valid"] = 1.0
            body = rows[1:]
            tuple_set = set((r[0], r[1]) for r in body if len(r) >= 2)
            if yaml_data is not None and tuple_set == expected_rows_set and len(body) == len(expected_rows_set):
                scores["discrepancies_rows_correct"] = 1.0
            else:
                scores["discrepancies_rows_correct"] = 0.0
        else:
            scores["discrepancies_csv_valid"] = 0.0
            scores["discrepancies_rows_correct"] = 0.0
    except Exception:
        scores["discrepancies_csv_valid"] = 0.0
        scores["discrepancies_rows_correct"] = 0.0

    # Validate docs/offerings.md updated section and intact other sections
    current_doc_text = _read_text(doc_path)
    if current_doc_text is not None:
        current_doc_text_norm = current_doc_text.replace("\r\n", "\n")
        pre_cur, section_cur, post_cur = _split_current_packages_section(current_doc_text_norm)

        # Evaluate active-only and content correctness if we can compute expected catalog
        if yaml_data is not None and expected_catalog is not None and section_cur is not None:
            active_pkgs = [p for p in yaml_data.get("packages", []) if bool(p.get("active"))]
            active_names = [p.get("name") for p in active_pkgs]
            inactive_names = [p.get("name") for p in yaml_data.get("packages", []) if not bool(p.get("active"))]
            bullets = _extract_bullet_lines(section_cur)
            bullet_names_present: List[str] = []
            for b in bullets:
                extracted = _extract_names_from_doc_bullets(b)
                if extracted:
                    bullet_names_present.append(extracted[0])
                else:
                    # fallback: find by presence
                    for n in active_names + inactive_names:
                        if n in b:
                            bullet_names_present.append(n)
                            break
            cond_only_active = (
                set(bullet_names_present) == set(active_names)
                and len(bullet_names_present) == len(active_names)
                and all(n in bullet_names_present for n in active_names)
                and all(n not in bullet_names_present for n in inactive_names)
            )
            if cond_only_active:
                scores["doc_current_packages_active_only"] = 1.0

            expected_by_name: Dict[str, Dict[str, Any]] = {obj["name"]: obj for obj in expected_catalog}
            line_checks_ok = True
            if cond_only_active:
                for name in active_names:
                    matching_lines = [b for b in bullets if name in b]
                    if not matching_lines:
                        line_checks_ok = False
                        break
                    line = matching_lines[0]
                    exp = expected_by_name.get(name, {})
                    price_val = exp.get("final_price_with_tax")
                    if not isinstance(price_val, (int, float)):
                        line_checks_ok = False
                        break
                    price_str = f"{price_val:.2f}"
                    if price_str not in line:
                        line_checks_ok = False
                        break
                    ys = exp.get("yoga_sessions")
                    ym = exp.get("yoga_minutes")
                    ms = exp.get("massage_sessions")
                    mm = exp.get("massage_minutes")
                    lower_line = line.lower()
                    if str(ys) not in lower_line or "yoga" not in lower_line:
                        line_checks_ok = False
                        break
                    if str(ym) not in lower_line or "min" not in lower_line:
                        line_checks_ok = False
                        break
                    if str(ms) not in lower_line or "massage" not in lower_line:
                        line_checks_ok = False
                        break
                    if str(mm) not in lower_line or "min" not in lower_line:
                        line_checks_ok = False
                        break
                    addons = exp.get("included_add_ons", [])
                    if addons:
                        for addon in addons:
                            if addon.lower() not in lower_line:
                                line_checks_ok = False
                                break
                        if not line_checks_ok:
                            break
            else:
                line_checks_ok = False
            scores["doc_package_lines_prices_and_descriptions_correct"] = 1.0 if line_checks_ok else 0.0

        # Check that only the "Current Packages" section changed; gate this on having updated section correct
        pre_orig, section_orig, post_orig = _split_current_packages_section(ORIGINAL_DOC_TEXT.replace("\r\n", "\n"))
        if (
            pre_cur is not None and post_cur is not None and
            pre_orig is not None and post_orig is not None and
            scores["doc_current_packages_active_only"] == 1.0 and
            scores["doc_package_lines_prices_and_descriptions_correct"] == 1.0
        ):
            if pre_cur == pre_orig and post_cur == post_orig:
                scores["doc_sections_intact"] = 1.0
            else:
                scores["doc_sections_intact"] = 0.0
        else:
            scores["doc_sections_intact"] = 0.0
    else:
        # Document missing; leave doc-related scores at 0.0
        pass

    return scores


def main() -> None:
    if len(sys.argv) > 1:
        workspace_path = sys.argv[1]
    else:
        workspace_path = "."
    result = grade([], workspace_path)
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

import json
import sys
import csv
import re
from pathlib import Path
from typing import Optional, Tuple, Dict, List


def _read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _load_json(path: Path) -> Optional[dict]:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None


def _parse_tag_attributes(tag_str: str) -> Dict[str, str]:
    attrs: Dict[str, str] = {}
    # Remove starting "<... " and trailing ">"
    inner = tag_str.strip()
    if inner.startswith("<"):
        inner = inner[1:]
    if inner.endswith(">"):
        inner = inner[:-1]
    # Now parse attributes in the remainder after the tag name
    # Split on whitespace first token is tag name
    parts = inner.split(None, 1)
    attr_part = parts[1] if len(parts) > 1 else ""
    # Regex to find key="value" or key='value'
    for m in re.finditer(r'([^\s=]+)\s*=\s*("([^"]*)"|\'([^\']*)\')', attr_part, flags=re.S):
        key = m.group(1).strip().lower()
        val = m.group(3) if m.group(3) is not None else m.group(4)
        attrs[key] = val
    # Also capture boolean attributes (no equals) as present with empty string
    for m in re.finditer(r'([^\s=]+)(?=(\s|$))', attr_part):
        key = m.group(1).strip().lower()
        if key and key not in attrs:
            # Avoid capturing tag name again
            # Ensure it's not something like '/' from self-closing
            if key not in ("/",):
                attrs[key] = ""
    return attrs


def _extract_head_body(html: str) -> Tuple[Optional[str], Optional[str]]:
    if html is None:
        return None, None
    head_match = re.search(r'<head\b[^>]*>(.*?)</head\s*>', html, flags=re.I | re.S)
    body_match = re.search(r'<body\b[^>]*>(.*?)</body\s*>', html, flags=re.I | re.S)
    head_html = head_match.group(1) if head_match else None
    body_html = body_match.group(1) if body_match else None
    return head_html, body_html


def _parse_title(head_html: Optional[str]) -> Optional[str]:
    if not head_html:
        return None
    m = re.search(r'<title\b[^>]*>(.*?)</title\s*>', head_html, flags=re.I | re.S)
    if not m:
        return None
    # Strip inner whitespace
    title = m.group(1).strip()
    # Collapse internal whitespace to single spaces
    title = re.sub(r'\s+', ' ', title)
    return title


def _parse_meta_description(head_html: Optional[str]) -> Optional[str]:
    if not head_html:
        return None
    metas = re.findall(r'<meta\b[^>]*>', head_html, flags=re.I | re.S)
    for tag in metas:
        attrs = _parse_tag_attributes(tag)
        name = attrs.get("name", "")
        if name is not None and name.lower() == "description":
            content = attrs.get("content")
            if content is None:
                return ""
            return content
    return None


def _parse_canonical(head_html: Optional[str]) -> Tuple[bool, Optional[str]]:
    if not head_html:
        return False, None
    links = re.findall(r'<link\b[^>]*>', head_html, flags=re.I | re.S)
    for tag in links:
        attrs = _parse_tag_attributes(tag)
        rel = attrs.get("rel", "")
        if rel is not None and rel.lower() == "canonical":
            href = attrs.get("href")
            return True, href
    return False, None


def _parse_images(body_html: Optional[str]) -> List[Dict[str, Optional[str]]]:
    imgs: List[Dict[str, Optional[str]]] = []
    if not body_html:
        return imgs
    tags = re.findall(r'<img\b[^>]*>', body_html, flags=re.I | re.S)
    for tag in tags:
        attrs = _parse_tag_attributes(tag)
        alt = attrs.get("alt")
        # Treat None or empty string as missing/empty
        imgs.append({"alt": alt})
    return imgs


def _img_missing_alt_count(imgs: List[Dict[str, Optional[str]]]) -> int:
    count = 0
    for img in imgs:
        alt = img.get("alt")
        if alt is None or alt.strip() == "":
            count += 1
    return count


def _h1_present(body_html: Optional[str]) -> bool:
    if not body_html:
        return False
    return re.search(r'<h1\b[^>]*>', body_html, flags=re.I) is not None


def _count_internal_links(body_html: Optional[str]) -> int:
    if not body_html:
        return 0
    tags = re.findall(r'<a\b[^>]*>', body_html, flags=re.I | re.S)
    count = 0
    for tag in tags:
        attrs = _parse_tag_attributes(tag)
        href = attrs.get("href") or ""
        if href.lower().endswith(".html"):
            count += 1
    return count


def _normalize_body_for_compare(body_html: Optional[str]) -> Optional[str]:
    if body_html is None:
        return None
    # Remove all alt attributes (case-insensitive), including whitespace around them
    without_alt = re.sub(r'\s+alt\s*=\s*(".*?"|\'.*?\')', '', body_html, flags=re.I | re.S)
    # Collapse whitespace
    normalized = re.sub(r'\s+', ' ', without_alt).strip()
    return normalized


def _includes_brand_in_title(title: Optional[str]) -> bool:
    if not title:
        return False
    t = title.lower()
    return ("greenswell cooperative" in t) or ("greenswell" in t)


def _includes_any_keyword(text: Optional[str], keywords: List[str]) -> bool:
    if not text:
        return False
    t = text.lower()
    for kw in keywords:
        if kw.lower() in t:
            return True
    return False


def _find_keyword_used(text: Optional[str], keywords: List[str]) -> Optional[str]:
    if not text:
        return None
    t = text.lower()
    for kw in keywords:
        if kw.lower() in t:
            return kw
    return None


def _parse_robots(robots_text: Optional[str]) -> Dict[str, object]:
    disallows: List[str] = []
    disallow_count = 0
    sitemap_present = False
    if robots_text:
        for line in robots_text.splitlines():
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            lower = line.lower()
            if lower.startswith("disallow:"):
                # Extract value after colon
                val = line.split(":", 1)[1].strip()
                disallows.append(val)
                disallow_count += 1
            elif lower.startswith("sitemap:"):
                sitemap_present = True
    return {
        "disallow_count": disallow_count,
        "disallows": disallows,
        "sitemap_present": sitemap_present,
    }


def _compute_page_metrics(html_text: Optional[str]) -> Dict[str, object]:
    head, body = _extract_head_body(html_text or "")
    title = _parse_title(head)
    meta_desc = _parse_meta_description(head)
    has_canonical, canonical_href = _parse_canonical(head)
    imgs = _parse_images(body)
    img_count = len(imgs)
    img_missing_alt = _img_missing_alt_count(imgs)
    h1 = _h1_present(body)
    internal_links = _count_internal_links(body)
    body_norm = _normalize_body_for_compare(body)
    return {
        "title": title,
        "meta_description": meta_desc if meta_desc is not None else None,
        "has_canonical": has_canonical,
        "canonical_href": canonical_href,
        "img_count": img_count,
        "img_missing_alt": img_missing_alt,
        "imgs": imgs,
        "h1_present": h1,
        "internal_link_count": internal_links,
        "body_norm": body_norm,
        "body_raw": body or "",
    }


def _strict_len_in_range(s: Optional[str], min_len: int, max_len: int) -> bool:
    if s is None:
        return False
    n = len(s)
    return min_len <= n <= max_len


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "outputs_in_expected_paths": 0.0,
        "index_title_ok": 0.0,
        "products_title_ok": 0.0,
        "blog_title_ok": 0.0,
        "index_meta_ok": 0.0,
        "products_meta_ok": 0.0,
        "blog_meta_ok": 0.0,
        "index_imgs_alt_ok": 0.0,
        "products_imgs_alt_ok": 0.0,
        "blog_imgs_alt_ok": 0.0,
        "index_body_preserved": 0.0,
        "products_body_preserved": 0.0,
        "blog_body_preserved": 0.0,
        "canonical_handling_correct": 0.0,
        "audit_csv_correct": 0.0,
        "summary_json_correct": 0.0,
    }

    # Paths
    input_pages_dir = workspace / "input" / "pages"
    output_pages_dir = workspace / "output" / "optimized" / "pages"
    audit_csv_path = workspace / "output" / "audit" / "seo_audit.csv"
    summary_json_path = workspace / "output" / "audit" / "summary.json"
    robots_path = workspace / "input" / "robots.txt"
    config_path = workspace / "input" / "site-config.json"

    expected_pages = ["index.html", "products.html", "blog.html"]

    # Load config
    config = _load_json(config_path)
    if config is None:
        # Default ranges as fallback (task-specified), but missing config still impacts checks reliant on keywords
        preferred_keywords = []
        title_range = (50, 60)
        meta_range = (140, 160)
    else:
        preferred_keywords = config.get("preferred_keywords", []) or []
        tr = config.get("title_length_range", [50, 60])
        mr = config.get("meta_description_length_range", [140, 160])
        try:
            title_range = (int(tr[0]), int(tr[1]))
        except Exception:
            title_range = (50, 60)
        try:
            meta_range = (int(mr[0]), int(mr[1]))
        except Exception:
            meta_range = (140, 160)

    # Read inputs and outputs
    inputs: Dict[str, Dict[str, object]] = {}
    outputs: Dict[str, Dict[str, object]] = {}

    for page in expected_pages:
        before_text = _read_text(input_pages_dir / page)
        after_text = _read_text(output_pages_dir / page)
        inputs[page] = _compute_page_metrics(before_text) if before_text is not None else {}
        outputs[page] = _compute_page_metrics(after_text) if after_text is not None else {}

    # outputs_in_expected_paths
    if all((output_pages_dir / p).exists() for p in expected_pages):
        scores["outputs_in_expected_paths"] = 1.0

    # Per-page checks
    for page in expected_pages:
        after = outputs.get(page) or {}
        before = inputs.get(page) or {}

        # Title check
        title_ok = False
        title_after = after.get("title")
        if title_after is not None and _strict_len_in_range(title_after, title_range[0], title_range[1]) and _includes_brand_in_title(title_after):
            title_ok = True
        scores_key = f"{page.split('.')[0]}_title_ok"
        if scores_key in scores and title_ok:
            scores[scores_key] = 1.0

        # Meta description check
        meta_ok = False
        meta_after = after.get("meta_description")
        if (
            isinstance(meta_after, str)
            and _strict_len_in_range(meta_after, meta_range[0], meta_range[1])
            and _includes_any_keyword(meta_after, preferred_keywords)
        ):
            meta_ok = True
        scores_key = f"{page.split('.')[0]}_meta_ok"
        if scores_key in scores and meta_ok:
            scores[scores_key] = 1.0

        # Images alt check
        imgs_ok = False
        imgs_before = before.get("imgs") if before else None
        imgs_after = after.get("imgs") if after else None
        if isinstance(imgs_before, list) and isinstance(imgs_after, list) and len(imgs_before) == len(imgs_after):
            per_ok = True
            for i in range(len(imgs_before)):
                alt_b = imgs_before[i].get("alt")
                alt_a = imgs_after[i].get("alt")
                if alt_b is None or (isinstance(alt_b, str) and alt_b.strip() == ""):
                    # After must be non-empty and under 80 chars
                    if not (isinstance(alt_a, str) and alt_a.strip() != "" and len(alt_a) <= 80):
                        per_ok = False
                        break
                else:
                    # After must equal before
                    if alt_a != alt_b:
                        per_ok = False
                        break
            # Also ensure no missing alt remain after
            if per_ok:
                missing_after = _img_missing_alt_count(imgs_after)
                if missing_after != 0:
                    per_ok = False
            imgs_ok = per_ok
        scores_key = f"{page.split('.')[0]}_imgs_alt_ok"
        if scores_key in scores and imgs_ok:
            scores[scores_key] = 1.0

        # Body preserved (ignoring alt attributes)
        body_ok = False
        body_before_norm = before.get("body_norm") if before else None
        body_after_norm = after.get("body_norm") if after else None
        if body_before_norm is not None and body_after_norm is not None and body_before_norm == body_after_norm:
            body_ok = True
        scores_key = f"{page.split('.')[0]}_body_preserved"
        if scores_key in scores and body_ok:
            scores[scores_key] = 1.0

    # Canonical handling: preserve existing and do not add where absent
    canonical_ok = True
    # products.html had canonical; must be present after and same href
    before_prod = inputs.get("products.html") or {}
    after_prod = outputs.get("products.html") or {}
    if not before_prod or not after_prod:
        canonical_ok = False
    else:
        if not (before_prod.get("has_canonical") is True and after_prod.get("has_canonical") is True):
            canonical_ok = False
        else:
            if before_prod.get("canonical_href") != after_prod.get("canonical_href"):
                canonical_ok = False
    # index.html and blog.html had no canonical; must not have after
    for page in ["index.html", "blog.html"]:
        before_p = inputs.get(page) or {}
        after_p = outputs.get(page) or {}
        if not before_p or not after_p:
            canonical_ok = False
        else:
            if before_p.get("has_canonical") is True:
                # If it had canonical originally (not expected), still must preserve? But according to inputs it's absent.
                # We'll enforce that after must match before.
                if after_p.get("has_canonical") is not True:
                    canonical_ok = False
            else:
                if after_p.get("has_canonical") is True:
                    canonical_ok = False
    if canonical_ok:
        scores["canonical_handling_correct"] = 1.0

    # Audit CSV correctness
    def _validate_csv(csv_path: Path) -> bool:
        required_header = [
            "page",
            "title_before",
            "title_after",
            "title_length_after",
            "meta_description_before",
            "meta_description_after",
            "meta_description_length_after",
            "h1_present",
            "canonical_present",
            "img_count_before",
            "img_missing_alt_before",
            "img_missing_alt_after",
            "internal_link_count_before",
            "keyword_used_in_description",
        ]
        try:
            with csv_path.open("r", encoding="utf-8", newline="") as f:
                reader = csv.reader(f)
                rows = list(reader)
        except Exception:
            return False
        if not rows:
            return False
        header = rows[0]
        if header != required_header:
            return False
        data_rows = rows[1:]
        if len(data_rows) != len(expected_pages):
            return False
        # Build map from page to row dict
        idx_map = {name: i for i, name in enumerate(required_header)}
        seen_pages = set()
        for row in data_rows:
            if len(row) != len(required_header):
                return False
            page_name = row[idx_map["page"]]
            if page_name not in expected_pages:
                return False
            if page_name in seen_pages:
                return False
            seen_pages.add(page_name)
            before = inputs.get(page_name) or {}
            after = outputs.get(page_name) or {}
            if not before or not after:
                return False
            # title_before
            tb = before.get("title") or ""
            if row[idx_map["title_before"]] != tb:
                return False
            # title_after
            ta = after.get("title") or ""
            if row[idx_map["title_after"]] != ta:
                return False
            # title_length_after
            try:
                tla = int(row[idx_map["title_length_after"]])
            except Exception:
                return False
            if tla != len(ta):
                return False
            # meta_description_before (empty if missing)
            mdb_before = before.get("meta_description")
            mdb_str = "" if (mdb_before is None) else (mdb_before)
            if row[idx_map["meta_description_before"]] != mdb_str:
                return False
            # meta_description_after
            mda = after.get("meta_description") or ""
            if row[idx_map["meta_description_after"]] != mda:
                return False
            # meta_description_length_after
            try:
                mdla = int(row[idx_map["meta_description_length_after"]])
            except Exception:
                return False
            if mdla != len(mda):
                return False
            # h1_present (true/false) - compute from input
            h1b = before.get("h1_present") is True
            h1_csv = row[idx_map["h1_present"]].strip().lower()
            if h1_csv not in ("true", "false"):
                return False
            if (h1_csv == "true") != h1b:
                return False
            # canonical_present (true/false) - compute from after
            can_after = after.get("has_canonical") is True
            can_csv = row[idx_map["canonical_present"]].strip().lower()
            if can_csv not in ("true", "false"):
                return False
            if (can_csv == "true") != can_after:
                return False
            # img_count_before
            try:
                icb = int(row[idx_map["img_count_before"]])
            except Exception:
                return False
            if icb != int(before.get("img_count") or 0):
                return False
            # img_missing_alt_before
            try:
                imab = int(row[idx_map["img_missing_alt_before"]])
            except Exception:
                return False
            if imab != int(before.get("img_missing_alt") or 0):
                return False
            # img_missing_alt_after
            try:
                imaa = int(row[idx_map["img_missing_alt_after"]])
            except Exception:
                return False
            if imaa != int(after.get("img_missing_alt") or 0):
                return False
            # internal_link_count_before
            try:
                ilcb = int(row[idx_map["internal_link_count_before"]])
            except Exception:
                return False
            if ilcb != int(before.get("internal_link_count") or 0):
                return False
            # keyword_used_in_description: one value from preferred_keywords that is present in rewritten meta description
            kw_csv = row[idx_map["keyword_used_in_description"]]
            if kw_csv not in preferred_keywords:
                return False
            if kw_csv.lower() not in (mda or "").lower():
                return False
        # ensure all expected pages covered
        if set(expected_pages) != seen_pages:
            return False
        return True

    if audit_csv_path.exists() and _validate_csv(audit_csv_path):
        scores["audit_csv_correct"] = 1.0

    # Summary JSON correctness
    def _validate_summary_json(path: Path) -> bool:
        summary = _load_json(path)
        if summary is None:
            return False
        # Compute expected
        total_pages = len(expected_pages)
        pages_missing_meta_before = 0
        total_images_before = 0
        total_images_missing_alt_before = 0
        total_images_missing_alt_after = 0
        title_lengths_after: List[int] = []
        meta_lengths_after: List[int] = []

        for page in expected_pages:
            before = inputs.get(page) or {}
            after = outputs.get(page) or {}
            md_before = before.get("meta_description")
            if md_before is None:
                pages_missing_meta_before += 1
            total_images_before += int(before.get("img_count") or 0)
            total_images_missing_alt_before += int(before.get("img_missing_alt") or 0)
            total_images_missing_alt_after += int(after.get("img_missing_alt") or 0)
            ta = after.get("title")
            if isinstance(ta, str):
                title_lengths_after.append(len(ta))
            mda = after.get("meta_description")
            if isinstance(mda, str):
                meta_lengths_after.append(len(mda))

        avg_title_len_after = sum(title_lengths_after) / total_pages if total_pages > 0 else 0.0
        avg_meta_len_after = sum(meta_lengths_after) / total_pages if total_pages > 0 else 0.0

        # Robots
        robots_text = _read_text(robots_path)
        robots_metrics = _parse_robots(robots_text)

        # Validate fields
        try:
            if int(summary.get("total_pages")) != total_pages:
                return False
            if int(summary.get("pages_missing_meta_description_before")) != pages_missing_meta_before:
                return False
            # Allow minor float rounding; compare within tiny epsilon
            def _approx_equal(a, b, eps=1e-6):
                try:
                    return abs(float(a) - float(b)) <= eps
                except Exception:
                    return False
            if not _approx_equal(summary.get("avg_title_length_after"), avg_title_len_after):
                return False
            if not _approx_equal(summary.get("avg_meta_description_length_after"), avg_meta_len_after):
                return False
            if int(summary.get("total_images_before")) != total_images_before:
                return False
            if int(summary.get("total_images_missing_alt_before")) != total_images_missing_alt_before:
                return False
            if int(summary.get("total_images_missing_alt_after")) != total_images_missing_alt_after:
                return False
            robots_obj = summary.get("robots")
            if not isinstance(robots_obj, dict):
                return False
            if int(robots_obj.get("disallow_count")) != robots_metrics["disallow_count"]:
                return False
            # Disallows must match exactly including order
            if robots_obj.get("disallows") != robots_metrics["disallows"]:
                return False
            sp = robots_obj.get("sitemap_present")
            if not isinstance(sp, bool):
                return False
            if sp != robots_metrics["sitemap_present"]:
                return False
        except Exception:
            return False
        return True

    if summary_json_path.exists() and _validate_summary_json(summary_json_path):
        scores["summary_json_correct"] = 1.0

    return scores


def main() -> None:
    workspace = sys.argv[1] if len(sys.argv) > 1 else "."
    result = grade([], workspace)
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

import csv
import json
import re
import sys
from pathlib import Path
from typing import Dict, List, Tuple, Optional


def _read_text(path: Path) -> Optional[str]:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return None


def _load_csv_dicts(path: Path) -> Optional[List[dict]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            rows = list(reader)
            return rows
    except Exception:
        return None


def _load_json(path: Path) -> Optional[dict]:
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _load_jsonl(path: Path) -> Optional[List[dict]]:
    out = []
    try:
        with path.open("r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = json.loads(line)
                except Exception:
                    return None
                if not isinstance(obj, dict):
                    return None
                out.append(obj)
        return out
    except Exception:
        return None


def _tokenize_basic(text: str) -> List[str]:
    # Lowercase, treat hyphens as separators (replace with spaces),
    # ignore apostrophes (remove), remove other punctuation, split on whitespace.
    if not isinstance(text, str):
        return []
    s = text.lower()
    s = s.replace("-", " ")
    s = s.replace("’", "'")
    s = s.replace("‘", "'")
    s = s.replace("`", "'")
    s = s.replace("'", "")  # ignore apostrophes
    cleaned = []
    for ch in s:
        if ch.isalnum() or ch.isspace():
            cleaned.append(ch)
    s2 = "".join(cleaned)
    tokens = s2.split()
    return tokens


def _count_keywords(text: str, keywords: List[str]) -> Dict[str, int]:
    tokens = _tokenize_basic(text)
    counts: Dict[str, int] = {k: 0 for k in keywords}
    for t in tokens:
        if t in counts:
            counts[t] += 1
    return counts


def _load_keywords(workspace: Path) -> Optional[List[str]]:
    kw_csv = workspace / "input" / "keywords.csv"
    rows = _load_csv_dicts(kw_csv)
    if rows is None:
        return None
    try:
        with kw_csv.open("r", encoding="utf-8", newline="") as f:
            header_line = f.readline()
    except Exception:
        return None
    header = [h.strip().lower() for h in header_line.strip().split(",")] if header_line else []
    if "keyword" not in header:
        return None
    keywords = []
    for r in rows:
        if "keyword" not in r:
            return None
        v = (r["keyword"] or "").strip().lower()
        if v:
            keywords.append(v)
    if not keywords:
        return None
    return keywords


def _extract_chapter_labels_from_text(txt: str) -> List[str]:
    labels = []
    for line in txt.splitlines():
        if line.startswith("CHAPTER"):
            labels.append(line.rstrip("\r\n"))
    return labels


def grade(transcript: list, workspace_path: str) -> dict:
    workspace = Path(workspace_path)
    scores = {
        "downloads_wikipedia_biodiversity_html": 0.0,
        "downloads_wikipedia_ecology_html": 0.0,
        "downloads_gutenberg_origin_text": 0.0,
        "extracted_wikipedia_biodiversity_jsonl_valid": 0.0,
        "extracted_wikipedia_ecology_jsonl_valid": 0.0,
        "extracted_gutenberg_chapters_jsonl_valid": 0.0,
        "keyword_counts_csv_structure": 0.0,
        "keyword_counts_csv_counts_match": 0.0,
        "summary_json_correct": 0.0,
        "report_includes_sources_and_segment_counts": 0.0,
        "report_includes_top_three_keywords": 0.0,
    }

    # File paths
    biod_html = workspace / "downloads" / "wikipedia" / "biodiversity.html"
    ecol_html = workspace / "downloads" / "wikipedia" / "ecology.html"
    guten_txt = workspace / "downloads" / "gutenberg" / "origin_of_species.txt"

    biod_jsonl = workspace / "extracted" / "wikipedia" / "biodiversity_sections.jsonl"
    ecol_jsonl = workspace / "extracted" / "wikipedia" / "ecology_sections.jsonl"
    guten_jsonl = workspace / "extracted" / "gutenberg" / "origin_of_species_chapters.jsonl"

    counts_csv = workspace / "output" / "keyword_counts.csv"
    summary_json = workspace / "output" / "summary.json"
    report_md = workspace / "REPORT.md"

    # Check downloads: Wikipedia HTML
    biod_html_text = _read_text(biod_html)
    ecol_html_text = _read_text(ecol_html)
    if biod_html_text and "<html" in biod_html_text.lower():
        scores["downloads_wikipedia_biodiversity_html"] = 1.0
    if ecol_html_text and "<html" in ecol_html_text.lower():
        scores["downloads_wikipedia_ecology_html"] = 1.0

    # Check Gutenberg text
    guten_text = _read_text(guten_txt)
    if guten_text and "chapter" in guten_text and "CHAPTER" in guten_text:
        scores["downloads_gutenberg_origin_text"] = 1.0

    # Load extracted JSONL files
    biod_sections = _load_jsonl(biod_jsonl)
    ecol_sections = _load_jsonl(ecol_jsonl)
    guten_chapters = _load_jsonl(guten_jsonl)

    # Validate wikipedia biodiversity sections JSONL
    valid_biod = False
    if biod_sections is not None and len(biod_sections) > 0:
        try:
            valid = True
            for rec in biod_sections:
                if not isinstance(rec.get("title"), str) or not isinstance(rec.get("section"), str) or not isinstance(rec.get("text"), str):
                    valid = False
                    break
                if rec.get("title") != "Biodiversity":
                    valid = False
                    break
                if rec.get("section", "").strip() == "":
                    valid = False
                    break
                if rec.get("text", "").strip() == "":
                    valid = False
                    break
            valid_biod = valid
        except Exception:
            valid_biod = False
    if valid_biod:
        scores["extracted_wikipedia_biodiversity_jsonl_valid"] = 1.0

    # Validate wikipedia ecology sections JSONL
    valid_ecol = False
    if ecol_sections is not None and len(ecol_sections) > 0:
        try:
            valid = True
            for rec in ecol_sections:
                if not isinstance(rec.get("title"), str) or not isinstance(rec.get("section"), str) or not isinstance(rec.get("text"), str):
                    valid = False
                    break
                if rec.get("title") != "Ecology":
                    valid = False
                    break
                if rec.get("section", "").strip() == "":
                    valid = False
                    break
                if rec.get("text", "").strip() == "":
                    valid = False
                    break
            valid_ecol = valid
        except Exception:
            valid_ecol = False
    if valid_ecol:
        scores["extracted_wikipedia_ecology_jsonl_valid"] = 1.0

    # Validate gutenberg chapters JSONL and labels match raw text markers
    valid_guten = False
    if guten_chapters is not None and len(guten_chapters) > 0 and isinstance(guten_text, str):
        try:
            for rec in guten_chapters:
                if not isinstance(rec.get("chapter"), str) or not isinstance(rec.get("text"), str):
                    valid_guten = False
                    break
                if not rec.get("chapter", "").startswith("CHAPTER"):
                    valid_guten = False
                    break
                if rec.get("text", "").strip() == "":
                    valid_guten = False
                    break
            else:
                labels_from_jsonl = [rec["chapter"] for rec in guten_chapters]
                labels_from_text = _extract_chapter_labels_from_text(guten_text)
                if len(labels_from_text) > 0 and set(labels_from_jsonl) == set(labels_from_text):
                    valid_guten = True
                else:
                    valid_guten = False
        except Exception:
            valid_guten = False
    if valid_guten:
        scores["extracted_gutenberg_chapters_jsonl_valid"] = 1.0

    # Load keywords
    keywords = _load_keywords(workspace)
    expected_counts: Dict[Tuple[str, str, str], int] = {}
    expected_totals: Dict[str, Dict[str, int]] = {}
    have_all_inputs = keywords is not None and valid_biod and valid_ecol and valid_guten

    if have_all_inputs:
        kws = keywords or []
        # Wikipedia Biodiversity
        src_biod = "wikipedia:Biodiversity"
        expected_totals[src_biod] = {k: 0 for k in kws}
        for rec in biod_sections:
            seg = rec["section"]
            counts = _count_keywords(rec["text"], kws)
            for k, v in counts.items():
                expected_counts[(src_biod, seg, k)] = v
                expected_totals[src_biod][k] += v
        # Wikipedia Ecology
        src_ecol = "wikipedia:Ecology"
        expected_totals[src_ecol] = {k: 0 for k in kws}
        for rec in ecol_sections:
            seg = rec["section"]
            counts = _count_keywords(rec["text"], kws)
            for k, v in counts.items():
                expected_counts[(src_ecol, seg, k)] = v
                expected_totals[src_ecol][k] += v
        # Gutenberg OriginOfSpecies
        src_guten = "gutenberg:OriginOfSpecies"
        expected_totals[src_guten] = {k: 0 for k in kws}
        for rec in guten_chapters:
            seg = rec["chapter"]
            counts = _count_keywords(rec["text"], kws)
            for k, v in counts.items():
                expected_counts[(src_guten, seg, k)] = v
                expected_totals[src_guten][k] += v

    # Validate keyword_counts.csv structure and counts
    csv_rows = _load_csv_dicts(counts_csv)
    csv_header_ok = False
    csv_counts_match = False
    if csv_rows is not None:
        try:
            with counts_csv.open("r", encoding="utf-8", newline="") as f:
                header_line = f.readline()
        except Exception:
            header_line = ""
        header = [h.strip() for h in header_line.strip().split(",")] if header_line else []
        if header == ["source", "segment", "keyword", "count"]:
            csv_header_ok = True

        if csv_header_ok and have_all_inputs:
            got_map: Dict[Tuple[str, str, str], int] = {}
            unique_ok = True
            try:
                for r in csv_rows:
                    src = (r.get("source") or "").strip()
                    seg = (r.get("segment") or "").strip()
                    kw = (r.get("keyword") or "").strip().lower()
                    cnt_raw = (r.get("count") or "").strip()
                    if src == "" or seg == "" or kw == "" or cnt_raw == "":
                        unique_ok = False
                        break
                    try:
                        cnt = int(cnt_raw)
                    except Exception:
                        unique_ok = False
                        break
                    key = (src, seg, kw)
                    if key in got_map:
                        unique_ok = False
                        break
                    got_map[key] = cnt
                if not unique_ok:
                    csv_counts_match = False
                else:
                    if set(got_map.keys()) != set(expected_counts.keys()):
                        csv_counts_match = False
                    else:
                        equal = True
                        for k, v in expected_counts.items():
                            if got_map.get(k) != v:
                                equal = False
                                break
                        csv_counts_match = equal
            except Exception:
                csv_counts_match = False

    if csv_header_ok:
        scores["keyword_counts_csv_structure"] = 1.0
    if csv_counts_match:
        scores["keyword_counts_csv_counts_match"] = 1.0

    # Validate summary.json correctness
    summary = _load_json(summary_json)
    summary_ok = False
    if summary is not None and have_all_inputs:
        try:
            expected_sources = {"wikipedia:Biodiversity", "wikipedia:Ecology", "gutenberg:OriginOfSpecies"}
            if set(summary.keys()) == expected_sources:
                all_match = True
                for src, totals in expected_totals.items():
                    got = summary.get(src)
                    if not isinstance(got, dict):
                        all_match = False
                        break
                    if set(got.keys()) != set(totals.keys()):
                        all_match = False
                        break
                    for kw, expected_val in totals.items():
                        gv = got.get(kw)
                        if not isinstance(gv, int):
                            all_match = False
                            break
                        if gv != expected_val:
                            all_match = False
                            break
                    if not all_match:
                        break
                summary_ok = all_match
            else:
                summary_ok = False
        except Exception:
            summary_ok = False
    if summary_ok:
        scores["summary_json_correct"] = 1.0

    # REPORT.md checks
    report_text = _read_text(report_md)
    report_sources_and_counts_ok = False
    report_top_keywords_ok = False
    if report_text is not None and isinstance(report_text, str) and report_text.strip():
        expected_segments_counts: Dict[str, int] = {}
        if have_all_inputs:
            expected_segments_counts["Biodiversity"] = len(biod_sections or [])
            expected_segments_counts["Ecology"] = len(ecol_sections or [])
            expected_segments_counts["Origin of Species"] = len(guten_chapters or [])

        def _has_number_near_marker(text: str, marker_lower: str, expected_num: int) -> bool:
            lines = text.splitlines()
            for i, line in enumerate(lines):
                if marker_lower in line.lower():
                    block = "\n".join(lines[i:i+3])
                    nums = re.findall(r"\b\d+\b", block)
                    for n in nums:
                        try:
                            if int(n) == expected_num:
                                return True
                        except Exception:
                            pass
            return False

        try:
            has_biod = "biodiversity" in report_text.lower()
            has_ecol = "ecology" in report_text.lower()
            has_origin = ("origin of species" in report_text.lower()) or ("originofspecies" in report_text.lower())
            sources_present = has_biod and has_ecol and has_origin

            counts_correct = False
            if have_all_inputs and sources_present:
                biod_ok = _has_number_near_marker(report_text, "biodiversity", expected_segments_counts["Biodiversity"])
                ecol_ok = _has_number_near_marker(report_text, "ecology", expected_segments_counts["Ecology"])
                origin_ok = _has_number_near_marker(report_text, "origin of species", expected_segments_counts["Origin of Species"])
                counts_correct = biod_ok and ecol_ok and origin_ok

            report_sources_and_counts_ok = sources_present and (counts_correct if have_all_inputs else True)
        except Exception:
            report_sources_and_counts_ok = False

        if have_all_inputs:
            try:
                def _top_three(totals: Dict[str, int]) -> List[str]:
                    items = sorted(totals.items(), key=lambda kv: (-kv[1], kv[0]))
                    top = [k for k, v in items[:3]]
                    return top

                top_biod = _top_three(expected_totals.get("wikipedia:Biodiversity", {}))
                top_ecol = _top_three(expected_totals.get("wikipedia:Ecology", {}))
                top_guten = _top_three(expected_totals.get("gutenberg:OriginOfSpecies", {}))

                def _all_keywords_present(text: str, kws: List[str]) -> bool:
                    tl = text.lower()
                    return all(k.lower() in tl for k in kws)

                ok_biod = _all_keywords_present(report_text, top_biod) if top_biod else False
                ok_ecol = _all_keywords_present(report_text, top_ecol) if top_ecol else False
                ok_guten = _all_keywords_present(report_text, top_guten) if top_guten else False
                report_top_keywords_ok = ok_biod and ok_ecol and ok_guten
            except Exception:
                report_top_keywords_ok = False
        else:
            report_top_keywords_ok = False

    if report_sources_and_counts_ok:
        scores["report_includes_sources_and_segment_counts"] = 1.0
    if report_top_keywords_ok:
        scores["report_includes_top_three_keywords"] = 1.0

    return scores


